// Debug helpers — call from F12 console
// 1) List all stored activity names under a target:
//    debugScanTarget("Hayden Chan", "Math")
window.debugScanTarget = async function(studentName, targetName) {
  const students = await loadStudentsConfig();
  const student = students.find(s => s.name === studentName);
  if (!student) { console.error("Student not found:", studentName); return; }
  const sessions = await getAllSessionsForStudent(student.id);
  console.log(`Scanning ${sessions.length} sessions for ${studentName} / ${targetName}...`);
  const counts = {};
  sessions.forEach(s => {
    Object.values(s.activities || {}).forEach(a => {
      if (a.targetName !== targetName) return;
      const key = a.activityName || "(no name)";
      counts[key] = (counts[key] || 0) + 1;
    });
  });
  console.table(counts);
};

// 1b) READ-ONLY. Diagnose suspected duplicate activities under one target.
//     Shows every config entry with its id, both name fields, type and dates,
//     then how many session records point at each one and where they sit. Two
//     entries holding the same remark text in the same session is the signature
//     of a duplicate; an entry with records but no config is a stranded record.
//     Writes nothing. Full data left on window.__dupCheck.
//     debugDuplicates("Kayden Koh", "Learning")
window.debugDuplicates = async function(studentName, targetName) {
  const students = await loadStudentsConfig();
  const student = students.find(s => s.name === studentName);
  if (!student) { console.error("Student not found:", studentName); return; }
  const target = (student.targets || []).find(t => t.name === targetName);
  if (!target) { console.error("Target not found:", targetName); return; }

  const acts = target.predefinedActivities || [];
  const cfgRows = acts.map((a, i) => ({
    idx: i + 1,
    id: a.id || "(no id)",
    title: a.title || "",
    name: a.name || "",
    type: a.type || a.activityType || "",
    created: a.createdOn || a.created || "",
    masteredOn: a.masteredOn || "",
    discontinuedOn: a.discontinuedOn || "",
    order: a.order === undefined ? "" : a.order,
    isHeading: !!a.isHeading
  }));
  console.log(`CONFIG — ${acts.length} entries for ${studentName} / ${targetName}`);
  console.table(cfgRows);

  const sessions = await getAllSessionsForStudent(student.id);
  const byCfg = {};      // configId -> { count, first, last, names:Set, samples:[] }
  const perSession = {}; // sessionDate -> [ {cfgId, name, text} ]
  sessions.forEach(s => {
    Object.entries(s.activities || {}).forEach(([recId, a]) => {
      if (a.targetName !== targetName) return;
      const cid = a.configId || "(none)";
      const b = byCfg[cid] || (byCfg[cid] = { count: 0, first: null, last: null, names: new Set(), samples: [] });
      b.count++;
      if (!b.first || s.date < b.first) b.first = s.date;
      if (!b.last || s.date > b.last) b.last = s.date;
      b.names.add(a.activityName || "(no name)");
      // Remarks live in a flat map on the SESSION, keyed by remark id, each
      // carrying activityId. They are not nested under the activity.
      const rems = Object.values(s.remarks || {}).filter(r => r.activityId === recId);
      const txt = rems.map(r => {
        const t = plainTextForEdit(r.text || r.masteryNote || "").trim();
        const tr = (r.trials || []).filter(v => v !== null && v !== -1);
        return t || (tr.length ? `[trials ${tr.join(",")}]` : "");
      }).filter(Boolean).join(" | ");
      if (txt && b.samples.length < 3) b.samples.push(`${s.date}: ${txt.slice(0, 60)}`);
      (perSession[s.date] || (perSession[s.date] = [])).push({ cfgId: cid, name: a.activityName || "", text: txt.slice(0, 60) });
    });
  });

  const cfgIds = new Set(acts.map(a => a.id).filter(Boolean));
  console.log(`RECORDS — across ${sessions.length} sessions`);
  console.table(Object.entries(byCfg).map(([cid, b]) => ({
    configId: cid,
    inConfig: cid === "(none)" ? "NO configId" : (cfgIds.has(cid) ? "yes" : "STRANDED"),
    records: b.count,
    first: b.first,
    last: b.last,
    distinctNames: b.names.size,
    namesUsed: [...b.names].join(" || "),
    sample: b.samples[0] || ""
  })));

  // Sessions where two different records carry identical remark text: the
  // clearest sign that one activity was duplicated rather than renamed.
  const clashes = [];
  Object.entries(perSession).forEach(([date, rows]) => {
    const seen = {};
    rows.forEach(r => {
      if (!r.text) return;
      if (seen[r.text]) clashes.push({ date, text: r.text, a: seen[r.text].name, aId: seen[r.text].cfgId, b: r.name, bId: r.cfgId });
      else seen[r.text] = r;
    });
  });
  console.log(`DUPLICATE REMARK TEXT in the same session — ${clashes.length} found`);
  if (clashes.length) console.table(clashes.slice(0, 40));

  window.__dupCheck = { student: studentName, target: targetName, config: cfgRows, byCfg, clashes, perSession };
  console.log("Full data on window.__dupCheck");
  console.log('For every record of one activity: debugActivityRecords("' + studentName + '", "' + targetName + '", "<configId>")');
};

// 1e) Move session records from one config activity to another. DRY RUN by
//     default; pass true as the last argument to write. Refuses any session
//     that already holds a record for the destination, since repointing there
//     would create a real duplicate inside one session.
//     debugRepoint("Kayden Koh", "Learning", "amt73xzqm73w53", "amqknhgnoek9u")
//     debugRepoint("Kayden Koh", "Learning", "amt73xzqm73w53", "amqknhgnoek9u", true)
window.debugRepoint = async function(studentName, targetName, fromCfg, toCfg, apply = false) {
  const students = await loadStudentsConfig();
  const student = students.find(s => s.name === studentName);
  if (!student) { console.error("Student not found:", studentName); return; }
  const target = (student.targets || []).find(t => t.name === targetName);
  if (!target) { console.error("Target not found:", targetName); return; }
  const acts = target.predefinedActivities || [];
  if (!acts.some(a => a.id === toCfg)) { console.error("Destination configId is not in this target:", toCfg); return; }

  const sessions = await getAllSessionsForStudent(student.id);
  const plan = [], conflicts = [];
  sessions.forEach(s => {
    const mine = [], theirs = [];
    Object.entries(s.activities || {}).forEach(([recId, a]) => {
      if (a.targetName !== targetName) return;
      if (a.configId === fromCfg) mine.push([recId, a]);
      else if (a.configId === toCfg) theirs.push(recId);
    });
    if (!mine.length) return;
    if (theirs.length) { conflicts.push({ date: s.date, session: s.sessionNumber || s.id, movingRecords: mine.length, alreadyThere: theirs.length }); return; }
    mine.forEach(([recId, a]) => plan.push({
      sessionId: s.id, date: s.date, session: s.sessionNumber || s.id, recId,
      activityName: a.activityName || "", parentActivity: a.parentActivity || null,
      remarks: Object.values(s.remarks || {}).filter(r => r.activityId === recId).length
    }));
  });

  console.log(`${apply ? "APPLYING" : "DRY RUN"} — repoint ${fromCfg} → ${toCfg}`);
  console.log(`${plan.length} record(s) to move across ${new Set(plan.map(p => p.date)).size} session(s)`);
  console.table(plan);
  if (conflicts.length) {
    console.warn(`${conflicts.length} session(s) SKIPPED — they already hold a record for the destination:`);
    console.table(conflicts);
  }
  if (!apply) { console.log("Nothing written. Re-run with true as the last argument to apply."); return; }

  let done = 0;
  for (const p of plan) {
    await adoptOrphanActivity(p.sessionId, p.recId, p.parentActivity, toCfg);
    done++;
  }
  console.log(`Done — ${done} record(s) repointed.`);
};

// 1h) Repair activities converted to Multiple Choice / Checkboxes BEFORE the
//     conversion migration existed. For such an activity, rem.text means "which
//     option was chosen" and free prose belongs in rem.masteryNote, so old prose
//     left in rem.text renders as a grey "Old data:" line with an empty remark
//     box. This moves that prose into the note field where it belongs.
//     Only touches remarks whose text is NOT one of the options AND whose note
//     is empty, so a real selection is never destroyed and no note is
//     overwritten. Omit configId to sweep every option-based activity in the
//     target. DRY RUN by default.
//     debugFixOldData("Kayden Koh", "Learning")
//     debugFixOldData("Kayden Koh", "Learning", null, true)
window.debugFixOldData = async function(studentName, targetName, configId = null, apply = false) {
  const students = await loadStudentsConfig();
  const student = students.find(s => s.name === studentName);
  if (!student) { console.error("Student not found:", studentName); return; }
  const target = (student.targets || []).find(t => t.name === targetName);
  if (!target) { console.error("Target not found:", targetName); return; }

  const acts = (target.predefinedActivities || []).filter(a =>
    !a.isHeading && !a.isNote && !a.isExportNote && parseOpts(a.inlineOptions).length > 0
    && (!configId || a.id === configId));
  if (!acts.length) { console.log("No option-based activities matched."); return; }

  const sessions = await getAllSessionsForStudent(student.id);
  const plan = [];   // { sessionId, date, remId, activity, from }
  for (const pa of acts) {
    const opts = parseOpts(pa.inlineOptions);
    sessions.forEach(s => {
      const recIds = Object.entries(s.activities || {})
        .filter(([, a]) => a.targetName === targetName
          && (a.configId === pa.id || (pa.name && a.activityName === pa.name) || (pa.title && a.activityName === pa.title)))
        .map(([id]) => id);
      if (!recIds.length) return;
      Object.entries(s.remarks || {}).forEach(([remId, r]) => {
        if (!recIds.includes(r.activityId)) return;
        const txt = (r.text || "").replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").trim();
        if (!txt) return;
        if (opts.includes(txt)) return;              // a real selection, leave alone
        if ((r.masteryNote || "").trim()) return;    // never overwrite an existing note
        plan.push({ sessionId: s.id, date: s.date, session: s.sessionNumber || s.id, remId,
                    activity: pa.title || pa.name || "(untitled)", from: txt.slice(0, 70) });
      });
    });
  }

  console.log(`${apply ? "APPLYING" : "DRY RUN"} — move prose out of rem.text into rem.masteryNote`);
  console.log(`${plan.length} remark(s) across ${new Set(plan.map(p => p.date)).size} session(s), ${acts.length} activity(ies)`);
  console.table(plan.slice(0, 60));
  if (plan.length > 60) console.log(`…and ${plan.length - 60} more`);
  if (!apply) { console.log("Nothing written. Re-run with true as the last argument to apply."); return; }

  const bySession = {};
  plan.forEach(p => {
    (bySession[p.sessionId] || (bySession[p.sessionId] = {}))[p.remId] = { text: "", masteryNote: p.from };
  });
  // Re-read the untruncated text rather than the 70-char preview used for display.
  for (const s of sessions) {
    if (!bySession[s.id]) continue;
    const changes = {};
    for (const remId of Object.keys(bySession[s.id])) {
      const r = (s.remarks || {})[remId];
      if (!r) continue;
      const txt = (r.text || "").replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").trim();
      changes[remId] = { text: "", masteryNote: txt };
    }
    if (Object.keys(changes).length) await migrateRemarksToNote(s.id, changes);
  }
  console.log(`Done — ${plan.length} remark(s) moved.`);
};

// 1g) Merge two records for the same target inside ONE session: every remark
//     on the dropped record moves to the kept one, then the emptied record is
//     removed. Nothing is deleted, only re-pointed. DRY RUN by default.
//     debugMergeInSession("Kayden Koh", "Learning", "2026-06-18", "amqknhgnoek9u", "amt73xzqm73w53")
window.debugMergeInSession = async function(studentName, targetName, sessionDate, keepCfg, dropCfg, apply = false) {
  const students = await loadStudentsConfig();
  const student = students.find(s => s.name === studentName);
  if (!student) { console.error("Student not found:", studentName); return; }
  const sessions = (await getAllSessionsForStudent(student.id)).filter(s => s.date === sessionDate);
  if (!sessions.length) { console.error("No session on", sessionDate); return; }

  for (const s of sessions) {
    const keep = [], drop = [];
    Object.entries(s.activities || {}).forEach(([recId, a]) => {
      if (a.targetName !== targetName) return;
      if (a.configId === keepCfg) keep.push([recId, a]);
      else if (a.configId === dropCfg) drop.push([recId, a]);
    });
    if (!keep.length || !drop.length) {
      console.log(`Session ${s.sessionNumber || s.id} (${s.date}): nothing to merge (keep=${keep.length}, drop=${drop.length})`);
      continue;
    }
    if (keep.length > 1) { console.error(`Session ${s.sessionNumber || s.id}: ${keep.length} records for the KEEP side, too ambiguous. Stopping.`); return; }
    const rows = [];
    [...keep, ...drop].forEach(([recId, a]) => {
      Object.values(s.remarks || {}).filter(r => r.activityId === recId).forEach(r => {
        const tr = (r.trials || []).filter(v => v !== null && v !== -1);
        rows.push({ side: a.configId === keepCfg ? "KEEP" : "DROP", recId, name: a.activityName || "", text: plainTextForEdit(r.text || "").slice(0, 70), trials: tr.join(",") });
      });
    });
    console.log(`${apply ? "APPLYING" : "DRY RUN"} — session ${s.sessionNumber || s.id} (${s.date}): moving ${drop.length} record(s) onto ${keep[0][0]}`);
    console.table(rows);
    if (!apply) continue;
    for (const [dropId] of drop) await mergeDuplicateActivity(s.id, keep[0][0], dropId);
    console.log("Merged.");
  }
  if (!apply) console.log("Nothing written. Re-run with true as the last argument to apply.");
};

// 1f) Remove a config activity entry WITHOUT touching session data. Refuses
//     while any record still points at it, so it can only be used after
//     debugRepoint has emptied it. DRY RUN by default.
//     debugDropConfigEntry("Kayden Koh", "Learning", "amt73xzqm73w53", true)
window.debugDropConfigEntry = async function(studentName, targetName, configId, apply = false) {
  const students = await loadStudentsConfig();
  const student = students.find(s => s.name === studentName);
  if (!student) { console.error("Student not found:", studentName); return; }
  const target = (student.targets || []).find(t => t.name === targetName);
  if (!target) { console.error("Target not found:", targetName); return; }
  const acts = target.predefinedActivities || [];
  const idx = acts.findIndex(a => a.id === configId);
  if (idx < 0) { console.error("configId not in this target:", configId); return; }

  const sessions = await getAllSessionsForStudent(student.id);
  let still = 0;
  sessions.forEach(s => Object.values(s.activities || {}).forEach(a => {
    if (a.targetName === targetName && a.configId === configId) still++;
  }));
  if (still > 0) {
    console.error(`REFUSED — ${still} session record(s) still point at ${configId}. Run debugRepoint first.`);
    return;
  }
  const entry = acts[idx];
  console.log(`${apply ? "APPLYING" : "DRY RUN"} — remove config entry ${configId} = "${entry.title || entry.name || "(blank)"}"`);
  console.log("No session records reference it, so no session data is touched.");
  if (!apply) { console.log("Nothing written. Re-run with true as the last argument to apply."); return; }

  acts.splice(idx, 1);
  acts.forEach((a, i) => a.order = i);
  target.predefinedActivities = acts;
  await saveStudent(student);
  console.log(`Done — entry removed, ${acts.length} activities remain.`);
};

// 1d) READ-ONLY. Every session record whose activityName matches, regardless of
//     configId. This is the honest answer to "which sessions hold data for this
//     activity", because records that lost their configId are invisible to a
//     configId lookup but still show on screen, matched by name.
//     debugRecordsByName("Kayden Koh", "Learning", "b) 2 Animals instructions")
window.debugRecordsByName = async function(studentName, targetName, activityName) {
  const students = await loadStudentsConfig();
  const student = students.find(s => s.name === studentName);
  if (!student) { console.error("Student not found:", studentName); return; }
  const sessions = await getAllSessionsForStudent(student.id);
  const rows = [];
  sessions.forEach(s => {
    Object.entries(s.activities || {}).forEach(([recId, a]) => {
      if (a.targetName !== targetName) return;
      if ((a.activityName || "") !== activityName) return;
      const rems = Object.values(s.remarks || {}).filter(r => r.activityId === recId);
      if (!rems.length) rows.push({ date: s.date, session: s.sessionNumber || s.id, configId: a.configId || "(none)", text: "(no remarks)", trials: "" });
      rems.forEach(r => {
        const tr = (r.trials || []).filter(v => v !== null && v !== -1);
        rows.push({
          date: s.date,
          session: s.sessionNumber || s.id,
          configId: a.configId || "(none)",
          text: plainTextForEdit(r.text || r.masteryNote || "").slice(0, 90),
          trials: tr.join(",")
        });
      });
    });
  });
  rows.sort((a, b) => (a.date < b.date ? -1 : 1));
  const dates = [...new Set(rows.map(r => r.date))];
  console.log(`${rows.length} remark rows across ${dates.length} sessions for name "${activityName}"`);
  console.log("configIds seen:", [...new Set(rows.map(r => r.configId))].join(", "));
  console.table(rows);
};

// 1c) READ-ONLY. Every session record for ONE activity, with its remark text,
//     so a suspected duplicate can be compared against the original before
//     anything is deleted. Writes nothing.
//     debugActivityRecords("Kayden Koh", "Learning", "amt73xzqm73w53")
window.debugActivityRecords = async function(studentName, targetName, configId) {
  const students = await loadStudentsConfig();
  const student = students.find(s => s.name === studentName);
  if (!student) { console.error("Student not found:", studentName); return; }
  const sessions = await getAllSessionsForStudent(student.id);
  const rows = [];
  sessions.forEach(s => {
    Object.entries(s.activities || {}).forEach(([recId, a]) => {
      if (a.targetName !== targetName) return;
      if ((a.configId || "(none)") !== configId) return;
      Object.values(s.remarks || {}).filter(r => r.activityId === recId).forEach(r => {
        const tr = (r.trials || []).filter(v => v !== null && v !== -1);
        rows.push({
          date: s.date,
          session: s.sessionNumber || s.id,
          activityName: a.activityName || "",
          text: plainTextForEdit(r.text || "").slice(0, 90),
          masteryNote: plainTextForEdit(r.masteryNote || "").slice(0, 60),
          trials: tr.join(","),
          optionScore: r.optionScore === undefined ? "" : r.optionScore
        });
      });
    });
  });
  rows.sort((a, b) => (a.date < b.date ? -1 : 1));
  console.log(`${rows.length} remark rows for configId ${configId}`);
  console.table(rows);
};

// 2) Show config dates for all activities in a target — reveals hidden activeTo/activeFrom:
//    debugTargetConfig("Hayden Chan", "Math")
window.debugTargetConfig = async function(studentName, targetName) {
  const students = await loadStudentsConfig();
  const student = students.find(s => s.name === studentName);
  if (!student) { console.error("Student not found:", studentName); return; }
  const target = (student.targets || []).find(t => t.name === targetName);
  if (!target) { console.error("Target not found:", targetName); return; }
  const acts = target.predefinedActivities || [];
  console.log(`${acts.length} activities in config for ${studentName} / ${targetName}:`);
  acts.forEach((a, i) => {
    const dateInfo = [];
    if (a.activeFrom) dateInfo.push(`activeFrom: ${a.activeFrom}`);
    if (a.activeTo)   dateInfo.push(`activeTo: ${a.activeTo}`);
    if (a.masteredOn)    dateInfo.push(`masteredOn: ${a.masteredOn}`);
    if (a.discontinuedOn) dateInfo.push(`discontinuedOn: ${a.discontinuedOn}`);
    if (a.isCompleted) dateInfo.push("isCompleted");
    if (a.isArchived)  dateInfo.push("isArchived");
    if (a.isStopped)   dateInfo.push("isStopped");
    console.log(`${i + 1}) ${a.title || a.name || "(heading)"}`, dateInfo.length ? dateInfo.join(", ") : "no date flags");
  });
};

// 2b) READ-ONLY. Compare what the session records contain against what the
//     target config still lists, and show everything needed to rebuild the
//     activities that the pre-2026-08-23 reorder bug deleted from the config.
//     Writes nothing — the full result is also left on window.__recoveryPlan.
//     debugRecoveryPlan("Hayden Chan", "Math")
window.debugRecoveryPlan = async function(studentName, targetName) {
  const students = await loadStudentsConfig();
  const student = students.find(s => s.name === studentName);
  if (!student) { console.error("Student not found:", studentName); return; }
  const target = (student.targets || []).find(t => t.name === targetName);
  if (!target) { console.error("Target not found:", targetName); return; }

  const acts = target.predefinedActivities || [];
  const cfgIds   = new Set(acts.map(a => a.id).filter(Boolean));
  const cfgNames = new Set(acts.flatMap(a => [a.name, a.title]).filter(Boolean));

  const sessions = await getAllSessionsForStudent(student.id);
  const found = {};   // key -> record we are building up

  for (const s of sessions) {
    const date = s.date || s.sessionDate || "(no date)";
    const remarksByAct = {};
    Object.values(s.remarks || {}).forEach(r => {
      (remarksByAct[r.activityId] ||= []).push(r);
    });
    for (const [actId, a] of Object.entries(s.activities || {})) {
      if (a.targetName !== targetName) continue;
      const name = a.activityName || a.activityTitle || "(no name)";
      const key  = a.configId || name;
      const rec = found[key] ||= {
        name, title: a.activityTitle || "", configId: a.configId || "",
        parentActivity: a.parentActivity || "",
        sessions: 0, withText: 0, withTrials: 0,
        firstDate: date, lastDate: date, orders: new Set()
      };
      rec.sessions++;
      if (date < rec.firstDate) rec.firstDate = date;
      if (date > rec.lastDate)  rec.lastDate  = date;
      if (typeof a.order === "number") rec.orders.add(a.order);
      for (const r of (remarksByAct[actId] || [])) {
        if ((r.text || "").trim()) rec.withText++;
        if ((r.trials || []).length) rec.withTrials++;
      }
    }
  }

  const rows = Object.values(found).map(r => ({
    ...r,
    orders: [...r.orders].sort((a, b) => a - b).join(","),
    inConfig: (r.configId && cfgIds.has(r.configId)) || cfgNames.has(r.name)
  })).sort((a, b) => (a.lastDate < b.lastDate ? 1 : a.lastDate > b.lastDate ? -1 : 0));

  const missing = rows.filter(r => !r.inConfig);
  console.log(`${studentName} / ${targetName}: ${sessions.length} sessions, ` +
    `${acts.length} config entries, ${rows.length} distinct activities in session data, ` +
    `${missing.length} MISSING from config.`);
  console.table(rows.map(r => ({
    Activity: r.name.length > 60 ? r.name.slice(0, 57) + "..." : r.name,
    InConfig: r.inConfig ? "yes" : "MISSING",
    Sessions: r.sessions, Remarks: r.withText, Trials: r.withTrials,
    First: r.firstDate, Last: r.lastDate, Orders: r.orders, ConfigId: r.configId || "-"
  })));
  window.__recoveryPlan = { student: studentName, target: targetName, config: acts, rows, missing };
  console.log("Full data left on window.__recoveryPlan — run: copy(JSON.stringify(window.__recoveryPlan.missing, null, 2))");
  return `${missing.length} missing`;
};

// 3) Clear legacy activeTo/activeFrom from all activities in a target:
//    debugClearActivePeriod("Hayden Chan", "Math")
window.debugClearActivePeriod = async function(studentName, targetName) {
  const students = await loadStudentsConfig();
  const student = students.find(s => s.name === studentName);
  if (!student) { console.error("Student not found:", studentName); return; }
  const target = (student.targets || []).find(t => t.name === targetName);
  if (!target) { console.error("Target not found:", targetName); return; }
  let cleared = 0;
  (target.predefinedActivities || []).forEach(pa => {
    if (pa.activeTo)   { delete pa.activeTo;   cleared++; }
    if (pa.activeFrom) { delete pa.activeFrom; cleared++; }
  });
  if (!cleared) { console.log("Nothing to clear."); return; }
  await saveStudent(student);
  console.log(`Cleared ${cleared} date field(s) from ${targetName}. Refresh the page.`);
};

// 4) Deep-check a specific activity name (must match exactly what debugScanTarget shows):
//    debugDeleteCheck("Hayden Chan", "Math", "Writing/Spelling Numbers in Letters")
window.debugDeleteCheck = async function(studentName, targetName, activityName) {
  const students = await loadStudentsConfig();
  const student = students.find(s => s.name === studentName);
  if (!student) { console.error("Student not found:", studentName); return; }
  const sessions = await getAllSessionsForStudent(student.id);
  console.log(`Found ${sessions.length} sessions for ${studentName}`);
  sessions.forEach(s => {
    const sActs = s.activities || {};
    const sRems = s.remarks || {};
    const matchIds = Object.entries(sActs)
      .filter(([, a]) => a.targetName === targetName && a.activityName === activityName)
      .map(([id]) => id);
    if (!matchIds.length) return;
    matchIds.forEach(actId => {
      const hits = Object.entries(sRems).filter(([, r]) => r.activityId === actId);
      if (!hits.length) { console.log(`Session #${s.sessionNumber || s.id}: actId=${actId} — NO remarks`); return; }
      hits.forEach(([rid, r]) => {
        const hasText = (r.text || "").replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").trim().length > 0;
        const hasMasteryNote = (r.masteryNote || "").trim().length > 0;
        const hasTrials = (r.trials || []).some(t => t !== null && t !== -1);
        const hasOption = r.optionScore !== undefined && r.optionScore !== null;
        console.log(`Session #${s.sessionNumber || s.id} (${s.date}): actId=${actId} remId=${rid}`, {
          activityEntry: sActs[actId],
          remark: r,
          flags: { hasText, hasMasteryNote, hasTrials, hasOption }
        });
      });
    });
  });
};
