function renderDatePickerCalendar(displayDate, takenDates, today, currentDate) {
  const [y, m] = displayDate.split("-").map(Number);
  const monthLabel = new Date(y, m - 1, 1)
    .toLocaleString("default", { month: "long", year: "numeric" });
  const [ty, tm] = today.split("-").map(Number);
  const canNext = y < ty || (y === ty && m < tm);

  const pad = n => String(n).padStart(2, "0");
  const prevM = m === 1  ? `${y - 1}-12-01` : `${y}-${pad(m - 1)}-01`;
  const nextM = m === 12 ? `${y + 1}-01-01` : `${y}-${pad(m + 1)}-01`;

  const firstDow  = new Date(y, m - 1, 1).getDay();
  const daysInMon = new Date(y, m, 0).getDate();

  let html = `<div class="date-picker-wrap">
    <p class="date-picker-subtitle">Select a new date</p>
    <p class="date-picker-legend"><span class="date-taken-dot">✓︎</span> Session exists on this day</p>
    <div class="date-picker-cal">
      <div class="date-picker-nav">
        <button class="btn-date-prev">‹</button>
        <span class="date-picker-month-label">${escHtml(monthLabel)}</span>
        <button class="btn-date-next"${canNext ? "" : " disabled"}>›</button>
      </div>
      <div class="date-picker-day-headers">
        <span>Su</span><span>Mo</span><span>Tu</span><span>We</span>
        <span>Th</span><span>Fr</span><span>Sa</span>
      </div>
      <div class="date-picker-grid">`;

  // Always render 42 cells (6 rows) so height never changes between months
  for (let cell = 0; cell < 42; cell++) {
    const d = cell - firstDow + 1;
    if (d < 1 || d > daysInMon) { html += `<span></span>`; continue; }
    const ds     = `${y}-${pad(m)}-${pad(d)}`;
    const isCur  = ds === currentDate;
    const isFut  = ds > today;
    const isTaken = takenDates.has(ds);
    const dis    = isFut || isTaken;
    let cls = "date-picker-day";
    if (isCur)   cls += " date-picker-day-current";
    if (isFut)   cls += " date-picker-day-future";
    if (isTaken) cls += " date-picker-day-taken";
    const dotCls = isTaken ? "date-taken-dot" : "day-dot-spacer";
    html += `<button class="${cls}" data-date="${ds}"${dis ? " disabled" : ""}><span class="day-num">${d}</span><span class="${dotCls}">${isTaken ? "✓︎" : ""}</span></button>`;
  }
  html += `</div></div></div>`;

  $("session-picker-title").textContent = "Edit Date";
  $("session-picker-list").innerHTML = html;

  $("session-picker-list").querySelector(".btn-date-prev").addEventListener("click", () => {
    renderDatePickerCalendar(prevM, takenDates, today, currentDate);
  });
  if (canNext) {
    $("session-picker-list").querySelector(".btn-date-next").addEventListener("click", () => {
      renderDatePickerCalendar(nextM, takenDates, today, currentDate);
    });
  }
  $("session-picker-list").querySelectorAll(".date-picker-day:not([disabled])").forEach(btn => {
    btn.addEventListener("click", async () => {
      const newDate = btn.dataset.date;
      closeSessionPicker();
      if (newDate === currentDate) return;
      try {
        await updateSessionDate(state.viewSessionId, newDate, state.viewStudent.id);
      } catch (err) {
        alert(err.message);
      }
    });
  });
}

// ============================================================
// SESSION SCREEN
// ============================================================

function getEffectiveTargets() {
  return state.currentStudent?.targets || [];
}

async function openSession(student, existingSessionId = null, dateStr = null, participants = null) {
  // Jumping to another date for the SAME student via "Go To Another
  // Session" should land back on whatever target they were already
  // looking at, not silently reset to the first target in the list —
  // only a genuine student switch starts fresh.
  const preservedTargetName = state.currentStudent?.id === student.id ? state.selectedTargetName : null;

  // Capture the outgoing session before wiping state — "Go To Another Session" skips
  // leaveSession, so we run the same empty-entry cleanup here instead.
  const _prevSessionId = state.currentSessionId;
  const _prevData      = state.sessionData;
  const _prevStudent   = state.currentStudent;
  if (_prevSessionId && _prevData) await state.entryRemarkSaver?.flush();

  // Show the session screen immediately — before any network call — so
  // closing the picker never flashes the home screen while we fetch.
  state.currentStudent     = student;
  state.selectedTargetName = null;
  state.sessionData        = null;
  state.pendingNewActivity = null;
  state.pendingNewRemark   = null;
  state.renderPending      = false;
  _selectedSectionIdx      = 0;

  showScreen("screen-session");
  $("session-student-name").textContent = studentLabel(student);
  $("session-meta").textContent = "";
  $("target-content").innerHTML = `<div class="loading">Loading…</div>`;
  $("target-select").innerHTML  = `<option value="">— loading —</option>`;
  $("btn-manage-targets")?.classList.add("hidden");
  $("target-type-chip")?.classList.add("hidden");

  const gotoEntryBtn = $("btn-entry-goto-session");
  if (gotoEntryBtn) {
    gotoEntryBtn.classList.remove("hidden");
    gotoEntryBtn.onclick = () => showGoToAnotherSessionForEntry(student);
  }

  if (state.fbUnsubscribe) { state.fbUnsubscribe(); state.fbUnsubscribe = null; }
  state.entryRemarkSaver?.cleanup();
  if (_prevSessionId && _prevData && _prevStudent) {
    const _allTgtNames = new Set(Object.values(_prevData.activities || {}).map(a => a.targetName));
    _allTgtNames.forEach(name => {
      const target = (_prevStudent.targets || []).find(t => t.name === name);
      cleanupEmptyEntries(_prevSessionId, _prevData, name, target, true).catch(() => {});
    });
  }
  state.entryRemarkSaver = setupEntryRemarkSaving($("target-content"), () => state.currentSessionId, () => {
    if (!state.renderPending || state.entryActionsInFlight > 0) return;
    if (document.activeElement === $("target-select")) return;
    const _tc = $("target-content"), _ae = document.activeElement;
    if (_tc?.contains(_ae) && (_ae?.tagName === "TEXTAREA" || _ae?.tagName === "INPUT")) return;
    state.renderPending = false;
    renderTargetContent();
  });
  state.entryEnterKeyCleanup?.();
  state.entryEnterKeyCleanup = setupEntryEnterKeyDelegation($("target-content"),
    () => getEffectiveTargets().find(t => t.name === state.selectedTargetName));

  // When the session ID is already known, start the listener immediately so
  // onSnapshot can serve from the Firestore cache while the student-config
  // refresh happens in the background. When the ID isn't known yet we still
  // need getOrCreateSessionForDate first, but student refresh runs in parallel.
  try {
    let sessionId;
    if (existingSessionId) {
      sessionId = existingSessionId;
      getStudentById(student.id).then(fresh => {
        if (!fresh) return;
        Object.assign(student, fresh);
        state.currentStudent = student;
        const si = (state.students || []).findIndex(s => s.id === student.id);
        if (si >= 0) state.students[si] = student;
      }).catch(() => {});
    } else {
      const [fresh, sid] = await Promise.all([
        getStudentById(student.id).catch(() => null),
        getOrCreateSessionForDate(student.id, dateStr || getTodayString(), student.targets)
      ]);
      sessionId = sid;
      if (fresh) {
        Object.assign(student, fresh);
        state.currentStudent = student;
        const si = (state.students || []).findIndex(s => s.id === student.id);
        if (si >= 0) state.students[si] = student;
      }
    }

    // Backfill activeFrom on all activities that don't have one yet
    try {
      let _bfNeedsSave = false;
      for (const t of (student.targets || [])) {
        for (const a of (t.predefinedActivities || [])) {
          if (!a.isHeading && !a.isMaintainHeading && !a.isNote && !a.isExportNote && a.activeFrom == null) {
            a.activeFrom = "2026-01-01";
            _bfNeedsSave = true;
          }
        }
      }
      if (_bfNeedsSave) saveStudent(student).catch(() => {});
    } catch {}
    state.currentSessionId = sessionId;
    if (participants && !existingSessionId) {
      updateSessionParticipants(sessionId, participants).catch(() => {});
    }

    state.fbUnsubscribe = listenToSession(sessionId, async data => {
      const firstLoad = state.sessionData === null;
      // Strip orphan extra activities from EVERY incoming snapshot (empty name
      // + no substantive remarks) before storing in state — prevents pre-existing
      // orphans from old sessions ever being shown.
      const orphanActIds = [];
      const orphanRemIds = [];
      for (const [actId, act] of Object.entries(data.activities || {})) {
        if (act.isPredefined || act.parentActivity || (act.activityName || "").trim()) continue;
        const remEntries = Object.entries(data.remarks || {}).filter(([, r]) => r.activityId === actId);
        if (remEntries.some(([, r]) => remarkHasContent(r))) continue;
        orphanActIds.push(actId);
        for (const [remId] of remEntries) orphanRemIds.push(remId);
        delete data.activities[actId];
        if (data.remarks) for (const [remId] of remEntries) delete data.remarks[remId];
      }
      state.sessionData = data;
      if (firstLoad) {
        // Persist the Firestore cleanup once on open, not on every snapshot.
        if (orphanActIds.length > 0) {
          deleteOrphanActivities(sessionId, orphanActIds, orphanRemIds).catch(() => {});
        }
        // Clean up isPredefined session records for activities that are no longer
        // in the current target config (e.g., activities deleted from Edit Target after
        // they were already auto-filled into session data as maintained activities).
        // Without this, stale session records survive in Firestore forever and
        // autoFillMaintainedRemarks re-fills them on every snapshot.
        //
        // ONLY empty records may be deleted here. This sweep used to delete
        // unconditionally, which turned the pre-2026-08-23 reorder bug into
        // permanent data loss: that bug dropped mastered activities out of
        // predefinedActivities, and then merely opening a session deleted those
        // activities' remarks from Firestore. A deliberate delete purges its own
        // session records through the confirm-by-typing flow, so a stale record
        // that still holds data is always accidental — it must be kept and shown.
        const staleActIds = [];
        const staleRemIds = [];
        for (const [actId, act] of Object.entries(data.activities || {})) {
          if (!act.isPredefined || !act.targetName) continue;
          const tc = (student.targets || []).find(t => t.name === act.targetName);
          if (!tc) continue;
          const inConfig = (tc.predefinedActivities || []).some(pa =>
            (act.configId && pa.id && pa.id === act.configId) ||
            (act.activityName && (pa.name === act.activityName || pa.title === act.activityName))
          );
          if (inConfig) continue;
          const remEntries = Object.entries(data.remarks || {}).filter(([, r]) => r.activityId === actId);
          const hasData = remEntries.some(([, r]) =>
            (r.text || "").replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").trim().length > 0 ||
            (r.trials || []).some(t => t !== null && t !== -1) ||
            (r.masteryNote || "").replace(/<[^>]*>/g, "").trim().length > 0
          );
          if (hasData) continue;   // stranded but real — never delete
          staleActIds.push(actId);
          for (const [remId] of remEntries) staleRemIds.push(remId);
          delete data.activities[actId];
          if (data.remarks) for (const [remId] of remEntries) delete data.remarks[remId];
        }
        if (staleActIds.length > 0) {
          deleteOrphanActivities(sessionId, staleActIds, staleRemIds).catch(() => {});
        }
        const eff = getEffectiveTargets();
        state.selectedTargetName = (preservedTargetName && eff.some(t => t.name === preservedTargetName))
          ? preservedTargetName
          : (eff[0]?.name || null);
        populateTargetDropdown(eff);
        // Auto-create an empty remark for "pick from options" activities
        // (Select one / Tick boxes / Sentence Starter + either, or + Select
        // One + Free Text) so the boss can start picking immediately
        // instead of clicking "+ Add Remark & Trials" first. Wrapped in
        // try/catch so a malformed config never leaves the screen at "Loading…".
        // We render immediately after (rather than waiting for the Firestore
        // write's snapshot) so a delayed/missing follow-up snapshot can never
        // cause a permanent stuck-loading state. The subsequent snapshot from
        // the write will correct the display within ~100ms.
        try {
          await autoFillStructuredRemarks(student, sessionId);
        } catch (err) { console.error("autoFillStructuredRemarks failed:", err); }
      }
      // Mapped-score activities can become fillable any time during the
      // session (not just on open), so this check isn't gated to firstLoad.
      // Same render-immediately approach: don't wait for the write's snapshot.
      try {
        await autoFillMappedRemarks(student, sessionId);
      } catch (err) { console.error("autoFillMappedRemarks failed:", err); }
      try {
        await autoFillMaintainedRemarks(student, sessionId, state.selectedTargetName);
        // Don't return early — render now and let the Firestore write from
        // the fill trigger its own snapshot update rather than blocking here.
      } catch (err) { console.error("autoFillMaintainedRemarks failed:", err); }
      // Keep score modal trial badges in sync with Firestore
      if (state.scorePicker?.open && state.scorePicker?.remId) {
        renderScoreModalTrials(state.scorePicker.remId);
      }
      // Busy = dropdown open, or a button's own multi-step Firestore write
      // still in flight. Typing/focus itself never needs to defer a render —
      // captureActiveEditState/restoreActiveEditState (see renderTargetContent)
      // protect an in-progress edit through any render regardless of timing,
      // so gating on "is a box focused" here would only ever add delay, never
      // safety — including deferring forever while the user keeps typing
      // (which is exactly what made "+Add Remark & Trials" look like it
      // wasn't registering when clicked soon after typing elsewhere).
      const isEntryBusy = () => {
        const ae = document.activeElement;
        if (ae === $("target-select")) return true;
        if (state.entryActionsInFlight > 0) return true;
        if (ae?.classList.contains("pending-activity-name-input")) return true;
        // Any text field inside target-content means the user is actively typing.
        // Re-rendering now would destroy their unsaved input before the debounce saves it.
        const tc = $("target-content");
        if (tc?.contains(ae) && (ae?.tagName === "TEXTAREA" || ae?.tagName === "INPUT")) return true;
        return false;
      };
      if (isEntryBusy()) {
        state.renderPending = true;
      } else {
        // Re-check at fire time, not just now — an action button can be
        // mousedown'd (and thus guarded via entryActionsInFlight, see its
        // "mousedown" listener) in the gap between scheduling and running
        // this timeout, and rendering would destroy that button before its
        // own "click" fires, silently swallowing the click.
        setTimeout(() => {
          if (isEntryBusy()) { state.renderPending = true; }
          else { renderTargetContent(); }
        }, 0);
      }
    });

  } catch (err) {
    $("target-content").innerHTML =
      `<div class="error-msg">Could not load session.<br>${escHtml(err.message)}</div>`;
  }
}

async function leaveSession() {
  commitTextEditorSheet();
  $("text-editor-sheet").classList.add("hidden");
  // Flush any not-yet-saved typing while the Firestore listener is still
  // live, so state.sessionData reflects it before we decide what's "empty".
  await state.entryRemarkSaver?.flush();
  state.entryRemarkSaver?.cleanup();
  state.entryRemarkSaver = null;
  state.entryEnterKeyCleanup?.();
  state.entryEnterKeyCleanup = null;
  if (state.fbUnsubscribe) { state.fbUnsubscribe(); state.fbUnsubscribe = null; }
  const sessionId = state.currentSessionId;
  const data      = state.sessionData;
  const student   = state.currentStudent;
  state.currentSessionId   = null;
  state.sessionData        = null;
  state.currentStudent     = null;
  _pendingNewActivity      = null;
  state.pendingNewActivity = null;
  state.pendingNewRemark   = null;
  state.renderPending      = false;

  if (sessionId && data) {
    const stripEmpty = s => (s || "").replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").replace(/ /g, " ").trim();
    const fedcHasData = Object.values(data.fedcComments || {}).some(c => stripEmpty(c).length > 0);
    const remarkHasData = Object.values(data.remarks || {}).some(r => {
      const act = (data.activities || {})[r.activityId];
      if (!act) return false;
      const rText    = stripEmpty(r.text);
      const rNote    = stripEmpty(r.masteryNote);
      const rTrials  = (r.trials || []).filter(t => t !== null && t !== -1);
      const rOption  = r.optionScore !== undefined && r.optionScore !== null;
      const rSelected = (r.selectedOptions || []).length > 0;
      // Auto-fill "Maintain": Notes-Only puts it in text; structured puts it in masteryNote.
      // Not real data unless the user also added trials/options or changed the text.
      const isAutoFillMaintain =
        ((rText === "Maintain" && !rNote) || (rNote === "Maintain" && !rText)) &&
        rTrials.length === 0 && !rOption && !rSelected;
      if (isAutoFillMaintain) {
        const pa = (student?.targets || []).flatMap(t => t.predefinedActivities || [])
          .find(p => p.maintained && (p.name === act.activityName || (p.id && p.id === act.configId)));
        if (pa) return false;
      }
      return rText.length > 0 || rTrials.length > 0 || rNote.length > 0 || rOption || rSelected;
    });
    // Always clean up empty entries per target.
    const allTargetNames = new Set(Object.values(data.activities || {}).map(a => a.targetName));
    allTargetNames.forEach(name => {
      const target = (student?.targets || []).find(t => t.name === name);
      cleanupEmptyEntries(sessionId, data, name, target, true).catch(() => {});
    });
    // If no real data was entered, strip auto-fill "Maintain" placeholders so the calendar
    // doesn't show ✓ for a session the user immediately quit. Session itself is kept.
    if (!fedcHasData && !remarkHasData) {
      const maintainRemIds = Object.entries(data.remarks || {})
        .filter(([, r]) => {
          const rText = stripEmpty(r.text);
          const rNote = stripEmpty(r.masteryNote);
          if (!(rText === "Maintain" || rNote === "Maintain")) return false;
          if ((r.trials || []).some(t => t !== null && t !== -1)) return false;
          if (r.optionScore !== undefined && r.optionScore !== null) return false;
          if ((r.selectedOptions || []).length) return false;
          // Only delete auto-fills: activity must be maintained AND session must be on/after
          // pa.maintainedAt. Sessions before that date had "Maintain" typed by the boss — keep.
          const act = (data.activities || {})[r.activityId];
          if (!act) return false;
          const pa = (student?.targets || []).flatMap(t => t.predefinedActivities || [])
            .find(p => p.maintained && (p.name === act.activityName || (p.id && p.id === act.configId)));
          if (!pa) return false;
          return data.date >= (pa.maintainedAt || "2026-08-21");
        })
        .map(([id]) => id);
      if (maintainRemIds.length > 0) deleteRemarksBatch(sessionId, maintainRemIds).catch(() => {});
    }
  }

  showHome();
}

function updateSessionHeader() {
  const d = state.sessionData;
  if (!d) return;
  // sessionNumber is this student's lifetime individual-session count (see
  // getIndividualSessionsForStudent — independent of their group session
  // count) — no longer scoped to "this month", so it's shown plainly
  // rather than as "X of [Month]".
  $("session-meta").textContent =
    `Session ${d.sessionNumber} · ${formatDateWithDay(d.date)}${relativeDaySuffix(d.date)}`;
}


// Shared by individual + group target dropdowns, the Manage Targets reorder
// list, and the Word/Excel exports — keeps display order consistent with
// whatever the boss last dragged it to, falling back to alphabetical for
// any target predating the order field.
function uniqueTargetName(existingTargets, baseName) {
  const names = new Set(existingTargets.map(t => t.name));
  if (!names.has(baseName)) return baseName;
  let n = 1;
  while (names.has(`${baseName} (${n})`)) n++;
  return `${baseName} (${n})`;
}

function sortTargetsByOrder(targets) {
  return [...targets].sort((a, b) => (a.order ?? 0) - (b.order ?? 0) || a.name.localeCompare(b.name));
}

function populateTargetDropdown(targets) {
  const sel = $("target-select");
  const sorted = sortTargetsByOrder(targets).filter(t => !t.discontinuedOn);
  const placeholder = sorted.length === 0
    ? `<option value="" disabled selected>— no targets yet —</option>` : "";
  sel.innerHTML = placeholder +
    sorted.map(t =>
      `<option value="${escHtml(t.name)}">${escHtml(t.name)}</option>`
    ).join("") + `<option value="__add_target__">+ Add Target…</option>`;

  sel.value = state.selectedTargetName || sorted[0]?.name || "";

  const editInstBtn2 = $("btn-entry-edit-instructors");
  if (editInstBtn2) {
    editInstBtn2.classList.remove("hidden");
    editInstBtn2.onclick = () => {
      const curParticipants = state.sessionData?.participants || [];
      $("session-picker-title").textContent = "Edit Instructors";
      $("session-picker-list").innerHTML = `
        <div style="padding:1.5rem 1.25rem;display:flex;flex-direction:column;align-items:center">
          <p style="margin:0 0 1.25rem;font-weight:600;color:#374151;text-align:center">Who is facilitating this session?</p>
          <div style="width:100%;max-width:320px">
            ${INSTRUCTORS.map(inst => `
              <label style="display:flex;align-items:center;justify-content:center;gap:.85rem;padding:.75rem 0;cursor:pointer;font-size:1rem;border-bottom:1px solid #f3f4f6">
                <input type="checkbox" class="inst-edit-check" value="${inst.id}"${curParticipants.includes(inst.id) ? " checked" : ""}
                  style="width:1.2rem;height:1.2rem;accent-color:#3b82f6;cursor:pointer;flex-shrink:0">
                <span style="color:#1f2937;width:7rem">${escHtml(inst.name)}</span>
              </label>`).join("")}
          </div>
          <button class="btn-inst-save export-btn" style="margin-top:1.5rem;width:100%;padding:.85rem;font-size:1rem;text-align:center">Save</button>
        </div>`;
      $("session-picker-modal").classList.remove("hidden");
      $("session-picker-list").querySelector(".btn-inst-save").addEventListener("click", async () => {
        const participants = [...$("session-picker-list").querySelectorAll(".inst-edit-check:checked")].map(c => c.value);
        closeSessionPicker();
        await updateSessionParticipants(state.currentSessionId, participants).catch(() => {});
      });
    };
  }

  sel.onchange = async () => {
    if (sel.value === "__add_target__") {
      sel.value = state.selectedTargetName || sorted[0]?.name || "";
      showAddTargetPicker(state.currentStudent);
      return;
    }
    const prevTarget = state.selectedTargetName;
    // Flush any not-yet-saved typing on the target we're leaving before the
    // cleanup below decides what's "empty" — otherwise a just-typed remark
    // can lose the race against the still-stale local session data and get
    // deleted as if it were never entered.
    await state.entryRemarkSaver?.flush();
    state.selectedTargetName = sel.value;
    _selectedSectionIdx      = 0;
    _pendingNewActivity      = null;
    state.pendingNewActivity = null;
    state.pendingNewRemark   = null;
    // Clean up empty entries from the previous target (fire-and-forget)
    if (prevTarget && prevTarget !== sel.value) {
      const prevTargetObj = (state.currentStudent?.targets || []).find(t => t.name === prevTarget);
      cleanupEmptyEntries(state.currentSessionId, state.sessionData, prevTarget, prevTargetObj).catch(() => {});
    }
    // A <select> keeps focus after its own change event fires, and the
    // busy-check in openSession's listener treats "the dropdown is focused"
    // as "still choosing" — so leaving it focused here would block every
    // future render until the user happens to click elsewhere.
    sel.blur();
    // Render the newly-selected target synchronously NOW, before any async
    // work starts.  Auto-fills and snapshot callbacks can throw or arrive in
    // any order — this guarantees the correct target content is shown
    // immediately regardless of what happens next.
    try { renderTargetContent(); } catch(e) { console.error("renderTargetContent (sync) failed:", e); }
    // Also run auto-fills on target switch: the Firestore snapshot listener
    // only fires when session data changes, but switching targets alone doesn't
    // cause a write, so newly-added structured/mapped activities would otherwise
    // never auto-fill until a write happened.
    (async () => {
      try {
        await autoFillStructuredRemarks(state.currentStudent, state.currentSessionId);
        await autoFillMappedRemarks(state.currentStudent, state.currentSessionId);
        await autoFillMaintainedRemarks(state.currentStudent, state.currentSessionId, state.selectedTargetName);
      } catch (e) { console.error("auto-fill error on target switch:", e); }
      try { renderTargetContent(); } catch(e) { console.error("renderTargetContent (post-fill) failed:", e); }
    })();
  };
}

$("btn-back").addEventListener("click", leaveSession);

// ── Session page zoom controls ────────────────────────────────
// Stored in localStorage so zoom level persists across sessions.
// Applies CSS zoom to session-body only — header stays fixed size.
(function initSessionZoom() {
  const ZOOM_KEY  = "session-zoom";
  const ZOOM_MIN  = 0.7;
  const ZOOM_MAX  = 1.5;
  const ZOOM_STEP = 0.1;

  let zoom = Math.max(ZOOM_MIN, Math.min(ZOOM_MAX,
    parseFloat(localStorage.getItem(ZOOM_KEY) || "1") || 1));

  function applyZoom() {
    // All sizes in the app use rem, which is relative to html font-size (16px).
    // Zooming a child element doesn't move the rem baseline, so text stays the
    // same size. Changing the root font-size is the only way to scale rem values.
    document.documentElement.style.fontSize = (zoom * 16) + "px";
  }

  function setZoom(delta) {
    zoom = Math.max(ZOOM_MIN, Math.min(ZOOM_MAX,
      Math.round((zoom + delta) * 10) / 10));
    localStorage.setItem(ZOOM_KEY, zoom);
    applyZoom();
  }

  applyZoom();

  ["btn-zoom-in",     "btn-grp-zoom-in"   ].forEach(id => $( id)?.addEventListener("click", () => setZoom( ZOOM_STEP)));
  ["btn-zoom-out",    "btn-grp-zoom-out"  ].forEach(id => $( id)?.addEventListener("click", () => setZoom(-ZOOM_STEP)));
  ["btn-zoom-reset",  "btn-grp-zoom-reset"].forEach(id => $( id)?.addEventListener("click", () => { zoom = 1; localStorage.setItem(ZOOM_KEY, 1); applyZoom(); }));
})();

// ============================================================
// TARGET CONTENT RENDERING
// ============================================================

// Resolves a mapped-score activity's live display: the label naming its
// mapped target, and that target's current day average (null if unmapped,
// the mapped target was deleted, or it has no data yet today).
function resolveMappedScoreDisplay(pa, visited) {
  const mappedTarget = pa.mappedTargetId
    ? getEffectiveTargets().find(t => t.id === pa.mappedTargetId)
    : null;
  if (!mappedTarget) return { label: "Score (Not Mapped Yet)", pct: null };
  return {
    label: `Score (Mapped to ${mappedTarget.name}'s Average)`,
    pct: calcDaysAverage(mappedTarget, visited)
  };
}

// visited guards against a circular mapping chain (A maps to B, B maps back
// to A) recursing forever — direct self-mapping is already blocked in the
// Edit Target picker, but this is a defensive backstop, not the primary guard.
// One percentage per remark/activity, averaged equally — same method as
// calcViewDayAvg (View screen) and export.js's calcDailyAverage, so the live
// entry screen's day average always agrees with the View screen and every
// export instead of pooling raw trial points (which let activities with more
// trials outweigh ones with fewer, purely from incidental trial-count
// differences rather than how well each activity actually went).
function calcDaysAverage(target, visited = new Set()) {
  if (visited.has(target.id)) return null;
  visited.add(target.id);

  const avgs = [];
  const maxPts = target.maxPoints || 3;
  for (const act of getActivitiesForTarget(target.name)) {
    // "Remark Only (No Trials)" contributes nothing, whatever is still stored
    // against it — the type's guarantee shouldn't depend on the data being clean.
    if ((target.predefinedActivities || []).some(p => p.noTrials &&
        (p.name === act.activityName || (p.title && p.title === act.activityName) ||
         (act.configId && p.id === act.configId)))) continue;
    const pa = (target.predefinedActivities || []).find(p => p.isMapped &&
        (p.name === act.activityName || (act.configId && p.id === act.configId)));
    if (pa) {
      if (getRemarksForActivity(act.id).length === 0) continue;
      const mappedPct = resolveMappedScoreDisplay(pa, visited).pct;
      if (mappedPct !== null) avgs.push(mappedPct);
      continue;
    }
    const manualPa = (target.predefinedActivities || []).find(p => p.manualScore &&
        (p.name === act.activityName || (act.configId && p.id === act.configId)));
    for (const rem of getRemarksForActivity(act.id)) {
      if (manualPa) {
        const pct = parseManualScore(plainTextForEdit(rem.text || "").trim());
        if (pct !== null) avgs.push(pct);
        continue;
      }
      const trials = (rem.trials || []).filter(t => t !== -1);
      const allScores = rem.optionScore !== undefined ? [...trials, rem.optionScore] : trials;
      if (allScores.length === 0) continue;
      avgs.push(allScores.reduce((a, b) => a + b, 0) / (allScores.length * maxPts) * 100);
    }
  }
  return avgs.length > 0 ? Math.round(avgs.reduce((a, b) => a + b, 0) / avgs.length) : null;
}

function renderTargetContent() {
  if (!state.sessionData) return;
  updateSessionHeader();
  if (!state.selectedTargetName) {
    const mb = $("btn-manage-targets");
    if (mb) mb.classList.add("hidden");
    $("target-type-chip")?.classList.add("hidden");
    $("target-content").innerHTML =
      `<p class="empty-hint" contenteditable="false" style="padding:2rem;text-align:center">
        No targets added yet. Use the dropdown above to add one.
      </p>`;
    return;
  }
  const target = getEffectiveTargets().find(t => t.name === state.selectedTargetName);
  const manageBtn = $("btn-manage-targets");
  if (!target) {
    if (manageBtn) manageBtn.classList.add("hidden");
    $("target-type-chip")?.classList.add("hidden");
    return;
  }

  if (manageBtn) {
    manageBtn.classList.toggle("hidden", target.isStructured !== true && !target.predefinedActivities?.length);
  }

  $("target-type-chip")?.classList.add("hidden");

  const avg = calcDaysAverage(target);
  const avgEl = $("days-average-value");
  if (avgEl) avgEl.textContent = avg !== null ? avg + "%" : "—";

  const container = $("target-content");
  // Replacing innerHTML resets the scrolling ancestor's scrollTop to 0 in
  // every browser — capture/restore around the swap so clicking a button
  // (which has no cursor position for captureActiveEditState to preserve)
  // doesn't yank the page back to the top.
  const scrollHost = container.closest(".session-body");
  const scrollTop  = scrollHost?.scrollTop;
  // Also capture sec-main scroll — used when sidebar is expanded and sec-main is the scroll container
  const secMainScrollTop = container.querySelector(".sec-main")?.scrollTop || 0;
  const captured = captureActiveEditState(container);
  try {
    container.innerHTML = target.predefinedActivities?.length > 0
      ? renderFedcTarget(target)
      : renderRegularTarget(target);
  } catch(e) {
    console.error("renderTargetContent innerHTML failed for target:", target?.name, e);
    throw e;
  }

  attachTargetListeners(target);
  restoreActiveEditState(container, captured);
  if (scrollHost) scrollHost.scrollTop = scrollTop;
  // Restore sec-main scroll position (expanded sidebar layout)
  const newSecMain = container.querySelector(".sec-main");
  if (newSecMain && secMainScrollTop > 0) newSecMain.scrollTop = secMainScrollTop;
  // Re-evaluate which section is active after scroll is restored
  if (_triggerSecNavUpdate) _triggerSecNavUpdate();
}

// ─── SECTION SIDEBAR HELPERS ─────────────────────────────────

// Groups active top-level (non-sub) activities by their section heading.
// Activities before the first heading fall into an implicit "General" group.
// Notes are included in the section for inline rendering; headings themselves are not.
function groupPasBySections(target, dateStr, ignoreDate = false) {
  const sections = [];
  let current = null;
  for (const pa of (target.predefinedActivities || [])) {
    if (!ignoreDate && !isActivityActive(pa, dateStr)) continue;
    if (pa.parentActivity) continue;
    if (pa.isHeading || pa.isMaintainHeading) {
      current = { name: pa.name || "", headingPa: pa, pas: [] };
      sections.push(current);
    } else {
      if (!current) { current = { name: "General", headingPa: null, pas: [] }; sections.push(current); }
      current.pas.push(pa);
    }
  }
  return sections;
}

// Returns true if a predefined activity has any written data in the current individual session.
function paIsWritten(pa, target, parentName = null) {
  if ((pa.fixedRemark !== undefined || pa.isMaintain) && !pa.maintained) return false;
  const actData = findActivityByName(target.name, pa.title || pa.name, parentName, pa.id);
  if (!actData) return false;
  const stripH = t => (t || "").replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").trim();
  return getRemarksForActivity(actData.id).some(r =>
    stripH(r.text).length > 0 ||
    (r.trials || []).some(t => t !== null && t !== -1) ||
    (r.masteryNote || "").trim().length > 0
  );
}

// Returns true if a predefined activity in a group session has data for any attendee.
function grpPaIsWritten(pa, target, data, parentName = null) {
  const grpAllActs = Object.entries(data.activities || {});
  const stripH = t => (t || "").replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").trim();
  const hasContent = r =>
    stripH(r.text).length > 0 ||
    (r.trials || []).some(t => t !== null && t !== -1) ||
    (r.masteryNote || "").trim().length > 0 ||
    (r.optionScore !== undefined && r.optionScore !== null) ||
    (r.selectedOptions || []).length > 0;

  // Prefer exact configId match — if found, check that specific record only.
  if (pa.id) {
    const actId = grpAllActs.find(([, a]) => a.configId === pa.id && a.targetName === target.name)?.[0];
    if (actId) return Object.values(data.remarks || {}).some(r => r.activityId === actId && hasContent(r));
  }

  // No configId match — collect ALL records matching by name (title or details),
  // so a stale pa.name stub doesn't shadow a pa.title record that has real data.
  const candidateIds = new Set(
    grpAllActs
      .filter(([, a]) => {
        if (a.targetName !== target.name) return false;
        if (a.activityName !== (pa.title || pa.name) && a.activityName !== pa.name && a.activityName !== pa.title) return false;
        return parentName ? a.parentActivity === parentName : !a.parentActivity;
      })
      .map(([id]) => id)
  );
  if (candidateIds.size === 0) return false;
  return Object.values(data.remarks || {}).some(r => candidateIds.has(r.activityId) && hasContent(r));
}

// ─── FEDC TARGET ─────────────────────────────────────────────

function renderFedcTarget(target, _filterPaSet = null, _sectionOnly = false) {
  let html = "";

  const letters = "abcdefghij";
  let lastGroup = null;
  const allPas = target.predefinedActivities || [];
  const sessionDateForFilter = state.sessionData?.date || todayDateStr();
  let actNum = 0;

  // Self-healing: revert records that were wrongly adopted as sub-activity records while
  // a same-named top-level activity still exists in config. Only reverts when the adopted
  // record is the sole record for that name (i.e. the top-level activity has no record of
  // its own) — so we never touch records that legitimately belong to a sub-activity.
  if (state.sessionData?.activities) {
    const topLevelNames = new Set(
      allPas.filter(p => !p.parentActivity && !p.isHeading && !p.isNote && !p.isExportNote).map(p => p.name)
    );
    for (const [rid, rec] of Object.entries(state.sessionData.activities)) {
      if (rec.targetName !== target.name || !rec.parentActivity) continue;
      if (!topLevelNames.has(rec.activityName)) continue;
      const hasTopLevelRecord = Object.values(state.sessionData.activities).some(
        a => a.targetName === target.name && a.activityName === rec.activityName && !a.parentActivity
      );
      if (!hasTopLevelRecord) {
        delete rec.parentActivity;
        delete rec.configId;
        revertOrphanActivity(state.currentSessionId, rid).catch(() => {});
      }
    }
  }

  // Pre-compute active sub-activities per parent for visual grouping
  const subActsByParent = new Map();
  for (const pa of allPas) {
    if (pa.parentActivity && (pa.title || pa.name)?.trim() && isActivityActive(pa, sessionDateForFilter) && !pa.isCompleted && !pa.isArchived && !pa.isStopped) {
      if (!subActsByParent.has(pa.parentActivity)) subActsByParent.set(pa.parentActivity, []);
      subActsByParent.get(pa.parentActivity).push(pa);
    }
  }

  // Always use sidebar layout for non-filtered calls
  if (!_filterPaSet) {
    return renderFedcTargetWithSidebar(target, allPas, subActsByParent, sessionDateForFilter);
  }

  allPas.forEach((pa, idx) => {
    if (!isActivityActive(pa, sessionDateForFilter)) return;
    // Sub-activities are rendered within their parent's group block
    if (pa.parentActivity) return;
    // Note item — render inline in order, styled like a section heading
    if (pa.isNote || pa.isExportNote) {
      if (_filterPaSet && !_filterPaSet.has(pa)) return;
      if (pa.text) {
        const noteTag = pa.isExportNote
          ? `<div style="font-size:.82rem;color:#c2410c;margin-bottom:.25rem">📄 Included in Word export</div>`
          : `<div style="font-size:.82rem;color:#9a3412;margin-bottom:.25rem">🔒 This note is for ZORA's use only. Excluded from Word report</div>`;
        html += `<div class="entry-block" contenteditable="false" style="border-left:4px solid #f59e0b;">
          <div class="entry-field">
            <span class="field-label" style="color:#b45309">Note</span>
            <div style="flex:1;font-size:.93rem;font-weight:600">${noteTag}<div style="white-space:pre-wrap">${noteToHtml(pa.text)}</div></div>
          </div>
        </div>`;
      }
      return;
    }

    // Heading rows — blue, gray, or green based on headingColor property
    if (pa.isHeading || pa.isMaintainHeading) {
      if (_filterPaSet) return; // sidebar mode: section name shown in sidebar, not inline
      const isGray  = pa.headingColor === "gray" || pa.isMaintainHeading;
      const isGreen = pa.headingColor === "green";
      html += isGray
        ? `<div class="activity-group-heading" contenteditable="false" style="background:#9ca3af;border-color:#6b7280;color:#ffffff">${escHtml(pa.name || "")}</div>`
        : isGreen
        ? `<div class="activity-group-heading" contenteditable="false" style="background:#a9d18e;border-color:#70ad47;color:#1a4731">${escHtml(pa.name || "")}</div>`
        : `<div class="activity-group-heading" contenteditable="false">${escHtml(pa.name || "")}</div>`;
      return;
    }

    if (pa.isCompleted || pa.isArchived || pa.isStopped) return;
    if (_filterPaSet && !_filterPaSet.has(pa)) return;

    actNum++;
    const writtenDot = _filterPaSet
      ? (paIsWritten(pa, target)
        ? `<span style="display:inline-flex;align-items:center;justify-content:center;width:17px;height:17px;border-radius:50%;background:#22c55e;color:#fff;font-size:.6rem;font-weight:900;margin-right:.3rem;flex-shrink:0;align-self:flex-start;margin-top:.35rem">✓</span>`
        : `<span style="display:inline-flex;align-items:center;justify-content:center;width:17px;height:17px;border-radius:50%;border:2px solid #d1d5db;margin-right:.3rem;flex-shrink:0;align-self:flex-start;margin-top:.35rem"></span>`)
      : '';
    // Fixed remark activity — shown read-only with color block styling
    // pa.maintained supersedes the old fixedRemark/isMaintain flags — treat as free text.
    const isFixed = (pa.fixedRemark !== undefined || pa.isMaintain) && !pa.maintained;
    if (isFixed) {
      const fixedText = pa.fixedRemark ?? pa.maintainRemark ?? "";
      const isGrayFixed  = pa.isMaintain || pa.activityColor === "gray";
      const isGreenFixed = pa.activityColor === "green";
      const fixedStyle   = isGreenFixed
        ? 'style="background:#e2efda;border:1px solid #a9d18e;border-left:4px solid #70ad47"'
        : isGrayFixed
        ? 'style="background:#f3f4f6;border:1px solid #e5e7eb;border-left:4px solid #d1d5db"'
        : '';
      html += `<div class="entry-block entry-block-predefined" ${fixedStyle}>
        <div class="entry-field" contenteditable="false">
          <span class="field-label">Activity</span>
          <span class="field-value-fixed">${inactiveReasonBadge(pa)}<span style="color:#6b7280;font-weight:600;margin-right:.2rem">${actNum})</span>${paDisplayHtml(pa)}</span>
        </div>
        <div class="entry-field" contenteditable="false">
          <span class="field-label">Remark</span>
          <span class="field-value-fixed" style="white-space:pre-wrap;color:#111827">${formatActivityMarkup(fixedText)}</span>
        </div>
      </div>`;
      return;
    }

    // Old format: group field per activity (backward compat)
    if (pa.group && pa.group !== lastGroup) {
      lastGroup = pa.group;
      html += `<div class="activity-group-heading" contenteditable="false">${escHtml(pa.group)}</div>`;
    } else if (!pa.group) {
      lastGroup = null;
    }

    // Parent activity with sub-activities — render as a connected visual group
    const children = subActsByParent.get(pa.title || pa.name) || [];
    { const _pk2 = pa.title || pa.name; if (_pk2 && children.length === 0 && allPas.some(p => p.parentActivity === _pk2 && !p.isCompleted && !p.isArchived && !p.isStopped)) { actNum--; return; } } // parent with all subs now inactive
    if (children.length > 0) {
      const isGrayP  = pa.activityColor === "gray" || pa.isMaintainLive || pa.maintained;
      const isGreenP = pa.activityColor === "green";
      const pBorder  = isGreenP ? 'border:1px solid #a9d18e;border-left:4px solid #70ad47;background:#e2efda;'
                     : isGrayP  ? 'border:1px solid #e5e7eb;border-left:4px solid #d1d5db;background:#f3f4f6;'
                     : 'border:1px solid var(--border);border-left:5px solid var(--primary);background:var(--white);';
      html += `<div style="display:flex;flex-direction:column;gap:0">`;
      html += `<div class="entry-block" style="${pBorder}border-radius:var(--radius) var(--radius) 0 0;border-bottom:none;box-shadow:var(--shadow)">
        <div class="entry-field" contenteditable="false">
          <span class="field-label">Activity</span>
          <span class="field-value-fixed">${inactiveReasonBadge(pa)}<span style="color:#6b7280;font-weight:600;margin-right:.2rem">${actNum})</span>${paDisplayHtml(pa, true)}</span>
          <div style="display:flex;align-items:center;gap:.35rem;flex-shrink:0;align-self:flex-start">
            ${pa.activeFrom ? `<span style="font-size:.75rem;color:#9ca3af;white-space:nowrap">Created: ${fmtPeriodDate(pa.activeFrom)}</span>` : ""}
            ${pa.id ? `<button class="btn-icon btn-edit-activity-pencil" contenteditable="false" data-pa-id="${escHtml(pa.id)}" title="Edit in Edit Target" style="font-size:.85rem;opacity:.55;line-height:1">✏️</button>` : ""}
          </div>
        </div>
      </div>`;
      children.forEach((sub, si) => {
        let subActData = findActivityByName(target.name, sub.title || sub.name, pa.title || pa.name, sub.id);
        // Root cause of the alternating-display bug: a real data record (Record A, no
        // configId — created before configIds existed) coexists with an auto-fill
        // placeholder (Record B, has configId). findActivityByName always returns Record B
        // via exact-configId match, hiding Record A's real data. When Record B's empty
        // remark is cleaned up and recreated by autoFillStructuredRemarks, the display
        // briefly shows Record A, causing the visible alternation.
        // Fix: build a candidate pool that includes BOTH the configId-matched record AND
        // any no-configId record matching by name (old-format records), score all of them
        // by data richness, and always pick the winner. Then stamp the winner's configId
        // so findActivityByName finds it directly on subsequent renders.
        if (sub.id && state.sessionData) {
          const subCandidates = Object.entries(state.sessionData.activities || {}).filter(([, a]) => {
            if (a.targetName !== target.name) return false;
            if (a.configId === sub.id) return true;   // configId match
            if (a.configId) return false;              // different configId → belongs elsewhere
            const nameOk = a.activityName === sub.name || (sub.title && a.activityName === sub.title);
            if (!nameOk) return false;
            return !a.parentActivity || a.parentActivity === (pa.title || pa.name);
          });
          if (subCandidates.length > 1) {
            const subRemScore = ([actId]) => {
              let s = 0;
              for (const r of Object.values(state.sessionData.remarks || {})) {
                if (r.activityId !== actId) continue;
                s += (r.trials || []).filter(t => t !== null && t !== -1).length * 100;
                if ((r.masteryNote || "").trim()) s += 50;
                if ((r.text || "").trim()) s += 10;
                if (r.optionScore !== undefined) s += 5;
              }
              return s;
            };
            const subBest = subCandidates.reduce((a, b) => subRemScore(a) >= subRemScore(b) ? a : b);
            subActData = { id: subBest[0], ...subBest[1] };
            for (const [loserId] of subCandidates) {
              if (loserId === subBest[0]) continue;
              const loserRemIds = Object.entries(state.sessionData.remarks || {}).filter(([, r]) => r.activityId === loserId).map(([id]) => id);
              delete state.sessionData.activities[loserId];
              for (const remId of loserRemIds) delete state.sessionData.remarks[remId];
              deleteActivity(state.currentSessionId, loserId, loserRemIds).catch(() => {});
            }
            if (!subBest[1].configId && state.sessionData.activities[subBest[0]]) {
              state.sessionData.activities[subBest[0]].configId = sub.id;
              adoptOrphanActivity(state.currentSessionId, subBest[0], subBest[1].parentActivity || null, sub.id).catch(() => {});
            }
          }
        }
        if (!subActData && state.sessionData) {
          // Orphan adoption: old top-level activity was deleted from config but its
          // session record still exists. Claim it for this sub-activity by writing
          // parentActivity (and configId) onto it so future lookups find it correctly.
          // Guard: only adopt if no live top-level predefined activity with this name
          // still exists — if one does, its record belongs to it, not to this sub-activity.
          const hasLiveTopLevel = allPas.some(p =>
            !p.parentActivity && !p.isHeading && !p.isNote && !p.isExportNote && p.name === sub.name
          );
          if (!hasLiveTopLevel) {
            const orphan = Object.entries(state.sessionData.activities || {})
              .find(([, a]) => a.targetName === target.name && a.activityName === sub.name && !a.parentActivity && !a.configId);
            if (orphan) {
              const [oid, odata] = orphan;
              state.sessionData.activities[oid] = { ...odata, parentActivity: pa.name, ...(sub.id ? { configId: sub.id } : {}) };
              adoptOrphanActivity(state.currentSessionId, oid, pa.name, sub.id || null).catch(() => {});
              subActData = { id: oid, ...state.sessionData.activities[oid] };
            }
          }
        }
        const subActId   = subActData ? subActData.id : null;
        const subRemarks = subActId ? getRemarksForActivity(subActId) : [];
        const subPending = state.pendingNewRemark?.pendingKey === sub.name;
        const subLabel   = letters[si];
        const isLast     = si === children.length - 1;
        const subRadius  = isLast ? '0 0 var(--radius) var(--radius)' : '0';
        const subWrittenDot = _filterPaSet
          ? (paIsWritten(sub, target, pa.title || pa.name)
            ? `<span style="display:inline-flex;align-items:center;justify-content:center;width:17px;height:17px;border-radius:50%;background:#22c55e;color:#fff;font-size:.6rem;font-weight:900;margin-right:.3rem;flex-shrink:0;align-self:flex-start;margin-top:.45rem">✓</span>`
            : `<span style="display:inline-flex;align-items:center;justify-content:center;width:17px;height:17px;border-radius:50%;border:2px solid #d1d5db;margin-right:.3rem;flex-shrink:0;align-self:flex-start;margin-top:.45rem"></span>`)
          : '';
        html += `<div class="entry-block" style="border:1px solid var(--border);border-left:5px solid var(--primary);background:var(--white);border-top:1px solid var(--border);border-radius:${subRadius};box-shadow:var(--shadow)">
          <div class="entry-field" contenteditable="false">
            ${subWrittenDot}<span style="flex-shrink:0;align-self:flex-start;margin-top:.45rem;display:inline-block;background:#dbeafe;color:#1e40af;border-radius:.4rem;padding:.12rem .5rem;font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.04em;white-space:nowrap">Subactivity</span>
            <span class="field-value-fixed"><span style="color:#1e40af;font-weight:700;margin-right:.25rem">${subLabel})</span>${inactiveReasonBadge(sub)}${paDisplayHtml(sub)}</span>
            ${sub.activeFrom ? `<span style="font-size:.75rem;color:#9ca3af;white-space:nowrap;flex-shrink:0;align-self:flex-start;margin-top:.45rem">Created: ${fmtPeriodDate(sub.activeFrom)}</span>` : ""}
          </div>`;
        const _subNoOpts = (sub.remarkHasNote || sub.optionsMulti) && parseOpts(getActivityInlineOptions(sub)).length === 0;
        if (_subNoOpts) {
          html += `<div class="entry-field" contenteditable="false">
            <span class="field-label">${sub.optionsMulti ? "CHECKBOXES" : "MULTIPLE CHOICE"}</span>
            <span style="color:#9ca3af;font-style:italic;font-size:.88rem">&lt;Please Add Options in Edit Target&gt;</span>
          </div>`;
        } else {
        for (const rem of subRemarks) {
          html += renderRemarkFields(rem, target, getActivityInlineOptions(sub), sub.sentenceStarter || null, sub.optionsMulti || false, null, sub.remarkHasNote || false, false, sub.optionScores || null, !!(sub.manualScore || sub.remarkHasNote || sub.inlineOptions || sub.remarkPresetId), sub.noteSentenceStarter || null);
        }
        if (subPending) {
          html += renderPendingRemarkFields(sub.name, subActId, sub.name, idx, target);
        } else {
          html += `<button class="btn-add-remark" contenteditable="false"
            data-pending-key="${escHtml(sub.name || sub.title)}"
            data-act-id="${subActId || ""}"
            data-pa-name="${escHtml(sub.name || sub.title)}"
            data-pa-order="${idx}"
            data-pa-parent="${escHtml(pa.name || pa.title)}"
            data-cfg-id="${escHtml(sub.id || "")}"
            data-target="${escHtml(target.name)}">+ Add Remark &amp; Trials</button>`;
        }
        } // end _subNoOpts else
        html += `</div>`;
      });
      html += `</div>`;
      return;
    }

    const pendingKey = pa.name || pa.title;
    const actData    = findActivityByName(target.name, pa.name || pa.title, null, pa.id);
    // Claim unlinked records in local state immediately so the next same-named predefined
    // activity in the loop can't find and share the same Firestore record.
    // Also persist the configId to Firestore so future session opens can find this
    // activity by configId (not just by name), preventing duplicate activity creation.
    if (actData && pa.id && !actData.configId && state.sessionData?.activities?.[actData.id]) {
      state.sessionData.activities[actData.id].configId = pa.id;
      if (state.currentSessionId) {
        adoptOrphanActivity(state.currentSessionId, actData.id, actData.parentActivity || null, pa.id).catch(() => {});
      }
    }
    const actId      = actData ? actData.id : null;
    const remarks    = actId ? getRemarksForActivity(actId) : [];
    const isPending  = state.pendingNewRemark?.pendingKey === pendingKey;
    const mappedInfo = pa.isMapped ? resolveMappedScoreDisplay(pa) : null;

    const isGrayActivity  = pa.activityColor === "gray" || pa.isMaintainLive || pa.maintained;
    const isGreenActivity = pa.activityColor === "green";
    const activityStyle = isGrayActivity  ? ' style="background:#f3f4f6;border:1px solid #e5e7eb;border-left:4px solid #d1d5db"'
                        : isGreenActivity ? ' style="background:#e2efda;border:1px solid #a9d18e;border-left:4px solid #70ad47"'
                        : '';
    html += `<div class="entry-block entry-block-predefined"${activityStyle}>
      <div class="entry-field" contenteditable="false">
        ${writtenDot}<span class="field-label">Activity</span>
        <span class="field-value-fixed">${inactiveReasonBadge(pa)}<span style="color:#6b7280;font-weight:600;margin-right:.2rem">${actNum})</span>${paDisplayHtml(pa, true)}</span>
        <div style="display:flex;align-items:center;gap:.35rem;flex-shrink:0;align-self:flex-start">
          ${pa.activeFrom ? `<span style="font-size:.75rem;color:#9ca3af;white-space:nowrap">Created: ${fmtPeriodDate(pa.activeFrom)}</span>` : ""}
          ${pa.id ? `<button class="btn-icon btn-edit-activity-pencil" contenteditable="false" data-pa-id="${escHtml(pa.id)}" title="Edit in Edit Target" style="font-size:.85rem;opacity:.55;line-height:1">✏️</button>` : ""}
        </div>
      </div>`;

    if (pa.actNote && pa.actNote.trim()) {
      html += `<div class="entry-field" contenteditable="false">
        <span class="field-label">Note</span>
        <span class="field-value-note">${formatActivityMarkup(pa.actNote)}</span>
      </div>`;
    }

    // Reference notes (a, b, c… sub-items)
    if (pa.note && pa.note.length > 0) {
      const noteHtml = pa.note.map((line, i) =>
        `${letters[i]}) ${escHtml(line)}`
      ).join("<br>");
      html += `<div class="activity-note" contenteditable="false">${noteHtml}</div>`;
    }

    if (pa.predefinedRemarks) {
      for (const predRemName of pa.predefinedRemarks) {
        const rem = actId ? findRemarkByPredefinedKey(actId, predRemName) : null;
        if (rem) {
          html += renderPredefinedRemarkFields(rem, predRemName, target);
        } else {
          html += renderGhostRemarkFields(predRemName, actId, pa, idx, target);
        }
      }
    } else {
      const _paNoOpts = (pa.remarkHasNote || pa.optionsMulti) && parseOpts(getActivityInlineOptions(pa)).length === 0;
      if (_paNoOpts) {
        html += `<div class="entry-field" contenteditable="false">
          <span class="field-label">${pa.optionsMulti ? "CHECKBOXES" : "MULTIPLE CHOICE"}</span>
          <span style="color:#9ca3af;font-style:italic;font-size:.88rem">&lt;Please Add Options in Edit Target&gt;</span>
        </div>`;
      } else {
      for (const rem of remarks) {
        // Self-heal: data stranded in masteryNote by an accidental type-change roundtrip back to Notes Only
        if (!pa.inlineOptions && !pa.remarkPresetId && !pa.optionsMulti && !pa.remarkHasNote && !pa.manualScore
            && !rem.text && rem.masteryNote) {
          const rescued = rem.masteryNote;
          rem.text = rescued;
          rem.masteryNote = "";
          if (state.sessionData?.remarks?.[rem.id]) {
            state.sessionData.remarks[rem.id].text = rescued;
            state.sessionData.remarks[rem.id].masteryNote = "";
          }
          const sid = state.currentSessionId;
          if (sid) migrateRemarksToNote(sid, { [rem.id]: { text: rescued, masteryNote: "" } }).catch(() => {});
        }
        html += renderRemarkFields(rem, target, getActivityInlineOptions(pa), pa.sentenceStarter || null, pa.optionsMulti || false, mappedInfo, pa.remarkHasNote || false, pa.manualScore || false, pa.optionScores || null, !!(pa.manualScore || pa.remarkHasNote || pa.inlineOptions || pa.remarkPresetId), pa.noteSentenceStarter || null, pa.noTrials || false);
      }
      if (isPending) {
        html += renderPendingRemarkFields(pendingKey, actId, pa.name, idx, target);
      } else if (pa.maintained && remarks.length === 0 && !getActivityInlineOptions(pa) && !pa.optionsMulti && !pa.manualScore) {
        const addLabel = "Remark &amp; Trials";
        // Only show "Maintain" default and auto-fill on/after the maintained date
        const _maintAt = pa.maintainedAt || "2026-08-21";
        const _showMaintDefault = sessionDateForFilter >= _maintAt;
        html += `<div class="entry-divider" contenteditable="false"></div>
        <div class="entry-field" contenteditable="false">
          <span class="field-label">Remark</span>
          <textarea class="field-input${_showMaintDefault ? " maintained-remark-pending" : ""}" rows="1"
            data-act-id="${actId || ""}"
            data-pa-name="${escHtml(pa.name || pa.title)}"
            data-pa-order="${idx}"
            data-cfg-id="${escHtml(pa.id || "")}"
            data-target="${escHtml(target.name)}">${_showMaintDefault ? "Maintain" : ""}</textarea>
        </div>
        <button class="btn-add-remark" contenteditable="false"
          data-pending-key="${escHtml(pendingKey)}"
          data-act-id="${actId || ""}"
          data-pa-name="${escHtml(pa.name || pa.title)}"
          data-pa-order="${idx}"
          data-is-mapped="${pa.isMapped ? "1" : ""}"
          data-is-maintained="${_showMaintDefault ? "1" : ""}"
          data-cfg-id="${escHtml(pa.id || "")}"
          data-target="${escHtml(target.name)}">+ Add ${addLabel}</button>`;
      } else {
        const addLabel = pa.isMapped ? "Score" : pa.manualScore ? "Remark &amp; Score" : pa.noTrials ? "Remark" : "Remark &amp; Trials";
        html += `<button class="btn-add-remark" contenteditable="false"
          data-pending-key="${escHtml(pendingKey)}"
          data-act-id="${actId || ""}"
          data-pa-name="${escHtml(pa.name || pa.title)}"
          data-pa-order="${idx}"
          data-is-mapped="${pa.isMapped ? "1" : ""}"
          data-cfg-id="${escHtml(pa.id || "")}"
          data-target="${escHtml(target.name)}">+ Add ${addLabel}</button>`;
      }
      } // end _paNoOpts else
    }

    html += `</div>`;
  });

  if (!_sectionOnly) {
  // Extra (session-only) activities + add button (renderExtraActivitiesSection
  // handles all non-predefined activities, the pending-name input, and the
  // "+ Add Activity" button — no separate manualActivities loop needed here).
  html += renderExtraActivitiesSection(target);

  // Inactive predefined activities section
  const inactivePas = allPas.filter(pa =>
    !isActivityActive(pa, sessionDateForFilter) && !pa.isCompleted && !pa.isStopped &&
    (!pa.isArchived || pa.discontinuedOn)
  );
  if (inactivePas.length > 0) {
    // Top-level inactive items (not sub-activities)
    const inactiveTopLevel = inactivePas.filter(pa => !pa.parentActivity);
    const inactiveTopLevelKeys = new Set(
      inactiveTopLevel
        .filter(p => !p.isHeading && !p.isMaintainHeading && !p.isNote && !p.isExportNote)
        .map(p => p.title || p.name).filter(Boolean)
    );
    // Orphan subs: subs whose parent is still active. Group by parent+section so the
    // parent appears as the heading (with relevant subs indented) instead of
    // each sub appearing alone with "from Parent Activity: X".
    const _orphanSubGroups = new Map();
    for (const pa of inactivePas) {
      if (!pa.parentActivity || inactiveTopLevelKeys.has(pa.parentActivity)) continue;
      const sec = (pa.masteredOn || pa.inactiveReason === 'mastered') ? 'mastered'
        : (pa.discontinuedOn || pa.inactiveReason === 'discontinued') ? 'discontinued'
        : 'other';
      const key = `${pa.parentActivity}|${sec}`;
      if (!_orphanSubGroups.has(key)) {
        const parentPa = allPas.find(p => (p.title || p.name) === pa.parentActivity && !p.parentActivity) || null;
        _orphanSubGroups.set(key, { parentPa, parentKey: pa.parentActivity, subs: [] });
      }
      _orphanSubGroups.get(key).subs.push(pa);
    }
    const _orphanGroupsFor = sec => [..._orphanSubGroups.entries()]
      .filter(([k]) => k.endsWith(`|${sec}`)).map(([, v]) => v);

    const realInactive = inactiveTopLevel.filter(pa => !pa.isNote && !pa.isExportNote && !pa.isHeading && !pa.isMaintainHeading);
    const masteredPas     = realInactive.filter(pa => pa.masteredOn || pa.inactiveReason === 'mastered');
    const discontinuedPas = realInactive.filter(pa => pa.discontinuedOn || pa.inactiveReason === 'discontinued');
    const otherPas        = realInactive.filter(pa => !pa.masteredOn && !pa.discontinuedOn && !pa.inactiveReason);
    const _countPa = pa => {
      const subs = allPas.filter(p => p.parentActivity === (pa.title || pa.name) && !p.isCompleted && !p.isArchived && !p.isStopped);
      return subs.length > 0 ? subs.length : 1;
    };
    const renderSection = (label, color, pas, secKey, dateHeader) => {
      const orphanGroups = _orphanGroupsFor(secKey);
      const totalCount = pas.reduce((acc, pa) => acc + _countPa(pa), 0)
        + orphanGroups.reduce((acc, g) => acc + g.subs.length, 0);
      return renderInactiveStatusSection({ label, color, pas, orphanGroups, allPas, dateHeader, totalCount });
    };
    html += `<div style="margin-top:.4rem">
      ${renderSection('Mastered Activities', '#059669', masteredPas, 'mastered', 'Mastered On')}
      ${renderSection('Discontinued Activities', '#dc2626', discontinuedPas, 'discontinued', 'Discontinued On')}
      ${renderSection('Inactive Activities', '#6b7280', otherPas, 'other', 'Date')}
    </div>`;
  }
  } // end if (!_sectionOnly)

  return html;
}

// ─── SECTION SIDEBAR LAYOUT (individual session) ─────────────

function renderFedcTargetWithSidebar(target, allPas, subActsByParent, sessionDateForFilter) {
  const sections = groupPasBySections(target, sessionDateForFilter);
  if (!sections.length) return renderFedcTarget(target, new Set());

  if (_selectedSectionIdx >= sections.length) _selectedSectionIdx = 0;

  let totalActs = 0, totalWritten = 0;
  const sectionStats = sections.map(grp => {
    let secTotal = 0, secWritten = 0;
    for (const pa of grp.pas) {
      if (pa.isNote || pa.isExportNote || pa.isCompleted || pa.isArchived || pa.isStopped) continue;
      const children = subActsByParent.get(pa.title || pa.name) || [];
      if (children.length > 0) {
        for (const sub of children) {
          if (sub.isCompleted || sub.isArchived || sub.isStopped) continue;
          secTotal++;
          if (paIsWritten(sub, target, pa.title || pa.name)) secWritten++;
        }
      } else if (!pa.noRemark) {
        const _pk2 = pa.title || pa.name;
        if (!(_pk2 && allPas.some(p => p.parentActivity === _pk2 && !p.isCompleted && !p.isArchived && !p.isStopped))) {
          secTotal++;
          if (paIsWritten(pa, target)) secWritten++;
        }
      }
    }
    totalActs += secTotal;
    totalWritten += secWritten;
    return { total: secTotal, written: secWritten };
  });

  const pct = totalActs > 0 ? Math.round(totalWritten / totalActs * 100) : 0;

  // Hide sections whose activities are all invisible (before start date / mastered / discontinued)
  const _visData = sections.map((s, i) => ({ s, st: sectionStats[i] })).filter(({ st }) => st.total > 0);
  if (_visData.length === 0) return renderFedcTarget(target, new Set());
  if (_selectedSectionIdx >= _visData.length) _selectedSectionIdx = 0;

  // Render all sections continuously — each section wrapped in an anchor div for scroll tracking
  let allSectionsHtml = '';
  _visData.forEach(({ s: section }, i) => {
    const sectionPaSet = new Set(section.pas);
    // _sectionOnly=true skips extras/inactive — those are rendered once at the end
    const secContent = renderFedcTarget(target, sectionPaSet, true);
    allSectionsHtml += `<div class="sec-scroll-section" data-sec-anchor="${i}" style="display:flex;flex-direction:column;gap:.85rem">
      <div contenteditable="false" style="font-size:1.43rem;font-weight:700;color:#374151;padding-bottom:.5rem;border-bottom:2px solid #e5e7eb">${escHtml(section.name)}</div>
      ${secContent}
    </div>`;
  });
  // Extras (session-only activities + Add button) and inactive section — shown once after all sections
  // renderFedcTarget with an empty Set skips all predefined activities but runs extras+inactive
  allSectionsHtml += renderFedcTarget(target, new Set());

  if (_sidebarCollapsed) {
    return `<div class="sec-layout" contenteditable="false" style="display:flex;flex-direction:column;gap:0">
      <div contenteditable="false" style="display:flex;align-items:center;gap:.6rem;padding:.3rem 0 .5rem;margin-bottom:.4rem;border-bottom:1px solid #e5e7eb">
        <button class="sec-toggle-btn" contenteditable="false" title="Show sections" onmousedown="event.preventDefault()" style="background:none;border:1.5px solid var(--primary);border-radius:.4rem;cursor:pointer;font-size:1.21rem;color:var(--primary);padding:.2rem .4rem;line-height:1;flex-shrink:0">☰</button>
        <span style="font-size:.9rem;font-weight:700;color:#374151;white-space:nowrap">${totalWritten} of ${totalActs} written</span>
        <div style="flex:1;background:#e5e7eb;border-radius:9999px;height:4px;max-width:100px">
          <div style="background:var(--primary);height:100%;width:${pct}%;border-radius:9999px"></div>
        </div>
      </div>
      <div class="sec-main" style="display:flex;flex-direction:column;gap:.85rem;padding-bottom:2.5rem">
        ${allSectionsHtml}
      </div>
    </div>`;
  }

  // Sidebar: fixed header (pinned) + scrollable nav buttons below
  // sec-layout uses flex:1 + min-height:0 so the flex chain gives it a real height
  // from the session-body → target-content → sec-layout chain, allowing sec-main
  // to scroll independently. This is more reliable than position:sticky inside
  // an overflow:hidden ancestor (.screen { overflow:hidden } breaks sticky).
  let sidebarFixedHtml = `<div style="padding:.5rem .9rem .45rem;border-bottom:1px solid #e5e7eb;display:flex;align-items:center;justify-content:space-between;flex-shrink:0">
    <span style="font-size:.7rem;text-transform:uppercase;letter-spacing:.05em;color:#9ca3af;font-weight:600">Menu</span>
    <button class="sec-toggle-btn" contenteditable="false" title="Hide sections" style="background:none;border:none;cursor:pointer;font-size:1.3rem;color:#9ca3af;line-height:1;padding:.05rem .2rem;flex-shrink:0">×</button>
  </div>
  <div style="padding:.6rem .9rem .5rem;border-bottom:1px solid #e5e7eb;flex-shrink:0">
    <div style="font-size:.88rem;font-weight:700;color:#111827;margin-bottom:.35rem">${totalWritten} of ${totalActs} written</div>
    <div style="background:#e5e7eb;border-radius:9999px;height:5px"><div style="background:var(--primary);height:100%;width:${pct}%;border-radius:9999px"></div></div>
  </div>`;

  let sidebarNavHtml = '';
  _visData.forEach(({ s: grp, st: { total, written } }, i) => {
    // First section active initially; scroll listener updates dynamically
    const isAct = i === 0;
    sidebarNavHtml += `<button class="sec-nav-btn" data-sec-idx="${i}" contenteditable="false" onmousedown="event.preventDefault()"
      style="width:100%;text-align:left;padding:.6rem .9rem;border:none;border-bottom:1px solid #f3f4f6;cursor:pointer;background:${isAct ? 'var(--primary-light)' : 'transparent'};border-left:3px solid ${isAct ? 'var(--primary)' : 'transparent'};border-radius:0">
      <div style="font-size:.82rem;font-weight:${isAct ? '700' : '500'};color:${isAct ? 'var(--primary-dark)' : '#374151'};word-break:break-word;line-height:1.3">${escHtml(grp.name)}</div>
      <div style="font-size:.72rem;color:#9ca3af;margin-top:.15rem">${written}/${total}</div>
    </button>`;
  });

  // sec-layout: flex:1 + min-height:0 so it fills the flex chain without overflowing
  // sec-sidebar: flex-column with pinned top and scrollable nav list
  // sec-main: flex:1 + overflow-y:auto — the actual scroll container for section content
  return `<div class="sec-layout" style="display:flex;gap:0;align-items:stretch;flex:1;min-height:0">
    <div class="sec-sidebar" contenteditable="false" style="width:190px;flex-shrink:0;border-right:1px solid #e5e7eb;background:#fafafa;display:flex;flex-direction:column;min-height:0;overflow:hidden">
      ${sidebarFixedHtml}
      <div style="flex:1;overflow-y:auto">${sidebarNavHtml}</div>
    </div>
    <div class="sec-main" style="flex:1;min-width:0;min-height:0;padding-left:.75rem;padding-bottom:2.5rem;overflow-y:auto;display:flex;flex-direction:column;gap:.85rem">
      ${allSectionsHtml}
    </div>
  </div>`;
}

// ─── EXTRA ACTIVITIES (session-only) ─────────────────────────
// Guards against iOS ghost-click (synthesized click ~300ms after touchend
// landing on the freshly-rebuilt button and creating a second activity).
let _addActivityInFlight = false;
// Pending new activity — local only, NOT written to Firestore until the user
// types a name. Stores { actId, targetName, order, typedName, typedDetails, pendingIsBold, pendingIsUnderline }.
let _pendingNewActivity = null;

// Active section index and collapse state for the sidebar layout.
let _selectedSectionIdx = 0;
let _selectedGroupSectionIdx = 0;
let _sidebarCollapsed = true;
let _grpSidebarCollapsed = true;
// Scroll listeners for section auto-highlight — stored so they can be removed on re-render.
let _secScrollListener = null;
let _grpSecScrollListener = null;
// Force-update functions for nav highlighting (called after scroll position is restored).
let _triggerSecNavUpdate = null;
let _triggerGrpSecNavUpdate = null;

// A remark "has content" if its text (stripped of HTML), its mastery note, or a
// real trial is non-empty.
//
// This used to read r.remarkText and r.note — field names that don't exist on a
// remark. Every caller passes a raw Firestore remark, whose fields are text /
// masteryNote / trials, so the function always returned falsy: it never once
// reported that a remark had content. That made the snapshot sweep above delete
// nameless extra activities even when they held real typed remarks. Read the
// actual field names, and count trials as content too.
function remarkHasContent(r) {
  if (!r) return false;
  const strip = s => (s || "").replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").replace(/&[a-z]+;/gi, " ").trim();
  return strip(r.text).length > 0
      || strip(r.masteryNote).length > 0
      || (r.trials || []).some(t => t !== null && t !== -1)
      || r.optionScore !== undefined;
}

// Builds a test for "predefined session record whose config entry has gone
// missing, and which still holds real data". Used by the group entry screens;
// see renderExtraActivitiesSection for why these must keep rendering.
function makeStrandedPredefinedTest(target, data) {
  const pas      = target.predefinedActivities || [];
  const cfgIds   = new Set(pas.map(p => p.id).filter(Boolean));
  const cfgNames = new Set(pas.flatMap(p => [p.name, p.title]).filter(Boolean));
  const hasData  = actId => Object.values(data.remarks || {}).some(r =>
    r.activityId === actId && (
      (r.text || "").replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").trim().length > 0 ||
      (r.trials || []).some(t => t !== null && t !== -1) ||
      (r.masteryNote || "").replace(/<[^>]*>/g, "").trim().length > 0
    ));
  return (actId, a) => a.isPredefined && !a.parentActivity
    && !((a.configId && cfgIds.has(a.configId))
         || cfgNames.has(a.activityName) || cfgNames.has(a.activityTitle))
    && hasData(actId);
}

// Renders one collapsed status section (Mastered / Discontinued / Inactive) at
// the bottom of a Start Session screen as a table, so every activity lines up
// with its own date instead of the date floating at the end of a wrapped line.
//
// Shared by the individual and group screens so the two can't drift apart.
//
// Sub-activities get their OWN rows rather than being nested in the parent's
// cell: a sub can be mastered or discontinued on a different date from its
// parent, so each needs its own date cell. A parent that has subs shows no date
// of its own — the sub rows carry them.
//
// Note that multi-line activity details (e.g. "a. Movement / b. Written / c.
// Application - worksheets") are NOT sub-activities — they're the activity's own
// details text and stay inside the Activity cell, which is why it keeps
// white-space:pre-wrap.
function renderInactiveStatusSection({ label, color, pas, orphanGroups, allPas, dateHeader, totalCount }) {
  if (pas.length === 0 && orphanGroups.length === 0) return '';

  const _cellBase   = 'padding:.32rem .5rem;border:1px solid #000;vertical-align:top';
  const _numCell    = `${_cellBase};font-size:.78rem;font-weight:700;color:#6b7280;white-space:nowrap;width:2.6rem;text-align:center`;
  const _subNumCell = `${_cellBase};font-size:.78rem;font-weight:700;color:#0369a1;white-space:nowrap;text-align:center`;
  const _nameCell   = `${_cellBase};font-size:.88rem;line-height:1.45;white-space:pre-wrap;word-break:break-word`;
  const _dateCell   = `${_cellBase};font-size:.78rem;white-space:nowrap;text-align:center;width:7.5rem`;

  const dateText = pa => {
    if (pa.masteredOn)     return `<span style="color:#059669;font-weight:600">${fmtPeriodDate(pa.masteredOn)}</span>`;
    if (pa.discontinuedOn) return `<span style="color:#dc2626;font-weight:600">${fmtPeriodDate(pa.discontinuedOn)}</span>`;
    // Inactive Activities have neither date - that is what puts them in that
    // bucket. Show the active-period boundary that makes them inactive instead
    // of an empty dash, so the column says why rather than nothing.
    if (pa.activeTo)   return `<span style="color:#6b7280">Until ${fmtPeriodDate(pa.activeTo)}</span>`;
    if (pa.activeFrom) return `<span style="color:#6b7280">From ${fmtPeriodDate(pa.activeFrom)}</span>`;
    return `<span style="color:#d1d5db">—</span>`;
  };
  const nameOf = pa => paDisplayHtml(pa, true) || `<em style="color:#9ca3af;font-size:.85rem">Untitled</em>`;

  const row = (pa, marker, isSub) => `<tr>
      <td style="${isSub ? _subNumCell : _numCell}">${marker}</td>
      <td style="${_nameCell}${isSub ? ';padding-left:1.5rem' : ''}">${nameOf(pa)}</td>
      <td style="${_dateCell}">${dateText(pa)}</td>
    </tr>`;

  const subsOf = pa => allPas.filter(p =>
    p.parentActivity === (pa.title || pa.name) && !p.isCompleted && !p.isArchived && !p.isStopped);
  const subRows = subs => subs.map((sub, si) => row(sub, `${String.fromCharCode(97 + si)})`, true)).join('');

  // Group the rows under the section heading each activity sits beneath, the way
  // the Start Session list itself does. A heading with nothing under it in this
  // status group is not printed, and numbering restarts inside each section -
  // matching how activities are numbered on the entry screen.
  const headingOf = new Map();
  {
    let current = null;
    for (const pa of allPas) {
      if (pa.isHeading || pa.isMaintainHeading) { current = pa.title || pa.name || ""; continue; }
      headingOf.set(pa, current);
    }
  }

  const sectionBand = title => `<tr><td colspan="3" style="${_cellBase};background:#eef2ff;font-size:.82rem;font-weight:700;color:#3730a3">${escHtml(title)}</td></tr>`;

  // Keep the order the activities appear in, but break into runs by heading.
  const renderable = pas.filter(pa => !(pa.isHeading || pa.isMaintainHeading || pa.isNote || pa.isExportNote));
  const groups = [];
  for (const pa of renderable) {
    const h = headingOf.get(pa) ?? null;
    if (!groups.length || groups[groups.length - 1].heading !== h) groups.push({ heading: h, items: [] });
    groups[groups.length - 1].items.push(pa);
  }

  const topRows = groups.map(g => {
    let n = 0;
    const body = g.items.map(pa => {
      n++;
      const subs = subsOf(pa);
      // A parent with subs carries no date of its own — see the note above.
      return subs.length === 0
        ? row(pa, `${n})`, false)
        : `<tr>
            <td style="${_numCell}">${n})</td>
            <td style="${_nameCell}">${nameOf(pa)}</td>
            <td style="${_dateCell}"><span style="color:#d1d5db">—</span></td>
          </tr>${subRows(subs)}`;
    }).join('');
    return (g.heading ? sectionBand(g.heading) : '') + body;
  }).join('');

  // Sub-activities whose parent is still active: the parent heads the group for
  // context only, so it gets no number and no date.
  let orphanNum = 0;
  const orphanRows = orphanGroups.map(({ parentPa, parentKey, subs }) => {
    orphanNum++;
    const parentName = parentPa ? (paDisplayHtml(parentPa, true) || escHtml(parentKey)) : escHtml(parentKey);
    return `<tr>
        <td style="${_numCell}">${orphanNum})</td>
        <td style="${_nameCell}">${parentName}</td>
        <td style="${_dateCell}"><span style="color:#d1d5db">—</span></td>
      </tr>${subRows(subs)}`;
  }).join('');

  const _th = 'padding:.3rem .5rem;font-size:.72rem;font-weight:700;color:#374151;text-transform:uppercase;letter-spacing:.02em;border:1px solid #000;background:#f3f4f6;text-align:center;vertical-align:middle';
  return `<div style="margin-top:.5rem">
    <button class="btn-inactive-toggle" contenteditable="false" style="display:flex;align-items:center;gap:.4rem;width:100%;padding:.4rem .6rem;background:none;border:1px dashed #d1d5db;border-radius:.4rem;cursor:pointer;font-size:.8rem;color:${color};text-align:left">
      <span class="inactive-chevron" style="font-size:.7rem">▶</span> ${label} (${totalCount})
    </button>
    <div class="inactive-list" style="display:none;flex-direction:column;margin-top:.35rem">
      <div style="overflow-x:auto;width:100%">
        <table contenteditable="false" style="width:100%;border-collapse:collapse;border:1px solid #000">
          <thead><tr>
            <th style="${_th}">No.</th>
            <th style="${_th}">Activity</th>
            <th style="${_th}">${escHtml(dateHeader)}</th>
          </tr></thead>
          <tbody>${topRows}${orphanRows}</tbody>
        </table>
      </div>
    </div>
  </div>`;
}

// An extra (session-only) activity is an orphan if it has no name and none of
// its remarks contain any actual content. Empty-name activities with empty
// remark records (from "+Add Remark & Trials" being clicked then abandoned)
// still qualify as orphans.
function isOrphanExtraActivity(a) {
  if (a.isPredefined || a.parentActivity || (a.activityName || "").trim() || (a.activityTitle || "").trim()) return false;
  return !getRemarksForActivity(a.id).some(remarkHasContent);
}

// Renders non-predefined (session-only) activities + the "Add Activity" button.
// Used by both renderFedcTarget (appended after predefined activities) and
// renderRegularTarget (which has nothing else to render).
function renderExtraActivitiesSection(target) {
  // A predefined record whose config entry no longer exists is stranded: nothing
  // above renders it, so its remarks would be invisible in this session. Deleting
  // an activity on purpose purges its session records (the confirm-by-typing
  // flow), so a stranded record that still holds data is always accidental
  // damage — show it here rather than let real work disappear.
  const _pas      = target.predefinedActivities || [];
  const _cfgIds   = new Set(_pas.map(p => p.id).filter(Boolean));
  const _cfgNames = new Set(_pas.flatMap(p => [p.name, p.title]).filter(Boolean));
  const isStranded = a => a.isPredefined && !a.parentActivity
    && !((a.configId && _cfgIds.has(a.configId))
         || _cfgNames.has(a.activityName) || _cfgNames.has(a.activityTitle))
    && getRemarksForActivity(a.id).some(remarkHasContent);

  const seen = new Set();
  const extraActs = getActivitiesForTarget(target.name)
    .filter(a => {
      if (a.parentActivity) return false;
      if (a.isPredefined && !isStranded(a)) return false;
      // Hide any orphan activities (empty name + no substantive remarks) that
      // slipped through from old sessions — the snapshot stripping should have
      // removed them already, but this is a belt-and-suspenders guard.
      if (isOrphanExtraActivity(a)) return false;
      if (seen.has(a.id)) return false;
      seen.add(a.id);
      return true;
    });
  let html = "";
  const hasPending = _pendingNewActivity && _pendingNewActivity.targetName === target.name;
  for (const act of extraActs) {
    const isPending = state.pendingNewRemark?.pendingKey === act.id;
    const remarks   = getRemarksForActivity(act.id);
    const titleStyle = `${act.activityIsBold ? 'font-weight:700;' : ''}${act.activityIsUnderline ? 'text-decoration:underline;' : ''}`;
    html += `<div class="entry-block" data-act-id="${escHtml(act.id)}">
      <div class="entry-field" style="align-items:flex-start">
        <span class="field-label" contenteditable="false" style="padding-top:.3rem">Activity</span>
        <div style="flex:1;display:flex;flex-direction:column;gap:.3rem">
          <div style="display:flex;align-items:center;gap:.4rem">
            <span style="font-size:.76rem;color:#9ca3af;flex-shrink:0;min-width:3rem">Title</span>
            <input type="text" class="field-input activity-title-input"
              data-act-id="${escHtml(act.id)}"
              data-saved-html="${escHtml(act.activityTitle || '')}"
              placeholder="Chart / report label"
              value="${escHtml(act.activityTitle || '')}"
              style="flex:1;${titleStyle}" />
            <label style="display:flex;align-items:center;gap:.15rem;font-size:.78rem;cursor:pointer;flex-shrink:0;user-select:none" title="Bold">
              <input type="checkbox" class="activity-bold-cb" data-act-id="${escHtml(act.id)}"${act.activityIsBold ? ' checked' : ''}><b>B</b>
            </label>
            <label style="display:flex;align-items:center;gap:.15rem;font-size:.78rem;cursor:pointer;flex-shrink:0;user-select:none" title="Underline">
              <input type="checkbox" class="activity-underline-cb" data-act-id="${escHtml(act.id)}"${act.activityIsUnderline ? ' checked' : ''}><u>U</u>
            </label>
          </div>
          <div style="display:flex;align-items:center;gap:.4rem">
            <span style="font-size:.76rem;color:#9ca3af;flex-shrink:0;min-width:3rem">Details</span>
            <input type="text" class="field-input activity-name-input"
              data-act-id="${escHtml(act.id)}"
              data-original="${escHtml(act.activityName)}"
              data-saved-html="${escHtml(act.activityName)}" value="${escHtml(act.activityName)}" />
          </div>
        </div>
        <button class="btn-icon btn-delete-activity" contenteditable="false"
          data-act-id="${escHtml(act.id)}" title="Delete activity" style="align-self:flex-start">🗑</button>
      </div>`;
    for (const rem of remarks) {
      html += renderRemarkFields(rem, target);
    }
    if (isPending) {
      html += renderPendingRemarkFields(act.id, act.id, null, null, target);
    } else {
      html += `<button class="btn-add-remark" contenteditable="false"
        data-pending-key="${escHtml(act.id)}"
        data-act-id="${escHtml(act.id)}"
        data-target="${escHtml(target.name)}">+ Add Remark &amp; Trials</button>`;
    }
    html += `</div>`;
  }
  // Pending input always at the bottom, replacing the "+ Add Activity" button
  if (hasPending) {
    const pendTitleStyle = `${_pendingNewActivity.pendingIsBold ? 'font-weight:700;' : ''}${_pendingNewActivity.pendingIsUnderline ? 'text-decoration:underline;' : ''}`;
    html += `<div class="entry-block" data-pending-act="1">
      <div class="entry-field" style="align-items:flex-start">
        <span class="field-label" contenteditable="false" style="padding-top:.3rem">Activity</span>
        <div style="flex:1;display:flex;flex-direction:column;gap:.3rem">
          <div style="display:flex;align-items:center;gap:.4rem">
            <span style="font-size:.76rem;color:#9ca3af;flex-shrink:0;min-width:3rem">Title</span>
            <input type="text" class="field-input pending-activity-name-input"
              data-act-id="${escHtml(_pendingNewActivity.actId)}"
              placeholder="Chart / report label"
              value="${escHtml(_pendingNewActivity.typedName || '')}"
              style="flex:1;${pendTitleStyle}" />
            <label style="display:flex;align-items:center;gap:.15rem;font-size:.78rem;cursor:pointer;flex-shrink:0;user-select:none" title="Bold">
              <input type="checkbox" class="pending-bold-cb"${_pendingNewActivity.pendingIsBold ? ' checked' : ''}><b>B</b>
            </label>
            <label style="display:flex;align-items:center;gap:.15rem;font-size:.78rem;cursor:pointer;flex-shrink:0;user-select:none" title="Underline">
              <input type="checkbox" class="pending-underline-cb"${_pendingNewActivity.pendingIsUnderline ? ' checked' : ''}><u>U</u>
            </label>
          </div>
          <div style="display:flex;align-items:center;gap:.4rem">
            <span style="font-size:.76rem;color:#9ca3af;flex-shrink:0;min-width:3rem">Details</span>
            <input type="text" class="field-input pending-activity-details-input"
              data-act-id="${escHtml(_pendingNewActivity.actId)}"
              placeholder="Description (optional)"
              value="${escHtml(_pendingNewActivity.typedDetails || '')}" />
          </div>
          <div style="display:flex;gap:.4rem;justify-content:flex-end">
            <button class="btn-confirm-pending-activity" contenteditable="false"
              style="padding:.25rem .6rem;background:#6366f1;color:#fff;border:none;border-radius:.35rem;cursor:pointer;font-size:.82rem;font-weight:600"
              title="Save activity">Done</button>
            <button class="btn-icon btn-cancel-pending-activity" contenteditable="false"
              title="Cancel">✕</button>
          </div>
        </div>
      </div>
      <button class="btn-add-remark btn-add-remark-for-pending" contenteditable="false"
        data-act-id="${escHtml(_pendingNewActivity.actId)}"
        data-target="${escHtml(target.name)}">+ Add Remark &amp; Trials</button>
    </div>`;
  } else {
    // Small bottom margin only — .target-content now carries the padding that
    // keeps the last element clear of the window edge, so a big margin here just
    // opened a gap between this button and the Mastered/Discontinued sections.
    html += `<button class="btn-add-session-activity" style="display:block;margin-top:.6rem;margin-bottom:.6rem;padding:.55rem .9rem;background:transparent;border:1.5px dashed #a5b4fc;border-radius:.5rem;cursor:pointer;font-size:.85rem;color:#6366f1;margin-left:auto;margin-right:auto" contenteditable="false">+ Add Activity (only for this session, not saved to the target permanently)</button>`;
  }
  return html;
}

// ─── REGULAR TARGET ──────────────────────────────────────────

function renderRegularTarget(target) {
  let html = "";
  if (target.notes?.length > 0) {
    html += `<div class="target-notes" contenteditable="false">`;
    for (const n of target.notes) {
      if (n.text) html += `<div class="target-note-item">📌 ${escHtml(n.text)}</div>`;
    }
    html += `</div>`;
  }
  return html + renderExtraActivitiesSection(target);
}

// Returns the inline options string for an activity (new inlineOptions field,
// falling back to old remarkPresetId preset for backward compat).
function getActivityInlineOptions(a) {
  if (a.inlineOptions) return a.inlineOptions;
  if (a.remarkPresetId) {
    const preset = state.remarkPresets.find(p => p.id === a.remarkPresetId);
    if (preset?.options?.length) return preset.options.join("/");
  }
  return null;
}

function parseOpts(str) {
  if (!str) return [];
  // \x1F (Unit Separator) is the current delimiter; "/" is legacy for existing data
  const sep = str.includes("\x1F") ? "\x1F" : "/";
  return str.split(sep).map(s => s.trim()).filter(Boolean);
}

// Converts stored remark text (plain or legacy **bold**) to HTML for contenteditable display
function remarkToHtml(text) {
  if (!text) return "";
  return text.replace(/\*\*(.+?)\*\*/g, "<b>$1</b>");
}

// Session-entry remark/note boxes are real <textarea>/<input> elements (not
// contenteditable) so Grammarly, Enter, backspace and Ctrl+A all behave
// natively per-field. Stored text can still contain legacy HTML markup
// (literal "<br>" from the old contenteditable boxes, "<b>" from
// remarkToHtml) — these two functions round-trip between that stored format
// and the plain text a textarea's .value can actually hold.
function plainTextForEdit(html) {
  if (!html) return "";
  return html
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/?b>/gi, "**")
    .replace(/<[^>]*>/g, "")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&amp;/gi, "&");
}
function htmlForStorage(text) {
  return escHtml(text || "").replace(/\n/g, "<br>");
}

// Read-only display of activity name/note text that may contain
// *bold*/_underline_ markers (typed via wrapTextareaSelection below) —
// escapes the raw text first so it can't inject arbitrary HTML, then turns
// the markers into real tags.
function formatActivityMarkup(text) {
  return escHtml(text || "")
    .replace(/^\. /gm, "• ")
    .replace(/\*(.+?)\*/g, "<b>$1</b>")
    .replace(/_(.+?)_/g, "<u>$1</u>");
}

// Returns the display name for a predefined activity: pa.title if set, else pa.name.
function paDisplayName(pa) {
  return pa.title || pa.name;
}

// Returns the HTML to display a predefined activity's title (with checkbox-style
// bold/underline from pa.isBold/pa.isUnderline) and optional details below.
function paDisplayHtml(pa, showPlaceholder = false) {
  // pa.title → first line only (empty = nothing shown on line 1, or placeholder on session screen).
  // pa.name  → always the details/second line when non-empty.
  const titleText = (pa.title || "").trim();
  let html = "";
  if (titleText) {
    let style = "";
    if (pa.isBold) style += "font-weight:700;";
    if (pa.isUnderline) style += "text-decoration:underline;";
    html = style
      ? `<span style="${style}">${formatActivityMarkup(titleText)}</span>`
      : formatActivityMarkup(titleText);
  } else if (showPlaceholder) {
    html = `<span style="font-style:italic;color:#9ca3af;font-size:.85rem">&lt;Please give this activity a title in Edit Target&gt;</span>`;
  }
  const detailsText = (pa.name || "").trim();
  if (detailsText && detailsText !== titleText) {
    html += `<span style="display:block;margin-top:.1rem;font-weight:400;text-decoration:none">${formatActivityMarkup(detailsText)}</span>`;
  }
  return html;
}

// A "word" for cursor-with-no-selection formatting — letters/digits/'/- so
// "Self-Regulation" or "don't" count as one word, but stops at punctuation
// like ":" or "(" so parenthesised text doesn't get swept in.
function wordBoundsAt(value, pos) {
  const isWordChar = c => /[A-Za-z0-9'-]/.test(c);
  let start = pos, end = pos;
  while (start > 0 && isWordChar(value[start - 1])) start--;
  while (end < value.length && isWordChar(value[end])) end++;
  return { start, end };
}

// Finds a marker...marker pair anywhere in the text whose span (including
// the markers themselves) overlaps [selStart, selEnd] — covers all 3 ways a
// boss might re-select already-formatted text: just the inner words, the
// whole "**text**" including the markers, or just a bare cursor resting
// somewhere inside it.
function findMarkerSpan(value, selStart, selEnd, marker) {
  const esc = marker.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const re = new RegExp(esc + "(.+?)" + esc, "g");
  let m;
  while ((m = re.exec(value)) !== null) {
    const mStart = m.index, mEnd = m.index + m[0].length;
    if (mStart <= selEnd && mEnd >= selStart) return { start: mStart, end: mEnd, inner: m[1] };
  }
  return null;
}

// Formats the current selection in a plain <textarea>/<input> with a marker
// (* for bold, _ for underline) without going through the contenteditable
// sketch popup — Activity Name/Notes are the only fields that use this; a
// plain textarea can't render the result as real bold/underline inline, but
// this avoids the popup entirely, which is what the boss asked for.
//
// Same toggle behaviour as a word processor's Ctrl+B: if the cursor/selection
// overlaps an existing marker pair *in any way* (see findMarkerSpan above),
// that pair is removed — it can never stack into "**text**" no matter
// how it's re-selected. Otherwise, a bare cursor (no selection) expands to
// the whole word under it before wrapping, instead of dropping markers with
// nothing between them. Caller is responsible for keeping the field focused
// (see the mousedown handlers on the format buttons) so the selection
// survives long enough to read it.
function wrapTextareaSelection(el, marker) {
  const value = el.value;
  const mLen = marker.length;
  let start = el.selectionStart, end = el.selectionEnd;

  const existing = findMarkerSpan(value, start, end, marker);
  if (existing) {
    el.value = value.slice(0, existing.start) + existing.inner + value.slice(existing.end);
    el.setSelectionRange(existing.start, existing.start + existing.inner.length);
    el.dispatchEvent(new Event("input", { bubbles: true }));
    return;
  }

  if (start === end) {
    if (!value.trim()) return;
    start = 0; end = value.length;
  }

  const before = value.slice(0, start);
  const selected = value.slice(start, end);
  const after = value.slice(end);
  el.value = before + marker + selected + marker + after;
  el.setSelectionRange(start + mLen, end + mLen);
  el.dispatchEvent(new Event("input", { bubbles: true }));
}

// Small "B"/"U"/"•" buttons next to an Activity Name/Notes field — same wrap
// action as Ctrl+B/Ctrl+U/Ctrl+Shift+L, for anyone who doesn't know/use the shortcut.
function formatButtonsHtml(inputId) {
  return `<span class="fmt-btn-group">
    <button class="btn-fmt btn-fmt-bold" type="button" data-input-id="${inputId}" title="Bold (Ctrl+B)">B</button>
    <button class="btn-fmt btn-fmt-underline" type="button" data-input-id="${inputId}" title="Underline (Ctrl+U)">U</button>
    <button class="btn-fmt btn-fmt-bullet" type="button" data-input-id="${inputId}" title="Bullet point (Ctrl+Shift+L)">•</button>
  </span>`;
}

// Finds the start/end of the line containing `pos` in a plain textarea value.
function lineBoundsAt(value, pos) {
  const start = value.lastIndexOf("\n", pos - 1) + 1;
  let end = value.indexOf("\n", pos);
  if (end === -1) end = value.length;
  return { start, end };
}

// A line "has a bullet" if it starts with the • marker (whatever indentation
// precedes it) — checked with a plain regex, not a hidden flag, so a bullet
// typed by hand (bypassing the button entirely) is still recognized and can
// still be toggled off, same as the bold/underline markers.
function isBulletLine(line) {
  return /^\s*•\s?/.test(line);
}
function addBulletMarker(line) {
  return isBulletLine(line) ? line : "• " + line.replace(/^\s+/, "");
}
function stripBulletMarker(line) {
  return line.replace(/^(\s*)•\s?/, "$1");
}

// Toggle bullet points on the line(s) touched by the current selection in a
// plain <textarea> — same "format like Word" intent as wrapTextareaSelection,
// but bullets are a per-line prefix rather than a paired inline marker, so
// the logic works on whole lines instead of an arbitrary text span:
// - A highlighted range only needs to touch part of a line to affect the
//   whole line (selecting one character is enough), matching how Word's
//   bullet button always applies to the full paragraph(s) touched.
// - Re-toggling never accumulates: every line's bullet state is read fresh
//   from the text itself (via isBulletLine) each time, never assumed, so
//   clicking twice always returns to the original state.
// - A mixed selection (some lines already bulleted, some not) always adds
//   bullets to every line, matching Word's behaviour for a mixed selection.
// - Blank lines inside a multi-line selection are left alone (they're used
//   as readability separators between rubric sections, not list items) —
//   but a bare cursor resting on a single blank line starts a fresh bullet
//   right there, same as clicking the bullet button on an empty paragraph.
function toggleBulletSelection(el) {
  const value = el.value;
  const selStart = el.selectionStart, selEnd = el.selectionEnd;

  if (selStart === selEnd) {
    const { start, end } = lineBoundsAt(value, selStart);
    if (value.slice(start, end).trim() === "") {
      el.value = value.slice(0, start) + "• " + value.slice(end);
      el.setSelectionRange(start + 2, start + 2);
      el.dispatchEvent(new Event("input", { bubbles: true }));
      return;
    }
  }

  const blockStart = lineBoundsAt(value, selStart).start;
  const blockEnd = lineBoundsAt(value, Math.max(selEnd - 1, selStart)).end;
  const lines = value.slice(blockStart, blockEnd).split("\n");

  const nonBlank = lines.filter(ln => ln.trim() !== "");
  const shouldAdd = nonBlank.length === 0 || !nonBlank.every(isBulletLine);

  const newLines = lines.map(ln => {
    if (ln.trim() === "") return ln;
    return shouldAdd ? addBulletMarker(ln) : stripBulletMarker(ln);
  });

  const newBlock = newLines.join("\n");
  el.value = value.slice(0, blockStart) + newBlock + value.slice(blockEnd);
  el.setSelectionRange(blockStart, blockStart + newBlock.length);
  el.dispatchEvent(new Event("input", { bubbles: true }));
}

// ─── REMARK FIELDS ───────────────────────────────────────────

function renderRemarkFields(rem, target, inlineOptions = null, sentenceStarter = null, multiSelect = false, mappedInfo = null, remarkHasNote = false, manualScore = false, optionScores = null, noteCapable = false, noteSentenceStarter = null, noTrials = false) {
  const opts = parseOpts(inlineOptions);

  // Sync optionScore with current config whenever the target is re-rendered.
  // Covers the case where the user selects an option first (before points are
  // configured), then goes to Edit Target, adds points, and returns — the stored
  // rem.optionScore would be stale or missing without this sync.
  if (!multiSelect && optionScores && rem.text && opts.includes(rem.text)) {
    const cfgScore = optionScores[rem.text];
    const sid = state.currentSessionId || state.groupSessionId;
    if (cfgScore !== undefined && rem.optionScore !== cfgScore) {
      rem.optionScore = cfgScore;
      if (sid) setOptionScore(sid, rem.id, cfgScore).catch(() => {});
    } else if (cfgScore === undefined && rem.optionScore !== undefined) {
      delete rem.optionScore;
      if (sid) clearOptionScore(sid, rem.id).catch(() => {});
    }
  }

  // Manual Score type: a single text input replaces the full Remark+Trials block
  if (manualScore) {
    const currentVal = rem.text ? stripRemarkHtml(rem.text).trim() : "";
    const parsed = parseManualScore(currentVal);
    const parsedPct  = parsed !== null ? Math.round(parsed * 10) / 10 : null;
    const parsedHintText = parsedPct !== null ? `= ${parsedPct}%` : "";
    const parsedHint = `<span class="manual-score-hint" data-rem-id="${rem.id}" style="font-size:.93rem;font-family:inherit;color:#9ca3af;margin-left:.5rem;white-space:nowrap;align-self:center${parsedPct === null ? ";display:none" : ""}">${escHtml(parsedHintText)}</span>`;
    const msNoteField = noteCapable
      ? `<div class="entry-field entry-note-field" data-rem-id="${rem.id}">
          <span class="field-label" contenteditable="false">Remark</span>
          <button class="btn-sketch" contenteditable="false" data-rem-id="${rem.id}" aria-label="Open sketch board">✏</button>
          <textarea class="field-input mastery-note-input" rows="1"
            autocomplete="new-password"
            data-rem-id="${rem.id}"
            data-saved-html="${escHtml(rem.masteryNote || "")}">${escHtml(plainTextForEdit(rem.masteryNote || ""))}</textarea>
          <span class="entry-note-spacer" contenteditable="false" aria-hidden="true"></span>
        </div>`
      : "";
    return `
    <div class="entry-divider" contenteditable="false"></div>
    <div class="entry-field" contenteditable="false">
      <span class="field-label">Score</span>
      <input type="text" class="field-input remark-text-input" style="max-width:14rem"
        data-rem-id="${rem.id}" data-saved-html="${escHtml(currentVal)}"
        data-manual-score="1" autocomplete="one-time-code"
        placeholder="e.g. 5/20, 25%, 25, 0.25"
        value="${escHtml(currentVal)}">${parsedHint}
      <button class="btn-icon btn-delete-remark" contenteditable="false"
        data-rem-id="${rem.id}" title="Delete score">🗑</button>
    </div>
    ${msNoteField}`;
  }

  const trials = rem.trials || [];
  const regularBadges = trials.map((score, idx) =>
    `<span class="trial-badge">${score === -1 ? "—" : score}<button class="btn-trial-delete"
      data-rem-id="${rem.id}" data-idx="${idx}">×</button></span>`
  ).join("");
  const optBadge = rem.optionScore !== undefined
    ? `<span class="trial-badge trial-badge--option">${rem.optionScore}</span>` : "";
  const badgesHtml = regularBadges + optBadge;

  const _existingNote = (rem.masteryNote || "").replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").trim();

  // Remark Only (No Trials): the Trials row stays visible so the layout matches
  // every other activity, but the button is greyed out and inert (no
  // .btn-add-trial class, so no click listener is ever bound to it) — the
  // activity can never gain a score.
  const trailingField = noTrials
    ? `<div class="entry-field" contenteditable="false">
        <span class="field-label">Trials</span>
        <div class="trials-row">
          <div class="trials-badges"></div>
          <button class="btn-primary-sm btn-trial-not-required" disabled
            style="background:#e5e7eb;color:#9ca3af;border-color:#e5e7eb;cursor:default;box-shadow:none">+ Trial (Not Required)</button>
        </div>
      </div>`
    : mappedInfo
    ? `<div class="entry-field" contenteditable="false">
        <span class="field-label">${escHtml(mappedInfo.label)}</span>
        <span class="field-value-fixed">${mappedInfo.pct !== null ? mappedInfo.pct + "%" : "—"}</span>
      </div>`
    : `<div class="entry-field" contenteditable="false">
        <span class="field-label">Trials</span>
        <div class="trials-row">
          <div class="trials-badges">${badgesHtml}</div>
          <button class="btn-add-trial btn-primary-sm"
            data-rem-id="${rem.id}"
            data-target="${escHtml(target.name)}" onmousedown="event.preventDefault()">+ Trial</button>
        </div>
      </div>`;

  function makeOptPills(remId, remText) {
    if (opts.length === 0) return null;
    const removedBadge = (() => {
      if (!remText) {
        // Check for orphan records: same activityName, different actId, with old free-text data
        const actRec = state.sessionData?.activities?.[rem.activityId];
        if (actRec) {
          for (const [oid, oact] of Object.entries(state.sessionData.activities || {})) {
            if (oid === rem.activityId) continue;
            if (oact.targetName !== actRec.targetName || oact.activityName !== actRec.activityName) continue;
            for (const [, r] of Object.entries(state.sessionData.remarks || {})) {
              if (r.activityId !== oid) continue;
              const txt = (r.text || "").replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").trim();
              if (txt && !opts.includes(txt)) return `<div style="font-size:.78rem;color:#9ca3af;margin-top:.3rem;font-style:italic">Old data: ${escHtml(txt)}</div>`;
            }
          }
        }
        return "";
      }
      if (multiSelect) {
        const sel = remText.split(", ").map(s => s.trim()).filter(Boolean);
        const gone = sel.filter(s => !opts.includes(s));
        return gone.length ? `<div style="font-size:.78rem;color:#9ca3af;margin-top:.3rem;font-style:italic">Old data: ${escHtml(gone.join(", "))}</div>` : "";
      }
      return !opts.includes(remText) ? `<div style="font-size:.78rem;color:#9ca3af;margin-top:.3rem;font-style:italic">Old data: ${escHtml(remText)}</div>` : "";
    })();
    if (multiSelect) {
      const sel = (remText || "").split(", ").map(s => s.trim()).filter(Boolean);
      return `<div class="remark-preset-opts remark-preset-opts-multi" contenteditable="false">${opts.map(opt =>
        `<button class="btn-remark-opt btn-remark-opt--multi${sel.includes(opt) ? " active" : ""}"
          data-rem-id="${remId}" data-opt="${escHtml(opt)}" onmousedown="event.preventDefault()">${escHtml(opt)}</button>`
      ).join("")}${removedBadge}</div>`;
    }
    return `<div class="remark-preset-opts" contenteditable="false">${opts.map(opt =>
      `<button class="btn-remark-opt${remText === opt ? " active" : ""}"
        data-rem-id="${remId}" data-opt="${escHtml(opt)}"
        data-score="${optionScores?.[opt] !== undefined ? optionScores[opt] : ''}"
        onmousedown="event.preventDefault()">${escHtml(opt)}</button>`
    ).join("")}${removedBadge}</div>`;
  }

  const optBtns = makeOptPills(rem.id, rem.text)
    || `<textarea class="field-input remark-text-input" rows="1"
        data-rem-id="${rem.id}" placeholder="Remark…" data-saved-html="${escHtml(rem.text || "")}">${escHtml(plainTextForEdit(rem.text))}</textarea>`;

  // Sketch board button only shown when there's a free-text input (no preset opt pills)
  const sketchBtn = opts.length === 0
    ? `<button class="btn-sketch" contenteditable="false" data-rem-id="${rem.id}" aria-label="Open sketch board">✏</button>`
    : "";

  let remarkContent;
  if (sentenceStarter) {
    const starterClass = opts.length > 0 ? "remark-starter-wrap remark-starter-wrap--opts" : "remark-starter-wrap";
    remarkContent = `<div class="${starterClass}">
      <span class="remark-starter-prefix" contenteditable="false">${escHtml(sentenceStarter)}</span>
      ${makeOptPills(rem.id, rem.text)
        || `<textarea class="field-input remark-text-input" rows="1"
            data-rem-id="${rem.id}" placeholder="Remark…" data-saved-html="${escHtml(rem.text || "")}">${escHtml(plainTextForEdit(rem.text))}</textarea>`
      }
    </div>`;
  } else {
    remarkContent = optBtns;
  }

  // Note field: shown immediately if there's existing data; otherwise hidden until
  // user clicks [+ Note]. For activities that had noteCapable=false in the past
  // but somehow have note data, show an "Old data" fallback.
  const remarkLabel = multiSelect ? "Checkboxes" : (opts.length > 0 ? "Multiple Choice" : "Remark");

  let noteField;
  if (noteCapable) {
    const noteTextarea = `<textarea class="field-input mastery-note-input" rows="1"
          data-rem-id="${rem.id}"
          data-saved-html="${escHtml(rem.masteryNote || "")}">${escHtml(plainTextForEdit(rem.masteryNote || ""))}</textarea>`;
    const noteInput = noteSentenceStarter
      ? `<div class="remark-starter-wrap"><span class="remark-starter-prefix" contenteditable="false">${escHtml(noteSentenceStarter)}</span>${noteTextarea}</div>`
      : noteTextarea;
    noteField = `<div class="entry-field entry-note-field" data-rem-id="${rem.id}">
        <span class="field-label" contenteditable="false">Remark</span>
        <button class="btn-sketch" contenteditable="false" data-rem-id="${rem.id}" aria-label="Open sketch board">✏</button>
        ${noteInput}
        <span class="entry-note-spacer" contenteditable="false" aria-hidden="true"></span>
      </div>`;
  } else {
    noteField = _existingNote
      ? `<div class="entry-field">
          <span class="field-label" contenteditable="false">Remark</span>
          <div style="font-size:.78rem;color:#9ca3af;font-style:italic">Old data: ${escHtml(_existingNote)}</div>
        </div>`
      : "";
  }

  return `
    <div class="entry-divider" contenteditable="false"></div>
    <div class="entry-field">
      <span class="field-label" contenteditable="false">${remarkLabel}</span>
      ${sketchBtn}
      ${remarkContent}
      <button class="btn-icon btn-delete-remark" contenteditable="false"
        data-rem-id="${rem.id}" title="Delete remark">🗑</button>
    </div>
    ${noteField}
    ${trailingField}`;
}


function renderPendingRemarkFields(pendingKey, actId, paName, paOrder, target, initialValue = "") {
  return `
    <div class="entry-divider" contenteditable="false"></div>
    <div class="entry-field">
      <span class="field-label" contenteditable="false">Remark</span>
      <button class="btn-sketch btn-sketch-pending" contenteditable="false" aria-label="Open sketch board">✏</button>
      <textarea id="new-remark-textarea" class="field-input" rows="1"
        placeholder="Type remark…">${escHtml(initialValue)}</textarea>
    </div>
    <div class="pending-remark-actions" contenteditable="false">
      <button class="btn-cancel-remark btn-remark-cancel">✕ Cancel</button>
      <button class="btn-save-remark btn-remark-save">✓ Save</button>
    </div>`;
}

// Predefined remark that exists in Firebase — label as field-label, editable text input
function renderPredefinedRemarkFields(rem, predRemName, target) {
  const trials = rem.trials || [];
  const badgesHtml = trials.map((score, idx) =>
    `<span class="trial-badge">${score === -1 ? "—" : score}<button class="btn-trial-delete"
      data-rem-id="${rem.id}" data-idx="${idx}">×</button></span>`
  ).join("");
  return `
    <div class="entry-divider" contenteditable="false"></div>
    <div class="entry-field">
      <span class="field-label" contenteditable="false">${escHtml(predRemName)}</span>
      <input type="text" class="field-input predef-remark-input-live"
        data-rem-id="${rem.id}"
        data-original="${escHtml(rem.text || "")}"
        data-saved-html="${escHtml(rem.text || "")}"
        placeholder="e.g. 80%" value="${escHtml(rem.text || "")}" />
    </div>
    <div class="entry-field" contenteditable="false">
      <span class="field-label">Trials</span>
      <div class="trials-row">
        <div class="trials-badges">${badgesHtml}</div>
        <button class="btn-add-trial btn-primary-sm"
          data-rem-id="${rem.id}"
          data-target="${escHtml(target.name)}" onmousedown="event.preventDefault()">+ Trial</button>
      </div>
    </div>`;
}

// Predefined remark not yet in Firebase — label + empty text input
function renderGhostRemarkFields(predRemName, actId, pa, paIdx, target) {
  return `
    <div class="entry-divider" contenteditable="false"></div>
    <div class="entry-field">
      <span class="field-label" contenteditable="false">${escHtml(predRemName)}</span>
      <input type="text" class="field-input predef-remark-input"
        data-rem-name="${escHtml(predRemName)}"
        data-act-id="${actId || ""}"
        data-pa-name="${escHtml(pa.name)}"
        data-pa-order="${paIdx}"
        data-target="${escHtml(target.name)}"
        placeholder="e.g. 80%" />
    </div>
    <div class="entry-field" contenteditable="false">
      <span class="field-label">Trials</span>
      <div class="trials-row">
        <div class="trials-badges"></div>
        <button class="btn-primary-sm btn-init-predef-remark"
          data-rem-name="${escHtml(predRemName)}"
          data-act-id="${actId || ""}"
          data-pa-name="${escHtml(pa.name)}"
          data-pa-order="${paIdx}"
          data-target="${escHtml(target.name)}">+ Trial</button>
      </div>
    </div>`;
}

// ─── ATTACH LISTENERS ────────────────────────────────────────

function attachTargetListeners(target) {
  const c = $("target-content");

  // Section sidebar navigation
  // For expanded sidebar: sec-main is the scroll container (overflow-y:auto, fills flex chain height).
  // For collapsed sidebar: falls back to session-body so page scrolling works normally.
  const _secMainEl = c.querySelector(".sec-main[style*='overflow-y']");
  const _secScrollHost = _secMainEl || c.closest(".session-body");

  // Remove any previous scroll listener before attaching a new one
  if (_secScrollListener) {
    // previous host might be sec-main or session-body — remove from both to be safe
    c.querySelector(".sec-main")?.removeEventListener("scroll", _secScrollListener);
    c.closest(".session-body")?.removeEventListener("scroll", _secScrollListener);
    _secScrollListener = null;
  }
  _triggerSecNavUpdate = null;

  // Nav buttons: scroll to section anchor (no re-render)
  c.querySelectorAll(".sec-nav-btn").forEach(btn => {
    btn.addEventListener("click", () => {
      const idx = parseInt(btn.dataset.secIdx, 10) || 0;
      const anchor = c.querySelector(`.sec-scroll-section[data-sec-anchor="${idx}"]`);
      if (anchor && _secScrollHost) {
        const targetScrollTop = _secScrollHost.scrollTop + anchor.getBoundingClientRect().top - _secScrollHost.getBoundingClientRect().top;
        _secScrollHost.scrollTo({ top: targetScrollTop, behavior: "smooth" });
      }
    });
  });
  c.querySelectorAll(".sec-toggle-btn").forEach(btn => {
    btn.addEventListener("click", () => {
      _sidebarCollapsed = !_sidebarCollapsed;
      renderTargetContent();
    });
  });

  // Scroll listener: update active nav button based on scroll position
  if (_secScrollHost && c.querySelector(".sec-scroll-section")) {
    const updateActiveSection = () => {
      const anchors = c.querySelectorAll(".sec-scroll-section[data-sec-anchor]");
      if (!anchors.length) return;
      const atBottom = _secScrollHost.scrollTop + _secScrollHost.clientHeight >= _secScrollHost.scrollHeight - 24;
      let activeIdx = 0;
      if (atBottom) {
        activeIdx = anchors.length - 1;
      } else {
        const containerTop = _secScrollHost.getBoundingClientRect().top;
        anchors.forEach(section => {
          if (section.getBoundingClientRect().top <= containerTop + 8) {
            activeIdx = parseInt(section.dataset.secAnchor, 10) || 0;
          }
        });
      }
      if (activeIdx === _selectedSectionIdx) return;
      _selectedSectionIdx = activeIdx;
      c.querySelectorAll(".sec-nav-btn").forEach(navBtn => {
        const btnIdx = parseInt(navBtn.dataset.secIdx, 10);
        const isActive = btnIdx === activeIdx;
        navBtn.style.background = isActive ? 'var(--primary-light)' : 'transparent';
        navBtn.style.borderLeft = `3px solid ${isActive ? 'var(--primary)' : 'transparent'}`;
        const nameDiv = navBtn.querySelector("div:first-child");
        if (nameDiv) {
          nameDiv.style.fontWeight = isActive ? '700' : '500';
          nameDiv.style.color = isActive ? 'var(--primary-dark)' : '#374151';
        }
      });
    };
    _secScrollListener = updateActiveSection;
    _triggerSecNavUpdate = updateActiveSection;
    _secScrollHost.addEventListener("scroll", _secScrollListener, { passive: true });
    updateActiveSection(); // set initial state based on current scroll position
  }

  // Free-text boxes here are real <textarea>/<input> elements now, so their
  // own native Enter/backspace/Ctrl+A handling just works — only the app's
  // own Escape/Ctrl+Enter shortcuts are delegated from the host (set up ONCE
  // per session-open by setupEntryEnterKeyDelegation, see openSession).
  c.querySelectorAll("textarea.field-input").forEach(autoResizeTextarea);

  // Activity name (.activity-name-input) and title (.activity-title-input) are saved
  // by the shared merged-editing host — see setupEntryRemarkSaving.
  c.querySelectorAll(".activity-name-input").forEach(input => {
    input.addEventListener("blur", () => {
      if (!input.value.trim()) input.value = input.dataset.original;
    });
  });

  // Bold/underline checkboxes for activity title — immediate Firestore write + visual update.
  c.querySelectorAll(".activity-bold-cb, .activity-underline-cb").forEach(cb => {
    cb.addEventListener("change", async () => {
      const actId = cb.dataset.actId;
      const boldCb = c.querySelector(`.activity-bold-cb[data-act-id="${actId}"]`);
      const underlineCb = c.querySelector(`.activity-underline-cb[data-act-id="${actId}"]`);
      const titleInput = c.querySelector(`.activity-title-input[data-act-id="${actId}"]`);
      const isBold = boldCb?.checked ?? false;
      const isUnderline = underlineCb?.checked ?? false;
      if (titleInput) {
        titleInput.style.fontWeight = isBold ? "700" : "";
        titleInput.style.textDecoration = isUnderline ? "underline" : "";
      }
      const act = state.sessionData?.activities?.[actId];
      if (act) { act.activityIsBold = isBold; act.activityIsUnderline = isUnderline; }
      await updateActivityTitle(state.currentSessionId, actId, titleInput?.value?.trim() || "", isBold, isUnderline);
    });
  });

  // ── Inactive activities toggle (one per section) ────────
  c.querySelectorAll(".btn-inactive-toggle").forEach(btn => {
    btn.addEventListener("click", () => {
      const list = btn.nextElementSibling;
      const chevron = btn.querySelector(".inactive-chevron");
      if (!list) return;
      const open = list.style.display !== "none";
      list.style.display = open ? "none" : "flex";
      if (chevron) chevron.textContent = open ? "▶" : "▼";
    });
  });

  const addActBtn = c.querySelector(".btn-add-session-activity");
  if (addActBtn) {
    addActBtn.addEventListener("mousedown", () => {
      state.entryActionsInFlight++;
      let released = false;
      const release = () => {
        if (released) return;
        released = true;
        state.entryActionsInFlight = Math.max(0, state.entryActionsInFlight - 1);
        if (state.entryActionsInFlight === 0 && state.renderPending) {
          state.renderPending = false;
          renderTargetContent();
        }
      };
      addActBtn.addEventListener("click", release, { once: true });
      setTimeout(release, 600);
    });

    addActBtn.addEventListener("click", (e) => {
      if (_addActivityInFlight) return;
      _addActivityInFlight = true;
      // Create a local-only pending input — NO Firestore write until the user
      // types a name. This eliminates orphan activities entirely.
      _pendingNewActivity = { actId: generateId("a"), targetName: target.name, order: Date.now(), typedName: "", typedDetails: "", pendingIsBold: false, pendingIsUnderline: false };
      renderTargetContent();
      c.querySelector(".pending-activity-name-input")?.focus();
      setTimeout(() => { _addActivityInFlight = false; }, 600);
    });
  }

  // Pending activity inputs — save to Firestore only when user commits a title.
  // Title input (pending-activity-name-input) is required; Details optional.
  const pendingInput = c.querySelector(".pending-activity-name-input");
  if (pendingInput) {
    // Keep typed values in sync so they survive Firestore-triggered re-renders.
    pendingInput.addEventListener("input", () => {
      if (_pendingNewActivity) _pendingNewActivity.typedName = pendingInput.value;
    });
    c.querySelector(".pending-activity-details-input")?.addEventListener("input", (e) => {
      if (_pendingNewActivity) _pendingNewActivity.typedDetails = e.target.value;
    });
    c.querySelector(".pending-bold-cb")?.addEventListener("change", (e) => {
      if (_pendingNewActivity) {
        _pendingNewActivity.pendingIsBold = e.target.checked;
        pendingInput.style.fontWeight = e.target.checked ? "700" : "";
      }
    });
    c.querySelector(".pending-underline-cb")?.addEventListener("change", (e) => {
      if (_pendingNewActivity) {
        _pendingNewActivity.pendingIsUnderline = e.target.checked;
        pendingInput.style.textDecoration = e.target.checked ? "underline" : "";
      }
    });

    // Helper: commit pending activity to Firestore
    const commitPending = (openRemark = false) => {
      if (!_pendingNewActivity) return;
      const title   = (_pendingNewActivity.typedName || "").trim();
      const details = (_pendingNewActivity.typedDetails || "").trim();
      if (!title) { pendingInput.focus(); return; }
      const { actId, targetName: tName, order, pendingIsBold, pendingIsUnderline } = _pendingNewActivity;
      _pendingNewActivity = null;
      state.sessionData.activities = state.sessionData.activities || {};
      state.sessionData.activities[actId] = {
        targetName: tName, activityName: details, activityTitle: title,
        activityIsBold: pendingIsBold || false, activityIsUnderline: pendingIsUnderline || false,
        order, isPredefined: false
      };
      if (openRemark) state.pendingNewRemark = { pendingKey: actId };
      renderTargetContent();
      addActivity(state.currentSessionId, tName, details, order, false, actId, null, null, title, pendingIsBold || false, pendingIsUnderline || false).catch(err => {
        delete state.sessionData.activities?.[actId];
        renderTargetContent();
        alert("Couldn't save activity — check your connection.\n\n" + err.message);
      });
    };

    pendingInput.addEventListener("blur", () => {
      if (!_pendingNewActivity) return;
      const title = (_pendingNewActivity.typedName || "").trim();
      if (!title) {
        _pendingNewActivity = null;
        // Defer render if a button's mousedown guard is active
        if (state.entryActionsInFlight > 0) {
          state.renderPending = true;
        } else {
          setTimeout(() => {
            if (state.entryActionsInFlight > 0) state.renderPending = true;
            else renderTargetContent();
          }, 0);
        }
        return;
      }
      commitPending(false);
    });

    pendingInput.addEventListener("keydown", (e) => {
      if (e.key === "Enter") { e.preventDefault(); pendingInput.blur(); }
      if (e.key === "Escape") { e.preventDefault(); _pendingNewActivity = null; renderTargetContent(); }
    });

    c.querySelector(".btn-cancel-pending-activity")?.addEventListener("mousedown", (e) => {
      e.preventDefault(); // prevent blur from firing and clearing _pendingNewActivity first
      _pendingNewActivity = null;
      renderTargetContent();
    });

    const confirmBtn = c.querySelector(".btn-confirm-pending-activity");
    if (confirmBtn) {
      confirmBtn.addEventListener("mousedown", (e) => {
        e.preventDefault(); // prevent blur from stealing the click
      });
      confirmBtn.addEventListener("click", () => commitPending(false));
    }

    // "+ Add Remark & Trials" on the pending row: save the activity first (title
    // required), then immediately open the add-remark form for it.
    c.querySelector(".btn-add-remark-for-pending")?.addEventListener("click", () => commitPending(true));
  }

  // ── Delete activity ───────────────────────────────────────
  c.querySelectorAll(".btn-delete-activity").forEach(btn => {
    btn.addEventListener("click", async () => {
      if (!confirm("Delete this activity and all its remarks?")) return;
      const remIds = getRemarksForActivity(btn.dataset.actId).map(r => r.id);
      await deleteActivity(state.currentSessionId, btn.dataset.actId, remIds);
    });
  });

  // Saving for .remark-text-input / .mastery-note-input / .activity-name-input /
  // .predef-remark-input / .predef-remark-input-live is handled by the shared
  // host-level saver (state.entryRemarkSaver, set up in openSession) rather
  // than per-element blur — these boxes get torn down and rebuilt on every
  // render, so per-element listeners would need re-attaching constantly. See
  // setupEntryRemarkSaving.

  // ── Add remark (immediate creation) ──────────────────────
  c.querySelectorAll(".btn-add-remark").forEach(btn => {
    // Guards against a render (triggered by the blur this mousedown is
    // about to cause on whatever box the boss was just typing in, or by an
    // already-scheduled render from that typing's own autosave) replacing
    // this button before "click" fires — Chrome silently drops "click" if
    // its target is removed from the DOM between mousedown and mouseup.
    btn.addEventListener("mousedown", () => {
      state.entryActionsInFlight++;
      let released = false;
      const release = () => {
        if (released) return;
        released = true;
        state.entryActionsInFlight = Math.max(0, state.entryActionsInFlight - 1);
        // If "click" never actually fired (e.g. the press was dragged away),
        // the main click handler's own increment/decrement never ran either,
        // so catch up on any render its finally would otherwise have done.
        if (state.entryActionsInFlight === 0 && state.renderPending) {
          state.renderPending = false;
          renderTargetContent();
        }
      };
      // Released the instant "click" actually fires, proving the button
      // survived the gap — the main click handler renders synchronously
      // once it's done (no further write to guard against). The timeout is
      // only a fallback for a press that never resolves into a click at all.
      btn.addEventListener("click", release, { once: true });
      setTimeout(release, 600);
    });
    btn.addEventListener("click", async () => {
      if (btn.disabled) return;
      btn.disabled = true;
      try {
        const paName  = btn.dataset.paName || null;
        const paOrder = Number(btn.dataset.paOrder) || 0;
        let   actId   = btn.dataset.actId  || null;
        state.pendingNewActivity = null;
        // Mapped activities use autoFillMappedRemarks instead of the normal
        // path to avoid a race: addActivity's Firestore snapshot can re-enter
        // autoFillMappedRemarks before this handler adds the remark, creating
        // a duplicate. autoFillMappedRemarks's in-flight guard prevents that.
        if (btn.dataset.isMapped === "1") {
          await autoFillMappedRemarks(state.currentStudent, state.currentSessionId);
          return; // Firestore write will trigger snapshot → re-render
        }
        if (paName) actId = await ensureFedcActivity(target.name, paName, paOrder, btn.dataset.paParent || null, btn.dataset.cfgId || null);
        if (!actId) { btn.disabled = false; return; }
        // Maintained placeholder: ensure "Maintain" remark exists before adding the
        // empty one. Autofill may have already written it during the ensureFedcActivity
        // await, so check first to avoid a duplicate.
        if (btn.dataset.isMaintained === "1") {
          const alreadyMaintained = Object.values(state.sessionData.remarks || {})
            .some(r => r.activityId === actId && r.text === "Maintain");
          if (!alreadyMaintained) {
            const mId = generateId("r");
            state.sessionData.remarks = state.sessionData.remarks || {};
            state.sessionData.remarks[mId] = { activityId: actId, text: "Maintain", trials: [], order: Date.now() - 1 };
            addRemark(state.currentSessionId, actId, "Maintain", null, mId).catch(() => {
              delete state.sessionData.remarks[mId];
            });
          }
        }
        const initialText = "";
        // Write the remark into local state and render right away instead of
        // waiting on the Firestore round trip — addRemark() is handed the
        // same ID so it just confirms this row server-side in the background.
        const remId = generateId("r");
        state.sessionData.remarks = state.sessionData.remarks || {};
        state.sessionData.remarks[remId] = { activityId: actId, text: initialText, trials: [], order: Date.now() };
        renderTargetContent();
        addRemark(state.currentSessionId, actId, initialText, null, remId).catch(err => {
          delete state.sessionData.remarks[remId];
          renderTargetContent();
          alert("Couldn't add remark — check your connection and try again.\n\n" + err.message);
        });
      } catch (err) {
        btn.disabled = false;
        alert("Couldn't add remark — check your connection and try again.\n\n" + err.message);
      }
    });
  });

  // ── Remark option buttons (single-select) ─────────────────
  c.querySelectorAll(".remark-preset-opts:not(.remark-preset-opts-multi) .btn-remark-opt").forEach(btn => {
    btn.addEventListener("click", () => {
      const isActive = btn.classList.contains("active");
      btn.closest(".remark-preset-opts")?.querySelectorAll(".btn-remark-opt").forEach(b => b.classList.remove("active"));
      const newText = isActive ? "" : btn.dataset.opt;
      if (!isActive) btn.classList.add("active");
      const remId = btn.dataset.remId;
      const rem = state.sessionData?.remarks?.[remId];
      const prevText = rem?.text;
      if (rem) rem.text = newText;
      updateRemarkText(state.currentSessionId, remId, newText).catch(err => {
        if (rem) rem.text = prevText;
        alert("Couldn't save — check your connection and try again.\n\n" + err.message);
      });
      // Auto-score: set/clear optionScore (separate from manual trials)
      if (btn.dataset.score !== "") {
        const autoScore = Number(btn.dataset.score);
        if (!isNaN(autoScore)) {
          const prevOptScore = rem?.optionScore;
          if (!isActive) {
            if (rem) rem.optionScore = autoScore;
            renderTargetContent();
            setOptionScore(state.currentSessionId, remId, autoScore).catch(err => {
              if (rem) { if (prevOptScore !== undefined) rem.optionScore = prevOptScore; else delete rem.optionScore; }
              renderTargetContent();
              alert("Couldn't save — check your connection and try again.\n\n" + err.message);
            });
          } else {
            if (rem) delete rem.optionScore;
            renderTargetContent();
            clearOptionScore(state.currentSessionId, remId).catch(err => {
              if (rem) rem.optionScore = prevOptScore;
              renderTargetContent();
              alert("Couldn't save — check your connection and try again.\n\n" + err.message);
            });
          }
        }
      } else if (isActive && rem?.optionScore !== undefined) {
        // Deselecting a scoreless option — clear any lingering optionScore
        delete rem.optionScore;
        renderTargetContent();
        clearOptionScore(state.currentSessionId, remId).catch(() => {});
      }
    });
  });

  // ── Remark option buttons (multi-select) ──────────────────
  c.querySelectorAll(".remark-preset-opts-multi .btn-remark-opt").forEach(btn => {
    btn.addEventListener("click", () => {
      btn.classList.toggle("active");
      const container = btn.closest(".remark-preset-opts-multi");
      const selected = [...container.querySelectorAll(".btn-remark-opt.active")].map(b => b.dataset.opt);
      const newText = selected.join(", ");
      const remId = btn.dataset.remId;
      const rem = state.sessionData?.remarks?.[remId];
      const prevText = rem?.text;
      if (rem) rem.text = newText;
      updateRemarkText(state.currentSessionId, remId, newText).catch(err => {
        if (rem) rem.text = prevText;
        alert("Couldn't save — check your connection and try again.\n\n" + err.message);
      });
    });
  });


  // ── New remark: ✓ Save button or Ctrl/Cmd+Enter saves ───
  c.querySelectorAll(".btn-save-remark").forEach(btn => {
    btn.addEventListener("click", () => saveNewRemark(target));
  });
  // Enter/Ctrl+Enter inside #new-remark-textarea is handled by the delegated
  // keydown listener set up at the top of this function.

  // ── Cancel new remark ─────────────────────────────────────
  c.querySelectorAll(".btn-cancel-remark").forEach(btn => {
    btn.addEventListener("click", () => {
      state.pendingNewRemark = null;
      renderTargetContent();
    });
  });

  // ── Sketch board buttons (session screen) ─────────────────
  c.querySelectorAll(".btn-sketch[data-rem-id]").forEach(btn => {
    btn.addEventListener("click", () => {
      const id = btn.dataset.remId;
      const field = c.querySelector(`.remark-text-input[data-rem-id="${id}"]`)
                 || c.querySelector(`.mastery-note-input[data-rem-id="${id}"]`);
      if (field) openTextEditorSheet(field);
    });
  });
  c.querySelector(".btn-sketch-pending")?.addEventListener("click", () => {
    const field = $("new-remark-textarea");
    if (field) openTextEditorSheet(field);
  });

  // ── Delete remark ─────────────────────────────────────────
  c.querySelectorAll(".btn-delete-remark").forEach(btn => {
    btn.addEventListener("click", () => {
      if (!confirm("Delete this remark and its trials?")) return;
      const remId = btn.dataset.remId;
      const rem = state.sessionData?.remarks?.[remId];
      if (!rem) return;
      delete state.sessionData.remarks[remId];
      renderTargetContent();
      deleteRemark(state.currentSessionId, remId).catch(err => {
        state.sessionData.remarks[remId] = rem;
        renderTargetContent();
        alert("Couldn't delete remark — check your connection and try again.\n\n" + err.message);
      });
    });
  });

  // ── Delete note ───────────────────────────────────────────
  c.querySelectorAll(".btn-delete-note").forEach(btn => {
    btn.addEventListener("click", () => {
      if (!confirm("Delete this note? The text will be lost.")) return;
      const remId = btn.dataset.remId;
      const entryBlock = btn.closest(".entry-block");
      if (state.sessionData?.remarks?.[remId]) state.sessionData.remarks[remId].masteryNote = "";
      const sid = state.currentSessionId;
      if (sid) updateRemarkNote(sid, remId, "").catch(() => {});
      const noteDiv = entryBlock?.querySelector(`.entry-note-field[data-rem-id="${remId}"]`);
      if (noteDiv) {
        const ta = noteDiv.querySelector(".mastery-note-input");
        if (ta) { ta.value = ""; ta.dataset.savedHtml = ""; }
      }
    });
  });

  // Ghost (.predef-remark-input) and live (.predef-remark-input-live) predefined
  // remark inputs are also saved by the shared merged-editing host — see above.
  // Enter is handled by the delegated keydown listener at the top of this function.

  // ── Pencil: open Edit Target and scroll to this activity ──
  c.querySelectorAll(".btn-edit-activity-pencil").forEach(btn => {
    btn.addEventListener("click", () => {
      const paId = btn.dataset.paId;
      const student = state.currentStudent;
      const tgt = student?.targets?.find(t => t.name === state.selectedTargetName);
      if (!student || !tgt) return;
      openManageModal(student, tgt, null, null, paId || null);
    });
  });

  // ── Init predefined remark + open score picker ────────────
  c.querySelectorAll(".btn-init-predef-remark").forEach(btn => {
    btn.addEventListener("click", async () => {
      const tgt = state.currentStudent.targets.find(t => t.name === btn.dataset.target);
      if (!tgt) return;
      const paOrder = btn.dataset.paOrder !== "" ? Number(btn.dataset.paOrder) : 0;
      const actId = await ensureFedcActivity(tgt.name, btn.dataset.paName, paOrder);
      // Capture any text the boss already typed in the ghost input
      const ghostInput = [...c.querySelectorAll(".predef-remark-input")].find(
        inp => inp.dataset.remName === btn.dataset.remName
      );
      const initialText = ghostInput?.value.trim() || "";
      const remId = await ensurePredefinedRemark(actId, btn.dataset.remName, initialText);
      openScorePicker(remId, tgt.maxPoints || 3);
      // ensurePredefinedRemark already wrote initialText when creating a brand-new
      // remark — this only matters for the rare case where it already existed
      // with stale text, so don't block opening the score picker on it.
      if (initialText) updateRemarkText(state.currentSessionId, remId, initialText).catch(() => {});
    });
  });

  // ── Add trial ─────────────────────────────────────────────
  c.querySelectorAll(".btn-add-trial").forEach(btn => {
    btn.addEventListener("click", () => {
      const tgt = state.currentStudent.targets.find(t => t.name === btn.dataset.target);
      openScorePicker(btn.dataset.remId, tgt?.maxPoints || 3);
    });
  });

  // ── Delete trial ──────────────────────────────────────────
  c.querySelectorAll(".btn-trial-delete").forEach(btn => {
    btn.addEventListener("click", e => {
      e.stopPropagation();
      const rem = state.sessionData?.remarks?.[btn.dataset.remId];
      if (!rem) return;
      const idx = Number(btn.dataset.idx);
      const prevTrials = rem.trials || [];
      rem.trials = prevTrials.filter((_, i) => i !== idx);
      renderTargetContent();
      deleteTrial(state.currentSessionId, btn.dataset.remId, idx, prevTrials).catch(err => {
        rem.trials = prevTrials;
        renderTargetContent();
        alert("Couldn't delete trial — check your connection and try again.\n\n" + err.message);
      });
    });
  });

  // ── Manual score input: allow only numeric characters, update hint live ──
  c.querySelectorAll(".remark-text-input[data-manual-score='1']").forEach(input => {
    const _msHint = () => c.querySelector(`.manual-score-hint[data-rem-id="${input.dataset.remId}"]`);
    const _msSetHint = (hint, pct) => {
      if (pct !== null) { hint.textContent = `= ${pct}%`; hint.style.display = ""; hint.style.color = "#9ca3af"; }
      else              { hint.textContent = ""; hint.style.display = "none"; hint.style.color = ""; }
    };
    const _msUpdateAvgChip = (rawVal) => {
      const remId = input.dataset.remId;
      const rem = state.sessionData?.remarks?.[remId];
      if (!rem) return;
      const prevText = rem.text;
      rem.text = rawVal;
      const target = getEffectiveTargets().find(t => t.name === state.selectedTargetName);
      if (target) {
        const liveAvg = calcDaysAverage(target);
        const avgEl = $("days-average-value");
        if (avgEl) avgEl.textContent = liveAvg !== null ? liveAvg + "%" : "—";
      }
      rem.text = prevText;
    };
    const _msSanitize = (raw) => {
      let s = raw.replace(/[^0-9./%]/g, "");
      // Nothing allowed after %
      const pctIdx = s.indexOf("%");
      if (pctIdx !== -1) s = s.slice(0, pctIdx + 1);
      // Only one /
      const slashIdx = s.indexOf("/");
      if (slashIdx !== -1) s = s.slice(0, slashIdx + 1) + s.slice(slashIdx + 1).replace(/\//g, "");
      // Collapse consecutive dots
      s = s.replace(/\.{2,}/g, ".");
      return s;
    };
    input.addEventListener("input", () => {
      const sanitized = _msSanitize(input.value);
      if (input.value !== sanitized) {
        const pos = input.selectionStart - (input.value.length - sanitized.length);
        input.value = sanitized;
        input.setSelectionRange(Math.max(0, pos), Math.max(0, pos));
      }
      const hint = _msHint();
      if (!hint) return;
      const parsed = parseManualScore(sanitized.trim());
      const pct    = parsed !== null ? Math.round(parsed * 10) / 10 : null;
      _msSetHint(hint, pct);
      _msUpdateAvgChip(sanitized.trim());
    });
    let _msAlerting = false;
    input.addEventListener("blur", () => {
      if (_msAlerting) return;
      const val = input.value.trim();
      const err = validateManualScore(val);
      if (!err) {
        const hint = _msHint();
        if (hint) {
          const parsed = parseManualScore(val);
          _msSetHint(hint, parsed !== null ? Math.round(parsed * 10) / 10 : null);
        }
        return;
      }
      _msAlerting = true;
      alert(err);
      _msAlerting = false;
      setTimeout(() => input.focus(), 0);
    });
  });

}

// ─── ACTION HELPERS ──────────────────────────────────────────

async function confirmNewActivity(target) {
  const input = $("new-activity-textarea");
  if (!input) return;
  const name = input.value.trim();
  if (!name) { input.focus(); return; }
  state.pendingNewActivity = null;
  flashSaved(input);
  input.value = "";  // blur handler sees empty → calls renderTargetContent at +150ms
  input.blur();      // dismiss keyboard; flash shows for ~150ms then input removed
  await addActivity(state.currentSessionId, target.name, name, Date.now(), false);
}

function cancelPendingActivity() {
  state.pendingNewActivity = null;
  renderTargetContent();
}

async function saveNewRemark(target) {
  const ta = $("new-remark-textarea");
  if (!ta || !state.pendingNewRemark) return;

  const text    = htmlForStorage(ta.value);
  const p       = state.pendingNewRemark;
  const paName  = p.paName || null;
  const paOrder = p.paOrder ?? 0;
  let   actId   = p.actId  || null;

  state.pendingNewRemark = null; // prevent blur-handler double-save
  flashSaved(ta);
  ta.blur(); // clear focus so Firebase snapshot can trigger re-render

  if (paName) actId = await ensureFedcActivity(target.name, paName, paOrder);
  if (!actId) return;
  await addRemark(state.currentSessionId, actId, text);
}

// True for the remark types where there's a fixed set of things to pick from
// (Select one / Tick boxes / Sentence Starter + either, or + Select One +
// Free Text) — these warrant auto-opening a remark since there's no typing
// to do first. Free text and Sentence Starter + Free Text are excluded:
// there's nothing to pre-select, so they stay collapsed behind "+ Add
// Remark & Trials" until the boss actually has something to type.
function isAutoOpenRemarkType(pa) {
  if (pa.manualScore) return true;
  if (pa.remarkHasNote) return true;
  if (pa.sentenceStarter && pa.inlineOptions) return true;
  if (pa.sentenceStarter) return false;
  return !!(pa.inlineOptions || pa.remarkPresetId);
}

// Auto-create an empty remark for every "pick from options" activity on
// session open, unconditionally — the point is just to skip the extra click,
// there's no "previous value" to wait for first.
// Same in-flight guard as autoFillMappedRemarks below (structuredRemarkAutoFillInFlight,
// keyed the same way) — without it, a duplicate activity could be created
// here too if firstLoad re-entered before a prior addActivity+addRemark
// pair finished, the exact shape mergeDuplicateActivity (firebase-service.js)
// exists to clean up. This only protects re-entrancy within one open tab —
// it can't stop two devices/tabs racing each other, which is why the
// Data Integrity Check's duplicate-activity section exists as a backstop.
async function autoFillStructuredRemarks(student, sessionId) {
  const data = state.sessionData;

  // Collect everything that needs filling first (no await yet)
  const toFill = [];
  for (const target of (student.targets || [])) {
    for (const pa of (target.predefinedActivities || [])) {
      const _paIsNotesOnly = !getActivityInlineOptions(pa) && !pa.optionsMulti && !pa.manualScore;
      if (pa.isCompleted || pa.isArchived || pa.isStopped || pa.isMaintain || pa.isMaintainHeading || (pa.maintained && _paIsNotesOnly)) continue;
      if (!isAutoOpenRemarkType(pa)) continue;
      const paParent = pa.parentActivity || null;
      const paConfigId = pa.id || null;
      const allActs = Object.entries(data.activities || {});
      // Collect ALL candidate records for this activity slot: the configId-matched
      // record AND any unlinked (no configId) record matching by name+parent.
      // Two records can coexist when an old session has a data record created before
      // the configId system (Record A, no configId) alongside an auto-fill placeholder
      // (Record B, has configId). We must skip auto-fill if ANY candidate already
      // has a remark — not just the configId-matched one — otherwise we keep
      // creating a fresh placeholder for Record B even when Record A has real data,
      // causing the oscillating display bug.
      const allCandidateIds = allActs
        .filter(([, a]) => {
          if (a.targetName !== target.name) return false;
          if (paConfigId && a.configId === paConfigId) return true;
          if (a.configId) return false;
          const nameOk = (pa.name && a.activityName === pa.name) || (pa.title && a.activityName === pa.title);
          if (!nameOk) return false;
          return paParent ? (!a.parentActivity || a.parentActivity === paParent) : !a.parentActivity;
        })
        .map(([id]) => id);
      const allRemarkActIds = new Set(Object.values(data.remarks || {}).map(r => r.activityId));
      const _sMaintAt = pa.maintainedAt || "2026-08-21";
      const _sOnOrAfterMaint = !data.date || data.date >= _sMaintAt;
      if (allCandidateIds.some(id => allRemarkActIds.has(id))) {
        // Remark exists — patch empty masteryNote to "Maintain" for sessions on/after maintained date
        if (pa.maintained && _sOnOrAfterMaint) {
          for (const candId of allCandidateIds) {
            const actRems = Object.entries(data.remarks || {}).filter(([, r]) => r.activityId === candId);
            if (actRems.length > 1) {
              const _isMaintainAutoFill = ([, r]) =>
                !(r.text || "").trim() &&
                (r.masteryNote || "").replace(/<[^>]*>/g, "").trim() === "Maintain" &&
                !(r.trials || []).some(t => t >= 0) &&
                r.optionScore === undefined;
              const autoFillRems = actRems.filter(_isMaintainAutoFill);
              const realRems     = actRems.filter(e => !_isMaintainAutoFill(e));
              if (autoFillRems.length > 0 && realRems.length > 0) {
                const toDelete = autoFillRems.map(([id]) => id);
                for (const remId of toDelete) delete data.remarks[remId];
                deleteRemarksBatch(sessionId, toDelete).catch(() => {});
              }
              continue;
            }
            if (actRems.length !== 1) continue;
            const [[remId, r]] = actRems;
            const _remHasContent = !!(r.text || "").trim()
              || !!(r.masteryNote || "").replace(/<[^>]*>/g, "").trim()
              || ((r.selectedOptions || []).length > 0)
              || (r.optionScore !== undefined && r.optionScore !== null);
            if (!_remHasContent)
              updateRemarkNote(sessionId, remId, "Maintain").catch(() => {});
          }
        }
        continue;
      }
      // Guard: don't create a duplicate when a name-matched activity already has a remark
      const _sNameMatchHasRemark = allActs.some(([actId2, a2]) => {
        if (a2.targetName !== target.name) return false;
        const _nOk = (pa.name && a2.activityName === pa.name) || (pa.title && a2.activityName === pa.title);
        if (!_nOk) return false;
        const _pOk = paParent ? (!a2.parentActivity || a2.parentActivity === paParent) : !a2.parentActivity;
        return _pOk && allRemarkActIds.has(actId2);
      });
      if (_sNameMatchHasRemark) continue;
      const existingAct = allCandidateIds.length > 0
        ? allActs.find(([id]) => id === allCandidateIds[0])
        : null;
      let actId = existingAct?.[0] || null;
      const key = `${sessionId}:${target.name}:${paConfigId || pa.name}:${paParent || ""}`;
      if (structuredRemarkAutoFillInFlight.has(key)) continue;
      structuredRemarkAutoFillInFlight.add(key);
      const maintNote = pa.maintained && _sOnOrAfterMaint ? "Maintain" : "";
      toFill.push({ target, pa, actId, key, paParent, paConfigId, maintNote });
    }
  }
  if (toFill.length === 0) return 0;

  // Single wave: for items that need a brand-new activity, create the activity
  // AND its empty placeholder remark in ONE atomic Firestore write so no
  // intermediate snapshot can arrive showing "+Add Remark & Trials" between
  // the two operations. For existing activities (actId already known) only a
  // remark write is needed — no between-write gap risk there.
  await Promise.all(toFill.map(async item => {
    try {
      if (!item.actId) {
        await addAutoFillActivityAndRemark(sessionId, item.target.name, item.pa.title || item.pa.name, item.pa.order ?? 0, item.paParent, item.paConfigId, item.maintNote);
      } else {
        await addRemark(sessionId, item.actId, "", null, undefined, item.maintNote);
      }
    } catch {
      // silent — auto-fill is best-effort; the next session open will retry
    } finally {
      structuredRemarkAutoFillInFlight.delete(item.key);
    }
  }));

  return toFill.length;
}

// Auto-create an empty remark for a mapped-score activity as soon as its
// mapped target gains a computable average — otherwise the row stays
// collapsed (no remark of its own) even after the target it pulls from has
// real data. Unlike autoFillStructuredRemarks this runs on every snapshot,
// not just first load: the trigger ("the other target now has data") can
// become true at any point while this session stays open, not only when
// it's opened.
// Creating a mapped-score activity's first remark is two separate Firestore
// writes (addActivity, then addRemark) — each one's own snapshot can re-enter
// these auto-fill functions before the second write lands, racing into a
// duplicate remark for the same activity (or, for group sessions, the same
// attendee). Shared by all four autoFill*MappedRemarks functions below so a
// re-entrant call for the same key skips instead of double-adding.
const mappedRemarkAutoFillInFlight = new Set();

// The session screen finds an activity's session record by (pa.name || pa.title)
// — details first — plus pa.id as configId, and every other creation path stores
// it that way. The mapped/maintained auto-fills below used to create it under
// (pa.title || pa.name) — title first — and never stamped configId at all. For an
// activity with BOTH an Activity Title and Activity Details those two disagree, so
// the record was written under one name and looked up under another: the record and
// its remark became invisible, the screen fell back to "+ Add Score", and clicking
// that did nothing (the auto-fill found the hidden record by title, saw it already
// had a remark, and concluded there was nothing to do). Re-link any such record to
// the current config so it — and the remark already sitting on it — reappear.
function relinkAutoFillActivity(sessionId, data, actId, pa) {
  const rec = data?.activities?.[actId];
  if (!rec || !sessionId) return;
  if (pa.id && !rec.configId) {
    rec.configId = pa.id;
    adoptOrphanActivity(sessionId, actId, rec.parentActivity || null, pa.id).catch(() => {});
  }
  const wantName = pa.name || pa.title;
  if (!wantName || rec.activityName === wantName) return;
  // Never rename onto a name another record in this target already holds — that
  // would make two config activities share one record (see the heading-rename
  // hijack fixed in v606).
  const clash = Object.entries(data.activities || {}).some(([id, a]) =>
    id !== actId && a.targetName === rec.targetName && a.activityName === wantName);
  if (clash) return;
  rec.activityName = wantName;
  updateActivityName(sessionId, actId, wantName).catch(() => {});
}

async function autoFillMappedRemarks(student, sessionId) {
  const data = state.sessionData;

  const toFill = [];
  for (const target of (student.targets || [])) {
    for (const pa of (target.predefinedActivities || [])) {
      if (pa.isCompleted || pa.isArchived || pa.isStopped || pa.isMaintain || pa.isMaintainHeading) continue;
      if (!pa.isMapped) continue;
      const allMatches = Object.entries(data.activities || {})
        .filter(([, a]) => a.targetName === target.name &&
                           (a.activityName === pa.name || (pa.title && a.activityName === pa.title) || (pa.id && a.configId === pa.id)));
      const canonical = allMatches.find(([, a]) => pa.id && a.configId === pa.id) || allMatches[0] || null;
      for (const [dupeActId] of allMatches.filter(([aid]) => aid !== canonical?.[0] && !data.activities[aid]?.configId)) {
        const dupeRemIds = Object.entries(data.remarks || {}).filter(([, r]) => r.activityId === dupeActId).map(([rid]) => rid);
        deleteActivity(sessionId, dupeActId, dupeRemIds);
      }
      let actId = canonical?.[0] || null;
      // Heal records written by older title-first auto-fills before deciding
      // there's nothing to do — otherwise an invisible record with a remark on
      // it keeps this activity stuck showing "+ Add Score" forever.
      if (actId) relinkAutoFillActivity(sessionId, data, actId, pa);
      if (actId && Object.values(data.remarks || {}).some(r => r.activityId === actId)) continue;
      const key = `${sessionId}:${target.name}:${pa.name}`;
      if (mappedRemarkAutoFillInFlight.has(key)) continue;
      mappedRemarkAutoFillInFlight.add(key);
      toFill.push({ target, pa, actId, key });
    }
  }
  if (toFill.length === 0) return 0;

  await Promise.all(toFill.map(async item => {
    if (!item.actId) {
      try {
        // Name/configId must match what the renderer looks up with —
        // see relinkAutoFillActivity above.
        item.actId = await addActivity(sessionId, item.target.name, item.pa.name || item.pa.title, item.pa.order ?? 0, true, undefined, null, item.pa.id || null);
      } catch (err) {
        mappedRemarkAutoFillInFlight.delete(item.key);
        item.actId = null;
      }
    }
  }));

  await Promise.all(toFill.map(async item => {
    if (!item.actId) return;
    try {
      await addRemark(sessionId, item.actId, "");
    } finally {
      mappedRemarkAutoFillInFlight.delete(item.key);
    }
  }));

  return toFill.length;
}

// Auto-create a "Maintain" remark for every maintained activity in the session.
// Mirrors autoFillMappedRemarks — runs on first load and target switch only.
const maintainedRemarkAutoFillInFlight = new Set();

// Shared fill executor: creates the activity (if missing) then the remark.
async function _runMaintainedFills(sessionId, items) {
  await Promise.all(items.map(async item => {
    if (!item.actId) {
      try {
        // Name/configId must match what the renderer looks up with —
        // see relinkAutoFillActivity above.
        item.actId = await addActivity(sessionId, item.target.name, item.pa.name || item.pa.title, item.pa.order ?? 0, true, undefined, null, item.pa.id || null);
      } catch { maintainedRemarkAutoFillInFlight.delete(item.key); item.actId = null; }
    }
  }));
  await Promise.all(items.map(async item => {
    if (!item.actId) return;
    try { await addRemark(sessionId, item.actId, "Maintain"); }
    finally { maintainedRemarkAutoFillInFlight.delete(item.key); }
  }));
}

// selectedTargetName: the target currently on screen. Fills for that target
// block the return value (so the snapshot listener defers rendering until
// they land). Fills for OTHER targets start concurrently in the background
// so a target with many maintained activities never stalls a different
// target that has none.
async function autoFillMaintainedRemarks(student, sessionId, selectedTargetName = null) {
  const data = state.sessionData;
  const currentFill = [];
  const bgFill = [];
  for (const target of (student.targets || [])) {
    const bucket = (selectedTargetName === null || target.name === selectedTargetName)
      ? currentFill : bgFill;
    for (const pa of (target.predefinedActivities || [])) {
      if (!pa.maintained || pa.isHeading || pa.isNote || pa.isExportNote || pa.isMaintainHeading || (!pa.name && !pa.title) || pa.parentActivity) continue;
      // Non-Notes-Only activities (checkbox/MC/manual score) show their real UI via
      // autoFillStructuredRemarks; only Notes-Only gets a "Maintain" text remark here.
      if (getActivityInlineOptions(pa) || pa.optionsMulti || pa.manualScore) continue;
      // Skip if this activity is already being tracked as a sub-activity in the session
      // (e.g. maintained flag left over from when it was top-level before being made a sub-activity)
      if (Object.values(data.activities || {}).some(
        a => a.targetName === target.name && a.parentActivity &&
             (a.activityName === (pa.title || pa.name))
      )) continue;
      // Only auto-fill "Maintain" for sessions on or after the maintained date
      const _paMaintAt = pa.maintainedAt || "2026-08-21";
      if (data.date && data.date < _paMaintAt) continue;
      // Match by configId first, then by non-empty title/name. Never match by empty name —
      // that would false-positive against orphan records that also have activityName:"".
      const allMatches = Object.entries(data.activities || {})
        .filter(([, a]) => a.targetName === target.name && !a.parentActivity &&
                           ((pa.id && a.configId === pa.id) || (pa.title && a.activityName === pa.title) || (pa.name && a.activityName === pa.name)));
      // Prefer the activity that has configId set (the original predefined one).
      const canonical = allMatches.find(([, a]) => pa.id && a.configId === pa.id) || allMatches[0] || null;
      // Delete any name-only duplicates that lack configId — leftovers from the old bug.
      for (const [dupeActId] of allMatches.filter(([aid]) => aid !== canonical?.[0] && !data.activities[aid]?.configId)) {
        const dupeRemIds = Object.entries(data.remarks || {}).filter(([, r]) => r.activityId === dupeActId).map(([rid]) => rid);
        deleteActivity(sessionId, dupeActId, dupeRemIds);
      }
      let actId = canonical?.[0] || null;
      if (actId) {
        // Heal records written by older title-first auto-fills — see
        // relinkAutoFillActivity above.
        relinkAutoFillActivity(sessionId, data, actId, pa);
        const existingRems = Object.entries(data.remarks || {}).filter(([, r]) => r.activityId === actId);
        if (existingRems.length > 1) {
          // Cleanup: remove extra unmodified "Maintain" placeholders (race-created duplicates)
          const stripE = s => (s || "").replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").replace(/ /g, " ").trim();
          for (const [dupeId, dupeRem] of existingRems.slice(1)) {
            if (stripE(dupeRem.text) === "Maintain" && !stripE(dupeRem.masteryNote) && !(dupeRem.trials || []).some(t => t >= 0)) {
              delete data.remarks[dupeId];
              deleteRemark(sessionId, dupeId).catch(() => {});
            }
          }
        }
        if (Object.entries(data.remarks || {}).some(([, r]) => r.activityId === actId)) continue;
      }
      const key = `${sessionId}:${target.name}:${pa.name}:maintained`;
      if (maintainedRemarkAutoFillInFlight.has(key)) continue;
      maintainedRemarkAutoFillInFlight.add(key);
      bucket.push({ target, pa, actId, key });
    }
  }
  // Other targets: start fills but don't block rendering on them.
  if (bgFill.length > 0) _runMaintainedFills(sessionId, bgFill).catch(() => {});
  if (currentFill.length === 0) return 0;
  await _runMaintainedFills(sessionId, currentFill);
  return currentFill.length;
}

// Deletes remarks that have no text, no mastery note, and no valid trials for
// the given target, then removes any activity that is left with no remarks.
// A "-1" trial is the View/Edit screen's "+" placeholder for a slot that was
// added but never given an actual score — it never counts as real data: a
// remark that's otherwise empty gets deleted outright (as if "+" was never
// clicked), and one that has other real content just has that stray slot
// quietly dropped from its trials array.
async function cleanupEmptyEntries(sessionId, data, targetName, target = null, isLeaving = false) {
  if (!sessionId || !data) return;
  // Mapped-score activities are designed to have no remark of their own until
  // their mapped target gains an average (see autoFillMappedRemarks) — an
  // empty one isn't stale data, it's the activity waiting to auto-fill. Treat
  // them as exempt so this cleanup never races that auto-fill and deletes it.
  const mappedNames   = new Set((target?.predefinedActivities || []).filter(pa => pa.isMapped).map(pa => pa.name));
  // Maintained non-Notes-Only activities always keep their auto-created placeholder
  // remark so the proper UI (checkboxes/MC/manual score) stays visible on revisit.
  const maintainedStructuredNames = new Set(
    (target?.predefinedActivities || [])
      .filter(pa => pa.maintained && (getActivityInlineOptions(pa) || pa.optionsMulti || pa.manualScore))
      .map(pa => pa.title || pa.name)
  );
  // Auto-open activities (Select One / Tickbox / Sentence Starter + select) get
  // an empty placeholder remark on session open so the user can pick immediately.
  // During a target switch (isLeaving = false) keep them — they're waiting for input.
  // On session leave (isLeaving = true) treat them like any other empty remark so
  // they don't persist as ghost records when the session has other real data.
  const autoOpenNames = isLeaving
    ? new Set()
    : new Set((target?.predefinedActivities || []).filter(pa => isAutoOpenRemarkType(pa)).map(pa => pa.title || pa.name));
  const acts = Object.entries(data.activities || {})
    .filter(([, a]) => a.targetName === targetName && !mappedNames.has(a.activityName) &&
      // Always process maintained-structured activities so extra empty remarks get cleaned up,
      // even during target-switch when autoOpenNames would normally skip them.
      (!autoOpenNames.has(a.activityName) || maintainedStructuredNames.has(a.activityName)));
  const stripEmpty = s => (s || "").replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").replace(/ /g, " ").trim();
  for (const [actId, act] of acts) {
    const rems = Object.entries(data.remarks || {}).filter(([, r]) => r.activityId === actId);
    if (maintainedStructuredNames.has(act.activityName)) {
      // Keep the auto-fill "Maintain" placeholder; delete only empty extras the user added via "+"
      if (rems.length <= 1) continue;
      const sorted = [...rems].sort(([, a], [, b]) => (a.order || 0) - (b.order || 0));
      for (const [remId, r] of sorted.slice(1)) {
        const realTrials = (r.trials || []).filter(t => t !== -1);
        const rText = stripEmpty(r.text);
        const rNote = stripEmpty(r.masteryNote);
        const isEmpty = !rText.length && !rNote.length && realTrials.length === 0 && r.optionScore === undefined;
        // Also catch extras that got "Maintain" patched in before v1752 — those are still throwaways
        const isMaintainOnly = (rText === "Maintain" || rNote === "Maintain") && realTrials.length === 0 && r.optionScore === undefined;
        if (isEmpty || isMaintainOnly) await deleteRemark(sessionId, remId);
      }
      continue;
    }
    // Extra (session-only) activities with no name AND no remarks are orphans
    // from abandoned "+Add Activity" presses - clean them up here.
    if (rems.length === 0 && !act.isPredefined && !stripEmpty(act.activityName)) {
      await deleteActivity(sessionId, actId, []);
      continue;
    }
    const emptyIds = [];
    for (const [remId, r] of rems) {
      const trials     = r.trials || [];
      const realTrials = trials.filter(t => t !== -1);
      const hasText = stripEmpty(r.text).length > 0;
      const hasNote = stripEmpty(r.masteryNote).length > 0;
      if (!hasText && !hasNote && realTrials.length === 0 && r.optionScore === undefined) {
        emptyIds.push(remId);
      } else if (realTrials.length !== trials.length) {
        await setTrials(sessionId, remId, realTrials);
      }
    }
    if (!emptyIds.length) continue;
    if (emptyIds.length === rems.length) {
      await deleteActivity(sessionId, actId, emptyIds); // removes activity + all its empty remarks
    } else {
      for (const remId of emptyIds) await deleteRemark(sessionId, remId);
    }
  }
}

async function ensureFedcActivity(targetName, activityName, order, parentActivity = null, configId = null) {
  const existing = findActivityByName(targetName, activityName, parentActivity, configId);
  if (existing) {
    // Persist configId to Firestore for any unlinked record adopted by name so future
    // lookups use exact matching and same-named activities stop sharing Firestore data.
    if (configId && !existing.configId) {
      if (state.sessionData?.activities?.[existing.id]) state.sessionData.activities[existing.id].configId = configId;
      adoptOrphanActivity(state.currentSessionId, existing.id, existing.parentActivity || null, configId).catch(() => {});
    }
    return existing.id;
  }
  return await addActivity(state.currentSessionId, targetName, activityName, order, true, undefined, parentActivity, configId);
}

async function ensurePredefinedRemark(actId, remarkName, initialText = "") {
  const existing = findRemarkByPredefinedKey(actId, remarkName);
  if (existing) return existing.id;
  return await addRemark(state.currentSessionId, actId, initialText, remarkName);
}

function findRemarkByPredefinedKey(actId, key) {
  const found = Object.entries(state.sessionData?.remarks || {}).find(
    ([, r]) => r.activityId === actId && r.predefinedKey === key
  );
  return found ? { id: found[0], ...found[1] } : null;
}

// ─── SCORE PICKER MODAL ──────────────────────────────────────

function _activeSessionData() {
  return state.scorePicker?.isGroup ? state.groupSessionData : state.sessionData;
}
function _activeSessionId() {
  return state.scorePicker?.isGroup ? state.groupSessionId : state.currentSessionId;
}

function renderScoreModalTrials(remId) {
  const el = $("score-modal-trials");
  if (!el) return;
  const allTrials = _activeSessionData()?.remarks?.[remId]?.trials || [];
  const visible = allTrials.map((t, i) => ({ t, i })).filter(({ t }) => t !== -1);
  if (!visible.length) { el.innerHTML = ""; return; }

  el.innerHTML =
    `<span class="score-modal-trials-label">Added:</span>` +
    visible.map(({ t, i }) =>
      `<span class="score-modal-trial-badge">
        ${t}<button class="score-trial-del" data-idx="${i}" aria-label="Remove">×</button>
      </span>`
    ).join("");

  el.querySelectorAll(".score-trial-del").forEach(btn => {
    btn.addEventListener("click", async e => {
      e.stopPropagation();
      const idx = Number(btn.dataset.idx);
      btn.closest(".score-modal-trial-badge").remove(); // optimistic
      const rem = _activeSessionData()?.remarks?.[remId];
      if (rem) await deleteTrial(_activeSessionId(), remId, idx, rem.trials || []);
    });
  });
}

function openScorePicker(remId, target) {
  const maxPoints = (typeof target === "object" ? target?.maxPoints : target) || 3;
  const isGroup   = !!state.scorePicker?.isGroup;
  state.scorePicker = { open: true, remId, isGroup };
  const labels = CONFIG.SCORE_LABELS[maxPoints] || CONFIG.SCORE_LABELS[3];

  renderScoreModalTrials(remId);

  $("score-buttons").innerHTML = Object.entries(labels).map(([score, label]) =>
    `<button class="score-btn" data-score="${score}">
      <span class="score-num">${score}</span>
      <span class="score-label">${escHtml(label)}</span>
    </button>`
  ).join("");

  $("score-buttons").querySelectorAll(".score-btn").forEach(btn => {
    btn.addEventListener("click", async () => {
      const rem = _activeSessionData()?.remarks?.[remId];
      if (!rem) return;
      const score = Number(btn.dataset.score);
      await addTrial(_activeSessionId(), remId, score, rem.trials || []);
      // Firestore snapshot will call renderScoreModalTrials to update badges
    });
  });

  $("score-modal").classList.remove("hidden");
}

function closeScorePicker() {
  state.scorePicker = { open: false, remId: null };
  $("score-modal").classList.add("hidden");
}

$("score-modal-close").addEventListener("click",    closeScorePicker);
$("score-modal-backdrop").addEventListener("click", closeScorePicker);

// ============================================================
// SESSION VIEW SCREEN (table-based view/edit for past sessions)
// ============================================================

function getViewEffectiveTargets() {
  const currentTargets = state.viewStudent?.targets || [];
  if (!state.viewSessionData) return currentTargets;
  // Always use the current target list: new targets appear in old sessions,
  // deleted targets disappear from all sessions (data removed by deleteTargetDataFromSessions).
  return currentTargets;
}

async function openSessionView(student, sessionId) {
  commitTextEditorSheet();
  state.viewStudent         = student;
  state.viewSessionId       = sessionId;
  state.viewSessionData     = null;
  state.viewRenderPending   = false;
  state.viewActionsInFlight = 0;

  showScreen("screen-session-view");
  $("view-student-name").textContent = studentLabel(student);
  $("view-session-meta").textContent = "";
  $("session-view-body").innerHTML = `<div class="loading">Loading…</div>`;
  _viewChkConfirmRole = null; clearTimeout(_viewChkConfirmTimer);
  _viewReviewPanelOpen = false; _viewCommentDraft = ""; _viewSigningCmtId = null; _viewSigningName = "";

  if (state.fbViewUnsubscribe) { state.fbViewUnsubscribe(); state.fbViewUnsubscribe = null; }

  state.viewRemarkSaver?.cleanup();
  state.viewRemarkSaver = setupViewRemarkSaving($("session-view-body"), () => state.viewSessionId, "viewActionsInFlight", () => {
    if (!state.viewRenderPending || isViewBusy() || state.viewActionsInFlight > 0) return;
    state.viewRenderPending = false;
    renderSessionView();
  }, () => state.viewSessionData);

  if (state.viewClickDelegate) {
    $("session-view-body").removeEventListener("click", state.viewClickDelegate);
  }
  state.viewClickDelegate = async e => {
    if (await handleCheckedByClick(e, false)) return;
    const addRemarkBtn = e.target.closest(".view-add-remark-target");
    if (addRemarkBtn) { showViewAddRemarkPicker(addRemarkBtn.dataset.target); return; }

    const addTrialNewBtn = e.target.closest(".view-add-trial-new");
    if (addTrialNewBtn) {
      withViewAction("viewActionsInFlight", "viewRenderPending", isViewBusy, renderSessionView, async () => {
        let actId = addTrialNewBtn.dataset.actId;
        if (!actId) {
          actId = await addActivity(
            state.viewSessionId, addTrialNewBtn.dataset.targetName, addTrialNewBtn.dataset.actName,
            Date.now(), addTrialNewBtn.dataset.isPredefined === "true",
            undefined, addTrialNewBtn.dataset.parentActivity || null, addTrialNewBtn.dataset.configId || null
          );
        }
        const remId = await addRemark(state.viewSessionId, actId, "", null);
        await setTrials(state.viewSessionId, remId, [-1]);
        await waitForSessionData(() => !!state.viewSessionData?.remarks?.[remId]?.trials?.length);
      })();
      return;
    }

    const addTrialBtn = e.target.closest(".view-add-trial");
    if (addTrialBtn) {
      const rem = state.viewSessionData?.remarks?.[addTrialBtn.dataset.remId];
      if (!rem) return;
      const prevTrials = rem.trials || [];
      const trials = [...prevTrials, -1];
      rem.trials = trials;
      refreshViewTrialRow(addTrialBtn.dataset.remId);
      trackViewTrialWrite(setTrials(state.viewSessionId, addTrialBtn.dataset.remId, trials).catch(err => {
        rem.trials = prevTrials;
        refreshViewTrialRow(addTrialBtn.dataset.remId);
        alert("Couldn't add trial — check your connection and try again.\n\n" + err.message);
      }));
    }
  };
  $("session-view-body").addEventListener("click", state.viewClickDelegate);

  try {
    state.fbViewUnsubscribe = listenToSession(sessionId, async data => {
      state.viewSessionData = data;
      window._lastViewData = data; // debug: persists after navigation
      window._lastViewStudent = student;
      try {
        const filled = await autoFillViewMappedRemarks(student, sessionId, data);
        if (filled > 0) return;
      } catch (err) { console.error("autoFillViewMappedRemarks failed:", err); }
      try {
        const maintainedFilled = await autoFillViewMaintainedRemarks(student, sessionId, data);
        if (maintainedFilled > 0) return;
      } catch (err) { console.error("autoFillViewMaintainedRemarks failed:", err); }
      try {
        // Local state updated optimistically inside — fall through to render immediately.
        await autoFillViewStructuredRemarks(student, sessionId, data);
      } catch (err) { console.error("autoFillViewStructuredRemarks failed:", err); }
      if (isViewBusy() || state.viewActionsInFlight > 0) {
        state.viewRenderPending = true;
      } else {
        // Debounce snapshot-triggered renders by 250 ms. Server echo snapshots
        // (Firestore's ack of our own write) arrive after viewActionsInFlight
        // already dropped to 0 and can rebuild the DOM between a mousedown and
        // mouseup, swallowing the click. withViewAction's own render (in finally)
        // fires immediately and is unaffected by this timer.
        state.viewRenderPending = true;
        clearTimeout(state.viewSnapshotRenderTimer);
        state.viewSnapshotRenderTimer = setTimeout(() => {
          state.viewSnapshotRenderTimer = null;
          if (state.viewRenderPending && !isViewBusy()) {
            state.viewRenderPending = false;
            renderSessionView();
          }
        }, 250);
      }
    });
  } catch (err) {
    $("session-view-body").innerHTML =
      `<div class="error-msg">Could not load session.<br>${escHtml(err.message)}</div>`;
  }
}

async function leaveSessionView() {
  commitTextEditorSheet();
  $("text-editor-sheet").classList.add("hidden");
  $("btn-delete-session")?.classList.add("hidden");
  $("btn-goto-session")?.classList.add("hidden");
  _viewChkConfirmRole = null; clearTimeout(_viewChkConfirmTimer);
  _viewReviewPanelOpen = false; _viewCommentDraft = ""; _viewSigningCmtId = null; _viewSigningName = "";
  // Flush (and await it) while the Firestore listener is still live, same as
  // leaveSession() does for the live entry screen — flush() only writes to
  // Firestore, state.viewSessionData only updates once the listener echoes
  // it back, so unsubscribing first or not waiting for the flush both risk
  // the cleanup below seeing stale "empty" data for a remark just edited.
  await state.viewRemarkSaver?.flush();
  if (state.fbViewUnsubscribe) { state.fbViewUnsubscribe(); state.fbViewUnsubscribe = null; }
  state.viewRemarkSaver?.cleanup();
  state.viewRemarkSaver = null;
  if (state.viewClickDelegate) {
    $("session-view-body")?.removeEventListener("click", state.viewClickDelegate);
    state.viewClickDelegate = null;
  }
  const sessionId = state.viewSessionId;
  const data      = state.viewSessionData;
  const student   = state.viewStudent;
  state.viewSessionId       = null;
  state.viewSessionData     = null;
  state.viewStudent         = null;
  state.viewRenderPending   = false;
  state.viewActionsInFlight = 0;

  if (sessionId && data) {
    const stripEmpty = s => (s || "").replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").replace(/ /g, " ").trim();
    const fedcHasData = Object.values(data.fedcComments || {}).some(c => stripEmpty(c).length > 0);
    const remarkHasData = Object.values(data.remarks || {}).some(r => {
      const act = (data.activities || {})[r.activityId];
      if (!act) return false;
      const rText    = stripEmpty(r.text);
      const rNote    = stripEmpty(r.masteryNote);
      const rTrials  = (r.trials || []).filter(t => t !== null && t !== -1);
      const rOption  = r.optionScore !== undefined && r.optionScore !== null;
      const rSelected = (r.selectedOptions || []).length > 0;
      const isAutoFillMaintain =
        ((rText === "Maintain" && !rNote) || (rNote === "Maintain" && !rText)) &&
        rTrials.length === 0 && !rOption && !rSelected;
      if (isAutoFillMaintain) {
        const pa = (student?.targets || []).flatMap(t => t.predefinedActivities || [])
          .find(p => p.maintained && (p.name === act.activityName || (p.id && p.id === act.configId)));
        if (pa) return false;
      }
      return rText.length > 0 || rTrials.length > 0 || rNote.length > 0 || rOption || rSelected;
    });
    const allTargetNames = new Set(Object.values(data.activities || {}).map(a => a.targetName));
    allTargetNames.forEach(name => {
      const target = (student?.targets || []).find(t => t.name === name);
      cleanupEmptyEntries(sessionId, data, name, target, true).catch(() => {});
    });
    if (!fedcHasData && !remarkHasData) {
      const maintainRemIds = Object.entries(data.remarks || {})
        .filter(([, r]) => {
          const rText = stripEmpty(r.text);
          const rNote = stripEmpty(r.masteryNote);
          if (!(rText === "Maintain" || rNote === "Maintain")) return false;
          if ((r.trials || []).some(t => t !== null && t !== -1)) return false;
          if (r.optionScore !== undefined && r.optionScore !== null) return false;
          if ((r.selectedOptions || []).length) return false;
          // Only delete auto-fills: activity must be maintained AND session must be on/after
          // pa.maintainedAt. Sessions before that date had "Maintain" typed by the boss — keep.
          const act = (data.activities || {})[r.activityId];
          if (!act) return false;
          const pa = (student?.targets || []).flatMap(t => t.predefinedActivities || [])
            .find(p => p.maintained && (p.name === act.activityName || (p.id && p.id === act.configId)));
          if (!pa) return false;
          return data.date >= (pa.maintainedAt || "2026-08-21");
        })
        .map(([id]) => id);
      if (maintainRemIds.length > 0) deleteRemarksBatch(sessionId, maintainRemIds).catch(() => {});
    }
  }

  closeStickyNote();
  showHome();
}

$("btn-view-back").addEventListener("click", leaveSessionView);
$("btn-student-registry-back")?.addEventListener("click", showHome);
$("btn-todo-back")?.addEventListener("click", showHome);

// ── Checked By strip (View/Edit Past Sessions approval flow) ──────────────────
// Ray = assistant teacher; Daisy = main teacher. Rendered as the first item
// inside the scrollable body so it scrolls away with the content naturally.
// Confirm state lives in module-level vars (the DOM element is recreated on
// every renderSessionView call so dataset can't carry it between renders).

let _viewChkConfirmRole  = null;
let _viewChkConfirmTimer = null;
let _grpChkConfirmRole   = null;
let _grpChkConfirmTimer  = null;

// Review panel state (individual / group)
let _viewReviewPanelOpen = false;
let _viewCommentDraft    = "";
let _viewSigningCmtId    = null;
let _viewSigningName     = "";
let _grpReviewPanelOpen  = false;
let _grpCommentDraft     = "";
let _grpSigningCmtId     = null;
let _grpSigningName      = "";

// Sticky note (floating draggable corrections list)
let _stickyNoteSessionId      = null;
let _stickyNoteIsGroup        = false;
let _stickyNoteInstructorId   = null; // which instructor's corrections are shown
let _noteDebounce           = null;
let _focusNewRow            = false;
let _phase3Error            = null; // error string shown in Phase 3 node, auto-clears
const _textareaDebounce     = new Map();

// Returns null | "fixed" | "rejected" for a correction entry.
function getCmtStatus(c) {
  if (c.fixStatus) return c.fixStatus;  // new field ("fixed" | "rejected")
  if (c.fixedByName) return "fixed";    // backward compat
  return null;
}

function getWorkflowState(data) {
  const checks       = data?.checks || {};
  const participants = data?.participants || [];

  // ── Phase 1 ────────────────────────────────────────────────────
  const p1Ids   = participants;
  const p1Check = id => checks[`p1_${id}`] || null;
  const p1Done  = id => !!p1Check(id);
  const allP1Done = p1Ids.length > 0 && p1Ids.every(p1Done);

  const p3Ids   = p1Ids.filter(id => id !== "daisy");
  const daisyOnly = p1Ids.length === 1 && p1Ids[0] === "daisy";

  // ── Phase 2: per-instructor Check #1 (Daisy) ──────────────────
  // New keys: checks.p2_check_<id>
  // Backward compat: old reviewSubmitted covers all p3Ids when no new keys exist.
  const hasAnyNewP2    = p3Ids.some(id => !!checks[`p2_check_${id}`]);
  const reviewSubmittedOld = !!data?.reviewSubmitted;
  const p2CheckRaw  = id => checks[`p2_check_${id}`] || null;
  const p2CheckDone = id => {
    if (p2CheckRaw(id)) return true;
    if (!hasAnyNewP2 && reviewSubmittedOld && p1Done(id)) return true;
    return false;
  };
  const p2CheckAt = id => p2CheckRaw(id)?.at || (p2CheckDone(id) ? (data?.reviewSubmittedAt || 0) : 0);
  // Stale: this instructor's Phase 1 re-entered AFTER their Phase 2 check
  const p2CheckStale = id => {
    if (id === "daisy" || !p2CheckDone(id)) return false;
    const p1At = checks[`p1_${id}`]?.at || 0;
    const p2At = p2CheckAt(id);
    return p1At > 0 && p2At > 0 && p1At > p2At;
  };
  const p2EffDone = id => p2CheckDone(id) && !p2CheckStale(id);
  const allP2Done = p3Ids.length > 0 && p3Ids.every(p2EffDone);

  // ── Comments per instructor (computed first — needed by noCorr override) ──
  const comments = Object.entries(data?.reviewComments || {})
    .sort(([,a],[,b]) => (a.order || 0) - (b.order || 0));
  const commentsFor = id => comments.filter(([, c]) => {
    if (c.forInstructor) return c.forInstructor === id;
    // Multi-instructor sessions: corrections without forInstructor must not bleed across
    // instructors. Only use the legacy assignedTo fallback for single-instructor sessions.
    if (p3Ids.length > 1) return false;
    const a = c.assignedTo;
    return !a || a.length === 0 || a.includes(id);
  });
  const allFixedFor = id => {
    const mine = commentsFor(id);
    return mine.length === 0 || mine.every(([, c]) => getCmtStatus(c) === "fixed");
  };
  const allFixed = comments.length > 0 && comments.every(([, c]) => getCmtStatus(c) === "fixed");

  // ── No-corrections per instructor ─────────────────────────────
  // New keys: checks.no_corr_<id>
  // Backward compat: old no_corrections covers all p3Ids when no new keys exist.
  const hasAnyNewNoCorr = p3Ids.some(id => !!checks[`no_corr_${id}`]);
  const noCorrOld = checks["no_corrections"] || null;
  const noCorr = id => {
    const flagSet = !!(checks[`no_corr_${id}`] || (!hasAnyNewNoCorr && noCorrOld));
    if (!flagSet) return false;
    // Override stale flag: if real corrections exist in the list, bypass is cancelled
    return !commentsFor(id).some(([, c]) => (c.text || "").trim());
  };

  // ── Phase 3: Revision ──────────────────────────────────────────
  const p3Check = id => checks[`p3_${id}`] || null;
  const p3Done  = id => !!p3Check(id);
  const allP3Done = p3Ids.length === 0 || p3Ids.every(id => p3Done(id) || noCorr(id));
  const p3Bypassed = p3Ids.length === 0 || p3Ids.every(noCorr);
  const noComments = comments.length === 0;

  // ── Phase 4: per-instructor Check #2 (Daisy) ──────────────────
  // New keys: checks.p4_check_<id>
  // Backward compat: old p4_daisy covers all p3Ids when no new keys exist.
  const hasAnyNewP4 = p3Ids.some(id => !!checks[`p4_check_${id}`]);
  const p4DaisyOld  = checks["p4_daisy"] || null;
  const PHASE4_ADDED_AT = new Date("2026-08-17").getTime();
  const p4CheckRaw  = id => checks[`p4_check_${id}`] || null;
  const p4CheckDone = id => {
    if (p4CheckRaw(id)) return true;
    if (noCorr(id)) return true; // no corrections → Check #2 auto-skipped
    if (!hasAnyNewP4) {
      if (p4DaisyOld) return true;
      if (checks["p4_nigel"]) {
        // Only valid if Nigel exported AFTER this instructor's Phase 3 revision.
        // If p3 happened after the export, the export pre-dates the revision — Daisy still needs to check.
        const nigelAt = checks["p4_nigel"]?.at || 0;
        const p3RevAt = p3Check(id)?.at || 0;
        if (p3RevAt === 0 || nigelAt >= p3RevAt) return true;
      }
      if (reviewSubmittedOld && p3Done(id) && (data?.reviewSubmittedAt || 0) > 0 && data.reviewSubmittedAt < PHASE4_ADDED_AT) {
        // Only valid if this instructor's Phase 3 revision was also done before the new system
        const p3RevAt = p3Check(id)?.at || 0;
        if (p3RevAt === 0 || p3RevAt < PHASE4_ADDED_AT) return true;
      }
    }
    return false;
  };
  const allP4Done = p3Ids.length === 0 || p3Ids.every(p4CheckDone);

  // ── Ready for Export ───────────────────────────────────────────
  const ready = allP1Done && (daisyOnly || allP4Done);

  // ── Phase 5: Export (Nigel) ────────────────────────────────────
  const p4Check = checks["p4_nigel"] || null;
  const p4Done  = !!p4Check;

  // ── Legacy aliases (kept so unchanged code continues to work) ──
  const reviewSubmitted          = reviewSubmittedOld;
  const effectiveReviewSubmitted = allP2Done;
  const reviewIsStale            = p3Ids.some(p2CheckStale);
  const effectiveAllP3Done       = allP3Done;
  const reviewSubmitted2         = allP4Done;
  const noCorrectionsDecision    = noCorrOld;
  const p4DaisyCheck             = p4DaisyOld;
  const commentsForPerson        = commentsFor;  // alias
  const allFixedForPerson        = allFixedFor;  // alias

  const revisionDone = allP3Done && p3Ids.length > 0
    ? { by: "done", at: Math.max(...p3Ids.map(id => p3Check(id)?.at || 0)) }
    : null;

  return {
    p1Ids, p1Done, p1Check, allP1Done,
    p3Ids, p3Done, p3Check, allP3Done, p3Bypassed, effectiveAllP3Done,
    noCorr,
    p2CheckRaw, p2CheckDone, p2CheckStale, p2EffDone, p2CheckAt, allP2Done,
    p4CheckRaw, p4CheckDone, allP4Done,
    p4Check, p4Done,
    comments, commentsFor, allFixedFor,
    commentsForPerson, allFixedForPerson,
    allFixed, noComments,
    ready, revisionDone, daisyOnly,
    // Legacy
    reviewSubmitted, effectiveReviewSubmitted, reviewIsStale, reviewUnlocked: allP1Done,
    reviewSubmitted2, noCorrectionsDecision, p4DaisyCheck,
    rayDone: p1Done("ray"), daisyDone: p1Done("daisy"),
  };
}

// Derives the correct workflowStatus string from a ws snapshot.
function computeWorkflowStatus(ws) {
  if (ws.daisyOnly || ws.p3Ids.length === 0) return null;
  // Phase 4 check pending (highest priority — work almost done)
  if (ws.p3Ids.some(id => ws.p3Done(id) && !ws.p4CheckDone(id))) return "daisy_pending";
  // Phase 3 revisions pending
  if (ws.p3Ids.some(id => ws.p2EffDone(id) && !ws.noCorr(id) && !ws.p3Done(id))) return "ray_pending";
  // Phase 2 check pending
  if (ws.p3Ids.some(id => ws.p1Done(id) && !ws.p2EffDone(id))) return "daisy_pending";
  return null;
}

function fmtCheckTimestamp(ts) {
  const d = new Date(ts);
  const months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  const h = d.getHours(), m = String(d.getMinutes()).padStart(2, "0");
  return `${d.getDate()} ${months[d.getMonth()]} ${h % 12 || 12}:${m}${h < 12 ? "am" : "pm"}`;
}

function renderCheckedByStripHtml(data, confirmRole, isGroup = false) {
  const ws = getWorkflowState(data);

  // Refresh sticky note if open for this session
  const curSid = isGroup ? state.viewGroupSessionId : state.viewSessionId;
  if (_stickyNoteSessionId === curSid) renderStickyNoteContent(data, isGroup);

  const arrow = `<div class="wf-arrow" aria-hidden="true">
    <svg width="32" height="24" viewBox="0 0 32 24" fill="none">
      <line x1="0" y1="12" x2="22" y2="12" stroke="#9ca3af" stroke-width="2"/>
      <polygon points="19,6 32,12 19,18" fill="#9ca3af"/>
    </svg>
  </div>`;

  const mkConfirm = (role, msg) => `
    <div class="wf-confirming">
      <span class="wf-confirm-msg">${msg}</span>
      <div class="wf-confirm-btns">
        <button class="chk-btn-yes" data-role="${role}">Confirm ✓</button>
        <button class="chk-btn-no"  data-role="${role}">Cancel</button>
      </div>
    </div>`;

  const instName = id => (INSTRUCTORS.find(i => i.id === id) || { name: id }).name;

  // ── Phase 1: Enter Data ───────────────────────────────────────
  const mkPill1 = id => {
    const name = instName(id);
    const role = `p1_${id}`;
    const done = ws.p1Done(id);
    const at   = ws.p1Check(id)?.at;
    if (confirmRole === role) return mkConfirm(role, done ? `Undo ${name}?` : `${name}: Sure?`);
    if (done) return `<button class="wf-pill wf-pill--done" data-role="${role}">✓ ${escHtml(name)} · ${escHtml(fmtCheckTimestamp(at))}</button>`;
    return `<button class="wf-pill wf-pill--pending" data-role="${role}">○ ${escHtml(name)}: Incomplete</button>`;
  };

  const editInstBtn = `<button class="wf-pill wf-pill--edit-inst" data-action="edit-instructors"
    style="margin-top:.4rem;font-size:.78rem;padding:.2rem .65rem;background:#eff6ff;color:#3b82f6;border:1px solid #bfdbfe;border-radius:6px;cursor:pointer">✏ Edit Instructors</button>`;

  const p1State = ws.allP1Done ? "done" : "pending";
  const p1Body  = ws.p1Ids.length === 0
    ? `<div class="wf-pill wf-pill--pending">○ No instructors selected</div>${editInstBtn}`
    : `${ws.p1Ids.map(mkPill1).join("")}${editInstBtn}`;
  const p1Node = `<div class="wf-node wf-node--${p1State}">
    <div class="wf-node-label">Phase 1: Enter Data</div>
    <div class="wf-node-body">${p1Body}</div>
  </div>`;

  // ── Phase 2: per-instructor Check #1 (Daisy) ─────────────────
  // One row per p3Id; each unlocks as soon as that instructor finishes Phase 1.
  const mkPill2 = id => {
    const name = instName(id);
    const role = `p2_check_${id}`;
    if (!ws.p1Done(id)) {
      return `<div class="wf-pill wf-pill--locked">🔒 ${escHtml(name)}: Waiting for Phase 1</div>`;
    }
    const done   = ws.p2EffDone(id);
    const stale  = ws.p2CheckStale(id);
    const at     = ws.p2CheckAt(id);
    if (confirmRole === role) return mkConfirm(role, done ? `Undo check for ${name}?` : `Check ${name}'s work?`);
    if (done && !stale) return `<button class="wf-pill wf-pill--done" data-role="${role}">✓ Ms. Daisy · ${escHtml(fmtCheckTimestamp(at))}</button>`;
    if (stale) return `<button class="wf-pill wf-pill--attention" data-role="${role}">⚠ Ms. Daisy: Re-check ${escHtml(name)} (Phase 1 updated)</button>`;
    return `<button class="wf-pill wf-pill--attention" data-role="${role}">○ Ms. Daisy: Check ${escHtml(name)}'s Work</button>`;
  };

  let p2State, p2Body;
  if (ws.daisyOnly) {
    p2State = ws.allP1Done ? "done" : "locked";
    p2Body  = ws.allP1Done
      ? `<div class="wf-pill wf-pill--done">✓ Ms. Daisy is the only instructor for this session. No need to check.</div>`
      : `<div class="wf-pill wf-pill--locked">🔒 Complete Phase 1 first</div>`;
  } else if (ws.p3Ids.length === 0) {
    p2State = "locked";
    p2Body  = `<div class="wf-pill wf-pill--locked">🔒 No instructors selected</div>`;
  } else {
    const anyReady = ws.p3Ids.some(id => ws.p1Done(id));
    p2State = ws.allP2Done ? "done" : (anyReady ? "p2-active" : "locked");
    p2Body  = ws.p3Ids.map(mkPill2).join("");
  }
  const p2Node = `<div class="wf-node wf-node--${p2State}">
    <div class="wf-node-label">Phase 2: Check #1</div>
    <div class="wf-node-body">${p2Body}</div>
  </div>`;

  // ── Phase 3: Revision — per instructor, unlocks after their Phase 2 ──
  const mkPill3 = id => {
    const name = instName(id);
    const role = `p3_${id}`;
    if (ws.noCorr(id)) {
      return `<div class="wf-pill wf-pill--done">✓ ${escHtml(name)}: No revisions needed</div>`;
    }
    if (!ws.p2EffDone(id)) {
      return `<div class="wf-pill wf-pill--locked">🔒 ${escHtml(name)}: Check #1 not done yet</div>`;
    }
    const done = ws.p3Done(id);
    const at   = ws.p3Check(id)?.at;
    if (confirmRole === role) return mkConfirm(role, done ? `Undo ${name}?` : `${name}: Sure?`);
    if (done) return `<button class="wf-pill wf-pill--done" data-role="${role}">✓ ${escHtml(name)} · ${escHtml(fmtCheckTimestamp(at))}</button>`;
    return `<button class="wf-pill wf-pill--warn" data-role="${role}">○ ${escHtml(name)}: Incomplete</button>`;
  };

  let p3State, p3Body;
  if (ws.daisyOnly) {
    p3State = ws.allP1Done ? "done" : "locked";
    p3Body  = ws.allP1Done
      ? `<div class="wf-pill wf-pill--done">✓ Ms. Daisy is the only instructor for this session. No need to revise.</div>`
      : `<div class="wf-pill wf-pill--locked">🔒 Complete Phase 1 first</div>`;
  } else if (ws.p3Ids.length === 0) {
    p3State = "done";
    p3Body  = `<div class="wf-pill wf-pill--done">✓ No revision needed</div>`;
  } else {
    const anyUnlocked = ws.p3Ids.some(id => ws.p2EffDone(id));
    p3State = ws.allP3Done ? "done" : (anyUnlocked ? "corrections" : "locked");
    p3Body  = ws.p3Ids.map(mkPill3).join("");
  }
  const hasRejections = !ws.daisyOnly && ws.p3Ids.some(id =>
    ws.commentsFor(id).some(([, c]) => getCmtStatus(c) === "rejected"));
  const p3Node = `<div class="wf-node wf-node--${p3State}">
    <div class="wf-node-label">Phase 3: Revision</div>
    <div class="wf-node-body">${p3Body}</div>
    ${_phase3Error ? `<div class="wf-error-msg">${escHtml(_phase3Error)}</div>` : ""}
    ${hasRejections ? `<div class="wf-p3-hint">✗ Crosses indicate that Ms. Daisy has reviewed the work and errors are still present.</div>` : ""}
  </div>`;

  // ── Phase 4: Check #2 — per instructor, unlocks after their Phase 3 ──
  const mkPill4 = id => {
    const name = instName(id);
    const role = `p4_check_${id}`;
    if (ws.noCorr(id)) {
      return `<div class="wf-pill wf-pill--done">✓ Ms. Daisy: ${escHtml(name)} has no mistakes - Check #2 not required</div>`;
    }
    if (!ws.p3Done(id)) {
      return `<div class="wf-pill wf-pill--locked">🔒 ${escHtml(name)}: Awaiting revision</div>`;
    }
    const done = ws.p4CheckDone(id);
    const at   = ws.p4CheckRaw(id)?.at;
    if (confirmRole === role) return mkConfirm(role, done ? `Undo check for ${name}?` : `Check ${name}'s corrections?`);
    if (done) return `<button class="wf-pill wf-pill--done" data-role="${role}">✓ Ms. Daisy · ${at ? escHtml(fmtCheckTimestamp(at)) : ""}</button>`;
    return `<button class="wf-pill wf-pill--attention" data-role="${role}">○ Ms. Daisy: Check ${escHtml(name)}'s Corrected Work</button>`;
  };

  let p4State, p4Body;
  if (ws.daisyOnly) {
    p4State = ws.allP1Done ? "done" : "locked";
    p4Body  = ws.allP1Done
      ? `<div class="wf-pill wf-pill--done">✓ Ms. Daisy is the only instructor. No need to check.</div>`
      : `<div class="wf-pill wf-pill--locked">🔒 Complete Phase 1 first</div>`;
  } else if (ws.p3Ids.length === 0) {
    p4State = "done";
    p4Body  = `<div class="wf-pill wf-pill--done">✓ No check needed</div>`;
  } else {
    const anyUnlocked4 = ws.p3Ids.some(id => ws.p3Done(id) || ws.noCorr(id));
    p4State = ws.allP4Done ? "done" : (anyUnlocked4 ? "p2-active" : "locked");
    p4Body  = ws.p3Ids.map(mkPill4).join("");
    if (!ws.allP4Done) {
      p4Body += `<div class="wf-p4-hint">If their work still contains errors, go to their list of corrections and click any incorrect ticks (✓) to change them into crosses (✗). Add an extra note if needed.</div>`;
    }
  }
  const p4Node = `<div class="wf-node wf-node--${p4State}">
    <div class="wf-node-label">Phase 4: Check #2</div>
    <div class="wf-node-body">${p4Body}</div>
  </div>`;

  // ── Phase 5: Export (Nigel) ───────────────────────────────────
  let nigelState, nigelBody;
  const isMonthlyExport = !isGroup && state.viewStudent?.exportDuration === "monthly";
  if (isMonthlyExport && ws.ready) {
    nigelState = "nigel-ready";
    nigelBody  = `<div class="wf-pill wf-pill--done">✓ This student registered for the "Monthly Report" plan. No need to export this session.</div>`;
  } else if (!ws.ready) {
    nigelState = "locked";
    nigelBody  = `<div class="wf-pill wf-pill--locked">🔒 Complete previous phases first</div>`;
  } else if (confirmRole === "p4_nigel") {
    nigelState = "nigel-ready";
    nigelBody  = mkConfirm("p4_nigel", ws.p4Done ? "Undo export mark?" : "Mark as exported?");
  } else if (ws.p4Done) {
    nigelState = "nigel-ready";
    nigelBody  = `<button class="wf-pill wf-pill--done" data-role="p4_nigel">✓ Nigel · ${escHtml(fmtCheckTimestamp(ws.p4Check?.at))}</button>`;
  } else {
    nigelState = "nigel-ready";
    nigelBody  = `<button class="wf-pill wf-pill--attention" data-role="p4_nigel">○ Nigel: Incomplete</button>`;
  }
  const nigelNode  = `<div class="wf-node wf-node--${nigelState}">
    <div class="wf-node-label">Phase 5: Export</div>
    <div class="wf-node-body">${nigelBody}</div>
  </div>`;

  // ── Note trigger: one button per instructor ───────────────────
  const noteIds = ws.daisyOnly ? [] : ws.p3Ids;
  const noteTrigger = `<div class="wf-note-wrap">
    ${noteIds.length === 0
      ? `<button class="wf-note-btn" data-action="open-note" data-inst-id="">📝 List of Corrections</button>`
      : noteIds.map(id => {
          const idComments = ws.commentsFor(id);
          const cnt  = idComments.length;
          const name = instName(id);
          const allFixed  = cnt > 0 && idComments.every(([, c]) => getCmtStatus(c) === "fixed");
          const colorCls  = cnt === 0 ? "" : allFixed ? " wf-note-btn--green" : " wf-note-btn--red";
          return `<button class="wf-note-btn${colorCls}" data-action="open-note" data-inst-id="${escHtml(id)}">
            📝 List of Corrections – ${escHtml(name)}${cnt > 0 ? ` (${cnt})` : ""}
          </button>`;
        }).join("")}
  </div>`;

  const exportTrigger = `<div class="wf-export-wrap">
    <button class="chk-export-btn" title="Export this session to Word">📄 Export to Word</button>
  </div>`;

  return `<div class="checked-by-strip" contenteditable="false">
    <div class="workflow-chart">
      ${p1Node}${arrow}${p2Node}${arrow}${p3Node}${arrow}${p4Node}${arrow}${nigelNode}
      ${noteTrigger}
      ${exportTrigger}
    </div>
  </div>`;
}

async function handleCheckedByClick(e, isGroup) {
  const confirmRole  = isGroup ? _grpChkConfirmRole  : _viewChkConfirmRole;
  const setConfirm   = r => { if (isGroup) _grpChkConfirmRole = r; else _viewChkConfirmRole = r; };
  const clearTimer   = ()  => clearTimeout(isGroup ? _grpChkConfirmTimer : _viewChkConfirmTimer);
  const setTimer     = fn  => { const t = setTimeout(fn, 4000); if (isGroup) _grpChkConfirmTimer = t; else _viewChkConfirmTimer = t; };
  const rerender     = ()  => isGroup ? renderGroupSessionView() : renderSessionView();
  const getSid       = ()  => isGroup ? state.viewGroupSessionId  : state.viewSessionId;
  const getData      = ()  => isGroup ? state.viewGroupSessionData : state.viewSessionData;
  const getSubjectMeta = () => {
    const data = getData();
    return {
      subjectName: isGroup ? state.viewGroup?.name : state.viewStudent?.name,
      subjectId:   isGroup ? data?.groupId          : data?.studentId,
      isGroup:     !!isGroup,
      date:        data?.date
    };
  };

  // ── Note / corrections list button ───────────────────────────
  const noteBtn = e.target.closest("[data-action='open-note']");
  if (noteBtn) {
    const instId = noteBtn.dataset.instId || null;
    openStickyNote(getSid(), !!isGroup, getData(), instId);
    return true;
  }

  // ── Export to Word button ────────────────────────────────────
  const exportBtn = e.target.closest(".chk-export-btn");
  if (exportBtn) {
    requirePassword(() => {
      if (isGroup) {
        const attendees = state.viewGroupSessionData?.attendees || state.viewGroup?.students || [];
        const session   = { id: state.viewGroupSessionId, ...(state.viewGroupSessionData || {}) };
        if (attendees.length === 1) {
          exportGroupMemberSingleSessionWord(attendees[0], [state.viewGroup], session);
        } else {
          $("session-picker-title").textContent = "Export for…";
          $("session-picker-list").innerHTML = attendees.length
            ? `<div class="choice-list">` + attendees.map(name => `
                <button class="choice-btn choice-grp-view-export" data-name="${escHtml(name)}">
                  <span class="choice-icon">📤</span>
                  <div class="choice-text"><div class="choice-label">${escHtml(name)}</div></div>
                </button>`).join("") + `</div>`
            : `<p class="empty-hint">No attendees found.</p>`;
          $("session-picker-modal").classList.remove("hidden");
          $("session-picker-list").querySelectorAll(".choice-grp-view-export").forEach(btn => {
            btn.addEventListener("click", () => {
              closeSessionPicker();
              exportGroupMemberSingleSessionWord(btn.dataset.name, [state.viewGroup], session);
            });
          });
        }
      } else {
        exportStudentSingleSessionWord(state.viewStudent, { id: state.viewSessionId, ...(state.viewSessionData || {}) });
      }
    }, EXPORT_MSG);
    return true;
  }

  // ── Edit Instructors button ──────────────────────────────────
  if (e.target.closest("[data-action='edit-instructors']")) {
    const curParticipants = getData()?.participants || [];
    $("session-picker-title").textContent = "Edit Instructors";
    $("session-picker-list").innerHTML = `
      <div style="padding:1.5rem 1.25rem;display:flex;flex-direction:column;align-items:center">
        <p style="margin:0 0 1.25rem;font-weight:600;color:#374151;text-align:center">Who is facilitating this session?</p>
        <div style="width:100%;max-width:320px">
          ${INSTRUCTORS.map(inst => `
            <label style="display:flex;align-items:center;justify-content:center;gap:.85rem;padding:.75rem 0;cursor:pointer;font-size:1rem;border-bottom:1px solid #f3f4f6">
              <input type="checkbox" class="inst-edit-check" value="${inst.id}"${curParticipants.includes(inst.id) ? " checked" : ""}
                style="width:1.2rem;height:1.2rem;accent-color:#3b82f6;cursor:pointer;flex-shrink:0">
              <span style="color:#1f2937;width:7rem">${escHtml(inst.name)}</span>
            </label>`).join("")}
        </div>
        <button class="btn-inst-save export-btn" style="margin-top:1.5rem;width:100%;padding:.85rem;font-size:1rem;text-align:center">Save</button>
      </div>`;
    $("session-picker-modal").classList.remove("hidden");
    $("session-picker-list").querySelector(".btn-inst-save").addEventListener("click", async () => {
      const participants = [...$("session-picker-list").querySelectorAll(".inst-edit-check:checked")].map(c => c.value);
      closeSessionPicker();
      // Untick any newly added instructors so they start fresh
      const newlyAdded = participants.filter(id => !curParticipants.includes(id));
      if (newlyAdded.length > 0) {
        const updatedChecks = { ...(getData()?.checks || {}) };
        newlyAdded.forEach(id => {
          delete updatedChecks[`p1_${id}`];
          delete updatedChecks[`p2_check_${id}`];
          delete updatedChecks[`p3_${id}`];
          delete updatedChecks[`p4_check_${id}`];
          delete updatedChecks[`no_corr_${id}`];
        });
        await updateSessionChecks(getSid(), updatedChecks).catch(() => {});
      }
      await updateSessionParticipants(getSid(), participants).catch(() => {});
    });
    return true;
  }

  // ── Phase-pill click → confirm flow ─────────────────────────
  const pillBtn = e.target.closest(".wf-pill[data-role]");
  if (pillBtn) {
    clearTimer();
    setConfirm(pillBtn.dataset.role);
    rerender();
    setTimer(() => { setConfirm(null); rerender(); });
    return true;
  }

  // ── Confirm button ───────────────────────────────────────────
  const yesBtn = e.target.closest(".chk-btn-yes");
  if (yesBtn) {
    clearTimer(); setConfirm(null); rerender(); // remove confirm UI immediately — no lag
    const sid  = getSid();
    const data = getData();
    if (!sid) return true;
    const role = yesBtn.dataset.role;

    if (role.startsWith("p1_")) {
      const checks        = { ...(data?.checks || {}) };
      const wasDone       = !!checks[role];
      const participantId = role.slice(3);
      if (wasDone) {
        delete checks[role];
        if (participantId !== "daisy") {
          // Per-instructor cascade only — don't touch other instructors' state
          delete checks[`p2_check_${participantId}`];
          delete checks[`p3_${participantId}`];
          delete checks[`p4_check_${participantId}`];
          delete checks[`no_corr_${participantId}`];
          delete checks["p4_nigel"];
          if (data?.reviewSubmitted) await setReviewSubmitted(sid, false);
        }
      } else {
        checks[role] = { by: participantId, at: Date.now() };
      }
      try {
        await updateSessionChecks(sid, checks);
        const ws2 = getWorkflowState({ ...data, checks });
        const newStatus = computeWorkflowStatus(ws2);
        await updateWorkflowStatus(sid, newStatus, getSubjectMeta());
      } catch (err) { console.error("updateSessionChecks p1:", err); }
    } else if (role.startsWith("p2_check_")) {
      const id  = role.slice("p2_check_".length);
      const ws  = getWorkflowState(data);
      const instNameStr = (INSTRUCTORS.find(i => i.id === id) || { name: id }).name;
      const wasDone = ws.p2EffDone(id);
      try {
        if (!wasDone) {
          // Auto-delete empty corrections for this instructor
          const allCmts  = Object.entries(data?.reviewComments || {});
          const myEmpty  = allCmts.filter(([, c]) => {
            const fi = c.forInstructor;
            const belongs = fi ? fi === id : (!c.assignedTo || c.assignedTo.length === 0 || c.assignedTo.includes(id));
            return belongs && !(c.text || "").trim();
          });
          await Promise.all(myEmpty.map(([cid]) => deleteReviewComment(sid, cid).catch(() => {})));

          const myCmts = allCmts.filter(([cid, c]) => {
            if (myEmpty.some(([eid]) => eid === cid)) return false;
            const fi = c.forInstructor;
            return fi ? fi === id : (!c.assignedTo || c.assignedTo.length === 0 || c.assignedTo.includes(id));
          });
          const hasRealCorrections = myCmts.some(([, c]) => (c.text || "").trim());
          let skipPhase3 = false;
          if (!hasRealCorrections) {
            if (!confirm(`List of Corrections – ${instNameStr} is empty. Confirm no revisions needed?`)) {
              rerender();
              return;
            }
            skipPhase3 = true;
          }
          const checks = { ...(data?.checks || {}) };
          if (ws.p2CheckStale(id)) {
            // Re-checking stale — clear downstream for this instructor first
            delete checks[`p3_${id}`];
            delete checks[`p4_check_${id}`];
            delete checks[`no_corr_${id}`];
            delete checks["p4_nigel"];
          }
          checks[role] = { by: "daisy", at: Date.now() };
          if (skipPhase3) checks[`no_corr_${id}`] = { by: "daisy", at: Date.now() };
          await updateSessionChecks(sid, checks);
          const ws2 = getWorkflowState({ ...data, checks });
          await updateWorkflowStatus(sid, computeWorkflowStatus(ws2), getSubjectMeta());
        } else {
          // Untick — cascade for this instructor
          const checks = { ...(data?.checks || {}) };
          delete checks[role];
          delete checks[`p3_${id}`];
          delete checks[`p4_check_${id}`];
          delete checks[`no_corr_${id}`];
          delete checks["p4_nigel"];
          if (data?.reviewSubmitted) await setReviewSubmitted(sid, false);
          await updateSessionChecks(sid, checks);
          const ws2 = getWorkflowState({ ...data, checks });
          await updateWorkflowStatus(sid, computeWorkflowStatus(ws2), getSubjectMeta());
        }
      } catch (err) { console.error("toggleP2Check:", err); }
    } else if (role.startsWith("p3_")) {
      const ws     = getWorkflowState(data);
      const id     = role.slice(3);
      const newDone = !ws.p3Done(id);
      if (newDone && !ws.allFixedFor(id)) {
        const notFixed = ws.commentsFor(id).filter(([, c]) => getCmtStatus(c) !== "fixed");
        const nRemain = notFixed.length;
        _phase3Error = `⚠ ${nRemain} task${nRemain === 1 ? "" : "s"} remain${nRemain === 1 ? "s" : ""} in the "List of Corrections – ${instName(id)}". Tick ${nRemain === 1 ? "it" : "them"} (✓) to complete this phase.`;
        rerender();
        return true;
      }
      _phase3Error = null;
      const checks  = { ...(data?.checks || {}) };
      if (newDone) {
        checks[role] = { by: id, at: Date.now() };
      } else {
        delete checks[role];
        delete checks[`p4_check_${id}`];
        delete checks["p4_nigel"];
      }
      try {
        await updateSessionChecks(sid, checks);
        const ws2 = getWorkflowState({ ...data, checks });
        await updateWorkflowStatus(sid, computeWorkflowStatus(ws2), getSubjectMeta());
      } catch (err) { console.error("updateSessionChecks p3:", err); }
    } else if (role.startsWith("p4_check_")) {
      const id  = role.slice("p4_check_".length);
      const ws  = getWorkflowState(data);
      const checks = { ...(data?.checks || {}) };
      try {
        if (!ws.p4CheckDone(id)) {
          checks[role] = { by: "daisy", at: Date.now() };
          await updateSessionChecks(sid, checks);
          const ws2 = getWorkflowState({ ...data, checks });
          await updateWorkflowStatus(sid, computeWorkflowStatus(ws2), getSubjectMeta());
        } else {
          delete checks[role];
          delete checks["p4_nigel"];
          await updateSessionChecks(sid, checks);
          const ws2 = getWorkflowState({ ...data, checks });
          await updateWorkflowStatus(sid, computeWorkflowStatus(ws2), getSubjectMeta());
        }
      } catch (err) { console.error("toggleP4Check:", err); }
    } else if (role === "p4_nigel") {
      const ws      = getWorkflowState(data);
      const newDone = !ws.p4Done;
      const checks  = { ...(data?.checks || {}) };
      if (newDone) { checks["p4_nigel"] = { by: "nigel", at: Date.now() }; } else { delete checks["p4_nigel"]; }
      try { await updateSessionChecks(sid, checks); }
      catch (err) { console.error("updateSessionChecks p4:", err); }
    }
    return true;
  }

  // ── Cancel button ────────────────────────────────────────────
  const noBtn = e.target.closest(".chk-btn-no");
  if (noBtn) { clearTimer(); setConfirm(null); rerender(); return true; }

  return false;
}

// ── Sticky Note — "List of Corrections" ──────────────────────

function renderStickyNoteContent(data, isGroup) {
  const tbody = document.getElementById("sticky-note-rows");
  if (!tbody) return;

  const ws  = getWorkflowState(data);
  // Filter comments to the open instructor
  const visible = _stickyNoteInstructorId
    ? ws.commentsFor(_stickyNoteInstructorId)
    : ws.comments;

  // Preserve scroll position
  const scrollEl    = tbody.closest(".snote-list-scroll");
  const savedScroll = scrollEl ? scrollEl.scrollTop : 0;

  // Preserve focused textarea and caret position across re-renders
  const activeEl     = document.activeElement;
  const focusedCmtId = activeEl?.classList.contains("snote-textarea") ? activeEl.dataset.cmtId : null;
  const caretPos     = focusedCmtId ? activeEl.selectionEnd : null;
  const liveText     = focusedCmtId ? activeEl.value : null;

  if (visible.length === 0) {
    tbody.innerHTML = "";
  } else {
    tbody.innerHTML = visible.map(([id, c], i) => {
      const text = (focusedCmtId === id && liveText !== null) ? liveText : (c.text || "");
      const st = getCmtStatus(c);
      const [stIcon, stCls] = st === "fixed" ? ["✓", "snote-status--fixed"]
        : st === "rejected" ? ["✗", "snote-status--rejected"]
        : ["", "snote-status--empty"];
      const rowCls = st === "fixed" ? " snote-row--done" : st === "rejected" ? " snote-row--rejected" : "";
      return `<tr class="snote-row${rowCls}">
        <td class="snote-no">${i + 1}</td>
        <td class="snote-text"><textarea class="snote-textarea" data-cmt-id="${id}" rows="1" placeholder="Type here…">${escHtml(text)}</textarea></td>
        <td class="snote-tick"><button class="snote-status-btn ${stCls}" data-cmt-id="${id}" title="Click to change status">${stIcon}</button></td>
        <td class="snote-del"><button class="snote-del-btn" data-cmt-id="${id}" title="Delete row">🗑</button></td>
      </tr>`;
    }).join("");

    tbody.querySelectorAll(".snote-textarea").forEach(ta => {
      ta.style.height = "auto";
      ta.style.height = ta.scrollHeight + "px";
    });
  }

  // Restore focus & caret
  if (focusedCmtId) {
    const ta = tbody.querySelector(`.snote-textarea[data-cmt-id="${focusedCmtId}"]`);
    if (ta) {
      ta.focus();
      if (caretPos !== null) { try { ta.selectionEnd = caretPos; ta.selectionStart = caretPos; } catch {} }
    }
  }

  const isNewRow = _focusNewRow;
  if (_focusNewRow) {
    _focusNewRow = false;
    const all = tbody.querySelectorAll(".snote-textarea");
    if (all.length > 0) all[all.length - 1].focus();
  }

  if (scrollEl && savedScroll > 0 && !isNewRow) scrollEl.scrollTop = savedScroll;
}

function openStickyNote(sessionId, isGroup, data, instructorId = null) {
  _stickyNoteSessionId    = sessionId;
  _stickyNoteIsGroup      = !!isGroup;
  _stickyNoteInstructorId = instructorId || null;
  const el = document.getElementById("sticky-note");
  if (!el) return;
  el.style.width   = "";
  el.style.height  = "";
  el.style.top     = "110px";
  el.style.right   = "20px";
  el.style.left    = "";
  el.style.bottom  = "";
  delete el.dataset.positioned;
  el.classList.remove("hidden");
  // Update title to show which instructor's list is open
  const titleEl = document.getElementById("sticky-note-title");
  if (titleEl) {
    const instName = instructorId
      ? (INSTRUCTORS.find(i => i.id === instructorId) || { name: instructorId }).name
      : null;
    titleEl.textContent = instName ? `📝 List of Corrections – ${instName}` : "📝 List of Corrections";
  }
  renderStickyNoteContent(data, isGroup);
}

function closeStickyNote() {
  const el = document.getElementById("sticky-note");
  if (el) el.classList.add("hidden");
  _stickyNoteSessionId = null;
}

function setupStickyNote() {
  const note    = document.getElementById("sticky-note");
  const handle  = document.getElementById("sticky-note-drag-handle");
  const closeEl = document.getElementById("btn-sticky-note-close");
  if (!note || !handle || !closeEl) return;

  // ── Drag ─────────────────────────────────────────────────────
  let dragging = false, ox = 0, oy = 0, nl = 0, nt = 0;

  function startDrag(cx, cy) {
    if (!note.dataset.positioned) {
      const rect = note.getBoundingClientRect();
      note.style.left  = rect.left + "px";
      note.style.right = "";
      note.style.top   = rect.top + "px";
      note.dataset.positioned = "1";
    }
    nl = parseFloat(note.style.left) || 0;
    nt = parseFloat(note.style.top)  || 0;
    ox = cx; oy = cy;
    dragging = true;
  }
  function onMove(cx, cy) {
    if (!dragging) return;
    note.style.left  = Math.max(0, nl + cx - ox) + "px";
    note.style.top   = Math.max(0, nt + cy - oy) + "px";
    note.style.right = "";
    note.dataset.positioned = "1";
  }
  handle.addEventListener("mousedown",  e => { startDrag(e.clientX, e.clientY); e.preventDefault(); });
  document.addEventListener("mousemove", e => onMove(e.clientX, e.clientY));
  document.addEventListener("mouseup",   () => { dragging = false; });
  handle.addEventListener("touchstart", e => { const t = e.touches[0]; startDrag(t.clientX, t.clientY); }, { passive: false });
  document.addEventListener("touchmove", e => { if (!dragging) return; const t = e.touches[0]; onMove(t.clientX, t.clientY); e.preventDefault(); }, { passive: false });
  document.addEventListener("touchend", () => { dragging = false; });

  // ── Edge resize (N/S/E/W — no corners) ───────────────────────
  const MIN_W = 280, MIN_H = 200;

  function startEdgeResize(startCX, startCY, dir) {
    // Convert to left-anchored so we can modify left/top directly
    if (!note.dataset.positioned) {
      const r = note.getBoundingClientRect();
      note.style.left  = r.left + "px";
      note.style.right = "";
      note.style.top   = r.top  + "px";
      note.dataset.positioned = "1";
    }
    const r  = note.getBoundingClientRect();
    const sw = r.width, sh = r.height, sl = r.left, st = r.top;

    function move(cx, cy) {
      const dx = cx - startCX, dy = cy - startCY;
      if (dir === "n") {
        const h = Math.max(MIN_H, sh - dy);
        note.style.height = h + "px";
        note.style.top    = (st + sh - h) + "px";
      } else if (dir === "s") {
        note.style.height = Math.max(MIN_H, sh + dy) + "px";
      } else if (dir === "e") {
        note.style.width  = Math.max(MIN_W, sw + dx) + "px";
      } else if (dir === "w") {
        const w = Math.max(MIN_W, sw - dx);
        note.style.width  = w + "px";
        note.style.left   = (sl + sw - w) + "px";
      }
    }
    function onMM(ev) { move(ev.clientX, ev.clientY); }
    function onTM(ev) { const t = ev.touches[0]; move(t.clientX, t.clientY); ev.preventDefault(); }
    function cleanup() {
      document.removeEventListener("mousemove", onMM);
      document.removeEventListener("mouseup",   cleanup);
      document.removeEventListener("touchmove", onTM);
      document.removeEventListener("touchend",  cleanup);
    }
    document.addEventListener("mousemove", onMM);
    document.addEventListener("mouseup",   cleanup);
    document.addEventListener("touchmove", onTM, { passive: false });
    document.addEventListener("touchend",  cleanup);
  }

  note.querySelectorAll("[data-dir]").forEach(handle => {
    const dir = handle.dataset.dir;
    handle.addEventListener("mousedown", e => { e.preventDefault(); startEdgeResize(e.clientX, e.clientY, dir); });
    handle.addEventListener("touchstart", e => { const t = e.touches[0]; e.preventDefault(); startEdgeResize(t.clientX, t.clientY, dir); }, { passive: false });
  });

  closeEl.addEventListener("click", async () => {
    const { sid, data } = getCtx();
    if (sid) {
      const ws2 = getWorkflowState(data);
      const visible = _stickyNoteInstructorId
        ? ws2.commentsFor(_stickyNoteInstructorId)
        : ws2.comments;
      const emptyIds = visible.filter(([, c]) => !(c.text || "").trim()).map(([id]) => id);
      await Promise.all(emptyIds.map(id => deleteReviewComment(sid, id).catch(() => {})));
    }
    closeStickyNote();
  });

  // ── Context helpers ──────────────────────────────────────────
  const getCtx = () => ({
    sid:    _stickyNoteSessionId,
    data:   _stickyNoteIsGroup ? state.viewGroupSessionData : state.viewSessionData,
    isGroup: _stickyNoteIsGroup,
    meta: {
      subjectName: _stickyNoteIsGroup ? state.viewGroup?.name : state.viewStudent?.name,
      subjectId:   _stickyNoteIsGroup ? state.viewGroupSessionData?.groupId : state.viewSessionData?.studentId,
      isGroup:     !!_stickyNoteIsGroup,
      date:        _stickyNoteIsGroup ? state.viewGroupSessionData?.date : state.viewSessionData?.date
    }
  });

  // ── Click delegation ─────────────────────────────────────────
  note.addEventListener("click", async e => {
    // + Add Correction
    if (e.target.id === "sticky-note-add-row-btn") {
      const { sid, data } = getCtx();
      if (!sid) return;
      _focusNewRow = true;
      try {
        await addReviewComment(sid, "", _stickyNoteInstructorId);
        // New correction means this instructor's Phase 3 is no longer done
        const checks = { ...(data?.checks || {}) };
        const id = _stickyNoteInstructorId;
        let changed = false;
        if (id) {
          if (checks[`p3_${id}`])       { delete checks[`p3_${id}`];       changed = true; }
          if (checks[`p4_check_${id}`]) { delete checks[`p4_check_${id}`]; changed = true; }
          if (checks[`no_corr_${id}`])  { delete checks[`no_corr_${id}`];  changed = true; }
        } else {
          const p3Keys = Object.keys(checks).filter(k => k.startsWith("p3_") || k.startsWith("no_corr_") || k === "no_corrections");
          if (p3Keys.length) { p3Keys.forEach(k => delete checks[k]); changed = true; }
        }
        if (changed) { delete checks["p4_nigel"]; await updateSessionChecks(sid, checks).catch(() => {}); }
      }
      catch (err) { console.error("addReviewComment:", err); }
      return;
    }

    // 3-state status button: empty → fixed (✓) → rejected (✗) → empty
    const statusBtn = e.target.closest(".snote-status-btn");
    if (statusBtn) {
      const { sid, data } = getCtx();
      if (!sid) return;
      const cmtId = statusBtn.dataset.cmtId;
      const cmt   = (data?.reviewComments || {})[cmtId];
      if (!cmt) return;
      const current = getCmtStatus(cmt);
      const next = current === null ? "fixed" : current === "fixed" ? "rejected" : null;
      try {
        await setCommentStatus(sid, cmtId, next);
        // Leaving "fixed" state → reset this instructor's Phase 3 & 4
        if (next !== "fixed") {
          const instId = cmt.forInstructor || _stickyNoteInstructorId;
          const ws2 = getWorkflowState(data);
          const affected = instId ? [instId] : ws2.p3Ids;
          const checks = { ...(data?.checks || {}) };
          let changed = false;
          affected.forEach(id => {
            if (checks[`p3_${id}`]) { delete checks[`p3_${id}`]; changed = true; }
            if (checks[`p4_check_${id}`]) { delete checks[`p4_check_${id}`]; changed = true; }
          });
          if (changed) { delete checks["p4_nigel"]; await updateSessionChecks(sid, checks).catch(() => {}); }
        }
      } catch (err) { console.error("setCommentStatus:", err); }
      return;
    }

    // Delete row
    const delBtn = e.target.closest(".snote-del-btn");
    if (delBtn) {
      const { sid } = getCtx();
      if (!sid) return;
      if (!confirm("Delete this row? This cannot be undone.")) return;
      const cmtId = delBtn.dataset.cmtId;
      try { await deleteReviewComment(sid, cmtId); }
      catch (err) { console.error("deleteReviewComment:", err); }
      return;
    }
  });

  // ── Textarea auto-save (debounced, per-row) ──────────────────
  note.addEventListener("input", e => {
    const ta = e.target.closest(".snote-textarea");
    if (!ta) return;
    const cmtId = ta.dataset.cmtId;
    if (!cmtId) return;
    // Auto-grow
    ta.style.height = "auto";
    ta.style.height = ta.scrollHeight + "px";
    // Keep bottom of focused textarea visible inside the scroll container
    const scrollEl = note.querySelector(".snote-list-scroll");
    if (scrollEl) {
      const taBottom  = ta.getBoundingClientRect().bottom;
      const boxBottom = scrollEl.getBoundingClientRect().bottom;
      if (taBottom > boxBottom) scrollEl.scrollTop += taBottom - boxBottom + 6;
    }
    // Debounce save
    if (_textareaDebounce.has(cmtId)) clearTimeout(_textareaDebounce.get(cmtId));
    _textareaDebounce.set(cmtId, setTimeout(async () => {
      _textareaDebounce.delete(cmtId);
      const { sid } = getCtx();
      if (!sid) return;
      try { await updateReviewCommentText(sid, cmtId, ta.value); }
      catch (err) { console.error("updateReviewCommentText:", err); }
    }, 600));
  });
}

function renderSessionView() {
  const data    = state.viewSessionData;
  const student = state.viewStudent;
  if (!data || !student) return;

  $("view-session-meta").innerHTML =
    `Session ${data.sessionNumber}: ${formatDateWithDay(data.date)}${relativeDaySuffix(data.date)}`
    + ` <button class="btn-edit-session-date">Edit Date</button>`;

  const delBtn = $("btn-delete-session");
  if (delBtn) delBtn.classList.remove("hidden");

  $("view-session-meta").querySelector(".btn-edit-session-date").addEventListener("click", () => {
    showEditDatePicker();
  });

  const gotoBtn = $("btn-goto-session");
  if (gotoBtn) {
    gotoBtn.classList.remove("hidden");
    gotoBtn.onclick = () => showGoToAnotherSession(state.viewStudent);
  }

  // Wire delete button (static element in header — re-attach each time)
  const _delBtn = $("btn-delete-session");
  if (_delBtn) {
    const newDelBtn = _delBtn.cloneNode(true); // remove old listeners
    newDelBtn.classList.remove("hidden");
    _delBtn.replaceWith(newDelBtn);
    newDelBtn.addEventListener("click", async () => {
      const typed = prompt(`Delete Session ${data.sessionNumber} (${formatDate(data.date)})?\n\nThis cannot be undone. Type DELETE to confirm:`);
      if (typed !== "DELETE") return;
      const sid = state.viewSessionId;
      leaveSessionView();
      await deleteSession(sid).catch(() => {});
    });
  }

  const targets = getViewEffectiveTargets();
  const sorted  = sortTargetsByOrder(targets);

  const body = $("session-view-body");
  const scrollTop = body.scrollTop;
  const captured = captureActiveEditState(body);
  const stripHtml = renderCheckedByStripHtml(data, _viewChkConfirmRole, false);
  body.innerHTML = stripHtml + (sorted.length
    ? sorted.map(t => buildTargetViewTable(t, data)).join("")
    : `<p style="color:var(--text-muted);padding:1rem">No targets recorded.</p>`);

  attachViewListeners();
  restoreActiveEditState(body, captured);
  body.scrollTop = scrollTop;
}

function buildTargetViewTable(target, data) {
  const dayAvg = calcViewDayAvg(data, target);

  let rows = "";
  if (target.predefinedActivities?.length > 0) {
    let no = 0;
    const subActLetterIdx = {};
    const matchedIds = new Set();
    const remCountByAct = {};
    for (const rem of Object.values(data.remarks || {})) {
      remCountByAct[rem.activityId] = (remCountByAct[rem.activityId] || 0) + 1;
    }
    const sortByData = arr => arr.slice().sort(([idA], [idB]) =>
      ((remCountByAct[idB] || 0) - (remCountByAct[idA] || 0)) || idA.localeCompare(idB)
    );
    const parentActNames = new Set(
      (target.predefinedActivities || []).filter(p => p.parentActivity).map(p => p.parentActivity)
    );
    let _pendingViewHeading = null;
    for (const pa of target.predefinedActivities) {
      if (!isActivityActive(pa, data.date)) continue;
      if (pa.isCompleted || pa.isArchived || pa.isStopped) continue;
      if (pa.isHeading || pa.isMaintainHeading) {
        const isGray = pa.headingColor === "gray" || pa.isMaintainHeading;
        const isGreen = pa.headingColor === "green";
        _pendingViewHeading = `<tr class="view-heading-row${isGray ? " view-gray-row" : isGreen ? " view-green-row" : ""}"><td colspan="6" contenteditable="false">${escHtml(pa.name)}</td></tr>`;
        continue;
      }
      if (pa.isNote || pa.isExportNote) {
        if (_pendingViewHeading) { rows += _pendingViewHeading; _pendingViewHeading = null; }
        rows += `<tr class="view-note-row"><td colspan="6" contenteditable="false">${noteToHtml(pa.text)}</td></tr>`;
        continue;
      }
      if (_pendingViewHeading) { rows += _pendingViewHeading; _pendingViewHeading = null; }
      const isSub = !!pa.parentActivity;
      // Skip orphaned sub-activities whose parent was deleted from the predefined config.
      // Edit Target hides them (line: if (a.parentActivity) return) but they still exist in
      // predefinedActivities with no flags — check parent presence to exclude them here too.
      if (isSub) {
        const parentExists = (target.predefinedActivities || []).some(
          p => !p.parentActivity && (p.name === pa.parentActivity || (p.title && p.title === pa.parentActivity))
            && isActivityActive(p, data.date)
            && !p.isCompleted && !p.isArchived && !p.isStopped
        );
        if (!parentExists) continue;
      }
      let displayNo;
      if (isSub) {
        const parentKey = pa.parentActivity;
        if (subActLetterIdx[parentKey] === undefined) subActLetterIdx[parentKey] = 0;
        displayNo = String.fromCharCode(97 + subActLetterIdx[parentKey]) + ")";
        subActLetterIdx[parentKey]++;
      } else {
        no++;
        displayNo = no;
      }
      if (!isSub && (parentActNames.has(pa.name) || (pa.title && parentActNames.has(pa.title)))) {
        Object.entries(data.activities || {})
          .filter(([, a]) => a.targetName === target.name && (
            (pa.name && a.activityName === pa.name) ||
            (pa.title && a.activityName === pa.title) ||
            (pa.id && a.configId === pa.id)
          ))
          .forEach(([id]) => matchedIds.add(id));
        const _paMastered = pa.masteredOn || (pa.inactiveReason === 'mastered' ? "2026-06-30" : null);
        const _paMaintBadge = pa.maintained
          ? `<span style="font-size:.72rem;color:#6b7280;font-weight:600;white-space:nowrap">(🆗 Maintained${pa.maintainedAt ? ` on ${fmtPeriodDate(pa.maintainedAt)}` : ''})</span> `
          : '';
        const paBadge = _paMaintBadge + (pa.discontinuedOn
          ? `<span style="font-size:.72rem;color:#dc2626;font-weight:600;white-space:nowrap">(🚩 ${fmtPeriodDate(pa.discontinuedOn)})</span> `
          : _paMastered
          ? `<span style="font-size:.72rem;color:#059669;font-weight:600;white-space:nowrap">(⭐ ${fmtPeriodDate(_paMastered)})</span> `
          : '');
        rows += `<tr style="background:#f3f4f6">
          <td class="vcol-no" contenteditable="false" style="color:#6b7280">${displayNo}</td>
          <td class="vcol-act" colspan="5" contenteditable="false" style="font-weight:600">${paBadge}${paDisplayHtml(pa)}</td>
        </tr>`;
        continue;
      }
      if ((pa.fixedRemark !== undefined || pa.isMaintain) && !pa.maintained) {
        const fixedEntries = Object.entries(data.activities || {})
          .filter(([, a]) => a.targetName === target.name && (a.activityName === pa.name || (pa.title && a.activityName === pa.title)));
        const fixedEntry = fixedEntries[0] || null;
        fixedEntries.forEach(([id]) => matchedIds.add(id));
        const fixedText = pa.fixedRemark ?? pa.maintainRemark ?? "";
        const isGrayFixed = pa.activityColor === "gray" || !!pa.isMaintainLive;
        const isGreenFixed = pa.activityColor === "green";
        rows += `<tr${isGrayFixed ? ' class="view-gray-row"' : isGreenFixed ? ' class="view-green-row"' : ' style="background:#f9fafb"'}>
          <td class="vcol-no" contenteditable="false">${displayNo}</td>
          <td class="vcol-act" contenteditable="false">${paDisplayHtml(pa)}</td>
          <td class="vcol-rem" contenteditable="false" style="color:#374151;cursor:pointer;white-space:pre-wrap"
            onclick="alert('This is a Fixed Remark — the text is set in Edit Target and cannot be changed here.')"
            title="Fixed Remark — click for info">${formatActivityMarkup(fixedText) || "<span style='color:#9ca3af;font-style:italic'>No remark set</span>"}</td>
          <td class="vcol-trials" contenteditable="false"><span class="view-mapped-label" style="color:#9ca3af;font-style:italic">Fixed Remark</span></td>
          <td class="vcol-total" contenteditable="false">&nbsp;</td>
          <td class="vcol-score" contenteditable="false">&nbsp;</td>
        </tr>`;
        continue;
      }
      const candidateEntries = Object.entries(data.activities || {})
        .filter(([id, a]) => a.targetName === target.name && (a.activityName === pa.name || (pa.title && a.activityName === pa.title) || (pa.id && a.configId === pa.id)) && !matchedIds.has(id));
      // Does an activity have at least one remark with real content?
      const actHasData = id => Object.values(data.remarks || {}).some(r =>
        r.activityId === id && (
          (r.text || "").trim() ||
          (r.trials || []).some(t => t >= 0) ||
          (r.masteryNote || "").replace(/<[^>]*>/g, "").trim()
        )
      );
      // When multiple records share the same configId (race: two devices both called
      // autoFillStructuredRemarks before either write landed), score by data richness
      // and pick the winner — delete the losers so only one record survives.
      let entry = null;
      if (pa.id) {
        const sameConfigEntries = candidateEntries.filter(([, a]) => a.configId === pa.id);
        if (sameConfigEntries.length > 1) {
          const viewScore = ([actId]) => {
            let s = 0;
            for (const r of Object.values(data.remarks || {})) {
              if (r.activityId !== actId) continue;
              s += (r.trials || []).filter(t => t !== null && t !== -1).length * 100;
              if ((r.text || "").trim()) s += 80;  // chip/option selection outweighs note-only
              if ((r.masteryNote || "").replace(/<[^>]*>/g, "").trim()) s += 50;
              if (r.optionScore !== undefined) s += 5;
            }
            return s;
          };
          entry = sameConfigEntries.reduce((a, b) => viewScore(a) >= viewScore(b) ? a : b);
          for (const [loserId] of sameConfigEntries) {
            if (loserId === entry[0]) continue;
            matchedIds.add(loserId);
            const loserRemIds = Object.entries(data.remarks || {}).filter(([, r]) => r.activityId === loserId).map(([id]) => id);
            delete data.activities[loserId];
            for (const remId of loserRemIds) delete data.remarks[remId];
            deleteActivity(state.viewSessionId, loserId, loserRemIds).catch(() => {});
          }
        } else {
          entry = sameConfigEntries[0] || null;
        }
      }
      // If the configId-matched record has no real data, fall through to name-based lookup.
      // Also applies to maintained top-level activities so the Maintain-only remark isn't discarded.
      if ((isSub || pa.maintained) && entry && !actHasData(entry[0])) entry = null;
      if (!entry) {
        if (isSub) {
          // All current config name/title keys — records whose parentActivity is NOT in this
          // set were stored with an old parent name (e.g. with *bold*/_underline_ markers
          // before the title/details split) and are "orphaned" from the current config.
          const knownConfigKeys = new Set(
            (target.predefinedActivities || []).flatMap(p => [p.name, p.title].filter(Boolean))
          );
          // Don't use orphaned/legacy fallbacks if a same-named top-level config exists —
          // that would steal data belonging to the genuine top-level activity.
          const hasTopLevelConfig = (target.predefinedActivities || []).some(p =>
            !p.parentActivity && !p.isHeading && !p.isNote && !p.isExportNote && p.name && p.name === pa.name
          );
          // Accepted candidates: (a) exact parentActivity match, (b) orphaned old-format
          // parent reference no longer in current config, (c) falsy parentActivity (legacy bug)
          const subCandidates = hasTopLevelConfig
            ? candidateEntries.filter(([, a]) => a.parentActivity === pa.parentActivity)
            : candidateEntries.filter(([, a]) =>
                a.parentActivity === pa.parentActivity ||
                (a.parentActivity && !knownConfigKeys.has(a.parentActivity)) ||
                !a.parentActivity
              );
          // Prefer the record with real data over empty placeholders
          const actHasReal = id => Object.values(data.remarks || {}).some(r =>
            r.activityId === id && ((r.text || "").trim() || (r.trials || []).some(t => t >= 0))
          );
          entry = subCandidates.find(([id]) => actHasReal(id)) || sortByData(subCandidates)[0] || null;
        } else {
          const claimable = pa.name === ""
            ? candidateEntries.filter(([, a]) => !a.parentActivity && a.activityName !== "")
            : candidateEntries.filter(([, a]) => !a.parentActivity);
          entry = sortByData(claimable)[0] || null;
        }
      }
      if (entry && pa.id && !entry[1].configId) {
        entry[1].configId = pa.id;
        if (isSub && pa.parentActivity && !entry[1].parentActivity) {
          entry[1].parentActivity = pa.parentActivity;
        }
        adoptOrphanActivity(
          state.viewSessionId,
          entry[0],
          isSub ? (pa.parentActivity || null) : null,
          pa.id
        ).catch(() => {});
      }
      if (entry) matchedIds.add(entry[0]);
      rows += viewActivityRows(displayNo, pa.title || pa.name, entry?.[0] || null, data, target, true, pa);
    }
    // Silently delete unmatched records that have no meaningful data — these
    // are empty ghost duplicates from historical bugs. Records with real data
    // still render below so the user can review and × them manually.
    for (const [actId, act] of Object.entries(data.activities || {})) {
      if (act.targetName !== target.name || matchedIds.has(actId)) continue;
      const remIds = Object.entries(data.remarks || {})
        .filter(([, r]) => r.activityId === actId).map(([id]) => id);
      const hasData = remIds.some(remId => {
        const r = data.remarks[remId];
        return r && (
          (r.text || "").replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").trim().length > 0 ||
          (r.trials || []).some(t => t !== null && t !== -1) ||
          (r.masteryNote || "").replace(/<[^>]*>/g, "").trim().length > 0
        );
      });
      if (!hasData) {
        matchedIds.add(actId);
        delete data.activities[actId];
        for (const remId of remIds) delete data.remarks[remId];
        deleteActivity(state.viewSessionId, actId, remIds).catch(() => {});
      }
    }
    // Manually-added (session-only) extra activities — rendered under an "Extra" heading.
    // Predefined records are included too, not just session-only ones: if an
    // activity is deleted from the target config on purpose, the confirm-by-typing
    // flow purges its session records, so a predefined record that still has data
    // but matches no config entry is always accidental damage (the pre-2026-08-23
    // reorder bug wiped mastered activities out of predefinedActivities). Without
    // this they match nothing and render nowhere, silently hiding real work.
    // Anything data-less was already deleted by the sweep above.
    const extraViewActs = Object.entries(data.activities || {})
      .filter(([actId, a]) => a.targetName === target.name && !matchedIds.has(actId) && !a.parentActivity && a.activityName?.trim())
      .sort(([, a], [, b]) => (a.order || 0) - (b.order || 0));
    if (extraViewActs.length > 0) {
      rows += `<tr class="view-heading-row"><td colspan="6" contenteditable="false">Extra</td></tr>`;
      let extraNo = 0;
      extraViewActs.forEach(([actId, act]) => {
        extraNo++;
        rows += viewActivityRows(extraNo, act.activityName, actId, data, target, false);
      });
    }
  } else {
    let no = 0;
    Object.entries(data.activities || {})
      .filter(([, a]) => a.targetName === target.name)
      .sort(([, a], [, b]) => (a.order || 0) - (b.order || 0))
      .forEach(([actId, act]) => {
        no++;
        rows += viewActivityRows(no, act.activityName, actId, data, target, false);
      });
  }

  if (target.hasComment) {
    const key     = sanitizeKey(target.name);
    const comment = (data.fedcComments || {})[key] || "";
    rows += `<tr class="view-comment-row">
      <td colspan="2" class="view-comment-label" contenteditable="false">Comment</td>
      <td colspan="4" contenteditable="false">
        <textarea class="view-comment-edit" data-target-key="${escHtml(key)}" rows="3"
        >${escHtml(comment)}</textarea>
      </td>
    </tr>`;
  }

  if (dayAvg !== null) {
    rows += `<tr class="view-dayavg-row">
      <td colspan="5" style="text-align:right" contenteditable="false">Day's Average</td>
      <td class="vcol-score" contenteditable="false">${dayAvg}%</td>
    </tr>`;
  }

  return `<div class="target-view-section">
    <div class="target-view-header" contenteditable="false">
      <span class="target-view-name">${escHtml(target.name)}</span>
      ${dayAvg !== null ? `<span class="target-view-avg">${dayAvg}%</span>` : ""}
    </div>
    <div class="view-table-wrapper">
      <table class="view-table">
        <thead><tr>
          <th class="vcol-no">No.</th>
          <th class="vcol-act">Activity</th>
          <th class="vcol-rem">Remark</th>
          <th class="vcol-trials">Trials</th>
          <th class="vcol-total">Total</th>
          <th class="vcol-score">% Score</th>
        </tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>
    <button class="view-add-remark-target" data-target="${escHtml(target.name)}">+ Add Remark &amp; Trials</button>
  </div>`;
}

function viewActivityRows(no, actName, actId, data, target, isPredefined = true, paConfig = null) {
  const remarks = actId ? viewGetRemarks(data, actId) : [];

  const actConfigId = actId ? data.activities?.[actId]?.configId : null;
  const paEntry = paConfig || (isPredefined
    ? (target.predefinedActivities?.find(pa => pa.name === actName) ||
       (actConfigId ? target.predefinedActivities?.find(pa => pa.id === actConfigId) : null))
    : null);

  const parentEntry = paEntry?.parentActivity
    ? (target.predefinedActivities || []).find(p => !p.parentActivity && (p.name === paEntry.parentActivity || (p.title && p.title === paEntry.parentActivity)))
    : null;
  const _discontinuedOn = paEntry?.discontinuedOn || parentEntry?.discontinuedOn || null;
  const _masteredOn     = paEntry?.masteredOn     || parentEntry?.masteredOn
    || (paEntry?.inactiveReason === 'mastered' ? "2026-06-30" : null)
    || (parentEntry?.inactiveReason === 'mastered' ? "2026-06-30" : null)
    || null;
  const _maintained     = !!(paEntry?.maintained   || parentEntry?.maintained);
  const _maintainedAt   = paEntry?.maintainedAt || parentEntry?.maintainedAt || null;
  const _maintBadge = _maintained
    ? `<span style="font-size:.72rem;color:#6b7280;font-weight:600;white-space:nowrap">(🆗 Maintained${_maintainedAt ? ` on ${fmtPeriodDate(_maintainedAt)}` : ''})</span> `
    : '';
  const statusBadge = _maintBadge + (_discontinuedOn
    ? `<span style="font-size:.72rem;color:#dc2626;font-weight:600;white-space:nowrap">(🚩 ${fmtPeriodDate(_discontinuedOn)})</span> `
    : _masteredOn
    ? `<span style="font-size:.72rem;color:#059669;font-weight:600;white-space:nowrap">(⭐ ${fmtPeriodDate(_masteredOn)})</span> `
    : '');

  const actCell = isPredefined
    ? statusBadge + (paEntry ? paDisplayHtml(paEntry) : formatActivityMarkup(actName)) + (paEntry?.actNote?.trim() ? `<div class="view-act-note">${formatActivityMarkup(paEntry.actNote)}</div>` : "")
    : `<div style="display:flex;align-items:center;gap:.3rem">
        <input class="view-act-edit" type="text" value="${escHtml(actName)}"
          data-act-id="${escHtml(actId || "")}" data-original="${escHtml(actName)}" />
        <button class="view-act-del" data-act-id="${escHtml(actId || "")}"
          data-target-name="${escHtml(target.name)}" title="Delete activity">×</button>
       </div>`;

  const inlineOptions   = paEntry ? getActivityInlineOptions(paEntry) : null;
  const sentenceStarter = paEntry?.sentenceStarter || null;
  const multiSelect     = paEntry?.optionsMulti || false;
  const remarkHasNote   = paEntry ? !!(paEntry.remarkHasNote || inlineOptions || paEntry.manualScore) : false;
  const mappedInfo      = paEntry?.isMapped ? resolveViewMappedScoreDisplay(paEntry, data) : null;
  const isGrayAct       = isPredefined && (_maintained || paEntry?.activityColor === "gray" || paEntry?.isMaintainLive);
  const isGreenAct      = isPredefined && paEntry?.activityColor === "green";
  const rowClass        = isGrayAct ? "view-gray-row" : isGreenAct ? "view-green-row" : "";

  if (remarks.length === 0) {
    const opts = parseOpts(inlineOptions);
    const showEmpty = opts.length === 0;
    if (showEmpty) {
      if ((remarkHasNote || multiSelect) && !paEntry?.manualScore) {
        const _lbl = multiSelect ? "CHECKBOXES" : "MULTIPLE CHOICE";
        const _noOptsMsg = `<span class="field-label">${_lbl}</span>
            <span style="color:#9ca3af;font-style:italic;font-size:.88rem">&lt;Please Add Options in Edit Target&gt;</span>`;
        const _noOptsNote = remarkHasNote
          ? `<textarea class="view-mastery-note view-mastery-note-empty" rows="1"
               data-act-id="${escHtml(actId || "")}" data-act-name="${escHtml(actName)}"
               data-target="${escHtml(target.name)}" data-is-predefined="${isPredefined}"
               data-parent-activity="${escHtml(paConfig?.parentActivity || "")}"
               data-config-id="${escHtml(paConfig?.id || "")}"
               placeholder="Remark…"></textarea>` : "";
        const _noOptsCell = remarkHasNote
          ? `<div class="view-starter-wrap view-starter-wrap-note" contenteditable="false">
               <div class="view-starter-top-row">${_noOptsMsg}</div>
               ${_noOptsNote}
             </div>`
          : `<div style="padding:.4rem .6rem">${_noOptsMsg}</div>`;
        return `<tr${rowClass ? ` class="${rowClass}"` : ""}>
          <td class="vcol-no" contenteditable="false">${no}</td>
          <td class="vcol-act" contenteditable="false">${actCell}</td>
          <td class="vcol-rem" contenteditable="false">${_noOptsCell}</td>
          <td class="vcol-trials" contenteditable="false">&nbsp;</td>
          <td class="vcol-total" contenteditable="false">&nbsp;</td>
          <td class="vcol-score" contenteditable="false">&nbsp;</td>
        </tr>`;
      }
      const emptyCell = `<textarea class="view-remark-edit view-remark-empty" rows="1"
           data-act-id="${escHtml(actId || "")}"
           data-act-name="${escHtml(actName)}"
           data-target="${escHtml(target.name)}"
           data-is-predefined="${isPredefined}"
           data-parent-activity="${escHtml(paConfig?.parentActivity || "")}"
           data-config-id="${escHtml(paConfig?.id || "")}"
           placeholder="${_maintained && data.date >= (_maintainedAt || "2026-01-01") ? "" : "Remark…"}">${_maintained && data.date >= (_maintainedAt || "2026-01-01") ? "Maintain" : ""}</textarea>`;
      const addTrialBtn = mappedInfo
        ? ""
        : `<button class="view-add-trial-new" data-act-id="${escHtml(actId || "")}"
        data-act-name="${escHtml(actName)}" data-target-name="${escHtml(target.name)}"
        data-is-predefined="${isPredefined}"
        data-parent-activity="${escHtml(paConfig?.parentActivity || "")}"
        data-config-id="${escHtml(paConfig?.id || "")}">+</button>`;
      const emptyTrialsContent = paConfig?.noTrials
        ? `<span class="view-trials-disabled" style="color:#9ca3af;font-style:italic">Trials are not required for this activity</span>`
        : mappedInfo
        ? `<span class="view-mapped-label">${escHtml(mappedInfo.label)}</span>`
        : (addTrialBtn || "&nbsp;");
      const emptyScoreContent = mappedInfo
        ? (mappedInfo.pct !== null ? mappedInfo.pct + "%" : "—")
        : "&nbsp;";
      return `<tr${rowClass ? ` class="${rowClass}"` : ""}>
        <td class="vcol-no" contenteditable="false">${no}</td>
        <td class="vcol-act" contenteditable="false">${actCell}</td>
        <td class="vcol-rem" contenteditable="false">${emptyCell}</td>
        <td class="vcol-trials" contenteditable="false">${emptyTrialsContent}</td>
        <td class="vcol-total" contenteditable="false">&nbsp;</td>
        <td class="vcol-score" contenteditable="false">${emptyScoreContent}</td>
      </tr>`;
    }
    // opts.length > 0 — show actual select/multi UI directly (no button)
    // When no matched record exists (actId=null), check for orphan records with
    // same activityName that carry old free-text (rename artifact).
    const _orphanOldText = actId === null ? (() => {
      for (const [oid, oact] of Object.entries(data.activities || {})) {
        if (oact.targetName !== target.name || oact.activityName !== actName) continue;
        for (const r of viewGetRemarks(data, oid)) {
          const txt = (r.text || "").replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").trim();
          if (txt && !opts.includes(txt)) return txt;
        }
      }
      return "";
    })() : "";
    const _orphanBadge = _orphanOldText ? `<div style="font-size:.78rem;color:#9ca3af;margin-top:.25rem;font-style:italic">Old data: ${escHtml(_orphanOldText)}</div>` : "";
    let emptySelHtml;
    if (multiSelect) {
      emptySelHtml = `<div class="view-remark-multi-opts" contenteditable="false">${opts.map(opt =>
        `<button class="view-multi-create-btn" data-opt="${escHtml(opt)}"
          data-act-id="${escHtml(actId || "")}" data-act-name="${escHtml(actName)}"
          data-target-name="${escHtml(target.name)}" data-is-predefined="${isPredefined}"
          data-maintained="${_maintained}">${escHtml(opt)}</button>`
      ).join("")}${_orphanBadge}</div>`;
    } else {
      emptySelHtml = `<div class="view-remark-multi-opts" contenteditable="false">${opts.map(opt => {
        const sc = (paEntry?.optionScores && paEntry.optionScores[opt] !== undefined) ? paEntry.optionScores[opt] : "";
        return `<button class="view-single-create-btn" data-opt="${escHtml(opt)}" data-score="${sc}"
          data-act-id="${escHtml(actId || "")}" data-act-name="${escHtml(actName)}"
          data-target-name="${escHtml(target.name)}" data-is-predefined="${isPredefined}">${escHtml(opt)}</button>`;
      }).join("")}${_orphanBadge}</div>`;
    }
    const noteEmptyHtml = remarkHasNote
      ? `<textarea class="view-mastery-note view-mastery-note-empty" rows="1"
           data-act-id="${escHtml(actId || "")}" data-act-name="${escHtml(actName)}"
           data-target="${escHtml(target.name)}" data-is-predefined="${isPredefined}"
           data-parent-activity="${escHtml(paConfig?.parentActivity || "")}"
           data-config-id="${escHtml(paConfig?.id || "")}"
           placeholder="Remark…"></textarea>`
      : "";
    let emptyRemCell;
    if (sentenceStarter && remarkHasNote) {
      emptyRemCell = `<div class="view-starter-wrap view-starter-wrap-note" contenteditable="false">
        <div class="view-starter-top-row"><span class="view-starter-prefix">${escHtml(sentenceStarter)}</span>${emptySelHtml}</div>
        ${noteEmptyHtml}
      </div>`;
    } else if (sentenceStarter) {
      emptyRemCell = `<div class="view-starter-wrap" contenteditable="false">
        <span class="view-starter-prefix">${escHtml(sentenceStarter)}</span>${emptySelHtml}
      </div>`;
    } else if (remarkHasNote) {
      emptyRemCell = `<div class="view-starter-wrap view-starter-wrap-note" contenteditable="false">
        <div class="view-starter-top-row">${emptySelHtml}</div>
        ${noteEmptyHtml}
      </div>`;
    } else {
      emptyRemCell = emptySelHtml;
    }
    const emptyTrialBtn = paConfig?.noTrials
      ? `<span class="view-trials-disabled" style="color:#9ca3af;font-style:italic">Trials are not required for this activity</span>`
      : mappedInfo
      ? `<span class="view-mapped-label">${escHtml(mappedInfo.label)}</span>`
      : `<button class="view-add-trial-new" data-act-id="${escHtml(actId || "")}"
          data-act-name="${escHtml(actName)}" data-target-name="${escHtml(target.name)}"
          data-is-predefined="${isPredefined}"
          data-parent-activity="${escHtml(paConfig?.parentActivity || "")}"
          data-config-id="${escHtml(paConfig?.id || "")}">+</button>`;
    return `<tr${rowClass ? ` class="${rowClass}"` : ""}>
      <td class="vcol-no" contenteditable="false">${no}</td>
      <td class="vcol-act" contenteditable="false">${actCell}</td>
      <td class="vcol-rem" contenteditable="false">${emptyRemCell}</td>
      <td class="vcol-trials" contenteditable="false">${emptyTrialBtn}</td>
      <td class="vcol-total" contenteditable="false">&nbsp;</td>
      <td class="vcol-score" contenteditable="false">${mappedInfo ? (mappedInfo.pct !== null ? mappedInfo.pct + "%" : "—") : "&nbsp;"}</td>
    </tr>`;
  }
  return remarks.map((rem, ri) => viewRemarkRow(
    ri === 0 ? no : null,
    ri === 0 ? actCell : null,
    rem, target, inlineOptions, sentenceStarter, multiSelect, mappedInfo, remarkHasNote, rowClass,
    paEntry?.optionScores || null, paEntry?.manualScore || false, paEntry?.noTrials || false
  )).join("");
}

// Shared by viewRemarkRow/viewGroupRemarkRow (initial render) and
// refreshViewTrialRow/refreshGroupViewTrialRow (surgical in-place update
// after a trial add/delete/score change — see the comment on
// bindViewTrialCellListeners for why those don't go through a full render).
function calcViewTrialSummary(trials, maxPts, optionScore = undefined) {
  const validTrials = (trials || []).filter(t => t !== -1);
  if (optionScore !== undefined) validTrials.push(optionScore);
  const total       = validTrials.reduce((a, b) => a + b, 0);
  const scorePct    = validTrials.length > 0
    ? Math.round(total / (validTrials.length * maxPts) * 100) + "%" : "";
  return { validTrials, total, scorePct };
}

function buildTrialCellsHtml(rem, maxPts) {
  const allTrials = rem.trials || [];
  const optBadge = rem.optionScore !== undefined
    ? `<span class="trial-badge trial-badge--option">${rem.optionScore}</span>` : "";
  return optBadge + allTrials.map((t, ti) => `
    <span class="trial-cell">
      <select class="view-trial-select" data-rem-id="${escHtml(rem.id)}" data-trial-idx="${ti}">
        <option value="-1"${t === -1 ? " selected" : ""}>—</option>
        ${Array.from({ length: maxPts + 1 }, (_, i) => maxPts - i)
          .map(v => `<option value="${v}"${v === t ? " selected" : ""}>${v}</option>`).join("")}
      </select>
      <button class="view-trial-del" data-rem-id="${escHtml(rem.id)}" data-trial-idx="${ti}">×</button>
    </span>`).join("") +
    `<button class="view-add-trial" data-rem-id="${escHtml(rem.id)}">+</button>`;
}

function viewRemarkRow(no, actName, rem, target, inlineOptions = null, sentenceStarter = null, multiSelect = false, mappedInfo = null, remarkHasNote = false, rowClass = "", optionScores = null, manualScore = false, noTrials = false) {
  const _sv = t => (t || "").replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").trim();
  const _remEmpty = !_sv(rem.text) && !_sv(rem.masteryNote) && !(rem.trials || []).some(t => t >= 0) && rem.optionScore === undefined;
  const delBtn = _remEmpty ? "" : `<button class="view-rem-del" data-rem-id="${escHtml(rem.id)}" title="Delete remark">×</button>`;
  // Manual score: render score input + = XX% hint; notes below; no trials
  if (manualScore) {
    const currentVal = rem.text ? plainTextForEdit(rem.text).trim() : "";
    const parsed = parseManualScore(currentVal);
    const parsedPct = parsed !== null ? Math.round(parsed * 10) / 10 : null;
    const hintHtml = `<span class="view-manual-score-hint" data-rem-id="${escHtml(rem.id)}"
      style="font-size:.85rem;color:#6b7280;white-space:nowrap${parsedPct === null ? ";display:none" : ""}">${parsedPct !== null ? `= ${parsedPct}%` : ""}</span>`;
    const scoreInput = `<div style="display:flex;align-items:center;gap:.5rem;flex-wrap:wrap;padding:.3rem .4rem .15rem">
      <span style="font-size:.7rem;font-weight:700;color:#6b7280;letter-spacing:.05em;white-space:nowrap">MANUAL SCORE</span>
      <input type="text" class="view-manual-score-input" data-rem-id="${escHtml(rem.id)}"
        data-saved-html="${escHtml(currentVal)}" value="${escHtml(currentVal)}"
        placeholder="e.g. 5/20, 25%"
        style="width:9rem;min-width:0;border:1px solid #b0b7c3;border-radius:4px;padding:.25rem .4rem;font-size:.85rem;font-family:var(--font);background:#fff;outline:none;box-sizing:border-box">
      ${hintHtml}
    </div>`;
    const noteCell = `<textarea class="view-mastery-note" rows="1" data-rem-id="${escHtml(rem.id)}"
      data-saved-html="${escHtml(rem.masteryNote || "")}"
      placeholder="Remark…">${escHtml(plainTextForEdit(rem.masteryNote))}</textarea>`;
    const remarkCell = `<div class="view-manual-score-wrap" contenteditable="false">${scoreInput}${noteCell}</div>`;
    const scoreColDisplay = parsedPct !== null ? parsedPct + "%" : "";
    return `<tr${rowClass ? ` class="${rowClass}"` : ""}>
      <td class="vcol-no" contenteditable="false">${no !== null ? no : ""}</td>
      <td class="vcol-act" contenteditable="false">${actName !== null ? actName : ""}</td>
      <td class="vcol-rem" contenteditable="false">${remarkCell}</td>
      <td class="vcol-trials" contenteditable="false">&nbsp;</td>
      <td class="vcol-total" contenteditable="false">&nbsp;</td>
      <td class="vcol-score" contenteditable="false">
        <div style="display:flex;align-items:center;gap:.3rem;justify-content:flex-end">
          <span class="view-manual-score-pct" data-rem-id="${escHtml(rem.id)}">${scoreColDisplay}</span>
          ${delBtn}
        </div>
      </td>
    </tr>`;
  }

  const maxPts = target.maxPoints || 3;
  const { validTrials, total, scorePct } = calcViewTrialSummary(rem.trials, maxPts, rem.optionScore);
  const trialCells = mappedInfo
    ? `<span class="view-mapped-label">${escHtml(mappedInfo.label)}</span>`
    : `<div class="trial-cells">${buildTrialCellsHtml(rem, maxPts)}</div>`;
  const totalCell = mappedInfo ? "&nbsp;" : (validTrials.length > 0 ? total : "&nbsp;");
  const scoreDisplay = mappedInfo
    ? (mappedInfo.pct !== null ? mappedInfo.pct + "%" : "—")
    : scorePct;

  const opts = parseOpts(inlineOptions);

  function makeViewOpts(remId, remText) {
    if (opts.length === 0) return null;
    const removedBadge = (() => {
      if (!remText) return "";
      if (multiSelect) {
        const sel = remText.split(", ").map(s => s.trim()).filter(Boolean);
        const gone = sel.filter(s => !opts.includes(s));
        return gone.length ? `<div style="font-size:.78rem;color:#9ca3af;margin-top:.25rem;font-style:italic">Old data: ${escHtml(gone.join(", "))}</div>` : "";
      }
      return !opts.includes(remText) ? `<div style="font-size:.78rem;color:#9ca3af;margin-top:.25rem;font-style:italic">Old data: ${escHtml(remText)}</div>` : "";
    })();
    if (multiSelect) {
      const sel = (remText || "").split(", ").map(s => s.trim()).filter(Boolean);
      return `<div class="view-remark-multi-opts" contenteditable="false">${opts.map(opt =>
        `<button class="view-remark-multi-btn view-remark-multi-btn--rect${sel.includes(opt) ? " active" : ""}"
          data-rem-id="${escHtml(remId)}" data-opt="${escHtml(opt)}">${escHtml(opt)}</button>`
      ).join("")}${removedBadge}</div>`;
    }
    return `<div class="view-remark-multi-opts" contenteditable="false">${opts.map(opt => {
      const sc = (optionScores && optionScores[opt] !== undefined) ? optionScores[opt] : "";
      return `<button class="view-remark-single-btn${remText === opt ? " active" : ""}"
        data-rem-id="${escHtml(remId)}" data-opt="${escHtml(opt)}" data-score="${sc}">${escHtml(opt)}</button>`;
    }).join("")}${removedBadge}</div>`;
  }

  if ((remarkHasNote || multiSelect) && opts.length === 0) {
    const _lbl2 = multiSelect ? "CHECKBOXES" : "MULTIPLE CHOICE";
    const _msg2 = `<span class="field-label">${_lbl2}</span>
      <span style="color:#9ca3af;font-style:italic;font-size:.88rem">&lt;Please Add Options in Edit Target&gt;</span>`;
    const _note2 = remarkHasNote
      ? `<textarea class="view-mastery-note" rows="1" data-rem-id="${escHtml(rem.id)}"
           data-saved-html="${escHtml(rem.masteryNote || "")}"
           placeholder="Remark…">${escHtml(plainTextForEdit(rem.masteryNote))}</textarea>` : "";
    const _cell2 = remarkHasNote
      ? `<div class="view-starter-wrap view-starter-wrap-note" contenteditable="false">
           <div class="view-starter-top-row">${_msg2}</div>
           ${_note2}
         </div>`
      : `<div style="padding:.4rem .6rem">${_msg2}</div>`;
    return `<tr${rowClass ? ` class="${rowClass}"` : ""}>
      <td class="vcol-no" contenteditable="false">${no !== null ? no : ""}</td>
      <td class="vcol-act" contenteditable="false">${actName !== null ? actName : ""}</td>
      <td class="vcol-rem" contenteditable="false">${_cell2}</td>
      <td class="vcol-trials" contenteditable="false">&nbsp;</td>
      <td class="vcol-total" contenteditable="false">&nbsp;</td>
      <td class="vcol-score" contenteditable="false">&nbsp;</td>
    </tr>`;
  }
  const optSelect = makeViewOpts(rem.id, rem.text)
    || `<textarea class="view-remark-edit" rows="1" data-rem-id="${escHtml(rem.id)}"
          placeholder="Remark…" data-saved-html="${escHtml(rem.text || "")}">${escHtml(plainTextForEdit(rem.text))}</textarea>`;

  // Show the note textarea if the current type includes it, OR if the remark
  // already has a masteryNote saved (e.g. type was +Free Text in the past and
  // was later changed back — old notes should remain visible and editable).
  const showNote = remarkHasNote || !!(rem.masteryNote && rem.masteryNote.trim().length > 0);
  const noteField = showNote
    ? `<textarea class="view-mastery-note" rows="1" data-rem-id="${escHtml(rem.id)}"
        data-saved-html="${escHtml(rem.masteryNote || "")}"
        placeholder="Remark…">${escHtml(plainTextForEdit(rem.masteryNote))}</textarea>`
    : "";

  let remarkCell;
  if (sentenceStarter) {
    const starterTopRow = `<span class="view-starter-prefix">${escHtml(sentenceStarter)}</span>
      ${makeViewOpts(rem.id, rem.text)
        || `<textarea class="view-starter-input" data-rem-id="${escHtml(rem.id)}"
            rows="1" style="overflow-y:hidden">${escHtml(rem.text || "")}</textarea>`
      }`;
    remarkCell = showNote
      ? `<div class="view-starter-wrap view-starter-wrap-note" contenteditable="false">
          <div class="view-starter-top-row">${starterTopRow}</div>
          ${noteField}
        </div>`
      : `<div class="view-starter-wrap" contenteditable="false">${starterTopRow}</div>`;
  } else if (showNote) {
    remarkCell = `<div class="view-starter-wrap view-starter-wrap-note" contenteditable="false">
      <div class="view-starter-top-row">${optSelect}</div>
      ${noteField}
    </div>`;
  } else {
    remarkCell = optSelect;
  }

  return `<tr${rowClass ? ` class="${rowClass}"` : ""}>
    <td class="vcol-no" contenteditable="false">${no !== null ? no : ""}</td>
    <td class="vcol-act" contenteditable="false">${actName !== null ? actName : ""}</td>
    <td class="vcol-rem" contenteditable="false">${remarkCell}</td>
    <td class="vcol-trials" contenteditable="false">${noTrials ? `<span class="view-trials-disabled" style="color:#9ca3af;font-style:italic">Trials are not required for this activity</span>` : trialCells}</td>
    <td class="vcol-total" contenteditable="false">${noTrials ? "&nbsp;" : totalCell}</td>
    <td class="vcol-score" contenteditable="false">
      <div style="display:flex;align-items:center;gap:.3rem;justify-content:flex-end">
        <span>${noTrials ? "" : scoreDisplay}</span>
        ${delBtn}
      </div>
    </td>
  </tr>`;
}

function viewGetRemarks(data, actId) {
  return Object.entries(data.remarks || {})
    .filter(([, r]) => r.activityId === actId)
    .sort(([, a], [, b]) => (a.order || 0) - (b.order || 0))
    .map(([id, r]) => ({ id, ...r }));
}

// visited guards against a circular mapping chain recursing forever — see
// calcDaysAverage's comment (this is the View-screen counterpart, working off
// a passed-in `data` snapshot instead of the live session's global state, so
// it doubles as both the individual and group View/Edit Past Sessions calc).
// Group sessions fold in each attendee's own per-attendee mapped score
// separately (one push per attendee with a remark on the activity) rather
// than a single blended number, per the boss's "per-attendee" decision —
// detected via data.attendees, same signal already used elsewhere for group
// session data.
function calcViewDayAvg(data, target, visited = new Set()) {
  if (visited.has(target.id)) return null;
  visited.add(target.id);

  const attendees = data.attendees || state.viewGroup?.students || null;
  const avgs = [];
  Object.entries(data.activities || {})
    .filter(([, a]) => a.targetName === target.name)
    .forEach(([actId, act]) => {
      const pa = (target.predefinedActivities || []).find(p => p.isMapped &&
          (p.name === act.activityName || (act.configId && p.id === act.configId)));
      if (pa) {
        const mappedTarget = pa.mappedTargetId
          ? (state.viewGroup?.targets || state.viewStudent?.targets || []).find(t => t.id === pa.mappedTargetId)
          : null;
        if (!mappedTarget) return;
        if (attendees) {
          attendees.forEach(studentName => {
            const hasRemark = Object.values(data.remarks || {})
              .some(r => r.activityId === actId && r.studentName === studentName);
            if (!hasRemark) return;
            const pct = calcGroupStudentDaysAverage(mappedTarget, data, studentName, visited);
            if (pct !== null) avgs.push(pct);
          });
        } else {
          if (viewGetRemarks(data, actId).length === 0) return;
          const pct = calcViewDayAvg(data, mappedTarget, visited);
          if (pct !== null) avgs.push(pct);
        }
        return;
      }
      const manualPa = (target.predefinedActivities || []).find(p => p.manualScore &&
          (p.name === act.activityName || (act.configId && p.id === act.configId)));
      viewGetRemarks(data, actId).forEach(rem => {
        if (manualPa) {
          const pct = parseManualScore(plainTextForEdit(rem.text || "").trim());
          if (pct !== null) avgs.push(pct);
          return;
        }
        const trials = (rem.trials || []).filter(t => t !== -1);
        const allScores = rem.optionScore !== undefined ? [...trials, rem.optionScore] : trials;
        if (!allScores.length) return;
        avgs.push(allScores.reduce((a, b) => a + b, 0) / (allScores.length * (target.maxPoints || 3)) * 100);
      });
    });
  return avgs.length ? Math.round(avgs.reduce((a, b) => a + b, 0) / avgs.length) : null;
}

// Resolves a mapped-score activity's display on the individual View/Edit Past
// Sessions screen — see resolveMappedScoreDisplay (live-entry counterpart).
function resolveViewMappedScoreDisplay(pa, data, visited) {
  const mappedTarget = pa.mappedTargetId
    ? getViewEffectiveTargets().find(t => t.id === pa.mappedTargetId)
    : null;
  if (!mappedTarget) return { label: "Score (Not Mapped Yet)", pct: null };
  return {
    label: `Score (Mapped to ${mappedTarget.name}'s Average)`,
    pct: calcViewDayAvg(data, mappedTarget, visited)
  };
}

// View/Edit Past Sessions counterpart of autoFillMappedRemarks (live-entry
// session) — same trigger (mapped target gained a computable average), but
// runs on every snapshot here since this screen has no "first load" gate and
// the mapped-to target's data could change at any time while it's open.
async function autoFillViewMappedRemarks(student, sessionId, data) {
  let count = 0;
  for (const target of (student.targets || [])) {
    for (const pa of (target.predefinedActivities || [])) {
      if (pa.isCompleted || pa.isArchived || pa.isStopped || pa.isMaintain || pa.isMaintainHeading) continue;
      if (!pa.isMapped) continue;

      const allMatchesV = Object.entries(data.activities || {})
        .filter(([, a]) => a.targetName === target.name &&
                           (a.activityName === pa.name || (pa.title && a.activityName === pa.title) || (pa.id && a.configId === pa.id)));
      const canonicalV = allMatchesV.find(([, a]) => pa.id && a.configId === pa.id) || allMatchesV[0] || null;
      for (const [dupeActId] of allMatchesV.filter(([aid]) => aid !== canonicalV?.[0] && !data.activities[aid]?.configId)) {
        const dupeRemIds = Object.entries(data.remarks || {}).filter(([, r]) => r.activityId === dupeActId).map(([rid]) => rid);
        deleteActivity(sessionId, dupeActId, dupeRemIds);
      }
      // No longer create empty remarks — the view screen now renders the mapped
      // score even when no remark exists, so the empty-remark creation step is
      // unnecessary and was the source of the 5-second delay + paste-disappears bug.
    }
  }
  return count;
}

// View/Edit Past Sessions counterpart of autoFillMaintainedRemarks.
// No hasRealData guard: maintained activities always show "Maintain" regardless
// of whether other activities in the session have data.
async function autoFillViewMaintainedRemarks(student, sessionId, data) {
  let count = 0;
  for (const target of (student.targets || [])) {
    for (const pa of (target.predefinedActivities || [])) {
      if (!pa.maintained || pa.isHeading || pa.isNote || pa.isExportNote || pa.isMaintainHeading || (!pa.name && !pa.title) || pa.parentActivity) continue;
      // Non-Notes-Only activities handled by autoFillViewStructuredRemarks
      if (getActivityInlineOptions(pa) || pa.optionsMulti || pa.manualScore) continue;
      // Only auto-fill "Maintain" for sessions on or after the maintained date
      const _viewMaintAt = pa.maintainedAt || "2026-01-01";
      if (data.date && data.date < _viewMaintAt) continue;
      const allMatches = Object.entries(data.activities || {})
        .filter(([, a]) => a.targetName === target.name && !a.parentActivity &&
                           (a.activityName === pa.name || (pa.title && a.activityName === pa.title) || (pa.id && a.configId === pa.id)));
      const canonical = allMatches.find(([, a]) => pa.id && a.configId === pa.id) || allMatches[0] || null;
      for (const [dupeActId] of allMatches.filter(([aid]) => aid !== canonical?.[0] && !data.activities[aid]?.configId)) {
        const dupeRemIds = Object.entries(data.remarks || {}).filter(([, r]) => r.activityId === dupeActId).map(([rid]) => rid);
        deleteActivity(sessionId, dupeActId, dupeRemIds);
      }
      let actId = canonical?.[0] || null;
      if (actId && Object.values(data.remarks || {}).some(r => r.activityId === actId)) continue;
      const key = `${sessionId}:${target.name}:${pa.name}:maintained`;
      if (maintainedRemarkAutoFillInFlight.has(key)) continue;
      maintainedRemarkAutoFillInFlight.add(key);
      try {
        if (!actId) actId = await addActivity(sessionId, target.name, pa.name, pa.order ?? 0, true);
        await addRemark(sessionId, actId, "Maintain");
        count++;
      } finally { maintainedRemarkAutoFillInFlight.delete(key); }
    }
  }
  return count;
}

// View-screen counterpart of autoFillStructuredRemarks — re-creates empty
// placeholder remarks for auto-open activities (Mastery Level / Select One /
// Tickbox) whose records were cleaned up when the session was last left.
// Without this, those activities render as view-single-create-btn (needing a
// new activity+remark write pair), and the intermediate Firestore snapshot
// between the two writes reverts the optimistic render. With this, by the
// time the user clicks, the record already exists and only a single
// updateRemarkText write is needed (no intermediate-state risk).
async function autoFillViewStructuredRemarks(student, sessionId, data) {
  // Non-maintained activities are skipped in empty sessions (no real data yet),
  // but maintained activities always get their "Maintain" auto-fill regardless.
  const hasRealData = Object.values(data.remarks || {}).some(r =>
    (r.text && r.text.trim()) || (r.trials || []).some(t => t >= 0) || r.optionScore !== undefined
  );
  const sessionDate = data.date || null;
  let count = 0;
  for (const target of (student.targets || [])) {
    for (const pa of (target.predefinedActivities || [])) {
      if (!isAutoOpenRemarkType(pa)) continue;
      if (!pa.maintained && !hasRealData) continue;
      const _viewIsNotesOnly = !getActivityInlineOptions(pa) && !pa.optionsMulti && !pa.manualScore;
      if ((pa.maintained && _viewIsNotesOnly) || pa.isMapped) continue;
      if (!isActivityActive(pa, sessionDate)) continue;
      const paConfigId = pa.id || null;
      const paParent = pa.parentActivity || null;
      const allActs = Object.entries(data.activities || {});
      // Skip if ANY candidate for this slot already has a remark (even empty).
      const candidateIds = allActs
        .filter(([, a]) => {
          if (a.targetName !== target.name) return false;
          if (paConfigId && a.configId === paConfigId) return true;
          if (a.configId) return false;
          const nameOk = (pa.name && a.activityName === pa.name) || (pa.title && a.activityName === pa.title);
          if (!nameOk) return false;
          return paParent ? (!a.parentActivity || a.parentActivity === paParent) : !a.parentActivity;
        })
        .map(([id]) => id);
      const remarkActIds = new Set(Object.values(data.remarks || {}).map(r => r.activityId));
      const _vMaintAt = pa.maintainedAt || "2026-01-01";
      const _vOnOrAfterMaint = !sessionDate || sessionDate >= _vMaintAt;
      if (candidateIds.some(id => remarkActIds.has(id))) {
        if (pa.maintained && _vOnOrAfterMaint) {
          for (const candId of candidateIds) {
            const actRems = Object.entries(data.remarks || {}).filter(([, r]) => r.activityId === candId);
            // Clean up existing "Maintain"-only auto-fill duplicates: if one remark is an empty
            // auto-fill placeholder (no chip selection, no real note, just masteryNote="Maintain")
            // and another remark has real content, delete the auto-fill one.
            if (actRems.length > 1) {
              const _isMaintainAutoFill = ([, r]) =>
                !(r.text || "").trim() &&
                (r.masteryNote || "").replace(/<[^>]*>/g, "").trim() === "Maintain" &&
                !(r.trials || []).some(t => t >= 0) &&
                r.optionScore === undefined;
              const autoFillRems = actRems.filter(_isMaintainAutoFill);
              const realRems     = actRems.filter(e => !_isMaintainAutoFill(e));
              if (autoFillRems.length > 0 && realRems.length > 0) {
                const toDelete = autoFillRems.map(([id]) => id);
                for (const remId of toDelete) delete data.remarks[remId];
                deleteRemarksBatch(sessionId, toDelete).catch(() => {});
              }
              continue;
            }
            if (actRems.length !== 1) continue;
            const [[remId, r]] = actRems;
            // Only check if masteryNote is already set — chip selection or text doesn't block it.
            const _hasMaintainNote = !!(r.masteryNote || "").replace(/<[^>]*>/g, "").trim();
            if (!_hasMaintainNote)
              updateRemarkNote(sessionId, remId, "Maintain").catch(() => {});
          }
        }
        continue;
      }
      // Guard: if any name-matched activity (even with a stale/different configId) already has
      // a remark, don't create a duplicate — the renderer will pick it up via name-based match.
      const _nameMatchHasRemark = allActs.some(([actId2, a2]) => {
        if (a2.targetName !== target.name) return false;
        const _nOk = (pa.name && a2.activityName === pa.name) || (pa.title && a2.activityName === pa.title);
        if (!_nOk) return false;
        const _pOk = paParent ? (!a2.parentActivity || a2.parentActivity === paParent) : !a2.parentActivity;
        return _pOk && remarkActIds.has(actId2);
      });
      if (_nameMatchHasRemark) continue;
      // Don't create placeholder records for maintained activities in pre-maintained sessions.
      if (pa.maintained && !_vOnOrAfterMaint) continue;
      const existingActId = candidateIds[0] || null;
      const key = `${sessionId}:${target.name}:${paConfigId || pa.name}:${paParent || ""}:view`;
      if (structuredRemarkAutoFillInFlight.has(key)) continue;
      structuredRemarkAutoFillInFlight.add(key);
      const _vMaintNote = pa.maintained && _vOnOrAfterMaint ? "Maintain" : "";
      try {
        if (existingActId) {
          const _preRemId = generateId("r");
          await addRemark(sessionId, existingActId, "", null, _preRemId, _vMaintNote);
          // Update local state optimistically so render shows view-remark-single-btn immediately.
          data.remarks = data.remarks || {};
          data.remarks[_preRemId] = { activityId: existingActId, text: "", trials: [], order: Date.now(), ...(_vMaintNote ? { masteryNote: _vMaintNote } : {}) };
        } else {
          const { actId: _newActId, remId: _newRemId } = await addAutoFillActivityAndRemark(sessionId, target.name, pa.title || pa.name, pa.order ?? 0, paParent, paConfigId, _vMaintNote);
          data.activities = data.activities || {};
          data.activities[_newActId] = { targetName: target.name, activityName: pa.title || pa.name, order: pa.order ?? 0, isPredefined: true, ...(paParent ? { parentActivity: paParent } : {}), ...(paConfigId ? { configId: paConfigId } : {}) };
          data.remarks = data.remarks || {};
          data.remarks[_newRemId] = { activityId: _newActId, text: "", trials: [], order: Date.now(), ...(_vMaintNote ? { masteryNote: _vMaintNote } : {}) };
        }
        count++;
      } catch { /* silent — next snapshot will retry */ }
      finally { structuredRemarkAutoFillInFlight.delete(key); }
    }
  }
  return count;
}

// Resolves a mapped-score activity's display for one attendee on the group
// View/Edit Past Sessions screen — see resolveGroupMappedScoreDisplay
// (live-entry counterpart). Per-attendee throughout, per the boss's decision.
function resolveViewGroupMappedScoreDisplay(pa, data, studentName, visited) {
  const mappedTarget = pa.mappedTargetId
    ? getViewGroupEffectiveTargets().find(t => t.id === pa.mappedTargetId)
    : null;
  if (!mappedTarget) return { label: "Score (Not Mapped Yet)", pct: null };
  return {
    label: `Score (Mapped to ${mappedTarget.name}'s Average)`,
    pct: calcGroupStudentDaysAverage(mappedTarget, data, studentName, visited)
  };
}

// Group View/Edit Past Sessions counterpart of autoFillMappedRemarks — unlike
// the live group entry version, this screen renders every target at once (no
// per-target lazy loading), so it checks all of them on every snapshot, same
// as the individual View screen's autoFillViewMappedRemarks.
async function autoFillViewGroupMappedRemarks(group, sessionId, data) {
  const attendees = data.attendees || (group.students || []).filter(Boolean);
  let count = 0;
  for (const target of (group.targets || [])) {
    for (const pa of (target.predefinedActivities || [])) {
      if (pa.isCompleted || pa.isArchived || pa.isStopped || pa.isMaintain || pa.isMaintainHeading) continue;
      if (!pa.isMapped) continue;
      const existingAct = Object.entries(data.activities || {})
        .find(([, a]) => a.targetName === target.name && (a.activityName === pa.name || (pa.title && a.activityName === pa.title)));
      let actId = existingAct?.[0] || null;

      for (const studentName of attendees) {
        const hasRemark = actId && Object.values(data.remarks || {})
          .some(r => r.activityId === actId && r.studentName === studentName);
        if (hasRemark) continue;
        const key = `${sessionId}:${target.name}:${pa.name}:${studentName}`;
        if (mappedRemarkAutoFillInFlight.has(key)) continue;
        mappedRemarkAutoFillInFlight.add(key);
        try {
          if (!actId) {
            actId = await addActivity(sessionId, target.name, pa.name, pa.order ?? 0, true);
          }
          await addGroupRemark(sessionId, actId, studentName, "");
          count++;
        } finally {
          mappedRemarkAutoFillInFlight.delete(key);
        }
      }
    }
  }
  return count;
}

// Group View/Edit Past Sessions counterpart of autoFillViewMaintainedRemarks.
// Creates "Maintain" remark per attendee for maintained Notes-Only activities
// on sessions on/after the maintained date, mirroring the individual view logic.
// No hasRealData guard: maintained activities always show "Maintain" regardless of other session data.
async function autoFillViewGroupMaintainedRemarks(group, sessionId, data) {
  const attendees = data.attendees || (group.students || []).filter(Boolean);
  let count = 0;
  for (const target of (group.targets || [])) {
    for (const pa of (target.predefinedActivities || [])) {
      if (!pa.maintained || pa.isHeading || pa.isNote || pa.isExportNote || pa.isMaintainHeading || (!pa.name && !pa.title) || pa.parentActivity) continue;
      // Non-Notes-Only activities handled by autoFillViewGroupStructuredRemarks
      if (getActivityInlineOptions(pa) || pa.optionsMulti || pa.manualScore) continue;
      const _maintAt = pa.maintainedAt || "2026-01-01";
      if (data.date && data.date < _maintAt) continue;
      const allMatches = Object.entries(data.activities || {})
        .filter(([, a]) => a.targetName === target.name && !a.parentActivity &&
                           (a.activityName === pa.name || (pa.title && a.activityName === pa.title) || (pa.id && a.configId === pa.id)));
      const canonical = allMatches.find(([, a]) => pa.id && a.configId === pa.id) || allMatches[0] || null;
      let actId = canonical?.[0] || null;
      if (!actId) {
        const actKey = `viewgrp:${sessionId}:${target.name}:${pa.name}:maintained:act`;
        if (maintainedRemarkAutoFillInFlight.has(actKey)) continue;
        maintainedRemarkAutoFillInFlight.add(actKey);
        try {
          actId = await addActivity(sessionId, target.name, pa.name, pa.order ?? 0, true);
        } catch { maintainedRemarkAutoFillInFlight.delete(actKey); continue; }
        maintainedRemarkAutoFillInFlight.delete(actKey);
      }
      for (const studentName of attendees) {
        const hasRemark = Object.values(data.remarks || {})
          .some(r => r.activityId === actId && r.studentName === studentName);
        if (hasRemark) continue;
        const key = `viewgrp:${sessionId}:${target.name}:${pa.name}:${studentName}:maintained`;
        if (maintainedRemarkAutoFillInFlight.has(key)) continue;
        maintainedRemarkAutoFillInFlight.add(key);
        try {
          await addGroupRemark(sessionId, actId, studentName, "Maintain");
          count++;
        } finally { maintainedRemarkAutoFillInFlight.delete(key); }
      }
    }
  }
  return count;
}

// Group View/Edit Past Sessions counterpart of autoFillViewStructuredRemarks.
// Creates one empty placeholder remark per attendee for each auto-open activity
// that was cleaned up on session leave, so they show as clickable buttons
// (view-remark-single-btn) rather than a "create" button requiring two writes.
async function autoFillViewGroupStructuredRemarks(group, sessionId, data) {
  const hasRealData = Object.values(data.remarks || {}).some(r =>
    (r.text && r.text.trim()) || (r.trials || []).some(t => t >= 0) || r.optionScore !== undefined
  );
  const attendees = data.attendees || (group.students || []).filter(Boolean);
  let count = 0;
  for (const target of (group.targets || [])) {
    for (const pa of (target.predefinedActivities || [])) {
      if (!isAutoOpenRemarkType(pa)) continue;
      if (!pa.maintained && !hasRealData) continue;
      const _vgIsNotesOnly = !getActivityInlineOptions(pa) && !pa.optionsMulti && !pa.manualScore;
      if ((pa.maintained && _vgIsNotesOnly) || pa.isMapped) continue;
      const existingAct = Object.entries(data.activities || {})
        .find(([, a]) => a.targetName === target.name &&
          (a.activityName === pa.name || (pa.title && a.activityName === pa.title) || (pa.id && a.configId === pa.id)));
      let actId = existingAct?.[0] || null;
      const _vgMaintAt = pa.maintainedAt || "2026-01-01";
      const _vgOnOrAfterMaint = !data.date || data.date >= _vgMaintAt;
      for (const studentName of attendees) {
        const hasRemark = actId && Object.values(data.remarks || {})
          .some(r => r.activityId === actId && r.studentName === studentName);
        if (hasRemark) {
          if (pa.maintained && _vgOnOrAfterMaint) {
            const studentRems = Object.entries(data.remarks || {}).filter(([, r]) => r.activityId === actId && r.studentName === studentName);
            if (studentRems.length === 1) {
              const [[remId, r]] = studentRems;
              if (!(r.masteryNote || "").replace(/<[^>]*>/g, "").trim())
                updateRemarkNote(sessionId, remId, "Maintain").catch(() => {});
            }
          }
          continue;
        }
        if (pa.maintained && !_vgOnOrAfterMaint) continue;
        const key = `${sessionId}:${target.name}:${pa.id || pa.name}:${studentName}:view`;
        if (structuredRemarkAutoFillInFlight.has(key)) continue;
        structuredRemarkAutoFillInFlight.add(key);
        const _vgMaintNote = pa.maintained && _vgOnOrAfterMaint ? "Maintain" : "";
        try {
          if (!actId) {
            actId = await addActivity(sessionId, target.name, pa.title || pa.name, pa.order ?? 0, true);
            data.activities = data.activities || {};
            data.activities[actId] = { targetName: target.name, activityName: pa.title || pa.name, order: pa.order ?? 0, isPredefined: true };
          }
          const _vgPreRemId = generateId("r");
          await addGroupRemark(sessionId, actId, studentName, "", _vgPreRemId, _vgMaintNote);
          data.remarks = data.remarks || {};
          data.remarks[_vgPreRemId] = { activityId: actId, studentName, text: "", trials: [], order: Date.now(), ...(_vgMaintNote ? { masteryNote: _vgMaintNote } : {}) };
          count++;
        } catch { /* silent */ }
        finally { structuredRemarkAutoFillInFlight.delete(key); }
      }
    }
  }
  return count;
}

// ── View-screen remark editing ───────────────────────────────
// Replaces the old merged-contenteditable-host saver. The View screens'
// remark/mastery-note boxes are real <textarea> elements now (same as the
// already-proven Session Entry screens via setupEntryRemarkSaving) — native
// Enter/backspace/Ctrl+A all just work per-field, with no nested-
// contenteditable quirks to fight, and no buttons-need-2-clicks issue since
// a normal table of buttons next to normal textareas never needs to
// preventDefault its own mousedown.
//
// counterKey (state.viewActionsInFlight / state.viewGroupActionsInFlight) is
// the same in-flight counter the screen's other action buttons already use
// to keep the background snapshot listener from rendering mid-write. Ghost
// boxes need it too: creating an activity/remark for a box that has none
// yet is multi-step (addActivity, then addRemark), and a render landing
// partway through would destroy this exact textarea — including the
// dataset.creating/actId/remId tracking that lives only on it — leaving a
// fresh-looking ghost box behind. If the user was still typing, that looked
// like the typed text vanishing and then reappearing as a duplicate remark
// a moment later, because the next flush had no way to know a remark was
// already being created for it.
function setupViewRemarkSaving(body, getSessionId, counterKey, onIdle, getData) {
  let saveTimer = null;

  function flush() {
    clearTimeout(saveTimer);
    saveTimer = null;
    const sid = getSessionId();
    if (!sid) return Promise.resolve();

    const pending = [];
    const trackWrite = p => { pending.push(Promise.resolve(p)); };

    const diffAndSave = (selector, getValue, doSave) => {
      body.querySelectorAll(selector).forEach(el => {
        const value = getValue(el);
        if (el.dataset.savedHtml === value) return;
        el.dataset.savedHtml = value;
        trackWrite(Promise.resolve(doSave(el, value)).catch(err => {
          // savedHtml already says this is saved — if the write actually
          // failed, leaving it pointing at the unsaved value means nothing
          // ever retries it, and the next render (from anything else on the
          // page) shows the server's older text instead, looking exactly
          // like what was just typed silently vanished.
          if (el.dataset.savedHtml === value) el.dataset.savedHtml = " ";
          alert("Couldn't save remark — check your connection and try again.\n\n" + err.message);
        }));
      });
    };

    diffAndSave(".view-remark-edit[data-rem-id]:not(.view-remark-empty)", el => htmlForStorage(el.value),
      (el, html) => updateRemarkText(sid, el.dataset.remId, html));

    diffAndSave(".view-manual-score-input[data-rem-id]", el => {
      const val = el.value.trim();
      if (val && validateManualScore(val) !== null) return el.dataset.savedHtml;
      return val;
    }, (el, val) => updateRemarkText(sid, el.dataset.remId, val));

    diffAndSave(".view-mastery-note[data-rem-id]", el => htmlForStorage(el.value),
      (el, html) => updateRemarkNote(sid, el.dataset.remId, html));

    body.querySelectorAll(".view-remark-empty").forEach(el => {
      const text = el.value.trim();
      // dataset.remId guards against flush() running a second time for this
      // exact box before a re-render ever replaces its markup — e.g. the
      // 700ms debounce timer firing and THEN focusout firing (or vice versa)
      // both call flush(); without this check, the second call sees
      // dataset.creating already reset to "false" by the first call's
      // completion and the same typed text still sitting in the box, and
      // creates a second, duplicate remark with identical text.
      if (!text || text === "Maintain" || el.dataset.creating === "true" || el.dataset.remId) return;
      el.dataset.creating = "true";
      state[counterKey]++;
      const create = async () => {
        try {
          let actId = el.dataset.actId;
          if (!actId) {
            actId = await addActivity(
              sid, el.dataset.target, el.dataset.actName, Date.now(), el.dataset.isPredefined === "true",
              undefined, el.dataset.parentActivity || null, el.dataset.configId || null
            );
          }
          // Group view's empty boxes are scoped to one attendee (data-student);
          // the individual view's aren't.
          const studentName = el.dataset.student;
          const remId = studentName
            ? await addGroupRemark(sid, actId, studentName, text)
            : await addRemark(sid, actId, text);
          el.dataset.actId     = actId;
          el.dataset.remId     = remId;
          el.dataset.savedHtml = htmlForStorage(text);
          // addRemark resolving doesn't mean state.viewSessionData has the new
          // remark yet — the snapshot listener delivers that a beat later.
          // Without waiting here, a render could land in that gap, see "no
          // remark yet" (since this textarea's local dataset tracking lives
          // only on the DOM, not in state), and redraw this exact box back to
          // its empty starting markup — which is what caused the typed text
          // to "vanish" and then get saved a second time as a duplicate when
          // re-typed into the fresh-looking box.
          await waitForSessionData(() => {
            const d = getData?.();
            return !!d?.activities?.[actId] && !!d?.remarks?.[remId];
          });
        } catch (err) {
          // Leaves remId/savedHtml unset — the next flush (next keystroke or
          // focusout) sees "no remark created yet" and retries from scratch,
          // instead of the typed text just sitting there unsaved forever.
          alert("Couldn't add remark — check your connection and try again.\n\n" + err.message);
        } finally {
          el.dataset.creating = "false";
          state[counterKey]--;
          // viewActionsInFlight just hit 0; if the Firestore snapshot that
          // resolved waitForSessionData came in while the counter was still >0
          // it set viewRenderPending=true but couldn't render — process it now.
          onIdle?.();
        }
      };
      trackWrite(create());
    });

    // Notes textarea typed before any selection button is clicked (empty-state
    // note-only path). Creates a remark with empty text then sets its masteryNote.
    body.querySelectorAll(".view-mastery-note-empty").forEach(el => {
      const noteText = el.value.trim();
      if (!noteText || el.dataset.creating === "true" || el.dataset.remId) return;
      el.dataset.creating = "true";
      state[counterKey]++;
      const create = async () => {
        try {
          let actId = el.dataset.actId;
          if (!actId) {
            actId = await addActivity(
              sid, el.dataset.target, el.dataset.actName, Date.now(), el.dataset.isPredefined === "true",
              undefined, el.dataset.parentActivity || null, el.dataset.configId || null
            );
          }
          const studentName = el.dataset.student;
          const remId = studentName
            ? await addGroupRemark(sid, actId, studentName, "")
            : await addRemark(sid, actId, "");
          await updateRemarkNote(sid, remId, htmlForStorage(noteText));
          el.dataset.actId     = actId;
          el.dataset.remId     = remId;
          el.dataset.savedHtml = htmlForStorage(noteText);
          await waitForSessionData(() => {
            const d = getData?.();
            return !!d?.activities?.[actId] && !!d?.remarks?.[remId];
          });
        } catch (err) {
          alert("Couldn't save note — check your connection and try again.\n\n" + err.message);
        } finally {
          el.dataset.creating = "false";
          state[counterKey]--;
          onIdle?.();
        }
      };
      trackWrite(create());
    });

    return Promise.all(pending);
  }

  const onInput = e => {
    if (e.target.tagName === "TEXTAREA") autoResizeTextarea(e.target);
    clearTimeout(saveTimer);
    saveTimer = setTimeout(() => { flush(); onIdle?.(); }, 700);
  };
  const onFocusOut = () => { flush(); onIdle?.(); };

  body.addEventListener("input", onInput);
  body.addEventListener("focusout", onFocusOut);

  return {
    flush,
    cleanup() {
      clearTimeout(saveTimer);
      body.removeEventListener("input", onInput);
      body.removeEventListener("focusout", onFocusOut);
    }
  };
}

// Same idea as setupViewRemarkSaving, but for the live Session Entry screens
// (#target-content / #group-target-content). The free-text boxes there are
// real <textarea>/<input> elements, not contenteditable — but they're still
// scattered across many activity/remark cards that get torn down and rebuilt
// on every render, so saving is still centralized on the host via debounced
// "input" + "focusout", same as the View screens. flush() returns a Promise
// so callers that are about to read session data to decide what's "empty"
// (switching targets, leaving the session) can await it first instead of
// racing a still-in-flight write.
function setupEntryRemarkSaving(host, getSessionId, onIdle) {
  let saveTimer = null;

  function flush() {
    clearTimeout(saveTimer);
    saveTimer = null;
    const sid = getSessionId();
    if (!sid) return Promise.resolve();

    const pending = [];
    const trackWrite = promiseLike => { pending.push(Promise.resolve(promiseLike)); };

    const diffAndSave = (selector, getValue, doSave) => {
      host.querySelectorAll(selector).forEach(el => {
        const value = getValue(el);
        if (el.dataset.savedHtml === value) return;
        el.dataset.savedHtml = value;
        trackWrite(doSave(el, value));
      });
    };

    diffAndSave(".remark-text-input[data-rem-id]", el => {
      // Block saving manual score inputs whose current value is invalid
      if (el.dataset.manualScore === '1' && el.value.trim() && validateManualScore(el.value.trim()) !== null)
        return el.dataset.savedHtml;
      return htmlForStorage(el.value);
    }, (el, html) => updateRemarkText(sid, el.dataset.remId, html));

    diffAndSave(".mastery-note-input[data-rem-id]", el => htmlForStorage(el.value),
      (el, html) => {
        const remId = el.dataset.remId;
        [state.sessionData, state.groupSessionData].forEach(d => {
          if (d?.remarks?.[remId]) d.remarks[remId].masteryNote = html;
        });
        return updateRemarkNote(sid, remId, html);
      });

    diffAndSave(".activity-name-input[data-act-id]", el => el.value.trim(),
      (el, name) => {
        if (!name) return; // don't persist an emptied-out name; blur reverts the box visually
        el.dataset.original = name;
        return updateActivityName(sid, el.dataset.actId, name);
      });

    diffAndSave(".activity-title-input[data-act-id]", el => el.value.trim(),
      (el, title) => {
        const actId = el.dataset.actId;
        const boldCb = host.querySelector(`.activity-bold-cb[data-act-id="${actId}"]`);
        const underlineCb = host.querySelector(`.activity-underline-cb[data-act-id="${actId}"]`);
        if (state.sessionData?.activities?.[actId]) {
          state.sessionData.activities[actId].activityTitle = title;
        }
        return updateActivityTitle(sid, actId, title, boldCb?.checked ?? false, underlineCb?.checked ?? false);
      });

    diffAndSave(".predef-remark-input-live[data-rem-id]", el => el.value.trim(),
      (el, text) => {
        el.dataset.original = text;
        return updateRemarkText(sid, el.dataset.remId, text);
      });

    diffAndSave(".group-remark-input[data-rem-id]:not(.group-remark-input-empty)", el => htmlForStorage(el.value),
      (el, html) => updateRemarkText(sid, el.dataset.remId, html));

    // Ghost predefined-remark inputs don't have a remark (or sometimes even an
    // activity) yet, so they need to be created first — guarded against
    // double-creation if flush() runs again before the first creation lands.
    host.querySelectorAll(".predef-remark-input[data-pa-name]").forEach(el => {
      const text = el.value.trim();
      if (!text || el.dataset.creating === "true") return;
      el.dataset.creating = "true";
      const create = async () => {
        try {
          const paOrder = el.dataset.paOrder !== "" ? Number(el.dataset.paOrder) : 0;
          const actId = await ensureFedcActivity(el.dataset.target, el.dataset.paName, paOrder);
          const remId = await ensurePredefinedRemark(actId, el.dataset.remName, text);
          await updateRemarkText(sid, remId, text);
        } finally {
          el.dataset.creating = "false";
        }
      };
      trackWrite(create());
    });

    // Free-text empty box for a pending group attendee (see
    // renderGroupStudentEmptyRow) — same "don't write anything until there's
    // real text" guard as above, plus a remId/creating check so a debounce
    // timer firing right after focusout (or vice versa) can't create a
    // second, duplicate remark from the same typed text.
    // Individual maintained placeholder — only save if user actually changed the text.
    // Autofill handles writing the default "Maintain" to Firestore; racing it here
    // caused duplicate remarks (v1253 bug). Same in-flight key as autoFillMaintainedRemarks.
    host.querySelectorAll(".maintained-remark-pending[data-pa-name]").forEach(el => {
      const text = el.value.trim();
      if (!text || text === "Maintain" || el.dataset.creating === "true" || el.dataset.remId) return;
      const key = `${sid}:${el.dataset.target}:${el.dataset.paName}:maintained`;
      if (maintainedRemarkAutoFillInFlight.has(key)) return;
      maintainedRemarkAutoFillInFlight.add(key);
      el.dataset.creating = "true";
      const create = async () => {
        try {
          const paOrder = el.dataset.paOrder !== "" ? Number(el.dataset.paOrder) : 0;
          let actId = el.dataset.actId || null;
          if (!actId) {
            actId = await addActivity(sid, el.dataset.target, el.dataset.paName, paOrder, true,
              undefined, null, el.dataset.cfgId || null);
          }
          const remId = await addRemark(sid, actId, text);
          el.dataset.actId = actId;
          el.dataset.remId = remId;
          el.dataset.savedHtml = htmlForStorage(text);
        } finally {
          el.dataset.creating = "false";
          maintainedRemarkAutoFillInFlight.delete(key);
        }
      };
      trackWrite(create());
    });

    host.querySelectorAll(".group-remark-input-empty[data-student]").forEach(el => {
      const text = el.value.trim();
      if (!text || el.dataset.creating === "true" || el.dataset.remId) return;
      // Maintained placeholder — autofill writes "Maintain" to Firestore, don't race it.
      if (text === "Maintain" && el.dataset.isMaintained === "true") return;
      el.dataset.creating = "true";
      const create = async () => {
        try {
          let actId = el.dataset.actId;
          if (!actId) {
            actId = await addActivity(
              sid, el.dataset.target, el.dataset.actName, Date.now(), el.dataset.isPredefined === "true",
              undefined, el.dataset.parentActivity || null, el.dataset.configId || null
            );
          }
          const remId = await addGroupRemark(sid, actId, el.dataset.student, text);
          el.dataset.actId = actId;
          el.dataset.remId = remId;
          el.dataset.savedHtml = htmlForStorage(text);
        } finally {
          el.dataset.creating = "false";
        }
      };
      trackWrite(create());
    });

    return Promise.all(pending);
  }

  // onIdle re-checks state.renderPending after a save settles, in case a
  // render was deferred for a reason unrelated to typing (dropdown open,
  // active text selection) and is now safe to run.
  const onInput = e => {
    if (e.target.tagName === "TEXTAREA") autoResizeTextarea(e.target);
    clearTimeout(saveTimer);
    // Defer onIdle one tick so document.activeElement has settled to the
    // newly-focused element before the callback checks it.
    saveTimer = setTimeout(() => { flush(); setTimeout(() => onIdle?.(), 0); }, 700);
  };
  // Same deferral for focusout: the browser moves activeElement from the
  // blurring element to the focusing one *after* focusout fires, so calling
  // onIdle synchronously here would see the wrong activeElement and could
  // fire renderTargetContent() while the target dropdown is opening.
  const onFocusOut = () => { flush(); setTimeout(() => onIdle?.(), 0); };

  host.addEventListener("input", onInput);
  host.addEventListener("focusout", onFocusOut);

  return {
    flush,
    cleanup() {
      clearTimeout(saveTimer);
      host.removeEventListener("input", onInput);
      host.removeEventListener("focusout", onFocusOut);
    }
  };
}

// Every previous fix for the caret-disappearing/text-flickering bug tried to
// predict and defer renders that land mid-edit (focus grace windows, write
// cooldowns, etc.) — all still left a timing race on a slow enough
// connection. This closes the gap a different way: instead of trying to
// avoid re-rendering while the user is mid-keystroke, make the re-render
// itself non-destructive. Before a render replaces #target-content's whole
// innerHTML, capture whichever box currently has focus (its identity,
// current — possibly unsaved — value, and caret/selection). After the
// render, if a box with that same identity exists in the fresh markup,
// restore the captured value and re-focus it at the same selection — so a
// render landing at the worst possible moment no longer matters. Real
// <textarea>/<input> elements expose selectionStart/selectionEnd directly,
// so this no longer needs any manual Range/offset math.
const EDITABLE_BOX_SELECTOR =
  ".remark-text-input, .mastery-note-input, .activity-name-input, .pending-activity-name-input, .predef-remark-input-live, .group-remark-input, " +
  ".view-remark-edit, .view-mastery-note, .view-act-edit, .view-starter-input";

function captureActiveEditState(host) {
  const el = document.activeElement;
  if (!el || !host.contains(el)) return null;
  if (el.tagName !== "TEXTAREA" && el.tagName !== "INPUT") return null;
  if (!el.matches(EDITABLE_BOX_SELECTOR)) return null;
  const idAttr = el.dataset.remId ? "remId" : el.dataset.actId ? "actId" : el.dataset.remIds ? "remIds" : null;
  if (idAttr) {
    return {
      className: el.className,
      idAttr,
      idValue: el.dataset[idAttr],
      value: el.value,
      selectionStart: el.selectionStart,
      selectionEnd: el.selectionEnd
    };
  }
  // No ID attrs yet (view-remark-empty for a predefined activity that has never had
  // a Firestore activity record). Match by target+actName so a snapshot-triggered
  // re-render (e.g. from an auto-fill for a different activity) can still restore focus.
  if (el.classList.contains("view-remark-empty") && el.dataset.actName) {
    return {
      className: el.className,
      compositeKey: `${el.dataset.target}::${el.dataset.actName}`,
      value: el.value,
      selectionStart: el.selectionStart,
      selectionEnd: el.selectionEnd
    };
  }
  return null;
}

function restoreActiveEditState(host, captured) {
  if (!captured) return;
  let el;
  if (captured.compositeKey) {
    // No-ID case: find the matching empty textarea by target+actName.
    el = [...host.querySelectorAll(".view-remark-empty")]
      .find(e => `${e.dataset.target}::${e.dataset.actName}` === captured.compositeKey);
  } else {
    // Normal case: try the exact class first (fastest, works when class didn't change).
    el = [...host.querySelectorAll(`.${captured.className.split(" ").join(".")}`)]
      .find(e => e.dataset[captured.idAttr] === captured.idValue);
    // Fallback: class may have changed, e.g. view-remark-empty → view-remark-edit
    // when flush() created the remark and the re-render shows it as non-empty.
    // Search all editable boxes by the ID attribute alone.
    if (!el) {
      el = [...host.querySelectorAll(EDITABLE_BOX_SELECTOR)]
        .find(e => captured.idAttr && e.dataset[captured.idAttr] === captured.idValue);
    }
  }
  if (!el) return;
  el.value = captured.value;
  if (el.tagName === "TEXTAREA") autoResizeTextarea(el);
  el.focus();
  el.setSelectionRange(captured.selectionStart, captured.selectionEnd);
}

// Delegated Escape/Ctrl+Enter handling for the individual session-entry
// screen's free-text fields. These are real <textarea>/<input> elements now
// (not contenteditable), so native Enter, backspace and Ctrl+A already work
// correctly per-field without any help — this only needs to cover the app's
// own confirm/cancel shortcuts. MUST be set up once per session-open (not
// per-render) — host is a persistent container whose children get replaced
// on every render, but the host itself never does, so re-attaching this on
// every render would stack up duplicate listeners.
function setupEntryEnterKeyDelegation(host, getTarget) {
  const onKeydown = e => {
    if (e.key !== "Enter" && e.key !== "Escape") return;
    const el = e.target.closest?.(
      ".activity-name-input, #new-activity-textarea, #new-remark-textarea, .predef-remark-input-live"
    );
    if (!el || !host.contains(el)) return;

    if (e.key === "Escape") {
      if (el.id === "new-activity-textarea") cancelPendingActivity();
      return;
    }
    const target = getTarget();
    if (el.matches(".activity-name-input")) {
      if (e.ctrlKey || e.metaKey) { e.preventDefault(); el.blur(); }
      return;
    }
    if (el.id === "new-activity-textarea") {
      if (e.ctrlKey || e.metaKey) { e.preventDefault(); confirmNewActivity(target); }
      return;
    }
    if (el.id === "new-remark-textarea") {
      if (e.ctrlKey || e.metaKey) { e.preventDefault(); saveNewRemark(target); }
      return;
    }
    if (el.matches(".predef-remark-input-live")) {
      e.preventDefault();
      el.blur();
    }
  };
  host.addEventListener("keydown", onKeydown);
  return () => host.removeEventListener("keydown", onKeydown);
}

function getViewMaxPtsForRemark(remId) {
  const data = state.viewSessionData;
  const rem  = data?.remarks?.[remId];
  const act  = rem && data.activities?.[rem.activityId];
  const target = act && getViewEffectiveTargets().find(t => t.name === act.targetName);
  return target?.maxPoints || 3;
}

// Patches just one remark's trial cells/running total/score in place instead
// of going through a full renderSessionView() — a render is safe to do at
// any time now (see isViewBusy/captureActiveEditState), but updating just
// this one row's own cells is still faster and avoids momentarily rebuilding
// anything else on the page for what's normally a quick, repeated action.
// Updating just this row's own cells sidesteps that defer system entirely:
// there's nothing else on the page this could disturb, so it's always safe
// to do immediately, no busy-check needed.
function refreshViewTrialRow(remId) {
  const rem = state.viewSessionData?.remarks?.[remId];
  if (!rem) return;
  const body = $("session-view-body");
  const tr   = body.querySelector(`.view-rem-del[data-rem-id="${remId}"]`)?.closest("tr");
  if (!tr) return;
  const maxPts = getViewMaxPtsForRemark(remId);
  const { validTrials, total, scorePct } = calcViewTrialSummary(rem.trials, maxPts, rem.optionScore);
  const trialCellsDiv = tr.querySelector(".trial-cells");
  if (trialCellsDiv) {
    trialCellsDiv.innerHTML = buildTrialCellsHtml(rem, maxPts);
    bindViewTrialCellListeners(trialCellsDiv);
  }
  const totalTd = tr.querySelector(".vcol-total");
  if (totalTd) totalTd.innerHTML = validTrials.length > 0 ? String(total) : "&nbsp;";
  const scoreSpan = tr.querySelector(".vcol-score span");
  if (scoreSpan) scoreSpan.textContent = scorePct;
}

// Each trial click fires its own independent Firestore write rather than
// awaiting the previous one (so clicking + repeatedly stays instant) — but
// openSessionView's snapshot listener overwrites state.viewSessionData and
// can trigger a full renderSessionView() the moment it's not "busy",
// regardless of whether every one of those writes has actually landed yet.
// If a render lands using a snapshot that only reflects some of several
// rapid-fire writes, it shows a stale (lower) trial count until the next
// snapshot catches up — visible as cells appearing then disappearing.
// Tracking each write against the same viewActionsInFlight counter the
// snapshot listener already checks defers that render until every write
// here has actually settled, instead of mid-flight.
function trackViewTrialWrite(promise) {
  state.viewActionsInFlight++;
  promise.finally(() => {
    state.viewActionsInFlight--;
    if (state.viewActionsInFlight === 0 && state.viewRenderPending && !isViewBusy()) {
      state.viewRenderPending = false;
      renderSessionView();
    }
  });
}

function bindViewTrialCellListeners(container) {
  container.querySelectorAll(".view-trial-select").forEach(sel => {
    sel.addEventListener("change", () => {
      const rem = state.viewSessionData?.remarks?.[sel.dataset.remId];
      if (!rem) return;
      const prevTrials = rem.trials || [];
      const trials = [...prevTrials];
      trials[Number(sel.dataset.trialIdx)] = Number(sel.value);
      rem.trials = trials;
      refreshViewTrialRow(sel.dataset.remId);
      trackViewTrialWrite(setTrials(state.viewSessionId, sel.dataset.remId, trials).catch(err => {
        rem.trials = prevTrials;
        refreshViewTrialRow(sel.dataset.remId);
        alert("Couldn't update — check your connection and try again.\n\n" + err.message);
      }));
    });
  });

  container.querySelectorAll(".view-trial-del").forEach(btn => {
    btn.addEventListener("click", () => {
      const rem = state.viewSessionData?.remarks?.[btn.dataset.remId];
      if (!rem) return;
      const prevTrials = rem.trials || [];
      const trials = prevTrials.filter((_, i) => i !== Number(btn.dataset.trialIdx));
      rem.trials = trials;
      refreshViewTrialRow(btn.dataset.remId);
      trackViewTrialWrite(setTrials(state.viewSessionId, btn.dataset.remId, trials).catch(err => {
        rem.trials = prevTrials;
        refreshViewTrialRow(btn.dataset.remId);
        alert("Couldn't update — check your connection and try again.\n\n" + err.message);
      }));
    });
  });

  // .view-add-trial is handled by the delegated click handler on
  // session-view-body set up once in openSessionView.
}

function showViewAddRemarkPicker(targetName) {
  const data = state.viewSessionData;
  const target = getViewEffectiveTargets().find(t => t.name === targetName);
  const dateStr = data?.date;

  const choices = [];
  if (target?.predefinedActivities?.length > 0) {
    let no = 0;
    const matchedIds = new Set();
    for (const pa of target.predefinedActivities) {
      if (!isActivityActive(pa, dateStr)) continue;
      if (pa.isHeading || pa.isMaintainHeading || pa.isNote || pa.isExportNote ||
          pa.isMaintain || pa.isCompleted || pa.isArchived || pa.isStopped) continue;
      no++;
      const entry = Object.entries(data?.activities || {})
        .find(([, a]) => a.targetName === targetName && (a.activityName === pa.name || (pa.title && a.activityName === pa.title)));
      if (entry && viewGetRemarks(data, entry[0]).length > 0) {
        matchedIds.add(entry[0]);
        choices.push({ actId: entry[0], name: pa.name, no });
      }
    }
    Object.entries(data?.activities || {})
      .filter(([actId, a]) => a.targetName === targetName && viewGetRemarks(data, actId).length > 0 && !matchedIds.has(actId))
      .sort(([, a], [, b]) => (a.order || 0) - (b.order || 0))
      .forEach(([actId, a]) => { no++; choices.push({ actId, name: a.activityName, no }); });
  } else {
    Object.entries(data?.activities || {})
      .filter(([actId, a]) => a.targetName === targetName && viewGetRemarks(data, actId).length > 0)
      .sort(([, a], [, b]) => (a.order || 0) - (b.order || 0))
      .forEach(([actId, a], i) => choices.push({ actId, name: a.activityName, no: i + 1 }));
  }

  $("session-picker-title").textContent = "Add Remark & Trials to which Activity?";
  $("session-picker-list").innerHTML = choices.length
    ? `<div class="choice-list">` + choices.map(c => `
        <button class="choice-btn view-add-remark-choice" data-act-id="${escHtml(c.actId)}">
          <div class="choice-text"><div class="choice-label">${escHtml(c.no + ". " + c.name)}</div></div>
        </button>`).join("") + `</div>`
    : `<p class="empty-hint">No activities with a remark yet — use the + under an activity's Trials column to start one.</p>`;
  $("session-picker-modal").classList.remove("hidden");

  $("session-picker-list").querySelectorAll(".view-add-remark-choice").forEach(btn => {
    btn.addEventListener("click", () => {
      const actId = btn.dataset.actId;
      closeSessionPicker();
      const remId = generateId("r");
      state.viewSessionData.remarks = state.viewSessionData.remarks || {};
      state.viewSessionData.remarks[remId] = { activityId: actId, text: "", trials: [], order: Date.now() };
      renderViewOrDefer("viewRenderPending", isViewBusy, renderSessionView);
      addRemark(state.viewSessionId, actId, "", null, remId).catch(err => {
        delete state.viewSessionData.remarks[remId];
        renderViewOrDefer("viewRenderPending", isViewBusy, renderSessionView);
        alert("Couldn't add remark — check your connection and try again.\n\n" + err.message);
      });
    });
  });
}

function showGroupViewAddRemarkPicker(targetName) {
  const data = state.viewGroupSessionData;
  const target = getViewGroupEffectiveTargets().find(t => t.name === targetName);
  const dateStr = data?.date;
  const attendees = data?.attendees || (state.viewGroup?.students || []).filter(Boolean);

  const choices = [];
  if (target?.predefinedActivities?.length > 0) {
    let no = 0;
    const matchedIds = new Set();
    for (const pa of target.predefinedActivities) {
      if (!isActivityActive(pa, dateStr)) continue;
      if (pa.isHeading || pa.isMaintainHeading || pa.isNote || pa.isExportNote ||
          pa.isMaintain || pa.isCompleted || pa.isArchived || pa.isStopped) continue;
      no++;
      const entry = Object.entries(data?.activities || {})
        .find(([, a]) => a.targetName === targetName && (a.activityName === pa.name || (pa.title && a.activityName === pa.title)));
      const rounds = entry ? viewGroupGetRounds(data, entry[0], attendees) : [];
      if (entry && rounds.length > 0) {
        matchedIds.add(entry[0]);
        choices.push({ actId: entry[0], name: pa.name, no });
      }
    }
    Object.entries(data?.activities || {})
      .filter(([actId, a]) => a.targetName === targetName && !matchedIds.has(actId) && viewGroupGetRounds(data, actId, attendees).length > 0)
      .sort(([, a], [, b]) => (a.order || 0) - (b.order || 0))
      .forEach(([actId, a]) => { no++; choices.push({ actId, name: a.activityName, no }); });
  } else {
    Object.entries(data?.activities || {})
      .filter(([actId, a]) => a.targetName === targetName && viewGroupGetRounds(data, actId, attendees).length > 0)
      .sort(([, a], [, b]) => (a.order || 0) - (b.order || 0))
      .forEach(([actId, a], i) => choices.push({ actId, name: a.activityName, no: i + 1 }));
  }

  $("session-picker-title").textContent = "Add Remark & Trials to which Activity?";
  $("session-picker-list").innerHTML = choices.length
    ? `<div class="choice-list">` + choices.map(c => `
        <button class="choice-btn grp-view-add-remark-choice" data-act-id="${escHtml(c.actId)}">
          <div class="choice-text"><div class="choice-label">${escHtml(c.no + ". " + c.name)}</div></div>
        </button>`).join("") + `</div>`
    : `<p class="empty-hint">No activities with a remark yet — use the textarea or + button on an activity row to start one.</p>`;
  $("session-picker-modal").classList.remove("hidden");

  $("session-picker-list").querySelectorAll(".grp-view-add-remark-choice").forEach(btn => {
    btn.addEventListener("click", () => {
      const actId = btn.dataset.actId;
      closeSessionPicker();
      const d = state.viewGroupSessionData;
      d.remarks = d.remarks || {};
      const order = Date.now();
      const remIds = attendees.map(() => generateId("r"));
      attendees.forEach((studentName, i) => {
        d.remarks[remIds[i]] = { activityId: actId, studentName, text: "", trials: [], order: order + i };
      });
      renderViewOrDefer("viewGroupRenderPending", isGroupViewBusy, renderGroupSessionView);
      addGroupRemarksBatch(state.viewGroupSessionId, attendees.map(studentName => ({ actId, studentName })), remIds)
        .catch(err => {
          remIds.forEach(id => delete d.remarks[id]);
          renderViewOrDefer("viewGroupRenderPending", isGroupViewBusy, renderGroupSessionView);
          alert("Couldn't add remark — check your connection and try again.\n\n" + err.message);
        });
    });
  });
}

function attachViewListeners() {
  const body = $("session-view-body");

  body.querySelectorAll("textarea.view-remark-edit, textarea.view-mastery-note").forEach(autoResizeTextarea);

  // ── Manual score input: sanitise, live hint update, blur validation ───
  body.querySelectorAll(".view-manual-score-input").forEach(input => {
    const msSanitize = raw => {
      let s = raw.replace(/[^0-9./%]/g, "");
      const pctIdx = s.indexOf("%"); if (pctIdx !== -1) s = s.slice(0, pctIdx + 1);
      const slashIdx = s.indexOf("/");
      if (slashIdx !== -1) s = s.slice(0, slashIdx + 1) + s.slice(slashIdx + 1).replace(/\//g, "");
      return s.replace(/\.{2,}/g, ".");
    };
    const getHint = () => body.querySelector(`.view-manual-score-hint[data-rem-id="${input.dataset.remId}"]`);
    const getPct  = () => input.closest("tr")?.querySelector(".view-manual-score-pct");
    input.addEventListener("input", () => {
      const san = msSanitize(input.value);
      if (input.value !== san) {
        const pos = input.selectionStart - (input.value.length - san.length);
        input.value = san;
        input.setSelectionRange(Math.max(0, pos), Math.max(0, pos));
      }
      const parsed = parseManualScore(san.trim());
      const pct = parsed !== null ? Math.round(parsed * 10) / 10 : null;
      const hint = getHint();
      if (hint) { if (pct !== null) { hint.textContent = `= ${pct}%`; hint.style.display = ""; } else { hint.textContent = ""; hint.style.display = "none"; } }
      const pctEl = getPct(); if (pctEl) pctEl.textContent = pct !== null ? pct + "%" : "";
    });
    let _alerting = false;
    input.addEventListener("blur", () => {
      if (_alerting) return;
      const err = validateManualScore(input.value.trim());
      if (!err) return;
      _alerting = true; alert(err); _alerting = false;
      setTimeout(() => input.focus(), 0);
    });
  });

  bindViewTrialCellListeners(body);

  // .view-add-remark-target, .view-add-trial-new, and .view-add-trial are
  // handled by the delegated click handler on session-view-body set up once
  // in openSessionView — not here — so they survive renderSessionView() calls.

  // ── Sketch board buttons (view screen) ────────────────────
  body.querySelectorAll(".btn-sketch[data-rem-id]").forEach(btn => {
    btn.addEventListener("click", () => {
      const id = btn.dataset.remId;
      const field = body.querySelector(`.view-remark-edit[data-rem-id="${id}"]`)
                 || body.querySelector(`.view-mastery-note[data-rem-id="${id}"]`);
      if (field) openTextEditorSheet(field);
    });
  });

  // Saving for .view-remark-edit / .view-remark-empty / .view-mastery-note is
  // handled by the shared host saver (state.viewRemarkSaver) set up once in
  // openSessionView, not here — this function runs on every render, and the
  // body persists across renders, so attaching per-box listeners here would
  // stack up duplicates.

  // These three handlers update state.viewSessionData synchronously (not
  // just the DOM/Firestore) before awaiting the write — leaveSessionView()
  // reads state.viewSessionData straight off a captured snapshot on the way
  // out with no guard for an in-flight write, so without this, leaving the
  // screen right after a click could see the OLD value and let
  // cleanupEmptyEntries() delete a remark the boss just set.
  body.querySelectorAll(".view-remark-single-btn").forEach(btn => {
    btn.addEventListener("click", withViewAction("viewActionsInFlight", "viewRenderPending", isViewBusy, renderSessionView, async () => {
      const isActive = btn.classList.contains("active");
      btn.closest(".view-remark-multi-opts")?.querySelectorAll(".view-remark-single-btn").forEach(b => b.classList.remove("active"));
      const newText = isActive ? "" : btn.dataset.opt;
      if (!isActive) btn.classList.add("active");
      const rem = state.viewSessionData?.remarks?.[btn.dataset.remId];
      const prevText = rem?.text;
      const prevOptScore = rem?.optionScore;
      if (rem) rem.text = newText;
      // Mirror the live session: update optionScore so Total/% score updates immediately.
      const scoreVal = btn.dataset.score !== "" ? Number(btn.dataset.score) : NaN;
      if (!isNaN(scoreVal) && !isActive) {
        if (rem) rem.optionScore = scoreVal;
      } else {
        if (rem) delete rem.optionScore;
      }
      try {
        await updateRemarkText(state.viewSessionId, btn.dataset.remId, newText);
        if (!isNaN(scoreVal) && !isActive) {
          await setOptionScore(state.viewSessionId, btn.dataset.remId, scoreVal);
        } else if (prevOptScore !== undefined) {
          await clearOptionScore(state.viewSessionId, btn.dataset.remId);
        }
      } catch (err) {
        if (rem) { rem.text = prevText; if (prevOptScore !== undefined) rem.optionScore = prevOptScore; else delete rem.optionScore; }
        alert("Couldn't save — check your connection and try again.\n\n" + err.message);
      }
    }));
  });

  body.querySelectorAll(".view-remark-multi-btn").forEach(btn => {
    btn.addEventListener("click", withViewAction("viewActionsInFlight", "viewRenderPending", isViewBusy, renderSessionView, async () => {
      btn.classList.toggle("active");
      const container = btn.closest(".view-remark-multi-opts");
      const selected = [...container.querySelectorAll(".view-remark-multi-btn.active")].map(b => b.dataset.opt);
      const newText = selected.join(", ");
      const rem = state.viewSessionData?.remarks?.[btn.dataset.remId];
      const prevText = rem?.text;
      if (rem) rem.text = newText;
      try {
        await updateRemarkText(state.viewSessionId, btn.dataset.remId, newText);
      } catch (err) {
        if (rem) rem.text = prevText;
        alert("Couldn't save — check your connection and try again.\n\n" + err.message);
      }
    }));
  });

  body.querySelectorAll(".view-starter-input").forEach(input => {
    input.addEventListener("blur", async () => {
      const rem = state.viewSessionData?.remarks?.[input.dataset.remId];
      if (!rem || input.value === (rem.text || "")) return;
      const prevText = rem.text;
      rem.text = input.value;
      try {
        await updateRemarkText(state.viewSessionId, input.dataset.remId, input.value);
      } catch (err) {
        rem.text = prevText;
        alert("Couldn't save — check your connection and try again.\n\n" + err.message);
      }
    });
  });

  body.querySelectorAll(".view-remark-new").forEach(ta => {
    ta.addEventListener("blur", async () => {
      const text = ta.value.trim();
      if (!text) return;
      let actId = ta.dataset.actId;
      if (!actId) actId = await addActivity(state.viewSessionId, ta.dataset.targetName, ta.dataset.actName, Date.now(), true);
      await addRemark(state.viewSessionId, actId, text, null);
    });
  });

  // "+ Add Remark" for preset-option/sentence-starter activities with
  // no remark yet — these don't get the typeable empty box (there's no free
  // text to click into), so without this the Remark cell is just blank with
  // no way to create the first remark at all.
  // Writes to local state and renders immediately (optimistic) instead of
  // awaiting both Firestore round trips first — addActivity/addRemark are
  // handed the same ids used locally so the writes settle into the exact
  // same keys once the snapshot listener catches up, with no mismatch.
  body.querySelectorAll(".view-add-remark-row").forEach(btn => {
    btn.addEventListener("click", () => {
      if (btn.disabled) return;
      btn.disabled = true;
      const data       = state.viewSessionData;
      const targetName = btn.dataset.targetName;
      const actName    = btn.dataset.actName;
      const isPredef   = btn.dataset.isPredefined === "true";
      const isNewAct   = !btn.dataset.actId;
      const actId      = btn.dataset.actId || generateId("a");
      const remId      = generateId("r");
      const actOrder   = Date.now();
      data.activities = data.activities || {};
      data.remarks    = data.remarks || {};
      if (isNewAct) {
        data.activities[actId] = { targetName, activityName: actName, order: actOrder, isPredefined: isPredef };
      }
      data.remarks[remId] = { activityId: actId, text: "", trials: [], order: actOrder };
      renderSessionView();
      (async () => {
        try {
          if (isNewAct) await addActivity(state.viewSessionId, targetName, actName, actOrder, isPredef, actId);
          await addRemark(state.viewSessionId, actId, "", null, remId);
        } catch (err) {
          if (isNewAct) delete data.activities[actId];
          delete data.remarks[remId];
          renderSessionView();
          alert("Couldn't add remark — check your connection and try again.\n\n" + err.message);
        }
      })();
    });
  });

  // Inline single-select for preset activities with no remark yet
  body.querySelectorAll(".view-single-create-btn").forEach(btn => {
    btn.addEventListener("click", withViewAction("viewActionsInFlight", "viewRenderPending", isViewBusy, renderSessionView, async () => {
      const data = state.viewSessionData;
      const targetName = btn.dataset.targetName;
      const actName = btn.dataset.actName;
      const isPredef = btn.dataset.isPredefined === "true";
      const isNewAct = !btn.dataset.actId;
      const actId = btn.dataset.actId || generateId("a");
      const remId = generateId("r");
      const order = Date.now();
      const val = btn.dataset.opt;
      const scoreVal = btn.dataset.score !== "" ? Number(btn.dataset.score) : NaN;
      data.activities = data.activities || {};
      data.remarks = data.remarks || {};
      if (isNewAct) data.activities[actId] = { targetName, activityName: actName, order, isPredefined: isPredef };
      const newRem = { activityId: actId, text: val, trials: [], order };
      if (!isNaN(scoreVal)) newRem.optionScore = scoreVal;
      data.remarks[remId] = newRem;
      renderSessionView();
      try {
        if (isNewAct) await addActivity(state.viewSessionId, targetName, actName, order, isPredef, actId);
        await addRemark(state.viewSessionId, actId, val, null, remId);
        if (!isNaN(scoreVal)) await setOptionScore(state.viewSessionId, remId, scoreVal);
      } catch (err) {
        if (isNewAct) delete data.activities[actId];
        delete data.remarks[remId];
        renderSessionView();
        alert("Couldn't add remark — check your connection and try again.\n\n" + err.message);
      }
    }));
  });

  body.querySelectorAll(".view-multi-create-btn").forEach(btn => {
    btn.addEventListener("click", withViewAction("viewActionsInFlight", "viewRenderPending", isViewBusy, renderSessionView, async () => {
      const data = state.viewSessionData;
      const targetName = btn.dataset.targetName;
      const actName = btn.dataset.actName;
      const isPredef = btn.dataset.isPredefined === "true";
      const isMaintained = btn.dataset.maintained === "true";
      const isNewAct = !btn.dataset.actId;
      const actId = btn.dataset.actId || generateId("a");
      const remId = generateId("r");
      const order = Date.now();
      const val = btn.dataset.opt;
      data.activities = data.activities || {};
      data.remarks = data.remarks || {};
      if (isNewAct) data.activities[actId] = { targetName, activityName: actName, order, isPredefined: isPredef };
      data.remarks[remId] = { activityId: actId, text: val, trials: [], order };
      if (isMaintained) data.remarks[remId].masteryNote = "Maintain";
      renderSessionView();
      try {
        if (isNewAct) await addActivity(state.viewSessionId, targetName, actName, order, isPredef, actId);
        await addRemark(state.viewSessionId, actId, val, null, remId, isMaintained ? "Maintain" : "");
      } catch (err) {
        if (isNewAct) delete data.activities[actId];
        delete data.remarks[remId];
        renderSessionView();
        alert("Couldn't add remark — check your connection and try again.\n\n" + err.message);
      }
    }));
  });

  // Auto-expand remark/starter textareas based on content height
  body.querySelectorAll(".view-remark-edit, .view-starter-input").forEach(ta => {
    if (ta.tagName !== "TEXTAREA") return;
    const expand = () => { ta.style.height = "auto"; ta.style.height = ta.scrollHeight + "px"; };
    expand();
    ta.addEventListener("input", expand);
  });

  body.querySelectorAll(".view-act-edit").forEach(input => {
    input.addEventListener("blur", async () => {
      const newName = input.value.trim();
      if (!newName || newName === input.dataset.original) return;
      if (!input.dataset.actId) return;
      input.dataset.original = newName;
      await updateActivityName(state.viewSessionId, input.dataset.actId, newName);
    });
    input.addEventListener("keydown", e => {
      if (e.key === "Enter") { e.preventDefault(); input.blur(); }
    });
  });

  body.querySelectorAll(".view-act-del").forEach(btn => {
    btn.addEventListener("click", withViewAction("viewActionsInFlight", "viewRenderPending", isViewBusy, renderSessionView, async () => {
      if (!confirm("Delete this activity and all its remarks?")) return;
      const actId = btn.dataset.actId;
      if (!actId) return;
      const remIds = viewGetRemarks(state.viewSessionData, actId).map(r => r.id);
      await deleteActivity(state.viewSessionId, actId, remIds);
    }));
  });

  body.querySelectorAll(".view-rem-del").forEach(btn => {
    btn.addEventListener("click", () => {
      if (!confirm("Delete this remark?")) return;
      const remId = btn.dataset.remId;
      const rem = state.viewSessionData?.remarks?.[remId];
      if (!rem) return;
      delete state.viewSessionData.remarks[remId];
      renderViewOrDefer("viewRenderPending", isViewBusy, renderSessionView);
      deleteRemark(state.viewSessionId, remId).catch(err => {
        state.viewSessionData.remarks[remId] = rem;
        renderViewOrDefer("viewRenderPending", isViewBusy, renderSessionView);
        alert("Couldn't delete remark — check your connection and try again.\n\n" + err.message);
      });
    });
  });

  body.querySelectorAll(".view-comment-edit").forEach(ta => {
    ta.addEventListener("blur", async () => {
      const key    = ta.dataset.targetKey;
      const target = getViewEffectiveTargets().find(t => sanitizeKey(t.name) === key);
      if (!target) return;
      const current = (state.viewSessionData?.fedcComments || {})[key] || "";
      if (ta.value === current) return;
      await updateFedcComment(state.viewSessionId, target.name, ta.value);
    });
  });

  // ── Review panel inputs (recreated on each render) ────────────
  const cmtInput = body.querySelector(".review-comment-input");
  if (cmtInput) {
    cmtInput.addEventListener("input", () => { _viewCommentDraft = cmtInput.value; });
    cmtInput.addEventListener("keydown", async e => {
      if (e.key !== "Enter" || !cmtInput.value.trim()) return;
      e.preventDefault();
      const text = cmtInput.value.trim();
      _viewCommentDraft = "";
      try { await addReviewComment(state.viewSessionId, text); } catch (err) { console.error("addReviewComment:", err); }
    });
  }
  const signInput = body.querySelector(".review-sign-input");
  if (signInput) {
    signInput.addEventListener("input", () => { _viewSigningName = signInput.value; });
    signInput.focus();
  }

}

// ============================================================
// GROUP SESSION VIEW (table-based view/edit of a past group session)
// Mirrors the individual screen-session-view above, with an added
// Student column and "Combine/Separate Remarks" support per activity.
// ============================================================

function getViewGroupEffectiveTargets() {
  return state.viewGroup?.targets || [];
}

async function openGroupSessionView(group, sessionId) {
  commitTextEditorSheet();
  state.viewGroup              = group;
  state.viewGroupSessionId     = sessionId;
  state.viewGroupSessionData   = null;
  state.viewGroupRenderPending = false;
  state.viewGroupActionsInFlight = 0;

  showScreen("screen-group-session-view");
  $("group-view-group-name").textContent = group.name;
  $("group-view-session-meta").textContent = "";
  $("group-session-view-body").innerHTML = `<div class="loading">Loading…</div>`;
  _grpChkConfirmRole = null; clearTimeout(_grpChkConfirmTimer);
  _grpReviewPanelOpen = false; _grpCommentDraft = ""; _grpSigningCmtId = null; _grpSigningName = "";
  if (state.viewGroupChkDelegate) $("group-session-view-body").removeEventListener("click", state.viewGroupChkDelegate);
  state.viewGroupChkDelegate = async e => { await handleCheckedByClick(e, true); };
  $("group-session-view-body").addEventListener("click", state.viewGroupChkDelegate);

  if (state.fbViewGroupUnsubscribe) { state.fbViewGroupUnsubscribe(); state.fbViewGroupUnsubscribe = null; }

  state.viewGroupRemarkSaver?.cleanup();
  state.viewGroupRemarkSaver = setupViewRemarkSaving($("group-session-view-body"), () => state.viewGroupSessionId, "viewGroupActionsInFlight", () => {
    if (!state.viewGroupRenderPending || isGroupViewBusy() || state.viewGroupActionsInFlight > 0) return;
    state.viewGroupRenderPending = false;
    renderGroupSessionView();
  }, () => state.viewGroupSessionData);

  try {
    state.fbViewGroupUnsubscribe = listenToSession(sessionId, async data => {
      state.viewGroupSessionData = data;
      try {
        const filled = await autoFillViewGroupMappedRemarks(group, sessionId, data);
        if (filled > 0) return; // the write triggers another snapshot, which renders
      } catch (err) { console.error("autoFillViewGroupMappedRemarks failed:", err); }
      try {
        const maintainedFilled = await autoFillViewGroupMaintainedRemarks(group, sessionId, data);
        if (maintainedFilled > 0) return;
      } catch (err) { console.error("autoFillViewGroupMaintainedRemarks failed:", err); }
      try {
        // Local state updated optimistically inside — fall through to render immediately.
        await autoFillViewGroupStructuredRemarks(group, sessionId, data);
      } catch (err) { console.error("autoFillViewGroupStructuredRemarks failed:", err); }
      if (isGroupViewBusy() || state.viewGroupActionsInFlight > 0) {
        state.viewGroupRenderPending = true;
      } else {
        state.viewGroupRenderPending = true;
        clearTimeout(state.viewGroupSnapshotRenderTimer);
        state.viewGroupSnapshotRenderTimer = setTimeout(() => {
          state.viewGroupSnapshotRenderTimer = null;
          if (state.viewGroupRenderPending && !isGroupViewBusy()) {
            state.viewGroupRenderPending = false;
            renderGroupSessionView();
          }
        }, 250);
      }
    });
  } catch (err) {
    $("group-session-view-body").innerHTML =
      `<div class="error-msg">Could not load session.<br>${escHtml(err.message)}</div>`;
  }
}

async function leaveGroupSessionView() {
  commitTextEditorSheet();
  $("text-editor-sheet").classList.add("hidden");
  $("btn-group-delete-session")?.classList.add("hidden");
  $("btn-group-goto-session")?.classList.add("hidden");
  _grpChkConfirmRole = null; clearTimeout(_grpChkConfirmTimer);
  _grpReviewPanelOpen = false; _grpCommentDraft = ""; _grpSigningCmtId = null; _grpSigningName = "";
  if (state.viewGroupChkDelegate) { $("group-session-view-body")?.removeEventListener("click", state.viewGroupChkDelegate); state.viewGroupChkDelegate = null; }
  // See the matching comment in leaveSessionView() — flush (and await it)
  // before unsubscribing, not after, so the listener is still alive to
  // reflect the flushed write into state.viewGroupSessionData before the
  // cleanup below reads it.
  await state.viewGroupRemarkSaver?.flush();
  if (state.fbViewGroupUnsubscribe) { state.fbViewGroupUnsubscribe(); state.fbViewGroupUnsubscribe = null; }
  state.viewGroupRemarkSaver?.cleanup();
  state.viewGroupRemarkSaver = null;
  const sessionId = state.viewGroupSessionId;
  const data      = state.viewGroupSessionData;
  const group     = state.viewGroup;
  state.viewGroupSessionId     = null;
  state.viewGroupSessionData   = null;
  state.viewGroup               = null;
  state.viewGroupRenderPending = false;
  state.viewGroupActionsInFlight = 0;

  if (sessionId && data) {
    const stripEmpty = s => (s || "").replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").replace(/ /g, " ").trim();
    const currentTargetNames = new Set((group?.targets || []).map(t => t.name));
    const fedcHasData = Object.values(data.fedcComments || {}).some(c => stripEmpty(c).length > 0);
    const remarkHasData = Object.values(data.remarks || {}).some(r => {
      const act = (data.activities || {})[r.activityId];
      if (!act) return false;
      // Count data under ANY targetName — renamed targets' old-name data is still real.
      return stripEmpty(r.text).length > 0
        || (r.trials || []).some(t => t !== null && t !== -1)
        || stripEmpty(r.masteryNote).length > 0;
    });
    if (!fedcHasData && !remarkHasData) {
      deleteSession(sessionId).catch(() => {});
    } else {
      const allTargetNames = new Set(Object.values(data.activities || {}).map(a => a.targetName));
      allTargetNames.forEach(name => {
        const target = (group?.targets || []).find(t => t.name === name);
        cleanupEmptyEntries(sessionId, data, name, target, true).catch(() => {});
      });
    }
  }

  closeStickyNote();
  showHome();
}

$("btn-group-view-back").addEventListener("click", leaveGroupSessionView);

function renderGroupSessionView() {
  const data  = state.viewGroupSessionData;
  const group = state.viewGroup;
  if (!data || !group) return;

  $("group-view-session-meta").innerHTML =
    `${formatDateWithDay(data.date)}${relativeDaySuffix(data.date)}`
    + ` <button class="btn-edit-session-date">Edit Date</button>`;

  const delBtn = $("btn-group-delete-session");
  if (delBtn) delBtn.classList.remove("hidden");

  $("group-view-session-meta").querySelector(".btn-edit-session-date").addEventListener("click", () => {
    showEditGroupDatePicker();
  });

  const gotoBtn = $("btn-group-goto-session");
  if (gotoBtn) {
    gotoBtn.classList.remove("hidden");
    gotoBtn.onclick = () => showGoToAnotherGroupSession(state.viewGroup);
  }

  // Wire delete button (static element in header — re-attach each time)
  const _delBtn = $("btn-group-delete-session");
  if (_delBtn) {
    const newDelBtn = _delBtn.cloneNode(true); // remove old listeners
    newDelBtn.classList.remove("hidden");
    _delBtn.replaceWith(newDelBtn);
    newDelBtn.addEventListener("click", async () => {
      const typed = prompt(`Delete Session ${data.sessionNumber} of ${data.month.split(" ")[0]} (${formatDate(data.date)})?\n\nThis cannot be undone. Type DELETE to confirm:`);
      if (typed !== "DELETE") return;
      const sid = state.viewGroupSessionId;
      leaveGroupSessionView();
      await deleteSession(sid).catch(() => {});
    });
  }

  const attendees = data.attendees || (group.students || []).filter(Boolean);
  const targets   = getViewGroupEffectiveTargets();
  const sorted    = sortTargetsByOrder(targets);

  const body = $("group-session-view-body");
  const scrollTop = body.scrollTop;
  const captured = captureActiveEditState(body);
  const grpStripHtml = renderCheckedByStripHtml(data, _grpChkConfirmRole, true);
  body.innerHTML = grpStripHtml + (sorted.length
    ? sorted.map(t => buildGroupTargetViewTable(t, data, attendees)).join("")
    : `<p style="color:var(--text-muted);padding:1rem">No targets recorded.</p>`);

  attachGroupViewListeners();
  restoreActiveEditState(body, captured);
  body.scrollTop = scrollTop;
}

// Pairs each attending student's remarks for one activity into "rounds" by creation order,
// with a { studentName, pending: true } placeholder for any attendee with no entry yet in that round.
function viewGroupGetRounds(data, actId, attendees) {
  const byStudent = {};
  for (const studentName of attendees) {
    byStudent[studentName] = Object.entries(data.remarks || {})
      .filter(([, r]) => r.activityId === actId && r.studentName === studentName)
      .sort(([, a], [, b]) => (a.order || 0) - (b.order || 0))
      .map(([id, r]) => ({ id, ...r }));
  }
  const maxRounds = Math.max(...Object.values(byStudent).map(arr => arr.length), 0);
  const rounds = [];
  for (let i = 0; i < maxRounds; i++) {
    rounds.push(attendees.map(studentName => {
      const rem = byStudent[studentName][i];
      return rem ? { studentName, ...rem } : { studentName, pending: true };
    }));
  }
  return rounds;
}

function groupAttendeeLabel(studentName) {
  const group = state.viewGroup;
  const links = group?.studentLinks || {};
  const sid = links[studentName];
  const student = sid ? (state.students || []).find(s => s.id === sid) : null;
  return escHtml(student?.preferredName || firstNameOf(studentName));
}

function buildGroupTargetViewTable(target, data, attendees) {
  // Per-attendee, not one blended figure — a group's two students can be at
  // very different stages, so a single combined "Day's Average" would hide
  // that. See calcGroupStudentDaysAverage (shared with the live-entry screen).
  const studentAvgs = attendees
    .map(studentName => ({ studentName, pct: calcGroupStudentDaysAverage(target, data, studentName, new Set()) }))
    .filter(sa => sa.pct !== null);

  let rows = "";
  if (target.predefinedActivities?.length > 0) {
    let no = 0;
    const matchedIds = new Set();
    const remCountByAct2 = {};
    for (const rem of Object.values(data.remarks || {})) {
      remCountByAct2[rem.activityId] = (remCountByAct2[rem.activityId] || 0) + 1;
    }
    const sortByData2 = arr => arr.slice().sort(([idA], [idB]) =>
      ((remCountByAct2[idB] || 0) - (remCountByAct2[idA] || 0)) || idA.localeCompare(idB)
    );
    const parentActNamesGrp = new Set(
      (target.predefinedActivities || []).filter(p => p.parentActivity).map(p => p.parentActivity)
    );
    let _pendingGrpViewHeading = null;
    for (const pa of target.predefinedActivities) {
      if (!isActivityActive(pa, data.date)) continue;
      if (pa.isCompleted || pa.isArchived || pa.isStopped) continue;
      if (pa.isHeading || pa.isMaintainHeading) {
        const isGray = pa.headingColor === "gray" || pa.isMaintainHeading;
        const isGreenHdg = pa.headingColor === "green";
        _pendingGrpViewHeading = `<tr class="view-heading-row${isGray ? " view-gray-row" : isGreenHdg ? " view-green-row" : ""}"><td colspan="7" contenteditable="false">${escHtml(pa.name)}</td></tr>`;
        continue;
      }
      if (pa.isNote || pa.isExportNote) {
        if (_pendingGrpViewHeading) { rows += _pendingGrpViewHeading; _pendingGrpViewHeading = null; }
        rows += `<tr class="view-note-row"><td colspan="7" contenteditable="false">${noteToHtml(pa.text)}</td></tr>`;
        continue;
      }
      if (_pendingGrpViewHeading) { rows += _pendingGrpViewHeading; _pendingGrpViewHeading = null; }
      if (!pa.parentActivity && parentActNamesGrp.has(pa.name)) {
        no++;
        Object.entries(data.activities || {})
          .filter(([, a]) => a.targetName === target.name && (a.activityName === pa.name || (pa.title && a.activityName === pa.title)))
          .forEach(([id]) => matchedIds.add(id));
        const _paGrpMastered = pa.masteredOn || (pa.inactiveReason === 'mastered' ? "2026-06-30" : null);
        const _paGrpMaintBadge = pa.maintained
          ? `<span style="font-size:.72rem;color:#6b7280;font-weight:600;white-space:nowrap">(🆗 Maintained${pa.maintainedAt ? ` on ${fmtPeriodDate(pa.maintainedAt)}` : ''})</span> `
          : '';
        const paBadgeGrp = _paGrpMaintBadge + (pa.discontinuedOn
          ? `<span style="font-size:.72rem;color:#dc2626;font-weight:600;white-space:nowrap">(🚩 ${fmtPeriodDate(pa.discontinuedOn)})</span> `
          : _paGrpMastered
          ? `<span style="font-size:.72rem;color:#059669;font-weight:600;white-space:nowrap">(⭐ ${fmtPeriodDate(_paGrpMastered)})</span> `
          : '');
        rows += `<tr style="background:#f3f4f6">
          <td class="vcol-no" contenteditable="false" style="color:#6b7280">${no}</td>
          <td class="vcol-act" colspan="6" contenteditable="false" style="font-weight:600">${paBadgeGrp}${paDisplayHtml(pa)}</td>
        </tr>`;
        continue;
      }
      if ((pa.fixedRemark !== undefined || pa.isMaintain) && !pa.maintained) {
        const fixedEntries2 = Object.entries(data.activities || {})
          .filter(([, a]) => a.targetName === target.name && (a.activityName === pa.name || (pa.title && a.activityName === pa.title)));
        fixedEntries2.forEach(([id]) => matchedIds.add(id));
        const fixedText = pa.fixedRemark ?? pa.maintainRemark ?? "";
        const isGrayFixed = pa.activityColor === "gray" || !!pa.isMaintainLive;
        const isGreenFixed2 = pa.activityColor === "green";
        no++;
        rows += `<tr${isGrayFixed ? ' class="view-gray-row"' : isGreenFixed2 ? ' class="view-green-row"' : ' style="background:#f9fafb"'}>
          <td class="vcol-no" contenteditable="false">${no}</td>
          <td class="vcol-act" contenteditable="false">${paDisplayHtml(pa)}</td>
          <td class="vcol-student" contenteditable="false">—</td>
          <td class="vcol-rem" contenteditable="false" style="color:#6b7280;white-space:pre-wrap">${formatActivityMarkup(fixedText) || "—"}</td>
          <td class="vcol-trials" contenteditable="false">—</td>
          <td class="vcol-total" contenteditable="false">—</td>
          <td class="vcol-score" contenteditable="false">—</td>
        </tr>`;
        continue;
      }
      const isSub2 = !!pa.parentActivity;
      if (isSub2) {
        const parentExists2 = (target.predefinedActivities || []).some(
          p => !p.parentActivity && (p.title || p.name) === pa.parentActivity
            && isActivityActive(p, data.date)
            && !p.isCompleted && !p.isArchived && !p.isStopped
        );
        if (!parentExists2) continue;
      }
      no++;
      const candidateEntries2 = Object.entries(data.activities || {})
        .filter(([id, a]) => a.targetName === target.name && (a.activityName === pa.name || (pa.title && a.activityName === pa.title) || (pa.id && a.configId === pa.id)) && !matchedIds.has(id));
      const actHasData2 = id => Object.values(data.remarks || {}).some(r =>
        r.activityId === id && ((r.text || "").trim() || (r.trials || []).some(t => t >= 0))
      );
      // Same deduplication as individual view: score by data richness, delete losers.
      let entry2 = null;
      if (pa.id) {
        const sameConfigEntries2 = candidateEntries2.filter(([, a]) => a.configId === pa.id);
        if (sameConfigEntries2.length > 1) {
          const viewScore2 = ([actId]) => {
            let s = 0;
            for (const r of Object.values(data.remarks || {})) {
              if (r.activityId !== actId) continue;
              s += (r.trials || []).filter(t => t !== null && t !== -1).length * 100;
              if ((r.masteryNote || "").trim()) s += 50;
              if ((r.text || "").trim()) s += 10;
              if (r.optionScore !== undefined) s += 5;
            }
            return s;
          };
          entry2 = sameConfigEntries2.reduce((a, b) => viewScore2(a) >= viewScore2(b) ? a : b);
          for (const [loserId2] of sameConfigEntries2) {
            if (loserId2 === entry2[0]) continue;
            matchedIds.add(loserId2);
            const loserRemIds2 = Object.entries(data.remarks || {}).filter(([, r]) => r.activityId === loserId2).map(([id]) => id);
            delete data.activities[loserId2];
            for (const remId of loserRemIds2) delete data.remarks[remId];
            deleteActivity(state.viewGroupSessionId, loserId2, loserRemIds2).catch(() => {});
          }
        } else {
          entry2 = sameConfigEntries2[0] || null;
        }
      }
      if (isSub2 && entry2 && !actHasData2(entry2[0])) entry2 = null;
      if (!entry2) {
        if (isSub2) {
          const knownConfigKeys2 = new Set(
            (target.predefinedActivities || []).flatMap(p => [p.name, p.title].filter(Boolean))
          );
          const hasTopLevelConfig2 = (target.predefinedActivities || []).some(p =>
            !p.parentActivity && !p.isHeading && !p.isNote && !p.isExportNote && p.name && p.name === pa.name
          );
          const subCandidates2 = hasTopLevelConfig2
            ? candidateEntries2.filter(([, a]) => a.parentActivity === pa.parentActivity)
            : candidateEntries2.filter(([, a]) =>
                a.parentActivity === pa.parentActivity ||
                (a.parentActivity && !knownConfigKeys2.has(a.parentActivity)) ||
                !a.parentActivity
              );
          const actHasReal2 = id => Object.values(data.remarks || {}).some(r =>
            r.activityId === id && ((r.text || "").trim() || (r.trials || []).some(t => t >= 0))
          );
          entry2 = subCandidates2.find(([id]) => actHasReal2(id)) || sortByData2(subCandidates2)[0] || null;
        } else {
          const claimable2 = pa.name === ""
            ? candidateEntries2.filter(([, a]) => !a.parentActivity && a.activityName !== "")
            : candidateEntries2.filter(([, a]) => !a.parentActivity);
          entry2 = sortByData2(claimable2)[0] || null;
        }
      }
      if (entry2 && pa.id && !entry2[1].configId) {
        entry2[1].configId = pa.id;
        if (isSub2 && pa.parentActivity && !entry2[1].parentActivity) {
          entry2[1].parentActivity = pa.parentActivity;
        }
        adoptOrphanActivity(
          state.viewGroupSessionId,
          entry2[0],
          isSub2 ? (pa.parentActivity || null) : null,
          pa.id
        ).catch(() => {});
      }
      if (entry2) matchedIds.add(entry2[0]);
      rows += viewGroupActivityRows(no, pa.title || pa.name, entry2?.[0] || null, data, target, attendees, true, pa);
    }
    // Silently delete unmatched records with no meaningful data (empty ghosts).
    for (const [actId, act] of Object.entries(data.activities || {})) {
      if (act.targetName !== target.name || matchedIds.has(actId)) continue;
      const remIds = Object.entries(data.remarks || {})
        .filter(([, r]) => r.activityId === actId).map(([id]) => id);
      const hasData = remIds.some(remId => {
        const r = data.remarks[remId];
        return r && (
          (r.text || "").replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").trim().length > 0 ||
          (r.trials || []).some(t => t !== null && t !== -1) ||
          (r.masteryNote || "").replace(/<[^>]*>/g, "").trim().length > 0
        );
      });
      if (!hasData) {
        matchedIds.add(actId);
        delete data.activities[actId];
        for (const remId of remIds) delete data.remarks[remId];
        deleteActivity(state.viewGroupSessionId, actId, remIds).catch(() => {});
      }
    }
    // Activities not matched above — both manually-added ones and predefined
    // records whose config entry has gone missing. See the matching comment in
    // buildTargetViewTable: a deliberate delete purges its session records, so a
    // predefined record that still has data but matches no config entry is
    // accidental damage and must still render rather than vanish. Sub-activities
    // (parentActivity set) stay excluded — they can't stand on their own.
    // Anything data-less was already deleted by the sweep above.
    // Rendered under an "Extra" heading, matching the individual View screen.
    // Anything landing here is either a session-only activity someone added by
    // hand, or a record whose config entry has gone missing - the heading makes
    // the second case visible instead of it blending into the numbered list.
    const grpExtraActs = Object.entries(data.activities || {})
      .filter(([actId, a]) => a.targetName === target.name && !matchedIds.has(actId) && !a.parentActivity)
      .sort(([, a], [, b]) => (a.order || 0) - (b.order || 0));
    if (grpExtraActs.length > 0) {
      rows += `<tr class="view-heading-row"><td colspan="6" contenteditable="false">Extra</td></tr>`;
      let grpExtraNo = 0;
      grpExtraActs.forEach(([actId, act]) => {
        grpExtraNo++;
        rows += viewGroupActivityRows(grpExtraNo, act.activityName, actId, data, target, attendees, false);
      });
    }
  } else {
    let no = 0;
    Object.entries(data.activities || {})
      .filter(([, a]) => a.targetName === target.name)
      .sort(([, a], [, b]) => (a.order || 0) - (b.order || 0))
      .forEach(([actId, act]) => {
        no++;
        rows += viewGroupActivityRows(no, act.activityName, actId, data, target, attendees, false);
      });
  }

  if (target.hasComment) {
    const key     = sanitizeKey(target.name);
    const comment = (data.fedcComments || {})[key] || "";
    rows += `<tr class="view-comment-row">
      <td colspan="3" class="view-comment-label" contenteditable="false">Comment</td>
      <td colspan="4" contenteditable="false">
        <textarea class="view-comment-edit" data-target-key="${escHtml(key)}" rows="3"
        >${escHtml(comment)}</textarea>
      </td>
    </tr>`;
  }

  if (studentAvgs.length > 0) {
    rows += studentAvgs.map(sa => `<tr class="view-dayavg-row">
      <td colspan="6" style="text-align:right" contenteditable="false">Day's Average (${escHtml(firstNameOf(sa.studentName))})</td>
      <td class="vcol-score" contenteditable="false">${sa.pct}%</td>
    </tr>`).join("");
  }

  return `<div class="target-view-section">
    <div class="target-view-header" contenteditable="false">
      <span class="target-view-name">${escHtml(target.name)}</span>
      ${studentAvgs.map(sa => `<span class="target-view-avg">${escHtml(firstNameOf(sa.studentName))}: ${sa.pct}%</span>`).join("")}
    </div>
    <div class="view-table-wrapper">
      <table class="view-table">
        <thead><tr>
          <th class="vcol-no">No.</th>
          <th class="vcol-act">Activity</th>
          <th class="vcol-student">Student</th>
          <th class="vcol-rem">Remark</th>
          <th class="vcol-trials">Trials</th>
          <th class="vcol-total">Total</th>
          <th class="vcol-score">% Score</th>
        </tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>
    <button class="view-add-remark-target-group" data-target="${escHtml(target.name)}">+ Add Remark &amp; Trials</button>
  </div>`;
}

function viewGroupActivityRows(no, actName, actId, data, target, attendees, isPredefined = true, paConfig = null) {
  const rounds           = actId ? viewGroupGetRounds(data, actId, attendees) : [];
  const grpActConfigId = actId ? data.activities?.[actId]?.configId : null;
  const paEntry = paConfig || (isPredefined
    ? (target.predefinedActivities?.find(pa => pa.name === actName) ||
       (grpActConfigId ? target.predefinedActivities?.find(pa => pa.id === grpActConfigId) : null))
    : null);

  const parentEntry = paEntry?.parentActivity
    ? (target.predefinedActivities || []).find(p => !p.parentActivity && (p.name === paEntry.parentActivity || (p.title && p.title === paEntry.parentActivity)))
    : null;
  const _discontinuedOn = paEntry?.discontinuedOn || parentEntry?.discontinuedOn || null;
  const _masteredOn     = paEntry?.masteredOn     || parentEntry?.masteredOn
    || (paEntry?.inactiveReason === 'mastered' ? "2026-06-30" : null)
    || (parentEntry?.inactiveReason === 'mastered' ? "2026-06-30" : null)
    || null;
  const _maintained     = !!(paEntry?.maintained   || parentEntry?.maintained);
  const _maintainedAt   = paEntry?.maintainedAt || parentEntry?.maintainedAt || null;
  const _maintBadge = _maintained
    ? `<span style="font-size:.72rem;color:#6b7280;font-weight:600;white-space:nowrap">(🆗 Maintained${_maintainedAt ? ` on ${fmtPeriodDate(_maintainedAt)}` : ''})</span> `
    : '';
  const statusBadge = _maintBadge + (_discontinuedOn
    ? `<span style="font-size:.72rem;color:#dc2626;font-weight:600;white-space:nowrap">(🚩 ${fmtPeriodDate(_discontinuedOn)})</span> `
    : _masteredOn
    ? `<span style="font-size:.72rem;color:#059669;font-weight:600;white-space:nowrap">(⭐ ${fmtPeriodDate(_masteredOn)})</span> `
    : '');

  const actCell = isPredefined
    ? statusBadge + (paEntry ? paDisplayHtml(paEntry) : formatActivityMarkup(actName)) + (paEntry?.actNote?.trim() ? `<div class="view-act-note">${formatActivityMarkup(paEntry.actNote)}</div>` : "")
    : `<div style="display:flex;align-items:center;gap:.3rem">
        <input class="view-act-edit" type="text" value="${escHtml(actName)}"
          data-act-id="${escHtml(actId || "")}" data-original="${escHtml(actName)}" />
        <button class="view-act-del" data-act-id="${escHtml(actId || "")}"
          data-target-name="${escHtml(target.name)}" title="Delete activity">×</button>
       </div>`;

  // Mapped-score activities have no trials/combine-remarks concept — bypass
  // the rounds/combine machinery entirely and list every attendee's own
  // remark + their own per-attendee mapped score (see renderGroupActivityCard's
  // live-entry counterpart for the same per-attendee bypass).
  if (paEntry?.isMapped) {
    const mappedInlineOptions   = getActivityInlineOptions(paEntry);
    const mappedSentenceStarter = paEntry.sentenceStarter || null;
    const mappedMultiSelect     = paEntry.optionsMulti || false;
    const mappedHasNote         = paEntry.remarkHasNote || false;
    let firstRow = true;
    return attendees.map(studentName => {
      const remarks = actId
        ? Object.entries(data.remarks || {})
            .filter(([, r]) => r.activityId === actId && r.studentName === studentName)
            .sort(([, a], [, b]) => (a.order || 0) - (b.order || 0))
            .map(([id, r]) => ({ id, ...r }))
        : [];
      const noVal  = firstRow ? no : null;
      const actVal = firstRow ? actCell : null;
      firstRow = false;
      if (remarks.length === 0) {
        return `<tr>
          <td class="vcol-no" contenteditable="false">${noVal !== null ? noVal : ""}</td>
          <td class="vcol-act" contenteditable="false">${actVal !== null ? actVal : ""}</td>
          <td class="vcol-student" contenteditable="false">${groupAttendeeLabel(studentName)}</td>
          <td class="vcol-rem" contenteditable="false">
            <button class="btn-view-group-add-remark-mapped-pending" data-act-id="${escHtml(actId || "")}"
              data-act-name="${escHtml(actName)}" data-target-name="${escHtml(target.name)}"
              data-student="${escHtml(studentName)}">+ Add Remark</button>
          </td>
          <td class="vcol-trials" contenteditable="false">&nbsp;</td>
          <td class="vcol-total" contenteditable="false">&nbsp;</td>
          <td class="vcol-score" contenteditable="false">&nbsp;</td>
        </tr>`;
      }
      const mappedInfo = resolveViewGroupMappedScoreDisplay(paEntry, data, studentName);
      return remarks.map((rem, ri) => viewGroupRemarkRow(
        ri === 0 ? noVal : null, ri === 0 ? actVal : null, studentName, rem, target,
        mappedInlineOptions, mappedSentenceStarter, mappedMultiSelect, null, mappedInfo, mappedHasNote, "", paEntry?.optionScores || null
      )).join("");
    }).join("");
  }

  // Per-round toggles are built inside the round loop below

  const inlineOptions   = paEntry ? getActivityInlineOptions(paEntry) : null;
  const sentenceStarter = paEntry?.sentenceStarter || null;
  const multiSelect     = paEntry?.optionsMulti || false;
  const remarkHasNote   = paEntry ? !!(paEntry.remarkHasNote || inlineOptions || paEntry.manualScore) : false;
  const opts            = parseOpts(inlineOptions);
  const isGrayAct       = isPredefined && (_maintained || paEntry?.activityColor === "gray" || paEntry?.isMaintainLive);
  const isGreenAct      = isPredefined && paEntry?.activityColor === "green";
  const rowClass        = isGrayAct ? "view-gray-row" : isGreenAct ? "view-green-row" : "";

  if (rounds.length === 0) {
    if (opts.length === 0) {
      if ((remarkHasNote || multiSelect) && !paEntry?.manualScore) {
        const _lbl = multiSelect ? "CHECKBOXES" : "MULTIPLE CHOICE";
        const _gMsg = `<span class="field-label">${_lbl}</span>
            <span style="color:#9ca3af;font-style:italic;font-size:.88rem">&lt;Please Add Options in Edit Target&gt;</span>`;
        return attendees.map((studentName, idx) => {
          const _gNote = remarkHasNote
            ? `<textarea class="view-mastery-note view-mastery-note-empty" rows="1"
                 data-act-id="${escHtml(actId || "")}" data-act-name="${escHtml(actName)}"
                 data-target="${escHtml(target.name)}" data-is-predefined="${isPredefined}"
                 data-student="${escHtml(studentName)}"
                 placeholder="Remark…"></textarea>` : "";
          const _gCell = remarkHasNote
            ? `<div class="view-starter-wrap view-starter-wrap-note" contenteditable="false">
                 <div class="view-starter-top-row">${_gMsg}</div>
                 ${_gNote}
               </div>`
            : `<div style="padding:.4rem .6rem">${_gMsg}</div>`;
          return `<tr${rowClass ? ` class="${rowClass}"` : ""}>
            <td class="vcol-no" contenteditable="false">${idx === 0 ? no : ""}</td>
            <td class="vcol-act" contenteditable="false">${idx === 0 ? actCell : ""}</td>
            <td class="vcol-student" contenteditable="false">${groupAttendeeLabel(studentName)}</td>
            <td class="vcol-rem" contenteditable="false">${_gCell}</td>
            <td class="vcol-trials" contenteditable="false">&nbsp;</td>
            <td class="vcol-total" contenteditable="false">&nbsp;</td>
            <td class="vcol-score" contenteditable="false">&nbsp;</td>
          </tr>`;
        }).join("");
      }
      return attendees.map((studentName, idx) => `<tr${rowClass ? ` class="${rowClass}"` : ""}>
        <td class="vcol-no" contenteditable="false">${idx === 0 ? no : ""}</td>
        <td class="vcol-act" contenteditable="false">${idx === 0 ? actCell : ""}</td>
        <td class="vcol-student" contenteditable="false">${groupAttendeeLabel(studentName)}</td>
        <td class="vcol-rem" contenteditable="false">
          <textarea class="view-remark-edit view-remark-empty" rows="1"
            data-act-id="${escHtml(actId || "")}"
            data-act-name="${escHtml(actName)}"
            data-target="${escHtml(target.name)}"
            data-is-predefined="${isPredefined}"
            data-student="${escHtml(studentName)}"
            data-parent-activity="${escHtml(paConfig?.parentActivity || "")}"
            data-config-id="${escHtml(paConfig?.id || "")}"
            placeholder="${_maintained && data.date >= (_maintainedAt || "2026-01-01") ? "" : "Remark…"}">${_maintained && data.date >= (_maintainedAt || "2026-01-01") ? "Maintain" : ""}</textarea>
        </td>
        <td class="vcol-trials" contenteditable="false">
          ${paEntry?.noTrials ? `<span class="view-trials-disabled" style="color:#9ca3af;font-style:italic">Trials are not required for this activity</span>` : `<button class="view-group-add-trial-new" data-act-id="${escHtml(actId || "")}"
            data-act-name="${escHtml(actName)}" data-target-name="${escHtml(target.name)}"
            data-is-predefined="${isPredefined}" data-student="${escHtml(studentName)}">+</button>`}
        </td>
        <td class="vcol-total" contenteditable="false">&nbsp;</td>
        <td class="vcol-score" contenteditable="false">&nbsp;</td>
      </tr>`).join("");
    }

    // opts.length > 0 — show per-attendee select/multi UI directly
    return attendees.map((studentName, idx) => {
      let gSelHtml;
      if (multiSelect) {
        gSelHtml = `<div class="view-remark-multi-opts" contenteditable="false">${opts.map(opt =>
          `<button class="view-group-multi-create-btn" data-opt="${escHtml(opt)}"
            data-act-id="${escHtml(actId || "")}" data-act-name="${escHtml(actName)}"
            data-target-name="${escHtml(target.name)}" data-student="${escHtml(studentName)}"
            data-maintained="${_maintained}">${escHtml(opt)}</button>`
        ).join("")}</div>`;
      } else {
        gSelHtml = `<div class="view-remark-multi-opts" contenteditable="false">${opts.map(opt =>
          `<button class="view-group-single-create-btn" data-opt="${escHtml(opt)}"
            data-act-id="${escHtml(actId || "")}" data-act-name="${escHtml(actName)}"
            data-target-name="${escHtml(target.name)}" data-student="${escHtml(studentName)}">${escHtml(opt)}</button>`
        ).join("")}</div>`;
      }
      const gNoteEmptyHtml = remarkHasNote
        ? `<textarea class="view-mastery-note view-mastery-note-empty" rows="1"
             data-act-id="${escHtml(actId || "")}" data-act-name="${escHtml(actName)}"
             data-target="${escHtml(target.name)}" data-is-predefined="${isPredefined}"
             data-student="${escHtml(studentName)}"
             placeholder="Remark…"></textarea>`
        : "";
      let gRemCell;
      if (sentenceStarter && remarkHasNote) {
        gRemCell = `<div class="view-starter-wrap view-starter-wrap-note" contenteditable="false">
          <div class="view-starter-top-row"><span class="view-starter-prefix">${escHtml(sentenceStarter)}</span>${gSelHtml}</div>
          ${gNoteEmptyHtml}
        </div>`;
      } else if (sentenceStarter) {
        gRemCell = `<div class="view-starter-wrap" contenteditable="false">
          <span class="view-starter-prefix">${escHtml(sentenceStarter)}</span>${gSelHtml}
        </div>`;
      } else if (remarkHasNote) {
        gRemCell = `<div class="view-starter-wrap view-starter-wrap-note" contenteditable="false">
          <div class="view-starter-top-row">${gSelHtml}</div>
          ${gNoteEmptyHtml}
        </div>`;
      } else {
        gRemCell = gSelHtml;
      }
      return `<tr${rowClass ? ` class="${rowClass}"` : ""}>
        <td class="vcol-no" contenteditable="false">${idx === 0 ? no : ""}</td>
        <td class="vcol-act" contenteditable="false">${idx === 0 ? actCell : ""}</td>
        <td class="vcol-student" contenteditable="false">${groupAttendeeLabel(studentName)}</td>
        <td class="vcol-rem" contenteditable="false">${gRemCell}</td>
        <td class="vcol-trials" contenteditable="false">
          ${paEntry?.noTrials ? `<span class="view-trials-disabled" style="color:#9ca3af;font-style:italic">Trials are not required for this activity</span>` : `<button class="view-group-add-trial-new" data-act-id="${escHtml(actId || "")}"
            data-act-name="${escHtml(actName)}" data-target-name="${escHtml(target.name)}"
            data-is-predefined="${isPredefined}" data-student="${escHtml(studentName)}">+</button>`}
        </td>
        <td class="vcol-total" contenteditable="false">&nbsp;</td>
        <td class="vcol-score" contenteditable="false">&nbsp;</td>
      </tr>`;
    }).join("");
  }

  let firstRowOverall = true;
  let html = "";
  for (let ri = 0; ri < rounds.length; ri++) {
    const round = rounds[ri];

    for (const entry of round) {
      const noVal  = firstRowOverall ? no : null;
      const actVal = firstRowOverall ? actCell : null;

      if (entry.pending) {
        // Free-text activities (no presets) get a ready-to-type empty box
        // here too, same as the "nobody has a remark yet" case below — only
        // preset-option/sentence-starter activities (which have no typeable
        // free text) still need an explicit button.
        if (opts.length === 0) {
          html += `<tr${rowClass ? ` class="${rowClass}"` : ""}>
            <td class="vcol-no" contenteditable="false">${noVal !== null ? noVal : ""}</td>
            <td class="vcol-act" contenteditable="false">${actVal !== null ? actVal : ""}</td>
            <td class="vcol-student" contenteditable="false">${groupAttendeeLabel(entry.studentName)}</td>
            <td class="vcol-rem" contenteditable="false">
              <textarea class="view-remark-edit view-remark-empty" rows="1"
                data-act-id="${escHtml(actId || "")}"
                data-act-name="${escHtml(actName)}"
                data-target="${escHtml(target.name)}"
                data-is-predefined="${isPredefined}"
                data-student="${escHtml(entry.studentName)}"></textarea>
            </td>
            <td class="vcol-trials" contenteditable="false">
              ${paEntry?.noTrials ? `<span class="view-trials-disabled" style="color:#9ca3af;font-style:italic">Trials are not required for this activity</span>` : `<button class="view-group-add-trial-new" data-act-id="${escHtml(actId || "")}"
                data-act-name="${escHtml(actName)}" data-target-name="${escHtml(target.name)}"
                data-is-predefined="${isPredefined}" data-student="${escHtml(entry.studentName)}">+</button>`}
            </td>
            <td class="vcol-total" contenteditable="false">&nbsp;</td>
            <td class="vcol-score" contenteditable="false">&nbsp;</td>
          </tr>`;
          firstRowOverall = false;
          firstInRound = false;
          continue;
        }
        // opts.length > 0 — show inline select/multi UI directly
        let pSelHtml;
        if (multiSelect) {
          pSelHtml = `<div class="view-remark-multi-opts" contenteditable="false">${opts.map(opt =>
            `<button class="view-group-multi-create-btn" data-opt="${escHtml(opt)}"
              data-act-id="${escHtml(actId || "")}" data-act-name="${escHtml(actName)}"
              data-target-name="${escHtml(target.name)}" data-student="${escHtml(entry.studentName)}"
              data-maintained="${_maintained}">${escHtml(opt)}</button>`
          ).join("")}</div>`;
        } else {
          pSelHtml = `<div class="view-remark-multi-opts" contenteditable="false">${opts.map(opt =>
            `<button class="view-group-single-create-btn" data-opt="${escHtml(opt)}"
              data-act-id="${escHtml(actId || "")}" data-act-name="${escHtml(actName)}"
              data-target-name="${escHtml(target.name)}" data-student="${escHtml(entry.studentName)}">${escHtml(opt)}</button>`
          ).join("")}</div>`;
        }
        const pNoteEmptyHtml = remarkHasNote
          ? `<textarea class="view-mastery-note view-mastery-note-empty" rows="1"
               data-act-id="${escHtml(actId || "")}" data-act-name="${escHtml(actName)}"
               data-target="${escHtml(target.name)}" data-is-predefined="${isPredefined}"
               data-student="${escHtml(entry.studentName)}"
               placeholder="Remark…"></textarea>`
          : "";
        let pRemCell;
        if (sentenceStarter && remarkHasNote) {
          pRemCell = `<div class="view-starter-wrap view-starter-wrap-note" contenteditable="false">
            <div class="view-starter-top-row"><span class="view-starter-prefix">${escHtml(sentenceStarter)}</span>${pSelHtml}</div>
            ${pNoteEmptyHtml}
          </div>`;
        } else if (sentenceStarter) {
          pRemCell = `<div class="view-starter-wrap" contenteditable="false">
            <span class="view-starter-prefix">${escHtml(sentenceStarter)}</span>${pSelHtml}
          </div>`;
        } else if (remarkHasNote) {
          pRemCell = `<div class="view-starter-wrap view-starter-wrap-note" contenteditable="false">
            <div class="view-starter-top-row">${pSelHtml}</div>
            ${pNoteEmptyHtml}
          </div>`;
        } else {
          pRemCell = pSelHtml;
        }
        html += `<tr${rowClass ? ` class="${rowClass}"` : ""}>
          <td class="vcol-no" contenteditable="false">${noVal !== null ? noVal : ""}</td>
          <td class="vcol-act" contenteditable="false">${actVal !== null ? actVal : ""}</td>
          <td class="vcol-student" contenteditable="false">${groupAttendeeLabel(entry.studentName)}</td>
          <td class="vcol-rem">${pRemCell}</td>
          <td class="vcol-trials" contenteditable="false">&nbsp;</td>
          <td class="vcol-total" contenteditable="false">&nbsp;</td>
          <td class="vcol-score" contenteditable="false">&nbsp;</td>
        </tr>`;
        firstRowOverall = false;
        firstInRound = false;
        continue;
      }

      html += viewGroupRemarkRow(
        noVal, actVal, entry.studentName, entry, target,
        inlineOptions, sentenceStarter, multiSelect, null, remarkHasNote, rowClass, paEntry?.optionScores || null, paEntry?.manualScore || false, paEntry?.noTrials || false
      );
      firstRowOverall = false;
    }
  }
  return html;
}

function viewGroupRemarkRow(no, actName, studentName, rem, target, inlineOptions = null, sentenceStarter = null, multiSelect = false, mappedInfo = null, remarkHasNote = false, rowClass = "", optionScores = null, manualScore = false, noTrials = false) {
  const _sv2 = t => (t || "").replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").trim();
  const _remEmpty2 = !_sv2(rem.text) && !_sv2(rem.masteryNote) && !(rem.trials || []).some(t => t >= 0) && rem.optionScore === undefined;
  const delBtn2 = _remEmpty2 ? "" : `<button class="view-rem-del" data-rem-id="${escHtml(rem.id)}" title="Delete remark">×</button>`;
  if (manualScore) {
    const currentVal = rem.text ? plainTextForEdit(rem.text).trim() : "";
    const parsed = parseManualScore(currentVal);
    const parsedPct = parsed !== null ? Math.round(parsed * 10) / 10 : null;
    const hintHtml = `<span class="view-manual-score-hint" data-rem-id="${escHtml(rem.id)}"
      style="font-size:.85rem;color:#6b7280;white-space:nowrap${parsedPct === null ? ";display:none" : ""}">${parsedPct !== null ? `= ${parsedPct}%` : ""}</span>`;
    const scoreInput = `<div style="display:flex;align-items:center;gap:.5rem;flex-wrap:wrap;padding:.3rem .4rem .15rem">
      <span style="font-size:.7rem;font-weight:700;color:#6b7280;letter-spacing:.05em;white-space:nowrap">MANUAL SCORE</span>
      <input type="text" class="view-manual-score-input" data-rem-id="${escHtml(rem.id)}"
        data-saved-html="${escHtml(currentVal)}" value="${escHtml(currentVal)}"
        placeholder="e.g. 5/20, 25%"
        style="width:9rem;min-width:0;border:1px solid #b0b7c3;border-radius:4px;padding:.25rem .4rem;font-size:.85rem;font-family:var(--font);background:#fff;outline:none;box-sizing:border-box">
      ${hintHtml}
    </div>`;
    const noteCell = `<textarea class="view-mastery-note" rows="1" data-rem-id="${escHtml(rem.id)}"
      data-saved-html="${escHtml(rem.masteryNote || "")}"
      placeholder="Remark…">${escHtml(plainTextForEdit(rem.masteryNote))}</textarea>`;
    const remarkCell = `<div class="view-manual-score-wrap" contenteditable="false">${scoreInput}${noteCell}</div>`;
    const scoreColDisplay = parsedPct !== null ? parsedPct + "%" : "";
    return `<tr${rowClass ? ` class="${rowClass}"` : ""}>
      <td class="vcol-no" contenteditable="false">${no !== null ? no : ""}</td>
      <td class="vcol-act" contenteditable="false">${actName !== null ? actName : ""}</td>
      <td class="vcol-student" contenteditable="false">${groupAttendeeLabel(studentName)}</td>
      <td class="vcol-rem" contenteditable="false">${remarkCell}</td>
      <td class="vcol-trials" contenteditable="false">&nbsp;</td>
      <td class="vcol-total" contenteditable="false">&nbsp;</td>
      <td class="vcol-score" contenteditable="false">
        <div style="display:flex;align-items:center;gap:.3rem;justify-content:flex-end">
          <span class="view-manual-score-pct" data-rem-id="${escHtml(rem.id)}">${scoreColDisplay}</span>
          ${delBtn2}
        </div>
      </td>
    </tr>`;
  }
  const maxPts = target.maxPoints || 3;
  const { validTrials, total, scorePct } = calcViewTrialSummary(rem.trials, maxPts, rem.optionScore);
  const trialCells = mappedInfo
    ? `<span class="view-mapped-label">${escHtml(mappedInfo.label)}</span>`
    : `<div class="trial-cells">${buildTrialCellsHtml(rem, maxPts)}</div>`;
  const totalCell = mappedInfo ? "&nbsp;" : (validTrials.length > 0 ? total : "&nbsp;");
  const scoreDisplay = mappedInfo
    ? (mappedInfo.pct !== null ? mappedInfo.pct + "%" : "—")
    : scorePct;

  let remarkTd = "";
  {
      const opts = parseOpts(inlineOptions);

      if ((remarkHasNote || multiSelect) && opts.length === 0) {
        const _lbl3 = multiSelect ? "CHECKBOXES" : "MULTIPLE CHOICE";
        const _msg3 = `<span class="field-label">${_lbl3}</span>
          <span style="color:#9ca3af;font-style:italic;font-size:.88rem">&lt;Please Add Options in Edit Target&gt;</span>`;
        const _note3 = remarkHasNote
          ? `<textarea class="view-mastery-note" rows="1" data-rem-id="${escHtml(rem.id)}"
               data-saved-html="${escHtml(rem.masteryNote || "")}"
               placeholder="Remark…">${escHtml(plainTextForEdit(rem.masteryNote))}</textarea>` : "";
        const _cell3 = remarkHasNote
          ? `<div class="view-starter-wrap view-starter-wrap-note" contenteditable="false">
               <div class="view-starter-top-row">${_msg3}</div>
               ${_note3}
             </div>`
          : `<div style="padding:.4rem .6rem">${_msg3}</div>`;
        remarkTd = `<td class="vcol-rem" contenteditable="false">${_cell3}</td>`;
      } else {
      const makeViewOpts = (remId, remText) => {
        if (opts.length === 0) return null;
        if (multiSelect) {
          const sel = (remText || "").split(", ").map(s => s.trim()).filter(Boolean);
          return `<div class="view-remark-multi-opts" contenteditable="false">${opts.map(opt =>
            `<button class="view-remark-multi-btn view-remark-multi-btn--rect${sel.includes(opt) ? " active" : ""}"
              data-rem-id="${escHtml(remId)}" data-opt="${escHtml(opt)}">${escHtml(opt)}</button>`
          ).join("")}</div>`;
        }
        return `<div class="view-remark-multi-opts" contenteditable="false">${opts.map(opt => {
          const sc = (optionScores && optionScores[opt] !== undefined) ? optionScores[opt] : "";
          return `<button class="view-remark-single-btn${remText === opt ? " active" : ""}"
            data-rem-id="${escHtml(remId)}" data-opt="${escHtml(opt)}" data-score="${sc}">${escHtml(opt)}</button>`;
        }).join("")}</div>`;
      };

      const optSelect = makeViewOpts(rem.id, rem.text)
        || `<textarea class="view-remark-edit" rows="1" data-rem-id="${escHtml(rem.id)}"
              placeholder="Remark…" data-saved-html="${escHtml(rem.text || "")}">${escHtml(plainTextForEdit(rem.text))}</textarea>`;

      const showNote = remarkHasNote || !!(rem.masteryNote && rem.masteryNote.trim().length > 0);
      const noteField = showNote
        ? `<textarea class="view-mastery-note" rows="1" data-rem-id="${escHtml(rem.id)}"
            data-saved-html="${escHtml(rem.masteryNote || "")}"
            placeholder="Remark…">${escHtml(plainTextForEdit(rem.masteryNote))}</textarea>`
        : "";

      let remarkCell;
      if (sentenceStarter) {
        const starterTopRow = `<span class="view-starter-prefix">${escHtml(sentenceStarter)}</span>
          ${makeViewOpts(rem.id, rem.text)
            || `<textarea class="view-starter-input" data-rem-id="${escHtml(rem.id)}"
                rows="1" style="overflow-y:hidden">${escHtml(rem.text || "")}</textarea>`
          }`;
        remarkCell = showNote
          ? `<div class="view-starter-wrap view-starter-wrap-note" contenteditable="false">
              <div class="view-starter-top-row">${starterTopRow}</div>
              ${noteField}
            </div>`
          : `<div class="view-starter-wrap" contenteditable="false">${starterTopRow}</div>`;
      } else if (showNote) {
        remarkCell = `<div class="view-starter-wrap view-starter-wrap-note" contenteditable="false">
          <div class="view-starter-top-row">${optSelect}</div>
          ${noteField}
        </div>`;
      } else {
        remarkCell = optSelect;
      }
      remarkTd = `<td class="vcol-rem" contenteditable="false">${remarkCell}</td>`;
      }
  }

  return `<tr${rowClass ? ` class="${rowClass}"` : ""}>
    <td class="vcol-no" contenteditable="false">${no !== null ? no : ""}</td>
    <td class="vcol-act" contenteditable="false">${actName !== null ? actName : ""}</td>
    <td class="vcol-student" contenteditable="false">${groupAttendeeLabel(studentName)}</td>
    ${remarkTd}
    <td class="vcol-trials" contenteditable="false">${noTrials ? `<span class="view-trials-disabled" style="color:#9ca3af;font-style:italic">Trials are not required for this activity</span>` : trialCells}</td>
    <td class="vcol-total" contenteditable="false">${noTrials ? "&nbsp;" : totalCell}</td>
    <td class="vcol-score" contenteditable="false">
      <div style="display:flex;align-items:center;gap:.3rem;justify-content:flex-end">
        <span>${noTrials ? "" : scoreDisplay}</span>
        ${delBtn2}
      </div>
    </td>
  </tr>`;
}

function getGroupViewMaxPtsForRemark(remId) {
  const data = state.viewGroupSessionData;
  const rem  = data?.remarks?.[remId];
  const act  = rem && data.activities?.[rem.activityId];
  const target = act && getViewGroupEffectiveTargets().find(t => t.name === act.targetName);
  return target?.maxPoints || 3;
}

// Group-view counterpart of refreshViewTrialRow — same reasoning applies
// (see its comment): the Trials column's buttons can't blur the shared
// contenteditable host, so a full renderGroupSessionView() after clicking
// one gets deferred by isGroupViewBusy() until something unrelated finally
// blurs the host. Patching just this row sidesteps that entirely.
function refreshGroupViewTrialRow(remId) {
  const rem = state.viewGroupSessionData?.remarks?.[remId];
  if (!rem) return;
  const body = $("group-session-view-body");
  const tr   = body.querySelector(`.view-rem-del[data-rem-id="${remId}"]`)?.closest("tr");
  if (!tr) return;
  const maxPts = getGroupViewMaxPtsForRemark(remId);
  const { validTrials, total, scorePct } = calcViewTrialSummary(rem.trials, maxPts, rem.optionScore);
  const trialCellsDiv = tr.querySelector(".trial-cells");
  if (trialCellsDiv) {
    trialCellsDiv.innerHTML = buildTrialCellsHtml(rem, maxPts);
    bindGroupViewTrialCellListeners(trialCellsDiv);
  }
  const totalTd = tr.querySelector(".vcol-total");
  if (totalTd) totalTd.innerHTML = validTrials.length > 0 ? String(total) : "&nbsp;";
  const scoreSpan = tr.querySelector(".vcol-score span");
  if (scoreSpan) scoreSpan.textContent = scorePct;
}

// See trackViewTrialWrite's comment — same race, group-view counterpart.
function trackGroupViewTrialWrite(promise) {
  state.viewGroupActionsInFlight++;
  promise.finally(() => {
    state.viewGroupActionsInFlight--;
    if (state.viewGroupActionsInFlight === 0 && state.viewGroupRenderPending && !isGroupViewBusy()) {
      state.viewGroupRenderPending = false;
      renderGroupSessionView();
    }
  });
}

function bindGroupViewTrialCellListeners(container) {
  container.querySelectorAll(".view-trial-select").forEach(sel => {
    sel.addEventListener("change", () => {
      const rem = state.viewGroupSessionData?.remarks?.[sel.dataset.remId];
      if (!rem) return;
      const prevTrials = rem.trials || [];
      const trials = [...prevTrials];
      trials[Number(sel.dataset.trialIdx)] = Number(sel.value);
      rem.trials = trials;
      refreshGroupViewTrialRow(sel.dataset.remId);
      trackGroupViewTrialWrite(setTrials(state.viewGroupSessionId, sel.dataset.remId, trials).catch(err => {
        rem.trials = prevTrials;
        refreshGroupViewTrialRow(sel.dataset.remId);
        alert("Couldn't update — check your connection and try again.\n\n" + err.message);
      }));
    });
  });

  container.querySelectorAll(".view-trial-del").forEach(btn => {
    btn.addEventListener("click", () => {
      const rem = state.viewGroupSessionData?.remarks?.[btn.dataset.remId];
      if (!rem) return;
      const prevTrials = rem.trials || [];
      const trials = prevTrials.filter((_, i) => i !== Number(btn.dataset.trialIdx));
      rem.trials = trials;
      refreshGroupViewTrialRow(btn.dataset.remId);
      trackGroupViewTrialWrite(setTrials(state.viewGroupSessionId, btn.dataset.remId, trials).catch(err => {
        rem.trials = prevTrials;
        refreshGroupViewTrialRow(btn.dataset.remId);
        alert("Couldn't update — check your connection and try again.\n\n" + err.message);
      }));
    });
  });

  container.querySelectorAll(".view-add-trial").forEach(btn => {
    btn.addEventListener("click", () => {
      const rem = state.viewGroupSessionData?.remarks?.[btn.dataset.remId];
      if (!rem) return;
      const prevTrials = rem.trials || [];
      const trials = [...prevTrials, -1];
      rem.trials = trials;
      refreshGroupViewTrialRow(btn.dataset.remId);
      trackGroupViewTrialWrite(setTrials(state.viewGroupSessionId, btn.dataset.remId, trials).catch(err => {
        rem.trials = prevTrials;
        refreshGroupViewTrialRow(btn.dataset.remId);
        alert("Couldn't add trial — check your connection and try again.\n\n" + err.message);
      }));
    });
  });
}

function attachGroupViewListeners() {
  const body = $("group-session-view-body");
  const sid  = () => state.viewGroupSessionId;

  body.querySelectorAll(".view-add-remark-target-group").forEach(btn => {
    btn.addEventListener("click", () => showGroupViewAddRemarkPicker(btn.dataset.target));
  });

  body.querySelectorAll("textarea.view-remark-edit, textarea.view-mastery-note").forEach(autoResizeTextarea);

  // ── Manual score input: sanitise, live hint update, blur validation ───
  body.querySelectorAll(".view-manual-score-input").forEach(input => {
    const msSanitize = raw => {
      let s = raw.replace(/[^0-9./%]/g, "");
      const pctIdx = s.indexOf("%"); if (pctIdx !== -1) s = s.slice(0, pctIdx + 1);
      const slashIdx = s.indexOf("/");
      if (slashIdx !== -1) s = s.slice(0, slashIdx + 1) + s.slice(slashIdx + 1).replace(/\//g, "");
      return s.replace(/\.{2,}/g, ".");
    };
    const getHint = () => body.querySelector(`.view-manual-score-hint[data-rem-id="${input.dataset.remId}"]`);
    const getPct  = () => input.closest("tr")?.querySelector(".view-manual-score-pct");
    input.addEventListener("input", () => {
      const san = msSanitize(input.value);
      if (input.value !== san) {
        const pos = input.selectionStart - (input.value.length - san.length);
        input.value = san;
        input.setSelectionRange(Math.max(0, pos), Math.max(0, pos));
      }
      const parsed = parseManualScore(san.trim());
      const pct = parsed !== null ? Math.round(parsed * 10) / 10 : null;
      const hint = getHint();
      if (hint) { if (pct !== null) { hint.textContent = `= ${pct}%`; hint.style.display = ""; } else { hint.textContent = ""; hint.style.display = "none"; } }
      const pctEl = getPct(); if (pctEl) pctEl.textContent = pct !== null ? pct + "%" : "";
    });
    let _alerting = false;
    input.addEventListener("blur", () => {
      if (_alerting) return;
      const err = validateManualScore(input.value.trim());
      if (!err) return;
      _alerting = true; alert(err); _alerting = false;
      setTimeout(() => input.focus(), 0);
    });
  });

  const wrap = fn => withViewAction("viewGroupActionsInFlight", "viewGroupRenderPending", isGroupViewBusy, renderGroupSessionView, fn);

  bindGroupViewTrialCellListeners(body);

  // ── Sketch board buttons (group view screen) ────────────────
  body.querySelectorAll(".btn-sketch[data-rem-id]").forEach(btn => {
    btn.addEventListener("click", () => {
      const id = btn.dataset.remId;
      const field = body.querySelector(`.view-remark-edit[data-rem-id="${id}"]`)
                 || body.querySelector(`.view-mastery-note[data-rem-id="${id}"]`);
      if (field) openTextEditorSheet(field);
    });
  });

  // Saving for .view-remark-edit / .group-remark-input-combined is handled by
  // the shared host saver (state.viewGroupRemarkSaver) set up once in
  // openGroupSessionView, not here — this function runs on every render, and
  // the body persists across renders, so attaching per-box listeners here
  // would stack up duplicates.

  // Saving for .view-remark-edit / .view-remark-empty / .view-mastery-note is
  // handled by the shared host saver (state.viewGroupRemarkSaver) set up once
  // in openGroupSessionView.

  // These three handlers update state.viewGroupSessionData synchronously
  // (not just the DOM/Firestore) before awaiting the write — see the matching
  // comment on the individual view screen's equivalent handlers for why:
  // leaveGroupSessionView()'s cleanup reads a captured snapshot with no guard
  // for an in-flight write, which could otherwise let it delete a remark the
  // boss just set.
  body.querySelectorAll(".view-remark-single-btn").forEach(btn => {
    btn.addEventListener("click", wrap(async () => {
      const isActive = btn.classList.contains("active");
      btn.closest(".view-remark-multi-opts")?.querySelectorAll(".view-remark-single-btn").forEach(b => b.classList.remove("active"));
      const newText = isActive ? "" : btn.dataset.opt;
      if (!isActive) btn.classList.add("active");
      const rem = state.viewGroupSessionData?.remarks?.[btn.dataset.remId];
      const prevText = rem?.text;
      const prevOptScore = rem?.optionScore;
      if (rem) rem.text = newText;
      const scoreVal = btn.dataset.score !== "" ? Number(btn.dataset.score) : NaN;
      if (!isNaN(scoreVal) && !isActive) {
        if (rem) rem.optionScore = scoreVal;
      } else {
        if (rem) delete rem.optionScore;
      }
      try {
        await updateRemarkText(sid(), btn.dataset.remId, newText);
        if (!isNaN(scoreVal) && !isActive) {
          await setOptionScore(sid(), btn.dataset.remId, scoreVal);
        } else if (prevOptScore !== undefined) {
          await clearOptionScore(sid(), btn.dataset.remId);
        }
      } catch (err) {
        if (rem) { rem.text = prevText; if (prevOptScore !== undefined) rem.optionScore = prevOptScore; else delete rem.optionScore; }
        alert("Couldn't save — check your connection and try again.\n\n" + err.message);
      }
    }));
  });

  body.querySelectorAll(".view-remark-multi-btn").forEach(btn => {
    btn.addEventListener("click", wrap(async () => {
      btn.classList.toggle("active");
      const container = btn.closest(".view-remark-multi-opts");
      const selected = [...container.querySelectorAll(".view-remark-multi-btn.active")].map(b => b.dataset.opt);
      const newText = selected.join(", ");
      const rem = state.viewGroupSessionData?.remarks?.[btn.dataset.remId];
      const prevText = rem?.text;
      if (rem) rem.text = newText;
      try {
        await updateRemarkText(sid(), btn.dataset.remId, newText);
      } catch (err) {
        if (rem) rem.text = prevText;
        alert("Couldn't save — check your connection and try again.\n\n" + err.message);
      }
    }));
  });

  body.querySelectorAll(".view-starter-input").forEach(input => {
    input.addEventListener("blur", async () => {
      const rem = state.viewGroupSessionData?.remarks?.[input.dataset.remId];
      if (!rem || input.value === (rem.text || "")) return;
      const prevText = rem.text;
      rem.text = input.value;
      try {
        await updateRemarkText(sid(), input.dataset.remId, input.value);
      } catch (err) {
        rem.text = prevText;
        alert("Couldn't save — check your connection and try again.\n\n" + err.message);
      }
    });
  });

  // "+ Add Remark & Trials" on a brand-new (round-less) activity — adds one
  // remark for every attendee. Writes to local state and renders immediately
  // (optimistic) instead of awaiting addActivity + addGroupRemarksBatch
  // first — both are handed the same ids used locally, so the background
  // writes settle into the exact same keys once the snapshot catches up.
  body.querySelectorAll(".btn-view-group-add-remark-all").forEach(btn => {
    btn.addEventListener("click", () => {
      if (btn.disabled) return;
      btn.disabled = true;
      const data       = state.viewGroupSessionData;
      const targetName = btn.dataset.targetName;
      const actName    = btn.dataset.actName;
      const attendees  = data.attendees || (state.viewGroup?.students || []).filter(Boolean);
      data.activities = data.activities || {};
      data.remarks    = data.remarks || {};
      let actId = btn.dataset.actId || Object.entries(data.activities)
        .find(([, a]) => a.targetName === targetName && a.activityName === actName)?.[0] || null;
      const isNewAct = !actId;
      const actOrder = Date.now();
      if (isNewAct) {
        actId = generateId("a");
        data.activities[actId] = { targetName, activityName: actName, order: actOrder, isPredefined: true };
      }
      const studentNames = attendees.filter(studentName => !Object.values(data.remarks)
        .some(r => r.activityId === actId && r.studentName === studentName));
      const remIds = studentNames.map(() => generateId("r"));
      studentNames.forEach((studentName, i) => {
        data.remarks[remIds[i]] = { activityId: actId, studentName, text: "", trials: [], order: actOrder };
      });
      renderGroupSessionView();
      (async () => {
        try {
          if (isNewAct) await addActivity(sid(), targetName, actName, actOrder, true, actId);
          if (studentNames.length) {
            await addGroupRemarksBatch(sid(), studentNames.map(studentName => ({ actId, studentName })), remIds);
          }
        } catch (err) {
          if (isNewAct) delete data.activities[actId];
          remIds.forEach(id => delete data.remarks[id]);
          renderGroupSessionView();
          alert("Couldn't add remark — check your connection and try again.\n\n" + err.message);
        }
      })();
    });
  });

  // "+ Add Remark & Trials" on a pending (missing) student within an existing
  // round — actId always already exists here (the round itself came from an
  // existing remark), so this is a single optimistic write.
  body.querySelectorAll(".btn-view-group-add-remark-pending").forEach(btn => {
    btn.addEventListener("click", () => {
      if (btn.disabled) return;
      btn.disabled = true;
      const data        = state.viewGroupSessionData;
      const actId        = btn.dataset.actId;
      const studentName  = btn.dataset.student;
      const remId        = generateId("r");
      data.remarks = data.remarks || {};
      data.remarks[remId] = { activityId: actId, studentName, text: "", trials: [], order: Date.now() };
      renderGroupSessionView();
      addGroupRemark(sid(), actId, studentName, "", remId).catch(err => {
        delete data.remarks[remId];
        renderGroupSessionView();
        alert("Couldn't add remark — check your connection and try again.\n\n" + err.message);
      });
    });
  });

  // "+ Add Remark" for a mapped-score activity, one attendee at a time — unlike
  // the plain pending button above, the activity may not exist yet at all
  // (mapped activities skip the bulk "add for everyone" button), so this
  // creates it on demand, same as ensureGroupActivityAndRemark's live-entry
  // counterpart — also optimistic now, for the same reason as the buttons above.
  body.querySelectorAll(".btn-view-group-add-remark-mapped-pending").forEach(btn => {
    btn.addEventListener("click", () => {
      if (btn.disabled) return;
      btn.disabled = true;
      const data       = state.viewGroupSessionData;
      const targetName = btn.dataset.targetName;
      const actName    = btn.dataset.actName;
      const studentName = btn.dataset.student;
      data.activities = data.activities || {};
      data.remarks    = data.remarks || {};
      let actId = btn.dataset.actId || Object.entries(data.activities)
        .find(([, a]) => a.targetName === targetName && a.activityName === actName)?.[0] || null;
      const isNewAct = !actId;
      const actOrder = Date.now();
      if (isNewAct) {
        actId = generateId("a");
        data.activities[actId] = { targetName, activityName: actName, order: actOrder, isPredefined: true };
      }
      const remId = generateId("r");
      data.remarks[remId] = { activityId: actId, studentName, text: "", trials: [], order: actOrder };
      renderGroupSessionView();
      (async () => {
        try {
          if (isNewAct) await addActivity(sid(), targetName, actName, actOrder, true, actId);
          await addGroupRemark(sid(), actId, studentName, "", remId);
        } catch (err) {
          if (isNewAct) delete data.activities[actId];
          delete data.remarks[remId];
          renderGroupSessionView();
          alert("Couldn't add remark — check your connection and try again.\n\n" + err.message);
        }
      })();
    });
  });

  // Inline single-select for group preset activities with no remark yet
  body.querySelectorAll(".view-group-single-create-btn").forEach(btn => {
    btn.addEventListener("click", wrap(async () => {
      const data = state.viewGroupSessionData;
      const targetName = btn.dataset.targetName;
      const actName = btn.dataset.actName;
      const studentName = btn.dataset.student;
      const val = btn.dataset.opt;
      data.activities = data.activities || {};
      data.remarks = data.remarks || {};
      let actId = btn.dataset.actId || Object.entries(data.activities)
        .find(([, a]) => a.targetName === targetName && a.activityName === actName)?.[0] || null;
      const isNewAct = !actId;
      const actOrder = Date.now();
      if (isNewAct) {
        actId = generateId("a");
        data.activities[actId] = { targetName, activityName: actName, order: actOrder, isPredefined: true };
      }
      const remId = generateId("r");
      data.remarks[remId] = { activityId: actId, studentName, text: val, trials: [], order: actOrder };
      renderGroupSessionView();
      try {
        if (isNewAct) await addActivity(sid(), targetName, actName, actOrder, true, actId);
        await addGroupRemark(sid(), actId, studentName, val, remId);
      } catch (err) {
        if (isNewAct) delete data.activities[actId];
        delete data.remarks[remId];
        renderGroupSessionView();
        alert("Couldn't add remark — check your connection and try again.\n\n" + err.message);
      }
    }));
  });

  body.querySelectorAll(".view-group-multi-create-btn").forEach(btn => {
    btn.addEventListener("click", wrap(async () => {
      const data = state.viewGroupSessionData;
      const targetName = btn.dataset.targetName;
      const actName = btn.dataset.actName;
      const studentName = btn.dataset.student;
      const val = btn.dataset.opt;
      const isMaintained = btn.dataset.maintained === "true";
      data.activities = data.activities || {};
      data.remarks = data.remarks || {};
      let actId = btn.dataset.actId || Object.entries(data.activities)
        .find(([, a]) => a.targetName === targetName && a.activityName === actName)?.[0] || null;
      const isNewAct = !actId;
      const actOrder = Date.now();
      if (isNewAct) {
        actId = generateId("a");
        data.activities[actId] = { targetName, activityName: actName, order: actOrder, isPredefined: true };
      }
      const remId = generateId("r");
      data.remarks[remId] = { activityId: actId, studentName, text: val, trials: [], order: actOrder };
      if (isMaintained) data.remarks[remId].masteryNote = "Maintain";
      renderGroupSessionView();
      try {
        if (isNewAct) await addActivity(sid(), targetName, actName, actOrder, true, actId);
        await addGroupRemark(sid(), actId, studentName, val, remId, isMaintained ? "Maintain" : "");
      } catch (err) {
        if (isNewAct) delete data.activities[actId];
        delete data.remarks[remId];
        renderGroupSessionView();
        alert("Couldn't add remark — check your connection and try again.\n\n" + err.message);
      }
    }));
  });

  // Auto-expand remark/starter textareas in group view
  body.querySelectorAll(".view-remark-edit, .view-starter-input").forEach(ta => {
    if (ta.tagName !== "TEXTAREA") return;
    const expand = () => { ta.style.height = "auto"; ta.style.height = ta.scrollHeight + "px"; };
    expand();
    ta.addEventListener("input", expand);
  });

  // "+" under Trials with no remark yet — creates the activity/remark for
  // this student and a first trial in one go.
  body.querySelectorAll(".view-group-add-trial-new").forEach(btn => {
    btn.addEventListener("click", wrap(async () => {
      let actId = btn.dataset.actId;
      if (!actId) {
        actId = await addActivity(
          sid(), btn.dataset.targetName, btn.dataset.actName, Date.now(),
          btn.dataset.isPredefined === "true"
        );
      }
      const remId = await addGroupRemark(sid(), actId, btn.dataset.student);
      await setTrials(sid(), remId, [-1]);
      await waitForSessionData(() => !!state.viewGroupSessionData?.remarks?.[remId]?.trials?.length);
    }));
  });

  body.querySelectorAll(".view-act-edit").forEach(input => {
    input.addEventListener("blur", async () => {
      const newName = input.value.trim();
      if (!newName || newName === input.dataset.original) return;
      if (!input.dataset.actId) return;
      input.dataset.original = newName;
      await updateActivityName(sid(), input.dataset.actId, newName);
    });
    input.addEventListener("keydown", e => {
      if (e.key === "Enter") { e.preventDefault(); input.blur(); }
    });
  });

  body.querySelectorAll(".view-act-del").forEach(btn => {
    btn.addEventListener("click", wrap(async () => {
      if (!confirm("Delete this activity and all its remarks?")) return;
      const actId = btn.dataset.actId;
      if (!actId) return;
      const remIds = viewGetRemarks(state.viewGroupSessionData, actId).map(r => r.id);
      await deleteActivity(sid(), actId, remIds);
    }));
  });

  body.querySelectorAll(".view-rem-del").forEach(btn => {
    btn.addEventListener("click", () => {
      if (!confirm("Delete this remark?")) return;
      const remId = btn.dataset.remId;
      const rem = state.viewGroupSessionData?.remarks?.[remId];
      if (!rem) return;
      delete state.viewGroupSessionData.remarks[remId];
      renderViewOrDefer("viewGroupRenderPending", isGroupViewBusy, renderGroupSessionView);
      deleteRemark(sid(), remId).catch(err => {
        state.viewGroupSessionData.remarks[remId] = rem;
        renderViewOrDefer("viewGroupRenderPending", isGroupViewBusy, renderGroupSessionView);
        alert("Couldn't delete remark — check your connection and try again.\n\n" + err.message);
      });
    });
  });

  body.querySelectorAll(".view-comment-edit").forEach(ta => {
    ta.addEventListener("blur", async () => {
      const key    = ta.dataset.targetKey;
      const target = getViewGroupEffectiveTargets().find(t => sanitizeKey(t.name) === key);
      if (!target) return;
      const current = (state.viewGroupSessionData?.fedcComments || {})[key] || "";
      if (ta.value === current) return;
      await updateFedcComment(sid(), target.name, ta.value);
    });
  });

  // ── Review panel inputs (recreated on each render) ────────────
  const grpCmtInput = body.querySelector(".review-comment-input");
  if (grpCmtInput) {
    grpCmtInput.addEventListener("input", () => { _grpCommentDraft = grpCmtInput.value; });
    grpCmtInput.addEventListener("keydown", async e => {
      if (e.key !== "Enter" || !grpCmtInput.value.trim()) return;
      e.preventDefault();
      const text = grpCmtInput.value.trim();
      _grpCommentDraft = "";
      try { await addReviewComment(sid(), text); } catch (err) { console.error("addReviewComment (grp):", err); }
    });
  }
  const grpSignInput = body.querySelector(".review-sign-input");
  if (grpSignInput) {
    grpSignInput.addEventListener("input", () => { _grpSigningName = grpSignInput.value; });
    grpSignInput.focus();
  }
}

// ── Go To Another (group) Session ─────────────────────────────
async function showGoToAnotherGroupSession(group) {
  $("session-picker-title").textContent = group.name;
  $("session-picker-list").innerHTML = `<div class="session-picker-loading">Loading sessions…</div>`;
  $("session-picker-modal").classList.remove("hidden");

  let sessions = [];
  try { sessions = await getRecentGroupSessions(group.id); } catch (_) {}

  const currentTargetNames = new Set((group.targets || []).map(t => t.name));
  const stripEmpty = s => (s || "").replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").replace(/ /g, " ").trim();
  const hasUsefulData = s => {
    if (Object.values(s.fedcComments || {}).some(c => stripEmpty(c).length > 0)) return true;
    return Object.values(s.remarks || {}).some(r => {
      const act = (s.activities || {})[r.activityId];
      if (!act || !currentTargetNames.has(act.targetName)) return false;
      const hasText   = stripEmpty(r.text).length > 0;
      const hasTrials = (r.trials      || []).some(t => t !== null && t !== -1);
      const hasNote   = stripEmpty(r.masteryNote).length > 0;
      return hasText || hasTrials || hasNote;
    });
  };
  // Don't auto-delete the session currently being viewed
  const empties = sessions.filter(s => s.id !== state.viewGroupSessionId && !hasUsefulData(s));
  empties.forEach(s => deleteSession(s.id).catch(() => {}));
  sessions = sessions.filter(s => !empties.some(e => e.id === s.id));

  const today = getTodayString();
  const byMonth = new Map();
  for (const s of sessions) {
    if (!byMonth.has(s.month)) byMonth.set(s.month, []);
    byMonth.get(s.month).push(s);
  }

  if (byMonth.size === 0) {
    $("session-picker-list").innerHTML = `<div class="session-picker-loading">No sessions found.</div>`;
    return;
  }

  const currentMonth = state.viewGroupSessionData?.month;
  if (currentMonth && byMonth.has(currentMonth)) {
    renderGoToGroupSessionsForMonth(group, currentMonth, byMonth.get(currentMonth), byMonth, today);
  } else {
    renderGoToGroupMonthGrid(group, byMonth, today);
  }
}

function renderGoToGroupMonthGrid(group, byMonth, today) {
  $("session-picker-title").textContent = group.name;
  let html = `<div class="month-grid">`;
  for (const month of byMonth.keys()) {
    const [name, year] = month.split(" ");
    html += `<button class="month-grid-btn" data-month="${escHtml(month)}">
      <span class="mgb-month">${escHtml(name.slice(0, 3))}</span>
      <span class="mgb-year">${escHtml(year)}</span>
    </button>`;
  }
  html += `</div>`;
  $("session-picker-list").innerHTML = html;
  $("session-picker-list").querySelectorAll(".month-grid-btn").forEach(btn => {
    btn.addEventListener("click", () => {
      const month = btn.dataset.month;
      renderGoToGroupSessionsForMonth(group, month, byMonth.get(month), byMonth, today);
    });
  });
}

function renderGoToGroupSessionsForMonth(group, month, monthSessions, byMonth, today) {
  $("session-picker-title").textContent = month;
  const sorted  = [...monthSessions].sort((a, b) => a.date.localeCompare(b.date));
  const display = [...sorted].reverse();
  let html = `<button class="btn-picker-back">← Back</button>`;
  html += renderSessionListRows(sorted, display, today, {
    isCurrentId: state.viewGroupSessionId,
    renderLabel: (s, dateLabel) => escHtml(dateLabel)
  });
  const list = $("session-picker-list");
  list.innerHTML = html;
  list.querySelector(".btn-picker-back").addEventListener("click", () => {
    renderGoToGroupMonthGrid(group, byMonth, today);
  });
  list.querySelectorAll(".session-list-item").forEach(item => {
    item.addEventListener("click", () => {
      const sid = item.dataset.sessionId;
      closeSessionPicker();
      if (sid !== state.viewGroupSessionId) {
        const open = () => openGroupSessionView(group, sid);
        if (isOlderThan7Days(item.dataset.sessionDate)) { requirePassword(open, EXPIRED_MSG); } else { open(); }
      }
    });
  });
}

// Header "Go To Another Session" button on the group live entry screen —
// same month-grid-then-list flow as the View screen's equivalent button,
// but jumps into live entry instead of View/Edit (openGroupSession instead
// of openGroupSessionView) when a session is picked. openGroupSession takes
// a date string rather than a session id, so the click handler looks up the
// picked session's date from the month's session list.
async function showGoToAnotherGroupSessionForEntry(group) {
  $("session-picker-title").textContent = group.name;
  $("session-picker-list").innerHTML = `<div class="session-picker-loading">Loading sessions…</div>`;
  $("session-picker-modal").classList.remove("hidden");

  let sessions = [];
  try { sessions = await getRecentGroupSessions(group.id); } catch (_) {}

  const currentTargetNames = new Set((group.targets || []).map(t => t.name));
  const stripEmpty = s => (s || "").replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").replace(/ /g, " ").trim();
  const hasUsefulData = s => {
    if (Object.values(s.fedcComments || {}).some(c => stripEmpty(c).length > 0)) return true;
    return Object.values(s.remarks || {}).some(r => {
      const act = (s.activities || {})[r.activityId];
      if (!act || !currentTargetNames.has(act.targetName)) return false;
      const hasText   = stripEmpty(r.text).length > 0;
      const hasTrials = (r.trials      || []).some(t => t !== null && t !== -1);
      const hasNote   = stripEmpty(r.masteryNote).length > 0;
      return hasText || hasTrials || hasNote;
    });
  };
  // Don't auto-delete the session currently being edited
  const empties = sessions.filter(s => s.id !== state.groupSessionId && !hasUsefulData(s));
  empties.forEach(s => deleteSession(s.id).catch(() => {}));
  sessions = sessions.filter(s => !empties.some(e => e.id === s.id));

  const today = getTodayString();
  const byMonth = new Map();
  for (const s of sessions) {
    if (!byMonth.has(s.month)) byMonth.set(s.month, []);
    byMonth.get(s.month).push(s);
  }

  if (byMonth.size === 0) {
    $("session-picker-list").innerHTML = `<div class="session-picker-loading">No sessions found.</div>`;
    return;
  }

  const currentMonth = state.groupSessionData?.month;
  if (currentMonth && byMonth.has(currentMonth)) {
    renderGoToGroupSessionsForMonthEntry(group, currentMonth, byMonth.get(currentMonth), byMonth, today);
  } else {
    renderGoToGroupMonthGridEntry(group, byMonth, today);
  }
}

function renderGoToGroupMonthGridEntry(group, byMonth, today) {
  $("session-picker-title").textContent = group.name;
  let html = `<div class="month-grid">`;
  for (const month of byMonth.keys()) {
    const [name, year] = month.split(" ");
    html += `<button class="month-grid-btn" data-month="${escHtml(month)}">
      <span class="mgb-month">${escHtml(name.slice(0, 3))}</span>
      <span class="mgb-year">${escHtml(year)}</span>
    </button>`;
  }
  html += `</div>`;
  $("session-picker-list").innerHTML = html;
  $("session-picker-list").querySelectorAll(".month-grid-btn").forEach(btn => {
    btn.addEventListener("click", () => {
      const month = btn.dataset.month;
      renderGoToGroupSessionsForMonthEntry(group, month, byMonth.get(month), byMonth, today);
    });
  });
}

function renderGoToGroupSessionsForMonthEntry(group, month, monthSessions, byMonth, today) {
  $("session-picker-title").textContent = month;
  const sorted  = [...monthSessions].sort((a, b) => a.date.localeCompare(b.date));
  const display = [...sorted].reverse();
  let html = `<button class="btn-picker-back">← Back</button>`;
  html += renderSessionListRows(sorted, display, today, {
    isCurrentId: state.groupSessionId,
    renderLabel: (s, dateLabel) => escHtml(dateLabel)
  });
  const list = $("session-picker-list");
  list.innerHTML = html;
  list.querySelector(".btn-picker-back").addEventListener("click", () => {
    renderGoToGroupMonthGridEntry(group, byMonth, today);
  });
  list.querySelectorAll(".session-list-item").forEach(item => {
    item.addEventListener("click", () => {
      const sid = item.dataset.sessionId;
      closeSessionPicker();
      if (sid === state.groupSessionId) return;
      const picked = sorted.find(s => s.id === sid);
      const open = () => openGroupSession(group, picked.date, group.students);
      if (isOlderThan7Days(picked.date)) { requirePassword(open, EXPIRED_MSG); } else { open(); }
    });
  });
}

// ── Edit Date (group view) ─────────────────────────────────────
async function showEditGroupDatePicker() {
  const group       = state.viewGroup;
  const currentDate = state.viewGroupSessionData.date;

  $("session-picker-title").textContent = "Edit Date";
  $("session-picker-list").innerHTML = `<div class="session-picker-loading">Loading…</div>`;
  $("session-picker-modal").classList.remove("hidden");

  let sessions = [];
  try { sessions = await getRecentGroupSessions(group.id); } catch (_) {}
  const takenDates = new Set(
    sessions.filter(s => s.id !== state.viewGroupSessionId).map(s => s.date)
  );
  renderGroupDatePickerCalendar(currentDate, takenDates, getTodayString(), currentDate);
}

function renderGroupDatePickerCalendar(displayDate, takenDates, today, currentDate) {
  const [y, m] = displayDate.split("-").map(Number);
  const monthLabel = new Date(y, m - 1, 1)
    .toLocaleString("default", { month: "long", year: "numeric" });
  const [ty, tm] = today.split("-").map(Number);
  const canNext = y < ty || (y === ty && m < tm);

  const pad = n => String(n).padStart(2, "0");
  const prevM = m === 1  ? `${y - 1}-12-01` : `${y}-${pad(m - 1)}-01`;
  const nextM = m === 12 ? `${y + 1}-01-01` : `${y}-${pad(m + 1)}-01`;

  const firstDow  = new Date(y, m - 1, 1).getDay();
  const daysInMon = new Date(y, m, 0).getDate();

  let html = `<div class="date-picker-wrap">
    <p class="date-picker-subtitle">Select a new date</p>
    <p class="date-picker-legend"><span class="date-taken-dot">✓︎</span> Session exists on this day</p>
    <div class="date-picker-cal">
      <div class="date-picker-nav">
        <button class="btn-date-prev">‹</button>
        <span class="date-picker-month-label">${escHtml(monthLabel)}</span>
        <button class="btn-date-next"${canNext ? "" : " disabled"}>›</button>
      </div>
      <div class="date-picker-day-headers">
        <span>Su</span><span>Mo</span><span>Tu</span><span>We</span>
        <span>Th</span><span>Fr</span><span>Sa</span>
      </div>
      <div class="date-picker-grid">`;

  for (let cell = 0; cell < 42; cell++) {
    const d = cell - firstDow + 1;
    if (d < 1 || d > daysInMon) { html += `<span></span>`; continue; }
    const ds      = `${y}-${pad(m)}-${pad(d)}`;
    const isCur   = ds === currentDate;
    const isFut   = ds > today;
    const isTaken = takenDates.has(ds);
    const dis     = isFut || isTaken;
    let cls = "date-picker-day";
    if (isCur)   cls += " date-picker-day-current";
    if (isFut)   cls += " date-picker-day-future";
    if (isTaken) cls += " date-picker-day-taken";
    const dotCls = isTaken ? "date-taken-dot" : "day-dot-spacer";
    html += `<button class="${cls}" data-date="${ds}"${dis ? " disabled" : ""}><span class="day-num">${d}</span><span class="${dotCls}">${isTaken ? "✓︎" : ""}</span></button>`;
  }
  html += `</div></div></div>`;

  $("session-picker-title").textContent = "Edit Date";
  $("session-picker-list").innerHTML = html;

  $("session-picker-list").querySelector(".btn-date-prev").addEventListener("click", () => {
    renderGroupDatePickerCalendar(prevM, takenDates, today, currentDate);
  });
  if (canNext) {
    $("session-picker-list").querySelector(".btn-date-next").addEventListener("click", () => {
      renderGroupDatePickerCalendar(nextM, takenDates, today, currentDate);
    });
  }
  $("session-picker-list").querySelectorAll(".date-picker-day:not([disabled])").forEach(btn => {
    btn.addEventListener("click", async () => {
      const newDate = btn.dataset.date;
      closeSessionPicker();
      if (newDate === currentDate) return;
      try {
        await updateGroupSessionDate(state.viewGroupSessionId, newDate, state.viewGroup.id);
      } catch (err) {
        alert(err.message);
      }
    });
  });
}

// ============================================================
// MANAGE MODAL (inline student / target / template config editing)
// ============================================================

function cfgId(prefix) {
  return prefix + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
}

function todayDateStr() {
  return new Date().toISOString().slice(0, 10);
}

function inactiveReasonBadge(pa) {
  const _badgeBase = "display:inline-flex;align-items:center;border-radius:.35rem;padding:.1rem .5rem;font-size:.93rem;font-weight:700;white-space:nowrap;margin-right:.4rem;vertical-align:middle;line-height:1.2";
  let badges = '';
  if (pa?.maintained)
    badges += `<span style="${_badgeBase};background:#e5e7eb;border:1px solid #9ca3af;color:#374151">🆗 Maintained${pa.maintainedAt ? ` on ${fmtPeriodDate(pa.maintainedAt)}` : ''}</span>`;
  const masteredDate = pa?.masteredOn || (pa?.inactiveReason === 'mastered' ? "2026-06-30" : null);
  if (masteredDate)
    badges += `<span style="${_badgeBase};background:#d1fae5;border:1px solid #6ee7b7;color:#059669">⭐ Mastered on ${fmtPeriodDate(masteredDate)}</span>`;
  else if (pa?.discontinuedOn || pa?.inactiveReason === 'discontinued') {
    const label = pa?.discontinuedOn ? `🚩 Discontinued on ${fmtPeriodDate(pa.discontinuedOn)}` : '● Discontinued';
    badges += `<span style="${_badgeBase};background:#fee2e2;border:1px solid #fca5a5;color:#dc2626">${label}</span>`;
  }
  return badges;
}

// Single-button acknowledgement popup, for a rule the user has to actively
// dismiss. An inline red line inside a sheet is easy to miss — this can't be.
// z-index sits above showDatePickerOverlay so it works from inside those sheets.
function showAlertOverlay({ title = "⚠️ Not allowed", message, okLabel = "OK" }) {
  return new Promise(resolve => {
    const overlay = document.createElement("div");
    overlay.style.cssText = "position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:10001;display:flex;align-items:center;justify-content:center;padding:1rem";
    overlay.innerHTML =
      `<div style="background:#fff;border-radius:.75rem;padding:1.35rem 1.5rem;max-width:390px;width:100%;box-shadow:0 8px 32px rgba(0,0,0,.25)">` +
      `<div style="font-size:1rem;font-weight:700;color:#b91c1c;margin-bottom:.55rem">${title}</div>` +
      `<div style="font-size:.92rem;color:#374151;margin-bottom:1.25rem;line-height:1.65">${message}</div>` +
      `<div style="display:flex;justify-content:flex-end">` +
      `<button class="dp-ok" style="padding:.55rem 1.6rem;border:none;border-radius:.4rem;background:var(--primary);color:#fff;cursor:pointer;font-size:.9rem;font-weight:600">${okLabel}</button>` +
      `</div></div>`;
    document.body.appendChild(overlay);
    const finish = () => { overlay.remove(); document.removeEventListener("keydown", onKey); resolve(); };
    const onKey = e => { if (e.key === "Escape" || e.key === "Enter") { e.preventDefault(); finish(); } };
    overlay.querySelector(".dp-ok").addEventListener("click", finish);
    document.addEventListener("keydown", onKey);
    overlay.querySelector(".dp-ok").focus();
  });
}

function showAutoDateConfirm({ message, confirmLabel }) {
  return new Promise(resolve => {
    const overlay = document.createElement("div");
    overlay.style.cssText = "position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:9999;display:flex;align-items:center;justify-content:center";
    overlay.innerHTML =
      `<div style="background:#fff;border-radius:.75rem;padding:1.5rem;max-width:360px;width:90%;box-shadow:0 8px 32px rgba(0,0,0,.22)">` +
      `<div style="font-size:.92rem;color:#374151;margin-bottom:1.25rem;line-height:1.65">${message}</div>` +
      `<div style="display:flex;gap:.6rem;justify-content:flex-end">` +
      `<button class="dp-cancel" style="padding:.5rem 1rem;border:1px solid #d1d5db;border-radius:.4rem;background:#fff;cursor:pointer;font-size:.9rem">Cancel</button>` +
      `<button class="dp-confirm" style="padding:.5rem 1rem;border:none;border-radius:.4rem;background:var(--primary);color:#fff;cursor:pointer;font-size:.9rem;font-weight:600">${confirmLabel}</button>` +
      `</div></div>`;
    document.body.appendChild(overlay);
    const finish = val => { overlay.remove(); document.removeEventListener("keydown", onKey); resolve(val); };
    overlay.querySelector(".dp-cancel").addEventListener("click", () => finish(false));
    overlay.querySelector(".dp-confirm").addEventListener("click", () => finish(true));
    const onKey = e => { if (e.key === "Escape") finish(false); };
    document.addEventListener("keydown", onKey);
  });
}

function showDatePickerOverlay({ heading, infoHtml, minDate, defaultDate, confirmLabel, dateLabel = "activity" }) {
  return new Promise(resolve => {
    const overlay = document.createElement("div");
    overlay.style.cssText = "position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:9999;display:flex;align-items:center;justify-content:center;padding:1rem";
    const min = minDate || todayDateStr();
    const def = defaultDate && defaultDate >= min ? defaultDate : min;
    const defFormatted = fmtPeriodDate(def) || def;
    overlay.innerHTML = `<div style="background:#fff;border-radius:.75rem;padding:1.5rem;max-width:400px;width:100%;box-shadow:0 8px 32px rgba(0,0,0,.22)">
      <div style="font-size:.93rem;font-weight:700;color:#111;margin-bottom:.55rem">${heading}</div>
      ${infoHtml ? `<div style="font-size:.85rem;color:#374151;margin-bottom:.9rem;line-height:1.6">${infoHtml}</div>` : ''}
      <label style="font-size:.82rem;font-weight:600;color:#374151;display:block;margin-bottom:.35rem">Please select the final date you want this ${dateLabel} to appear.</label>
      <style>#dp-date-inp::-webkit-calendar-picker-indicator{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:pointer}</style>
      <div style="position:relative;margin-bottom:1rem;border:1.5px solid #d1d5db;border-radius:.4rem;background:#fff;cursor:pointer">
        <input type="date" id="dp-date-inp" value="${def}" min="${min}" style="position:absolute;inset:0;width:100%;height:100%;border:none;background:transparent;opacity:0;outline:none;cursor:pointer;box-sizing:border-box">
        <div id="dp-date-display" style="padding:.5rem .7rem;font-size:.95rem;color:#111;pointer-events:none;display:flex;align-items:center"><span id="dp-date-text">${defFormatted}</span><span style="margin-left:auto;padding-left:.5rem;font-size:1rem;color:#6b7280">🗓</span></div>
      </div>
      <div style="display:flex;gap:.6rem;justify-content:flex-end">
        <button class="dp-cancel" style="padding:.5rem 1rem;border:1px solid #d1d5db;border-radius:.4rem;background:#fff;cursor:pointer;font-size:.9rem">Cancel</button>
        <button class="dp-confirm" style="padding:.5rem 1rem;border:none;border-radius:.4rem;background:var(--primary);color:#fff;cursor:pointer;font-size:.9rem;font-weight:600">${confirmLabel}</button>
      </div>
    </div>`;
    document.body.appendChild(overlay);
    const inp = overlay.querySelector("#dp-date-inp");
    const dpDisplay = overlay.querySelector("#dp-date-display");
    inp.addEventListener("input", () => { overlay.querySelector("#dp-date-text").textContent = inp.value ? (fmtPeriodDate(inp.value) || inp.value) : "Select a date"; });
    const finish = val => { overlay.remove(); document.removeEventListener("keydown", onKey); resolve(val); };
    overlay.querySelector(".dp-cancel").addEventListener("click", () => finish(null));
    overlay.querySelector(".dp-confirm").addEventListener("click", () => {
      if (!inp.value || inp.value < min) { inp.style.borderColor = "#dc2626"; return; }
      finish(inp.value);
    });
    const onKey = e => { if (e.key === "Escape") finish(null); };
    document.addEventListener("keydown", onKey);
    requestAnimationFrame(() => inp.focus());
  });
}

function addOneDay(dateStr) {
  const d = new Date(dateStr + "T00:00:00");
  d.setDate(d.getDate() + 1);
  // Use local date parts — toISOString() returns UTC which shifts the date in UTC+ timezones
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

function isActivityActive(pa, dateStr) {
  if (!dateStr) return true;
  if (pa.masteredOn    && dateStr > pa.masteredOn)    return false;
  if (pa.discontinuedOn && dateStr > pa.discontinuedOn) return false;
  if (pa.activeFrom && dateStr < pa.activeFrom) return false;
  if (pa.activeTo   && dateStr > pa.activeTo)   return false;
  return true;
}

// Earliest date an activity may be marked mastered/discontinued. With recorded
// session data that's the last session with data — the activity has to stay
// visible up to and including the day it was last used. With no data at all
// there's nothing to preserve, so it falls back to the day the activity was
// created (its Start Date) rather than today: an activity that was never used
// should stop appearing from where it began, not from whenever it happens to be
// cleaned up. Older records with no creation date recorded fall back to today.
function statusChangeFloorDate(pa, latestDate) {
  return latestDate || pa.activeFrom || pa.createdOn || todayDateStr();
}
// View/Edit uses > (strict) instead of >= so sessions on the exact
// discontinuation/mastery date still show — the user may have entered data
// that day before deciding to discontinue the activity.
function isActivityActiveForView(pa, dateStr) {
  if (!dateStr) return true;
  if (pa.masteredOn    && dateStr > pa.masteredOn)    return false;
  if (pa.discontinuedOn && dateStr > pa.discontinuedOn) return false;
  if (pa.activeFrom && dateStr < pa.activeFrom) return false;
  if (pa.activeTo   && dateStr > pa.activeTo)   return false;
  return true;
}

function fmtPeriodDate(d) {
  if (!d) return null;
  const [y, m, dy] = d.split("-").map(Number);
  return `${dy} ${["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"][m-1]} ${y}`;
}

function presetLabel(val) {
  return { "": "Remark Only", fixed_remark: "Fixed Remark", manual_score: "Manual Score",
    starter_fixed: "Multiple Choice", starter_fixed_multi: "Checkboxes",
    starter_fixed_note: "Multiple Choice" }[val] ?? "Remark Only";
}

function periodSectionHtml(activeFrom, activeTo, idx, withBorder, inactiveReason) {
  const fromLabel = activeFrom ? fmtPeriodDate(activeFrom) : '-∞';
  const toLabel   = activeTo   ? fmtPeriodDate(activeTo)   : '+∞';
  const fromBg    = activeFrom ? '#ffffff' : '#eff6ff';
  const toBg      = activeTo   ? '#ffffff' : '#eff6ff';
  const fromCol   = activeFrom ? '#111827' : '#6b7280';
  const toCol     = activeTo   ? '#111827' : '#6b7280';
  const border    = withBorder ? 'border-bottom:1px solid #f3f4f6;' : '';
  // Show "End Reason" dropdown only for activities (5th arg provided) when activeTo is set
  const reasonRow = (inactiveReason !== undefined && activeTo) ? `
    <div style="display:flex;align-items:center;gap:.5rem;margin-top:.35rem">
      <span style="font-size:.78rem;color:#6b7280;white-space:nowrap">End Reason:</span>
      <select class="mn-inactive-reason-select" data-idx="${idx}" style="flex:1;font-size:.8rem;padding:.2rem .4rem;border:1px solid #d1d5db;border-radius:.3rem;background:white;cursor:pointer">
        <option value="">— Not specified —</option>
        <option value="mastered"${inactiveReason === 'mastered' ? ' selected' : ''}>Mastered</option>
        <option value="discontinued"${inactiveReason === 'discontinued' ? ' selected' : ''}>Discontinued</option>
      </select>
    </div>` : '';
  return `<div style="padding:.45rem .6rem;${border}">
    <div style="font-size:.84rem;color:inherit;margin-bottom:.35rem">📅 Active Period</div>
    <div style="display:flex;align-items:center;gap:.4rem">
      <div style="position:relative;flex:1;min-width:0">
        <button class="mn-period-from-btn" data-idx="${idx}" style="width:100%;padding:.28rem .4rem;border:1px solid #d1d5db;border-radius:.3rem;background:${fromBg};cursor:pointer;font-size:.8rem;color:${fromCol};white-space:nowrap;text-align:center">${fromLabel}</button>
        <div class="mn-period-from-panel" data-idx="${idx}" style="display:none;position:absolute;top:calc(100% + 3px);left:0;z-index:300;background:#fff;border:1px solid #e5e7eb;border-radius:.45rem;padding:.4rem;box-shadow:0 4px 14px rgba(0,0,0,.12);min-width:175px">
          <input type="date" class="mn-period-date" data-idx="${idx}" data-which="from" value="${activeFrom||''}" style="width:100%;font-size:.8rem;border:1px solid #d1d5db;border-radius:.3rem;padding:.2rem .3rem;margin-bottom:.3rem;box-sizing:border-box">
          <button class="mn-period-inf" data-idx="${idx}" data-which="from" style="width:100%;padding:.25rem;font-size:.78rem;border:1px solid #bfdbfe;border-radius:.3rem;background:#eff6ff;cursor:pointer;color:#1d4ed8">Clear / Set as -∞</button>
        </div>
      </div>
      <span style="color:#9ca3af;flex-shrink:0">→</span>
      <div style="position:relative;flex:1;min-width:0">
        <button class="mn-period-to-btn" data-idx="${idx}" style="width:100%;padding:.28rem .4rem;border:1px solid #d1d5db;border-radius:.3rem;background:${toBg};cursor:pointer;font-size:.8rem;color:${toCol};white-space:nowrap;text-align:center">${toLabel}</button>
        <div class="mn-period-to-panel" data-idx="${idx}" style="display:none;position:absolute;top:calc(100% + 3px);right:0;z-index:300;background:#fff;border:1px solid #e5e7eb;border-radius:.45rem;padding:.4rem;box-shadow:0 4px 14px rgba(0,0,0,.12);min-width:175px">
          <input type="date" class="mn-period-date" data-idx="${idx}" data-which="to" value="${activeTo||''}" style="width:100%;font-size:.8rem;border:1px solid #d1d5db;border-radius:.3rem;padding:.2rem .3rem;margin-bottom:.3rem;box-sizing:border-box">
          <button class="mn-period-inf" data-idx="${idx}" data-which="to" style="width:100%;padding:.25rem;font-size:.78rem;border:1px solid #bfdbfe;border-radius:.3rem;background:#eff6ff;cursor:pointer;color:#1d4ed8">Clear / Set as +∞</button>
        </div>
      </div>
    </div>
    ${reasonRow}
  </div>`;
}

function actStartDateHtml(activeFrom, idx) {
  return `<button class="mn-act-start-btn" data-idx="${idx}" style="width:100%;padding:.55rem .9rem;text-align:left;background:none;border:none;border-bottom:1px solid #f3f4f6;cursor:pointer;font-size:.84rem;color:#374151;white-space:nowrap">📅 Set Start Date</button>`;
}

function showActStartDatePicker() {
  const act = _actStartPickerActs?.[_actStartPickerIdx];
  const hasExistingDate = !!act?.activeFrom;
  const activeFrom = act?.activeFrom || todayDateStr();
  const actName = (act?.title || act?.name || '').replace(/<[^>]*>/g, '').trim();
  let overlay = document.getElementById('act-start-picker-overlay');
  if (!overlay) {
    overlay = document.createElement('div');
    overlay.id = 'act-start-picker-overlay';
    document.body.appendChild(overlay);
  }
  overlay.innerHTML = `<div style="position:fixed;inset:0;z-index:9000;background:rgba(0,0,0,.45);display:flex;flex-direction:column;justify-content:flex-end" id="act-start-picker-backdrop">
    <div style="background:#fff;border-radius:1.1rem 1.1rem 0 0;padding:1.3rem 1.3rem calc(env(safe-area-inset-bottom,0px) + 1.3rem);box-shadow:0 -4px 24px rgba(0,0,0,.14)">
      <div style="font-weight:700;font-size:1rem;color:#111827;margin-bottom:.25rem">Set Start Date</div>
      <div style="font-size:.85rem;color:#6b7280;margin-bottom:.85rem">What date do you want this activity <strong style="color:#374151">(${escHtml(actName)})</strong> to start appearing?</div>
      <div id="act-start-picker-err" style="display:none;font-size:.82rem;color:#dc2626;margin-bottom:.5rem;line-height:1.4;padding:.4rem .6rem;background:#fee2e2;border-radius:.4rem"></div>
      <input type="date" id="act-start-picker-inp" value="${activeFrom}" style="width:100%;font-size:1rem;border:1.5px solid #d1d5db;border-radius:.5rem;padding:.55rem .65rem;box-sizing:border-box;margin-bottom:.85rem">
      <div style="display:flex;gap:.5rem">
        ${hasExistingDate ? `<button id="act-start-picker-clear" style="flex:1;padding:.65rem;font-size:.9rem;border:1px solid #fca5a5;border-radius:.5rem;background:#fee2e2;cursor:pointer;color:#dc2626;font-weight:600">✕ Clear Date</button>` : ''}
        <button id="act-start-picker-cancel" style="flex:1;padding:.65rem;font-size:.9rem;border:1px solid #d1d5db;border-radius:.5rem;background:#f9fafb;cursor:pointer;color:#6b7280;font-weight:600">Cancel</button>
      </div>
    </div>
  </div>`;
  document.getElementById('act-start-picker-backdrop').onclick = e => { if (e.target.id === 'act-start-picker-backdrop') closeActStartDatePicker(); };
  document.getElementById('act-start-picker-inp').addEventListener('change', handleActStartPickerChange);
  const clearBtn = document.getElementById('act-start-picker-clear');
  if (clearBtn) clearBtn.addEventListener('click', async () => { closeActStartDatePicker(); await _actStartPickerSaveFn(_actStartPickerIdx, 'activeFrom', null); });
  document.getElementById('act-start-picker-cancel').addEventListener('click', closeActStartDatePicker);
}

function closeActStartDatePicker() {
  const overlay = document.getElementById('act-start-picker-overlay');
  if (overlay) overlay.innerHTML = '';
}

async function handleActStartPickerChange() {
  const inp = document.getElementById('act-start-picker-inp');
  const errDiv = document.getElementById('act-start-picker-err');
  const value = inp?.value;
  if (errDiv) { errDiv.style.display = 'none'; errDiv.textContent = ''; }
  if (!value) return;
  const act = _actStartPickerActs?.[_actStartPickerIdx];
  if (!act) return;
  const actName = act.title || act.name;
  if (!_actStartPickerStudent && !_groupForTargetEdit) {
    closeActStartDatePicker();
    await _actStartPickerSaveFn(_actStartPickerIdx, 'activeFrom', value);
    return;
  }
  const allSessions = _groupForTargetEdit
    ? await getAllSessionsForGroup(_groupForTargetEdit.id).catch(() => [])
    : await getAllSessionsForStudent(_actStartPickerStudent.id).catch(() => []);
  let oldestDate = null;
  for (const session of allSessions) {
    const sActs = session.activities || {};
    const sRems = session.remarks || {};
    const matchingActIds = Object.entries(sActs)
      .filter(([, a]) => {
        if (a.targetName !== _actStartPickerTarget.name) return false;
        if (act.id && a.configId === act.id) return true;
        return a.activityName === actName || (act.title && a.activityName === act.title);
      })
      .map(([id]) => id);
    const hasData = matchingActIds.some(actId => Object.values(sRems).some(r =>
      r.activityId === actId && (
        (r.text || '').replace(/<[^>]*>/g, '').trim().length > 0 ||
        (r.masteryNote || '').trim().length > 0 ||
        (r.trials || []).some(t => t !== null && t !== -1) ||
        (r.optionScore !== undefined && r.optionScore !== null)
      )
    ));
    if (hasData && (!oldestDate || session.date < oldestDate)) oldestDate = session.date;
  }
  if (oldestDate && value > oldestDate) {
    if (inp) inp.value = act.activeFrom || '';
    await showAlertOverlay({
      title: "⚠️ Start date is too late",
      message: `This activity already has recorded data as far back as <strong>${fmtPeriodDate(oldestDate)}</strong>. ` +
               `Setting the start date later than that would hide sessions that already have data in them, ` +
               `so the earliest start date you can choose is <strong>${fmtPeriodDate(oldestDate)}</strong>.`
    });
    return;
  }
  closeActStartDatePicker();
  await _actStartPickerSaveFn(_actStartPickerIdx, 'activeFrom', value);
}

// ── Open / close ──────────────────────────────────────────────

function openManageModal(student, targetOrNull, templateOrNull = null, remarkPresetOrNull = null, scrollToPaId = null) {
  _mnCollapsedView = false;   // always opens expanded — see the declaration
  $("manage-modal").classList.remove("hidden");
  if (remarkPresetOrNull) {
    renderRemarkPresetManageContent(remarkPresetOrNull);
  } else if (templateOrNull) {
    renderTemplateManageContent(templateOrNull);
  } else if (targetOrNull) {
    // Password gate before revealing Edit Target
    $("manage-modal-title").textContent = "Edit Target";
    $("manage-modal-body").innerHTML = `
      <div style="padding:2rem 1rem;display:flex;flex-direction:column;align-items:center;gap:.75rem">
        <div style="font-size:.9rem;color:var(--text-muted)">Enter password to continue</div>
        <input id="edit-target-pw" type="text" class="admin-input"
          style="width:200px;text-align:center;font-size:1rem;-webkit-text-security:disc"
          placeholder="Enter password" autocomplete="off">
        <div id="edit-target-pw-err" style="font-size:.8rem;color:#dc2626;display:none">Incorrect password</div>
      </div>`;
    const pwInput = $("edit-target-pw");
    pwInput.value = "";
    setTimeout(() => { pwInput.value = ""; pwInput.focus(); }, 50);
    const checkPw = () => {
      if (pwInput.value !== "0823") {
        $("edit-target-pw-err").style.display = "";
        pwInput.value = "";
        return;
      }
      renderTargetManageContent(student, targetOrNull);
      if (scrollToPaId) {
        requestAnimationFrame(() => requestAnimationFrame(() => {
          const acts = targetOrNull.predefinedActivities || [];
          const idx = acts.findIndex(a => a.id === scrollToPaId);
          if (idx < 0) return;
          const modalBody = $("manage-modal-body");
          const el = modalBody?.querySelector(`.admin-list-item[data-idx="${idx}"]`);
          if (!el || !modalBody) return;
          modalBody.scrollTop = el.offsetTop - 120;
          el.classList.add("activity-cfg-blink");
          el.addEventListener("animationend", () => el.classList.remove("activity-cfg-blink"), { once: true });
        }));
      }
    };
    pwInput.addEventListener("keydown", e => { if (e.key === "Enter") checkPw(); });
  } else {
    renderStudentManageContent(student);
  }
}

